window.ExtraBibleBooks=window.ExtraBibleBooks||{};window.ExtraBibleBooks["1CH"]={"book":"1CH","editions":{"hbo-source":[[1,1,"אָדָ֥ם שֵׁ֖ת אֱנֽוֹשׁ׃","ʼádá֥m şé֖̌ţ ʼènֽwòş̌׃"],[1,2,"קֵינָ֥ן מַהֲלַלְאֵ֖ל יָֽרֶד׃","qéyná֥n mahàlalĕʼé֖l yáֽred׃"],[1,3,"חֲנ֥וֹךְ מְתוּשֶׁ֖לַח לָֽמֶךְ׃","ẖàn֥wòkĕ mĕţẇşě֖laẖ láֽmekĕ׃"],[1,4,"נֹ֥חַ שֵׁ֖ם חָ֥ם וָ⁠יָֽפֶת׃ס","nò֥ẖa şé֖̌m ẖá֥m wá⁠yáֽpeţ׃s"],[1,5,"בְּנֵ֣י יֶ֔פֶת גֹּ֣מֶר וּ⁠מָג֔וֹג וּ⁠מָדַ֖י וְ⁠יָוָ֣ן וְ⁠תֻבָ֑ל וּ⁠מֶ֖שֶׁךְ וְ⁠תִירָֽס׃ס","bĕ̇né֣y ye֔peţ gò֣̇mer ẇ⁠mág֔wòg ẇ⁠máda֖y wĕ⁠yáwá֣n wĕ⁠ţubá֑l ẇ⁠me֖şěkĕ wĕ⁠ţiyráֽs׃s"],[1,6,"וּ⁠בְנֵ֖י גֹּ֑מֶר אַשְׁכֲּנַ֥ז וְ⁠דִיפַ֖ת וְ⁠תוֹגַרְמָֽה׃","ẇ⁠bĕné֖y gò֑̇mer ʼaşĕ̌kà̇na֥z wĕ⁠diypa֖ţ wĕ⁠ţwògarĕmáֽh׃"],[1,7,"וּ⁠בְנֵ֥י יָוָ֖ן אֱלִישָׁ֣ה וְ⁠תַרְשִׁ֑ישָׁ⁠ה כִּתִּ֖ים וְ⁠רוֹדָנִֽים׃ס","ẇ⁠bĕné֥y yáwá֖n ʼèliyşá֣̌h wĕ⁠ţarĕşǐ֑yşá̌⁠h ki̇ţi֖̇ym wĕ⁠rwòdániֽym׃s"],[1,8,"בְּנֵ֖י חָ֑ם כּ֥וּשׁ וּ⁠מִצְרַ֖יִם פּ֥וּט וּ⁠כְנָֽעַן׃","bĕ̇né֖y ẖá֑m k֥̇ẇş̌ ẇ⁠miẕĕra֖yim ṗ֥ẇt ẇ⁠kĕnáֽʻan׃"],[1,9,"וּ⁠בְנֵ֣י כ֔וּשׁ סְבָא֙ וַ⁠חֲוִילָ֔ה וְ⁠סַבְתָּ֥א וְ⁠רַעְמָ֖א וְ⁠סַבְתְּכָ֑א וּ⁠בְנֵ֥י רַעְמָ֖א שְׁבָ֥א וּ⁠דְדָֽן׃ס","ẇ⁠bĕné֣y k֔ẇş̌ sĕbáʼ֙ wa⁠ẖàwiylá֔h wĕ⁠sabĕţá֥̇ʼ wĕ⁠raʻĕmá֖ʼ wĕ⁠sabĕţĕ̇ká֑ʼ ẇ⁠bĕné֥y raʻĕmá֖ʼ şĕ̌bá֥ʼ ẇ⁠dĕdáֽn׃s"],[1,10,"וְ⁠כ֖וּשׁ יָלַ֣ד אֶת־נִמְר֑וֹד ה֣וּא הֵחֵ֔ל לִ⁠הְי֥וֹת גִּבּ֖וֹר בָּ⁠אָֽרֶץ׃ס","wĕ⁠k֖ẇş̌ yála֣d ʼeţ-nimĕr֑wòd h֣ẇʼ héẖé֔l li⁠hĕy֥wòţ gi̇ḃ֖wòr bá̇⁠ʼáֽreẕ׃s"],[1,11,"וּ⁠מִצְרַ֡יִם יָלַ֞ד אֶת־לודיים וְ⁠אֶת־עֲנָמִ֛ים וְ⁠אֶת־לְהָבִ֖ים וְ⁠אֶת־נַפְתֻּחִֽים׃","ẇ⁠miẕĕra֡yim yála֞d ʼeţ-lwdyym wĕ⁠ʼeţ-ʻànámi֛ym wĕ⁠ʼeţ-lĕhábi֖ym wĕ⁠ʼeţ-napĕţu̇ẖiֽym׃"],[1,12,"וְֽ⁠אֶת־פַּתְרֻסִ֞ים וְ⁠אֶת־כַּסְלֻחִ֗ים אֲשֶׁ֨ר יָצְא֥וּ מִ⁠שָּׁ֛ם פְּלִשְׁתִּ֖ים וְ⁠אֶת־כַּפְתֹּרִֽים׃ס","wĕֽ⁠ʼeţ-pȧţĕrusi֞ym wĕ⁠ʼeţ-kȧsĕluẖi֗ym ʼàşě֨r yáẕĕʼ֥ẇ mi⁠şá֛̇̌m pĕ̇lişĕ̌ţi֖̇ym wĕ⁠ʼeţ-kȧpĕţò̇riֽym׃s"],[1,13,"וּ⁠כְנַ֗עַן יָלַ֛ד אֶת־צִיד֥וֹן בְּכֹר֖⁠וֹ וְ⁠אֶת־חֵֽת׃","ẇ⁠kĕna֗ʻan yála֛d ʼeţ-ẕiyd֥wòn bĕ̇kòr֖⁠wò wĕ⁠ʼeţ-ẖéֽţ׃"],[1,14,"וְ⁠אֶת־הַ⁠יְבוּסִי֙ וְ⁠אֶת־הָ֣⁠אֱמֹרִ֔י וְ⁠אֵ֖ת הַ⁠גִּרְגָּשִֽׁי׃","wĕ⁠ʼeţ-ha⁠yĕbẇsiy֙ wĕ⁠ʼeţ-há֣⁠ʼèmòri֔y wĕ⁠ʼé֖ţ ha⁠gi̇rĕgá̇şǐֽy׃"],[1,15,"וְ⁠אֶת־הַ⁠חִוִּ֥י וְ⁠אֶת־הַֽ⁠עַרְקִ֖י וְ⁠אֶת־הַ⁠סִּינִֽי׃","wĕ⁠ʼeţ-ha⁠ẖiwi֥̇y wĕ⁠ʼeţ-hֽa⁠ʻarĕqi֖y wĕ⁠ʼeţ-ha⁠si̇yniֽy׃"],[1,16,"וְ⁠אֶת־הָ⁠אַרְוָדִ֥י וְ⁠אֶת־הַ⁠צְּמָרִ֖י וְ⁠אֶת־הַֽ⁠חֲמָתִֽי׃ס","wĕ⁠ʼeţ-há⁠ʼarĕwádi֥y wĕ⁠ʼeţ-ha⁠ẕĕ̇mári֖y wĕ⁠ʼeţ-hֽa⁠ẖàmáţiֽy׃s"],[1,17,"בְּנֵ֣י שֵׁ֔ם עֵילָ֣ם וְ⁠אַשּׁ֔וּר וְ⁠אַרְפַּכְשַׁ֖ד וְ⁠ל֣וּד וַ⁠אֲרָ֑ם וְ⁠ע֥וּץ וְ⁠ח֖וּל וְ⁠גֶ֥תֶר וָ⁠מֶֽשֶׁךְ׃ס","bĕ̇né֣y şé̌֔m ʻéylá֣m wĕ⁠ʼaş̇̌֔ẇr wĕ⁠ʼarĕpȧkĕşǎ֖d wĕ⁠l֣ẇd wa⁠ʼàrá֑m wĕ⁠ʻ֥ẇẕ wĕ⁠ẖ֖ẇl wĕ⁠ge֥ţer wá⁠meֽşěkĕ׃s"],[1,18,"וְ⁠אַרְפַּכְשַׁ֖ד יָלַ֣ד אֶת־שָׁ֑לַח וְ⁠שֶׁ֖לַח יָלַ֥ד אֶת־עֵֽבֶר׃","wĕ⁠ʼarĕpȧkĕşǎ֖d yála֣d ʼeţ-şá֑̌laẖ wĕ⁠şě֖laẖ yála֥d ʼeţ-ʻéֽber׃"],[1,19,"וּ⁠לְ⁠עֵ֥בֶר יֻלַּ֖ד שְׁנֵ֣י בָנִ֑ים שֵׁ֣ם הָ⁠אֶחָ֞ד פֶּ֗לֶג כִּ֤י בְ⁠יָמָי⁠ו֙ נִפְלְגָ֣ה הָ⁠אָ֔רֶץ וְ⁠שֵׁ֥ם אָחִ֖י⁠ו יָקְטָֽן׃","ẇ⁠lĕ⁠ʻé֥ber yulȧ֖d şĕ̌né֣y báni֑ym şé֣̌m há⁠ʼeẖá֞d pė֗leg ki֤̇y bĕ⁠yámáy⁠w֙ nipĕlĕgá֣h há⁠ʼá֔reẕ wĕ⁠şé֥̌m ʼáẖi֖y⁠w yáqĕtáֽn׃"],[1,20,"וְ⁠יָקְטָ֣ן יָלַ֔ד אֶת־אַלְמוֹדָ֖ד וְ⁠אֶת־שָׁ֑לֶף וְ⁠אֶת־חֲצַרְמָ֖וֶת וְ⁠אֶת־יָֽרַח׃","wĕ⁠yáqĕtá֣n yála֔d ʼeţ-ʼalĕmwòdá֖d wĕ⁠ʼeţ-şá֑̌lep wĕ⁠ʼeţ-ẖàẕarĕmá֖weţ wĕ⁠ʼeţ-yáֽraẖ׃"],[1,21,"וְ⁠אֶת־הֲדוֹרָ֥ם וְ⁠אֶת־אוּזָ֖ל וְ⁠אֶת־דִּקְלָֽה׃","wĕ⁠ʼeţ-hàdwòrá֥m wĕ⁠ʼeţ-ʼẇzá֖l wĕ⁠ʼeţ-di̇qĕláֽh׃"],[1,22,"וְ⁠אֶת־עֵיבָ֥ל וְ⁠אֶת־אֲבִימָאֵ֖ל וְ⁠אֶת־שְׁבָֽא׃","wĕ⁠ʼeţ-ʻéybá֥l wĕ⁠ʼeţ-ʼàbiymáʼé֖l wĕ⁠ʼeţ-şĕ̌báֽʼ׃"],[1,23,"וְ⁠אֶת־אוֹפִ֥יר וְ⁠אֶת־חֲוִילָ֖ה וְ⁠אֶת־יוֹבָ֑ב כָּל־אֵ֖לֶּה בְּנֵ֥י יָקְטָֽן׃ס","wĕ⁠ʼeţ-ʼwòpi֥yr wĕ⁠ʼeţ-ẖàwiylá֖h wĕ⁠ʼeţ-ywòbá֑b ká̇l-ʼé֖lėh bĕ̇né֥y yáqĕtáֽn׃s"],[1,24,"שֵׁ֥ם ׀ אַרְפַּכְשַׁ֖ד שָֽׁלַח׃","şé֥̌m ׀ ʼarĕpȧkĕşǎ֖d şáֽ̌laẖ׃"],[1,25,"עֵ֥בֶר פֶּ֖לֶג רְעֽוּ׃","ʻé֥ber pė֖leg rĕʻֽẇ׃"],[1,26,"שְׂר֥וּג נָח֖וֹר תָּֽרַח׃","şĕ̂r֥ẇg náẖ֖wòr ţáֽ̇raẖ׃"],[1,27,"אַבְרָ֖ם ה֥וּא אַבְרָהָֽם׃ס","ʼabĕrá֖m h֥ẇʼ ʼabĕráháֽm׃s"],[1,28,"בְּנֵי֙ אַבְרָהָ֔ם יִצְחָ֖ק וְ⁠יִשְׁמָעֵֽאל׃ס","bĕ̇néy֙ ʼabĕráhá֔m yiẕĕẖá֖q wĕ⁠yişĕ̌máʻéֽʼl׃s"],[1,29,"אֵ֖לֶּה תֹּלְדוֹתָ֑⁠ם בְּכ֤וֹר יִשְׁמָעֵאל֙ נְבָי֔וֹת וְ⁠קֵדָ֥ר וְ⁠אַדְבְּאֵ֖ל וּ⁠מִבְשָֽׂם׃","ʼé֖lėh ţò̇lĕdwòţá֑⁠m bĕ̇k֤wòr yişĕ̌máʻéʼl֙ nĕbáy֔wòţ wĕ⁠qédá֥r wĕ⁠ʼadĕbĕ̇ʼé֖l ẇ⁠mibĕşáֽ̂m׃"],[1,30,"מִשְׁמָ֣ע וְ⁠דוּמָ֔ה מַשָּׂ֖א חֲדַ֥ד וְ⁠תֵימָֽא׃","mişĕ̌má֣ʻ wĕ⁠dẇmá֔h maşá֖̇̂ʼ ẖàda֥d wĕ⁠ţéymáֽʼ׃"],[1,31,"יְט֥וּר נָפִ֖ישׁ וָ⁠קֵ֑דְמָה אֵ֥לֶּה הֵ֖ם בְּנֵ֥י יִשְׁמָעֵֽאל׃ס","yĕt֥ẇr nápi֖yş̌ wá⁠qé֑dĕmáh ʼé֥lėh hé֖m bĕ̇né֥y yişĕ̌máʻéֽʼl׃s"],[1,32,"וּ⁠בְנֵ֨י קְטוּרָ֜ה פִּילֶ֣גֶשׁ אַבְרָהָ֗ם יָלְדָ֞ה אֶת־זִמְרָ֧ן וְ⁠יָקְשָׁ֛ן וּ⁠מְדָ֥ן וּ⁠מִדְיָ֖ן וְ⁠יִשְׁבָּ֣ק וְ⁠שׁ֑וּחַ וּ⁠בְנֵ֥י יָקְשָׁ֖ן שְׁבָ֥א וּ⁠דְדָֽן׃ס","ẇ⁠bĕné֨y qĕtẇrá֜h pi̇yle֣geş̌ ʼabĕráhá֗m yálĕdá֞h ʼeţ-zimĕrá֧n wĕ⁠yáqĕşá֛̌n ẇ⁠mĕdá֥n ẇ⁠midĕyá֖n wĕ⁠yişĕ̌bá֣̇q wĕ⁠ş֑̌ẇẖa ẇ⁠bĕné֥y yáqĕşá֖̌n şĕ̌bá֥ʼ ẇ⁠dĕdáֽn׃s"],[1,33,"וּ⁠בְנֵ֣י מִדְיָ֗ן עֵיפָ֤ה וָ⁠עֵ֨פֶר֙ וַ⁠חֲנ֔וֹךְ וַ⁠אֲבִידָ֖ע וְ⁠אֶלְדָּעָ֑ה כָּל־אֵ֖לֶּה בְּנֵ֥י קְטוּרָֽה׃ס","ẇ⁠bĕné֣y midĕyá֗n ʻéypá֤h wá⁠ʻé֨per֙ wa⁠ẖàn֔wòkĕ wa⁠ʼàbiydá֖ʻ wĕ⁠ʼelĕdá̇ʻá֑h ká̇l-ʼé֖lėh bĕ̇né֥y qĕtẇráֽh׃s"],[1,34,"וַ⁠יּ֥וֹלֶד אַבְרָהָ֖ם אֶת־יִצְחָ֑ק ס בְּנֵ֣י יִצְחָ֔ק עֵשָׂ֖ו וְ⁠יִשְׂרָאֵֽל׃ס","wa⁠ẏ֥wòled ʼabĕráhá֖m ʼeţ-yiẕĕẖá֑q s bĕ̇né֣y yiẕĕẖá֔q ʻéşá֖̂w wĕ⁠yişĕ̂ráʼéֽl׃s"],[1,35,"בְּנֵ֖י עֵשָׂ֑ו אֱלִיפַ֛ז רְעוּאֵ֥ל וִ⁠יע֖וּשׁ וְ⁠יַעְלָ֥ם וְ⁠קֹֽרַח׃ס","bĕ̇né֖y ʻéşá֑̂w ʼèliypa֛z rĕʻẇʼé֥l wi⁠yʻ֖ẇş̌ wĕ⁠yaʻĕlá֥m wĕ⁠qòֽraẖ׃s"],[1,36,"בְּנֵ֖י אֱלִיפָ֑ז תֵּימָ֤ן וְ⁠אוֹמָר֙ צְפִ֣י וְ⁠גַעְתָּ֔ם קְנַ֖ז וְ⁠תִמְנָ֥ע וַ⁠עֲמָלֵֽק׃ס","bĕ̇né֖y ʼèliypá֑z ţé̇ymá֤n wĕ⁠ʼwòmár֙ ẕĕpi֣y wĕ⁠gaʻĕţá̇֔m qĕna֖z wĕ⁠ţimĕná֥ʻ wa⁠ʻàmáléֽq׃s"],[1,37,"בְּנֵ֖י רְעוּאֵ֑ל נַ֥חַת זֶ֖רַח שַׁמָּ֥ה וּ⁠מִזָּֽה׃ס","bĕ̇né֖y rĕʻẇʼé֑l na֥ẖaţ ze֖raẖ şǎmá֥̇h ẇ⁠mizáֽ̇h׃s"],[1,38,"וּ⁠בְנֵ֣י שֵׂעִ֔יר לוֹטָ֥ן וְ⁠שׁוֹבָ֖ל וְ⁠צִבְע֣וֹן וַֽ⁠עֲנָ֑ה וְ⁠דִישֹׁ֥ן וְ⁠אֵ֖צֶר וְ⁠דִישָֽׁן׃","ẇ⁠bĕné֣y şé̂ʻi֔yr lwòtá֥n wĕ⁠ş̌wòbá֖l wĕ⁠ẕibĕʻ֣wòn wֽa⁠ʻàná֑h wĕ⁠diyşò֥̌n wĕ⁠ʼé֖ẕer wĕ⁠diyşáֽ̌n׃"],[1,39,"וּ⁠בְנֵ֥י לוֹטָ֖ן חֹרִ֣י וְ⁠הוֹמָ֑ם וַ⁠אֲח֥וֹת לוֹטָ֖ן תִּמְנָֽע׃ס","ẇ⁠bĕné֥y lwòtá֖n ẖòri֣y wĕ⁠hwòmá֑m wa⁠ʼàẖ֥wòţ lwòtá֖n ţi̇mĕnáֽʻ׃s"],[1,40,"בְּנֵ֣י שׁוֹבָ֔ל עַלְיָ֧ן וּ⁠מָנַ֛חַת וְ⁠עֵיבָ֖ל שְׁפִ֣י וְ⁠אוֹנָ֑ם ס וּ⁠בְנֵ֥י צִבְע֖וֹן אַיָּ֥ה וַ⁠עֲנָֽה׃","bĕ̇né֣y ş̌wòbá֔l ʻalĕyá֧n ẇ⁠mána֛ẖaţ wĕ⁠ʻéybá֖l şĕ̌pi֣y wĕ⁠ʼwòná֑m s ẇ⁠bĕné֥y ẕibĕʻ֖wòn ʼayá֥̇h wa⁠ʻànáֽh׃"],[1,41,"בְּנֵ֥י עֲנָ֖ה דִּישׁ֑וֹן ס וּ⁠בְנֵ֣י דִישׁ֔וֹן חַמְרָ֥ן וְ⁠אֶשְׁבָּ֖ן וְ⁠יִתְרָ֥ן וּ⁠כְרָֽן׃ס","bĕ̇né֥y ʻàná֖h di̇yş֑̌wòn s ẇ⁠bĕné֣y diyş̌֔wòn ẖamĕrá֥n wĕ⁠ʼeşĕ̌bá֖̇n wĕ⁠yiţĕrá֥n ẇ⁠kĕráֽn׃s"],[1,42,"בְּֽנֵי־אֵ֔צֶר בִּלְהָ֥ן וְ⁠זַעֲוָ֖ן יַעֲקָ֑ן בְּנֵ֥י דִישׁ֖וֹן ע֥וּץ וַ⁠אֲרָֽן׃פ","bĕֽ̇néy-ʼé֔ẕer bi̇lĕhá֥n wĕ⁠zaʻàwá֖n yaʻàqá֑n bĕ̇né֥y diyş֖̌wòn ʻ֥ẇẕ wa⁠ʼàráֽn׃p"],[1,43,"וְ⁠אֵ֣לֶּה הַ⁠מְּלָכִ֗ים אֲשֶׁ֤ר מָלְכוּ֙ בְּ⁠אֶ֣רֶץ אֱד֔וֹם לִ⁠פְנֵ֥י מְלָךְ־מֶ֖לֶךְ לִ⁠בְנֵ֣י יִשְׂרָאֵ֑ל בֶּ֚לַע בֶּן־בְּע֔וֹר וְ⁠שֵׁ֥ם עִיר֖⁠וֹ דִּנְהָֽבָה׃","wĕ⁠ʼé֣lėh ha⁠mĕ̇láki֗ym ʼàşě֤r málĕkẇ֙ bĕ̇⁠ʼe֣reẕ ʼèd֔wòm li⁠pĕné֥y mĕlákĕ-me֖lekĕ li⁠bĕné֣y yişĕ̂ráʼé֑l bė֚laʻ bėn-bĕ̇ʻ֔wòr wĕ⁠şé֥̌m ʻiyr֖⁠wò di̇nĕháֽbáh׃"],[1,44,"וַ⁠יָּ֖מָת בָּ֑לַע וַ⁠יִּמְלֹ֣ךְ תַּחְתָּ֔י⁠ו יוֹבָ֥ב בֶּן־זֶ֖רַח מִ⁠בָּצְרָֽה׃","wa⁠yá֖̇máţ bá֑̇laʻ wa⁠yi̇mĕlò֣kĕ ţȧẖĕţá̇֔y⁠w ywòbá֥b bėn-ze֖raẖ mi⁠bá̇ẕĕráֽh׃"],[1,45,"וַ⁠יָּ֖מָת יוֹבָ֑ב וַ⁠יִּמְלֹ֣ךְ תַּחְתָּ֔י⁠ו חוּשָׁ֖ם מֵ⁠אֶ֥רֶץ הַ⁠תֵּימָנִֽי׃","wa⁠yá֖̇máţ ywòbá֑b wa⁠yi̇mĕlò֣kĕ ţȧẖĕţá̇֔y⁠w ẖẇşá֖̌m mé⁠ʼe֥reẕ ha⁠ţé̇ymániֽy׃"],[1,46,"וַ⁠יָּ֖מָת חוּשָׁ֑ם וַ⁠יִּמְלֹ֨ךְ תַּחְתָּ֜י⁠ו הֲדַ֣ד בֶּן־בְּדַ֗ד הַ⁠מַּכֶּ֤ה אֶת־מִדְיָן֙ בִּ⁠שְׂדֵ֣ה מוֹאָ֔ב וְ⁠שֵׁ֥ם עִיר֖⁠וֹ עיות׃","wa⁠yá֖̇máţ ẖẇşá֑̌m wa⁠yi̇mĕlò֨kĕ ţȧẖĕţá̇֜y⁠w hàda֣d bėn-bĕ̇da֗d ha⁠mȧkė֤h ʼeţ-midĕyán֙ bi̇⁠şĕ̂dé֣h mwòʼá֔b wĕ⁠şé֥̌m ʻiyr֖⁠wò ʻywţ׃"],[1,47,"וַ⁠יָּ֖מָת הֲדָ֑ד וַ⁠יִּמְלֹ֣ךְ תַּחְתָּ֔י⁠ו שַׂמְלָ֖ה מִ⁠מַּשְׂרֵקָֽה׃","wa⁠yá֖̇máţ hàdá֑d wa⁠yi̇mĕlò֣kĕ ţȧẖĕţá̇֔y⁠w şâmĕlá֖h mi⁠mȧşĕ̂réqáֽh׃"],[1,48,"וַ⁠יָּ֖מָת שַׂמְלָ֑ה וַ⁠יִּמְלֹ֣ךְ תַּחְתָּ֔י⁠ו שָׁא֖וּל מֵ⁠רְחֹב֥וֹת הַ⁠נָּהָֽר׃","wa⁠yá֖̇máţ şâmĕlá֑h wa⁠yi̇mĕlò֣kĕ ţȧẖĕţá̇֔y⁠w şá̌ʼ֖ẇl mé⁠rĕẖòb֥wòţ ha⁠ná̇háֽr׃"],[1,49,"וַ⁠יָּ֖מָת שָׁא֑וּל וַ⁠יִּמְלֹ֣ךְ תַּחְתָּ֔י⁠ו בַּ֥עַל חָנָ֖ן בֶּן־עַכְבּֽוֹר׃","wa⁠yá֖̇máţ şá̌ʼ֑ẇl wa⁠yi̇mĕlò֣kĕ ţȧẖĕţá̇֔y⁠w bȧ֥ʻal ẖáná֖n bėn-ʻakĕḃֽwòr׃"],[1,50,"וַ⁠יָּ֨מָת֙ בַּ֣עַל חָנָ֔ן וַ⁠יִּמְלֹ֤ךְ תַּחְתָּי⁠ו֙ הֲדַ֔ד וְ⁠שֵׁ֥ם עִיר֖⁠וֹ פָּ֑עִי וְ⁠שֵׁ֨ם אִשְׁתּ֤⁠וֹ מְהֵיטַבְאֵל֙ בַּת־מַטְרֵ֔ד בַּ֖ת מֵ֥י זָהָֽב׃","wa⁠yá̇֨máţ֙ bȧ֣ʻal ẖáná֔n wa⁠yi̇mĕlò֤kĕ ţȧẖĕţá̇y⁠w֙ hàda֔d wĕ⁠şé֥̌m ʻiyr֖⁠wò pá֑̇ʻiy wĕ⁠şé̌֨m ʼişĕ̌ţ֤̇⁠wò mĕhéytabĕʼél֙ bȧţ-matĕré֔d bȧ֖ţ mé֥y záháֽb׃"],[1,51,"וַ⁠יָּ֖מָת הֲדָ֑ד ס וַ⁠יִּהְיוּ֙ אַלּוּפֵ֣י אֱד֔וֹם אַלּ֥וּף תִּמְנָ֛ע אַלּ֥וּף עליה אַלּ֥וּף יְתֵֽת׃","wa⁠yá֖̇máţ hàdá֑d s wa⁠yi̇hĕyẇ֙ ʼal̇ẇpé֣y ʼèd֔wòm ʼal֥̇ẇp ţi̇mĕná֛ʻ ʼal֥̇ẇp ʻlyh ʼal֥̇ẇp yĕţéֽţ׃"],[1,52,"אַלּ֧וּף אָהֳלִיבָמָ֛ה אַלּ֥וּף אֵלָ֖ה אַלּ֥וּף פִּינֹֽן׃","ʼal֧̇ẇp ʼáholiybámá֛h ʼal֥̇ẇp ʼélá֖h ʼal֥̇ẇp pi̇ynòֽn׃"],[1,53,"אַלּ֥וּף קְנַ֛ז אַלּ֥וּף תֵּימָ֖ן אַלּ֣וּף מִבְצָֽר׃","ʼal֥̇ẇp qĕna֛z ʼal֥̇ẇp ţé̇ymá֖n ʼal֣̇ẇp mibĕẕáֽr׃"],[1,54,"אַלּ֥וּף מַגְדִּיאֵ֖ל אַלּ֣וּף עִירָ֑ם אֵ֖לֶּה אַלּוּפֵ֥י אֱדֽוֹם׃פ","ʼal֥̇ẇp magĕdi̇yʼé֖l ʼal֣̇ẇp ʻiyrá֑m ʼé֖lėh ʼal̇ẇpé֥y ʼèdֽwòm׃p"],[2,1,"אֵ֖לֶּה בְּנֵ֣י יִשְׂרָאֵ֑ל רְאוּבֵ֤ן שִׁמְעוֹן֙ לֵוִ֣י וִ⁠יהוּדָ֔ה יִשָׂשכָ֖ר וּ⁠זְבֻלֽוּן׃","ʼé֖lėh bĕ̇né֣y yişĕ̂ráʼé֑l rĕʼẇbé֤n şǐmĕʻwòn֙ léwi֣y wi⁠yhẇdá֔h yişá̂şká֖r ẇ⁠zĕbulֽẇn׃"],[2,2,"דָּ֚ן יוֹסֵ֣ף וּ⁠בִנְיָמִ֔ן נַפְתָּלִ֖י גָּ֥ד וְ⁠אָשֵֽׁר׃ס","dá֚̇n ywòsé֣p ẇ⁠binĕyámi֔n napĕţá̇li֖y gá֥̇d wĕ⁠ʼáşéֽ̌r׃s"],[2,3,"בְּנֵ֣י יְהוּדָ֗ה עֵ֤ר וְ⁠אוֹנָן֙ וְ⁠שֵׁלָ֔ה שְׁלוֹשָׁה֙ נ֣וֹלַד ל֔⁠וֹ מִ⁠בַּת־שׁ֖וּעַ הַֽ⁠כְּנַעֲנִ֑ית וַ⁠יְהִ֞י עֵ֣ר ׀ בְּכ֣וֹר יְהוּדָ֗ה רַ֛ע בְּ⁠עֵינֵ֥י יְהוָ֖ה וַ⁠יְמִיתֵֽ⁠הוּ׃ס","bĕ̇né֣y yĕhẇdá֗h ʻé֤r wĕ⁠ʼwònán֙ wĕ⁠şé̌lá֔h şĕ̌lwòşá̌h֙ n֣wòlad l֔⁠wò mi⁠bȧţ-ş֖̌ẇʻa haֽ⁠kĕ̇naʻàni֑yţ wa⁠yĕhi֞y ʻé֣r ׀ bĕ̇k֣wòr yĕhẇdá֗h ra֛ʻ bĕ̇⁠ʻéyné֥y yĕhwá֖h wa⁠yĕmiyţéֽ⁠hẇ׃s"],[2,4,"וְ⁠תָמָר֙ כַּלָּת֔⁠וֹ יָ֥לְדָה לּ֖⁠וֹ אֶת־פֶּ֣רֶץ וְ⁠אֶת־זָ֑רַח כָּל־בְּנֵ֥י יְהוּדָ֖ה חֲמִשָּֽׁה׃ס","wĕ⁠ţámár֙ kȧlá̇ţ֔⁠wò yá֥lĕdáh l֖̇⁠wò ʼeţ-pė֣reẕ wĕ⁠ʼeţ-zá֑raẖ ká̇l-bĕ̇né֥y yĕhẇdá֖h ẖàmişáֽ̇̌h׃s"],[2,5,"בְּנֵי־פֶ֖רֶץ חֶצְר֥וֹן וְ⁠חָמֽוּל׃ס","bĕ̇néy-pe֖reẕ ẖeẕĕr֥wòn wĕ⁠ẖámֽẇl׃s"],[2,6,"וּ⁠בְנֵ֣י זֶ֗רַח זִ֠מְרִי וְ⁠אֵיתָ֧ן וְ⁠הֵימָ֛ן וְ⁠כַלְכֹּ֥ל וָ⁠דָ֖רַע כֻּלָּ֥⁠ם חֲמִשָּֽׁה׃ס","ẇ⁠bĕné֣y ze֗raẖ zi֠mĕriy wĕ⁠ʼéyţá֧n wĕ⁠héymá֛n wĕ⁠kalĕkò֥̇l wá⁠dá֖raʻ ku̇lá֥̇⁠m ẖàmişáֽ̇̌h׃s"],[2,7,"וּ⁠בְנֵ֖י כַּרְמִ֑י עָכָר֙ עוֹכֵ֣ר יִשְׂרָאֵ֔ל אֲשֶׁ֥ר מָעַ֖ל בַּ⁠חֵֽרֶם׃ס","ẇ⁠bĕné֖y kȧrĕmi֑y ʻákár֙ ʻwòké֣r yişĕ̂ráʼé֔l ʼàşě֥r máʻa֖l bȧ⁠ẖéֽrem׃s"],[2,8,"וּ⁠בְנֵ֥י אֵיתָ֖ן עֲזַרְיָֽה׃","ẇ⁠bĕné֥y ʼéyţá֖n ʻàzarĕyáֽh׃"],[2,9,"וּ⁠בְנֵ֥י חֶצְר֖וֹן אֲשֶׁ֣ר נוֹלַד־ל֑⁠וֹ אֶת־יְרַחְמְאֵ֥ל וְ⁠אֶת־רָ֖ם וְ⁠אֶת־כְּלוּבָֽי׃","ẇ⁠bĕné֥y ẖeẕĕr֖wòn ʼàşě֣r nwòlad-l֑⁠wò ʼeţ-yĕraẖĕmĕʼé֥l wĕ⁠ʼeţ-rá֖m wĕ⁠ʼeţ-kĕ̇lẇbáֽy׃"],[2,10,"וְ⁠רָ֖ם הוֹלִ֣יד אֶת־עַמִּינָדָ֑ב וְ⁠עַמִּינָדָב֙ הוֹלִ֣יד אֶת־נַחְשׁ֔וֹן נְשִׂ֖יא בְּנֵ֥י יְהוּדָֽה׃","wĕ⁠rá֖m hwòli֣yd ʼeţ-ʻami̇ynádá֑b wĕ⁠ʻami̇ynádáb֙ hwòli֣yd ʼeţ-naẖĕş̌֔wòn nĕşî֖yʼ bĕ̇né֥y yĕhẇdáֽh׃"],[2,11,"וְ⁠נַחְשׁוֹן֙ הוֹלִ֣יד אֶת־שַׂלְמָ֔א וְ⁠שַׂלְמָ֖א הוֹלִ֥יד אֶת־בֹּֽעַז׃","wĕ⁠naẖĕş̌wòn֙ hwòli֣yd ʼeţ-şâlĕmá֔ʼ wĕ⁠şâlĕmá֖ʼ hwòli֥yd ʼeţ-bòֽ̇ʻaz׃"],[2,12,"וּ⁠בֹ֨עַז֙ הוֹלִ֣יד אֶת־עוֹבֵ֔ד וְ⁠עוֹבֵ֖ד הוֹלִ֥יד אֶת־יִשָֽׁי׃","ẇ⁠bò֨ʻaz֙ hwòli֣yd ʼeţ-ʻwòbé֔d wĕ⁠ʻwòbé֖d hwòli֥yd ʼeţ-yişáֽ̌y׃"],[2,13,"וְ⁠אִישַׁ֛י הוֹלִ֥יד אֶת־בְּכֹר֖⁠וֹ אֶת־אֱלִיאָ֑ב וַ⁠אֲבִינָדָב֙ הַ⁠שֵּׁנִ֔י וְ⁠שִׁמְעָ֖א הַ⁠שְּׁלִישִֽׁי׃","wĕ⁠ʼiyşǎ֛y hwòli֥yd ʼeţ-bĕ̇kòr֖⁠wò ʼeţ-ʼèliyʼá֑b wa⁠ʼàbiynádáb֙ ha⁠şé̇̌ni֔y wĕ⁠şǐmĕʻá֖ʼ ha⁠şĕ̇̌liyşǐֽy׃"],[2,14,"נְתַנְאֵל֙ הָֽ⁠רְבִיעִ֔י רַדַּ֖י הַ⁠חֲמִישִֽׁי׃","nĕţanĕʼél֙ háֽ⁠rĕbiyʻi֔y radȧ֖y ha⁠ẖàmiyşǐֽy׃"],[2,15,"אֹ֚צֶם הַ⁠שִּׁשִּׁ֔י דָּוִ֖יד הַ⁠שְּׁבִעִֽי׃","ʼò֚ẕem ha⁠şi̇̌şi̇̌֔y dá̇wi֖yd ha⁠şĕ̇̌biʻiֽy׃"],[2,16,"ו⁠אחיתי⁠הם צְרוּיָ֣ה וַ⁠אֲבִיגָ֑יִל וּ⁠בְנֵ֣י צְרוּיָ֗ה אַבְשַׁ֛י וְ⁠יוֹאָ֥ב וַ⁠עֲשָׂה־אֵ֖ל שְׁלֹשָֽׁה׃","w⁠ʼẖyţy⁠hm ẕĕrẇyá֣h wa⁠ʼàbiygá֑yil ẇ⁠bĕné֣y ẕĕrẇyá֗h ʼabĕşǎ֛y wĕ⁠ywòʼá֥b wa⁠ʻàşá̂h-ʼé֖l şĕ̌lòşáֽ̌h׃"],[2,17,"וַ⁠אֲבִיגַ֕יִל יָלְדָ֖ה אֶת־עֲמָשָׂ֑א וַ⁠אֲבִ֣י עֲמָשָׂ֔א יֶ֖תֶר הַ⁠יִּשְׁמְעֵאלִֽי׃","wa⁠ʼàbiyga֕yil yálĕdá֖h ʼeţ-ʻàmáşá֑̂ʼ wa⁠ʼàbi֣y ʻàmáşá̂֔ʼ ye֖ţer ha⁠yi̇şĕ̌mĕʻéʼliֽy׃"],[2,18,"וְ⁠כָלֵ֣ב בֶּן־חֶצְר֗וֹן הוֹלִ֛יד אֶת־עֲזוּבָ֥ה אִשָּׁ֖ה וְ⁠אֶת־יְרִיע֑וֹת וְ⁠אֵ֣לֶּה בָנֶ֔י⁠הָ יֵ֥שֶׁר וְ⁠שׁוֹבָ֖ב וְ⁠אַרְדּֽוֹן׃","wĕ⁠kálé֣b bėn-ẖeẕĕr֗wòn hwòli֛yd ʼeţ-ʻàzẇbá֥h ʼişá֖̇̌h wĕ⁠ʼeţ-yĕriyʻ֑wòţ wĕ⁠ʼé֣lėh báne֔y⁠há yé֥şěr wĕ⁠ş̌wòbá֖b wĕ⁠ʼarĕḋֽwòn׃"],[2,19,"וַ⁠תָּ֖מָת עֲזוּבָ֑ה וַ⁠יִּֽקַּֽח־ל֤⁠וֹ כָלֵב֙ אֶת־אֶפְרָ֔ת וַ⁠תֵּ֥לֶד ל֖⁠וֹ אֶת־חֽוּר׃","wa⁠ţá֖̇máţ ʻàzẇbá֑h wa⁠yiֽ̇qȧֽẖ-l֤⁠wò káléb֙ ʼeţ-ʼepĕrá֔ţ wa⁠ţé֥̇led l֖⁠wò ʼeţ-ẖֽẇr׃"],[2,20,"וְ⁠חוּר֙ הוֹלִ֣יד אֶת־אוּרִ֔י וְ⁠אוּרִ֖י הוֹלִ֥יד אֶת־בְּצַלְאֵֽל׃ס","wĕ⁠ẖẇr֙ hwòli֣yd ʼeţ-ʼẇri֔y wĕ⁠ʼẇri֖y hwòli֥yd ʼeţ-bĕ̇ẕalĕʼéֽl׃s"],[2,21,"וְ⁠אַחַ֗ר בָּ֤א חֶצְרוֹן֙ אֶל־בַּת־מָכִיר֙ אֲבִ֣י גִלְעָ֔ד וְ⁠ה֣וּא לְקָחָ֔⁠הּ וְ⁠ה֖וּא בֶּן־שִׁשִּׁ֣ים שָׁנָ֑ה וַ⁠תֵּ֥לֶד ל֖⁠וֹ אֶת־שְׂגֽוּב׃","wĕ⁠ʼaẖa֗r bá֤̇ʼ ẖeẕĕrwòn֙ ʼel-bȧţ-mákiyr֙ ʼàbi֣y gilĕʻá֔d wĕ⁠h֣ẇʼ lĕqáẖá֔⁠ḣ wĕ⁠h֖ẇʼ bėn-şǐşi֣̇̌ym şá̌ná֑h wa⁠ţé֥̇led l֖⁠wò ʼeţ-şĕ̂gֽẇb׃"],[2,22,"וּ⁠שְׂג֖וּב הוֹלִ֣יד אֶת־יָאִ֑יר וַֽ⁠יְהִי־ל֗⁠וֹ עֶשְׂרִ֤ים וְ⁠שָׁלוֹשׁ֙ עָרִ֔ים בְּ⁠אֶ֖רֶץ הַ⁠גִּלְעָֽד׃","ẇ⁠şĕ̂g֖ẇb hwòli֣yd ʼeţ-yáʼi֑yr waֽ⁠yĕhiy-l֗⁠wò ʻeşĕ̂ri֤ym wĕ⁠şá̌lwòş̌֙ ʻári֔ym bĕ̇⁠ʼe֖reẕ ha⁠gi̇lĕʻáֽd׃"],[2,23,"וַ⁠יִּקַּ֣ח גְּשֽׁוּר־וַ֠⁠אֲרָם אֶת־חַוֺּ֨ת יָאִ֧יר מֵ⁠אִתָּ֛⁠ם אֶת־קְנָ֥ת וְ⁠אֶת־בְּנֹתֶ֖י⁠הָ שִׁשִּׁ֣ים עִ֑יר כָּל־אֵ֕לֶּה בְּנֵ֖י מָכִ֥יר אֲבִי־גִלְעָֽד׃","wa⁠yi̇qȧ֣ẖ gĕ̇şֽ̌ẇr-wa֠⁠ʼàrám ʼeţ-ẖaẇֺ֨ţ yáʼi֧yr mé⁠ʼiţá֛̇⁠m ʼeţ-qĕná֥ţ wĕ⁠ʼeţ-bĕ̇nòţe֖y⁠há şǐşi֣̇̌ym ʻi֑yr ká̇l-ʼé֕lėh bĕ̇né֖y máki֥yr ʼàbiy-gilĕʻáֽd׃"],[2,24,"וְ⁠אַחַ֥ר מוֹת־חֶצְר֖וֹן בְּ⁠כָלֵ֣ב אֶפְרָ֑תָה וְ⁠אֵ֤שֶׁת חֶצְרוֹן֙ אֲבִיָּ֔ה וַ⁠תֵּ֣לֶד ל֔⁠וֹ אֶת־אַשְׁח֖וּר אֲבִ֥י תְקֽוֹעַ׃","wĕ⁠ʼaẖa֥r mwòţ-ẖeẕĕr֖wòn bĕ̇⁠kálé֣b ʼepĕrá֑ţáh wĕ⁠ʼé֤şěţ ẖeẕĕrwòn֙ ʼàbiyá̇֔h wa⁠ţé֣̇led l֔⁠wò ʼeţ-ʼaşĕ̌ẖ֖ẇr ʼàbi֥y ţĕqֽwòʻa׃"],[2,25,"וַ⁠יִּהְי֧וּ בְנֵי־יְרַחְמְאֵ֛ל בְּכ֥וֹר חֶצְר֖וֹן הַ⁠בְּכ֣וֹר ׀ רָ֑ם וּ⁠בוּנָ֥ה וָ⁠אֹ֛רֶן וָ⁠אֹ֖צֶם אֲחִיָּֽה׃","wa⁠yi̇hĕy֧ẇ bĕnéy-yĕraẖĕmĕʼé֛l bĕ̇k֥wòr ẖeẕĕr֖wòn ha⁠bĕ̇k֣wòr ׀ rá֑m ẇ⁠bẇná֥h wá⁠ʼò֛ren wá⁠ʼò֖ẕem ʼàẖiyáֽ̇h׃"],[2,26,"וַ⁠תְּהִ֨י אִשָּׁ֥ה אַחֶ֛רֶת לִֽ⁠ירַחְמְאֵ֖ל וּ⁠שְׁמָ֣⁠הּ עֲטָרָ֑ה הִ֖יא אֵ֥ם אוֹנָֽם׃ס","wa⁠ţĕ̇hi֨y ʼişá֥̇̌h ʼaẖe֛reţ liֽ⁠yraẖĕmĕʼé֖l ẇ⁠şĕ̌má֣⁠ḣ ʻàtárá֑h hi֖yʼ ʼé֥m ʼwònáֽm׃s"],[2,27,"וַ⁠יִּהְי֥וּ בְנֵי־רָ֖ם בְּכ֣וֹר יְרַחְמְאֵ֑ל מַ֥עַץ וְ⁠יָמִ֖ין וָ⁠עֵֽקֶר׃","wa⁠yi̇hĕy֥ẇ bĕnéy-rá֖m bĕ̇k֣wòr yĕraẖĕmĕʼé֑l ma֥ʻaẕ wĕ⁠yámi֖yn wá⁠ʻéֽqer׃"],[2,28,"וַ⁠יִּהְי֥וּ בְנֵי־אוֹנָ֖ם שַׁמַּ֣י וְ⁠יָדָ֑ע וּ⁠בְנֵ֣י שַׁמַּ֔י נָדָ֖ב וַ⁠אֲבִישֽׁוּר׃","wa⁠yi̇hĕy֥ẇ bĕnéy-ʼwòná֖m şǎmȧ֣y wĕ⁠yádá֑ʻ ẇ⁠bĕné֣y şǎmȧ֔y nádá֖b wa⁠ʼàbiyşֽ̌ẇr׃"],[2,29,"וְ⁠שֵׁ֛ם אֵ֥שֶׁת אֲבִישׁ֖וּר אֲבִיהָ֑יִל וַ⁠תֵּ֣לֶד ל֔⁠וֹ אֶת־אַחְבָּ֖ן וְ⁠אֶת־מוֹלִֽיד׃","wĕ⁠şé֛̌m ʼé֥şěţ ʼàbiyş֖̌ẇr ʼàbiyhá֑yil wa⁠ţé֣̇led l֔⁠wò ʼeţ-ʼaẖĕbá֖̇n wĕ⁠ʼeţ-mwòliֽyd׃"],[2,30,"וּ⁠בְנֵ֥י נָדָ֖ב סֶ֣לֶד וְ⁠אַפָּ֑יִם וַ⁠יָּ֥מָת סֶ֖לֶד לֹ֥א בָנִֽים׃ס","ẇ⁠bĕné֥y nádá֖b se֣led wĕ⁠ʼapá֑̇yim wa⁠yá֥̇máţ se֖led lò֥ʼ bániֽym׃s"],[2,31,"וּ⁠בְנֵ֥י אַפַּ֖יִם יִשְׁעִ֑י וּ⁠בְנֵ֤י יִשְׁעִי֙ שֵׁשָׁ֔ן וּ⁠בְנֵ֥י שֵׁשָׁ֖ן אַחְלָֽי׃","ẇ⁠bĕné֥y ʼapȧ֖yim yişĕ̌ʻi֑y ẇ⁠bĕné֤y yişĕ̌ʻiy֙ şé̌şá̌֔n ẇ⁠bĕné֥y şé̌şá֖̌n ʼaẖĕláֽy׃"],[2,32,"וּ⁠בְנֵ֤י יָדָע֙ אֲחִ֣י שַׁמַּ֔י יֶ֖תֶר וְ⁠יוֹנָתָ֑ן וַ⁠יָּ֥מָת יֶ֖תֶר לֹ֥א בָנִֽים׃ס","ẇ⁠bĕné֤y yádáʻ֙ ʼàẖi֣y şǎmȧ֔y ye֖ţer wĕ⁠ywònáţá֑n wa⁠yá֥̇máţ ye֖ţer lò֥ʼ bániֽym׃s"],[2,33,"וּ⁠בְנֵ֥י יוֹנָתָ֖ן פֶּ֣לֶת וְ⁠זָזָ֑א אֵ֥לֶּה הָי֖וּ בְּנֵ֥י יְרַחְמְאֵֽל׃","ẇ⁠bĕné֥y ywònáţá֖n pė֣leţ wĕ⁠zázá֑ʼ ʼé֥lėh háy֖ẇ bĕ̇né֥y yĕraẖĕmĕʼéֽl׃"],[2,34,"וְ⁠לֹֽא־הָיָ֧ה לְ⁠שֵׁשָׁ֛ן בָּנִ֖ים כִּ֣י אִם־בָּנ֑וֹת וּ⁠לְ⁠שֵׁשָׁ֛ן עֶ֥בֶד מִצְרִ֖י וּ⁠שְׁמ֥⁠וֹ יַרְחָֽע׃","wĕ⁠lòֽʼ-háyá֧h lĕ⁠şé̌şá֛̌n bá̇ni֖ym ki֣̇y ʼim-bá̇n֑wòţ ẇ⁠lĕ⁠şé̌şá֛̌n ʻe֥bed miẕĕri֖y ẇ⁠şĕ̌m֥⁠wò yarĕẖáֽʻ׃"],[2,35,"וַ⁠יִּתֵּ֨ן שֵׁשָׁ֧ן אֶת־בִּתּ֛⁠וֹ לְ⁠יַרְחָ֥ע עַבְדּ֖⁠וֹ לְ⁠אִשָּׁ֑ה וַ⁠תֵּ֥לֶד ל֖⁠וֹ אֶת־עַתָּֽי׃","wa⁠yi̇ţé̇֨n şé̌şá֧̌n ʼeţ-bi̇ţ֛̇⁠wò lĕ⁠yarĕẖá֥ʻ ʻabĕḋ֖⁠wò lĕ⁠ʼişá֑̇̌h wa⁠ţé֥̇led l֖⁠wò ʼeţ-ʻaţáֽ̇y׃"],[2,36,"וְ⁠עַתַּי֙ הֹלִ֣יד אֶת־נָתָ֔ן וְ⁠נָתָ֖ן הוֹלִ֥יד אֶת־זָבָֽד׃","wĕ⁠ʻaţȧy֙ hòli֣yd ʼeţ-náţá֔n wĕ⁠náţá֖n hwòli֥yd ʼeţ-zábáֽd׃"],[2,37,"וְ⁠זָבָד֙ הוֹלִ֣יד אֶת־אֶפְלָ֔ל וְ⁠אֶפְלָ֖ל הוֹלִ֥יד אֶת־עוֹבֵֽד׃","wĕ⁠zábád֙ hwòli֣yd ʼeţ-ʼepĕlá֔l wĕ⁠ʼepĕlá֖l hwòli֥yd ʼeţ-ʻwòbéֽd׃"],[2,38,"וְ⁠עוֹבֵד֙ הוֹלִ֣יד אֶת־יֵה֔וּא וְ⁠יֵה֖וּא הוֹלִ֥יד אֶת־עֲזַרְיָֽה׃","wĕ⁠ʻwòbéd֙ hwòli֣yd ʼeţ-yéh֔ẇʼ wĕ⁠yéh֖ẇʼ hwòli֥yd ʼeţ-ʻàzarĕyáֽh׃"],[2,39,"וַ⁠עֲזַרְיָה֙ הֹלִ֣יד אֶת־חָ֔לֶץ וְ⁠חֶ֖לֶץ הֹלִ֥יד אֶת־אֶלְעָשָֽׂה׃","wa⁠ʻàzarĕyáh֙ hòli֣yd ʼeţ-ẖá֔leẕ wĕ⁠ẖe֖leẕ hòli֥yd ʼeţ-ʼelĕʻáşáֽ̂h׃"],[2,40,"וְ⁠אֶלְעָשָׂה֙ הֹלִ֣יד אֶת־סִֽסְמָ֔י וְ⁠סִסְמַ֖י הֹלִ֥יד אֶת־שַׁלּֽוּם׃","wĕ⁠ʼelĕʻáşá̂h֙ hòli֣yd ʼeţ-siֽsĕmá֔y wĕ⁠sisĕma֖y hòli֥yd ʼeţ-şǎlֽ̇ẇm׃"],[2,41,"וְ⁠שַׁלּוּם֙ הוֹלִ֣יד אֶת־יְקַמְיָ֔ה וִֽ⁠יקַמְיָ֖ה הֹלִ֥יד אֶת־אֱלִישָׁמָֽע׃","wĕ⁠şǎl̇ẇm֙ hwòli֣yd ʼeţ-yĕqamĕyá֔h wiֽ⁠yqamĕyá֖h hòli֥yd ʼeţ-ʼèliyşá̌máֽʻ׃"],[2,42,"וּ⁠בְנֵ֤י כָלֵב֙ אֲחִ֣י יְרַחְמְאֵ֔ל מֵישָׁ֥ע בְּכֹר֖⁠וֹ ה֣וּא אֲבִי־זִ֑יף וּ⁠בְנֵ֥י מָרֵשָׁ֖ה אֲבִ֥י חֶבְרֽוֹן׃","ẇ⁠bĕné֤y káléb֙ ʼàẖi֣y yĕraẖĕmĕʼé֔l méyşá֥̌ʻ bĕ̇kòr֖⁠wò h֣ẇʼ ʼàbiy-zi֑yp ẇ⁠bĕné֥y máréşá֖̌h ʼàbi֥y ẖebĕrֽwòn׃"],[2,43,"וּ⁠בְנֵ֖י חֶבְר֑וֹן קֹ֥רַח וְ⁠תַפֻּ֖חַ וְ⁠רֶ֥קֶם וָ⁠שָֽׁמַע׃","ẇ⁠bĕné֖y ẖebĕr֑wòn qò֥raẖ wĕ⁠ţapu֖̇ẖa wĕ⁠re֥qem wá⁠şáֽ̌maʻ׃"],[2,44,"וְ⁠שֶׁ֣מַע הוֹלִ֔יד אֶת־רַ֖חַם אֲבִ֣י יָרְקֳעָ֑ם וְ⁠רֶ֖קֶם הוֹלִ֥יד אֶת־שַׁמָּֽי׃","wĕ⁠şě֣maʻ hwòli֔yd ʼeţ-ra֖ẖam ʼàbi֣y yárĕqoʻá֑m wĕ⁠re֖qem hwòli֥yd ʼeţ-şǎmáֽ̇y׃"],[2,45,"וּ⁠בֶן־שַׁמַּ֖י מָע֑וֹן וּ⁠מָע֖וֹן אֲבִ֥י בֵֽית־צֽוּר׃","ẇ⁠ben-şǎmȧ֖y máʻ֑wòn ẇ⁠máʻ֖wòn ʼàbi֥y béֽyţ-ẕֽẇr׃"],[2,46,"וְ⁠עֵיפָה֙ פִּילֶ֣גֶשׁ כָּלֵ֔ב יָֽלְדָ֛ה אֶת־חָרָ֥ן וְ⁠אֶת־מוֹצָ֖א וְ⁠אֶת־גָּזֵ֑ז וְ⁠חָרָ֖ן הֹלִ֥יד אֶת־גָּזֵֽז׃ס","wĕ⁠ʻéypáh֙ pi̇yle֣geş̌ ká̇lé֔b yáֽlĕdá֛h ʼeţ-ẖárá֥n wĕ⁠ʼeţ-mwòẕá֖ʼ wĕ⁠ʼeţ-gá̇zé֑z wĕ⁠ẖárá֖n hòli֥yd ʼeţ-gá̇zéֽz׃s"],[2,47,"וּ⁠בְנֵ֖י יָהְדָּ֑י רֶ֧גֶם וְ⁠יוֹתָ֛ם וְ⁠גֵישָׁ֥ן וָ⁠פֶ֖לֶט וְ⁠עֵיפָ֥ה וָ⁠שָֽׁעַף׃","ẇ⁠bĕné֖y yáhĕdá֑̇y re֧gem wĕ⁠ywòţá֛m wĕ⁠géyşá֥̌n wá⁠pe֖let wĕ⁠ʻéypá֥h wá⁠şáֽ̌ʻap׃"],[2,48,"פִּלֶ֤גֶשׁ כָּלֵב֙ מַעֲכָ֔ה יָ֥לַד שֶׁ֖בֶר וְ⁠אֶֽת־תִּרְחֲנָֽה׃","pi̇le֤geş̌ ká̇léb֙ maʻàká֔h yá֥lad şě֖ber wĕ⁠ʼeֽţ-ţi̇rĕẖànáֽh׃"],[2,49,"וַ⁠תֵּ֗לֶד שַׁ֚עַף אֲבִ֣י מַדְמַנָּ֔ה אֶת־שְׁוָ֛א אֲבִ֥י מַכְבֵּנָ֖ה וַ⁠אֲבִ֣י גִבְעָ֑א וּ⁠בַת־כָּלֵ֖ב עַכְסָֽה׃ס","wa⁠ţé̇֗led şǎ֚ʻap ʼàbi֣y madĕmaná̇֔h ʼeţ-şĕ̌wá֛ʼ ʼàbi֥y makĕbé̇ná֖h wa⁠ʼàbi֣y gibĕʻá֑ʼ ẇ⁠baţ-ká̇lé֖b ʻakĕsáֽh׃s"],[2,50,"אֵ֤לֶּה הָיוּ֙ בְּנֵ֣י כָלֵ֔ב בֶּן־ח֖וּר בְּכ֣וֹר אֶפְרָ֑תָה שׁוֹבָ֕ל אֲבִ֖י קִרְיַ֥ת יְעָרִֽים׃","ʼé֤lėh háyẇ֙ bĕ̇né֣y kálé֔b bėn-ẖ֖ẇr bĕ̇k֣wòr ʼepĕrá֑ţáh ş̌wòbá֕l ʼàbi֖y qirĕya֥ţ yĕʻáriֽym׃"],[2,51,"שַׂלְמָא֙ אֲבִ֣י בֵֽית־לָ֔חֶם חָרֵ֖ף אֲבִ֥י בֵית־גָּדֵֽר׃","şâlĕmáʼ֙ ʼàbi֣y béֽyţ-lá֔ẖem ẖáré֖p ʼàbi֥y béyţ-gá̇déֽr׃"],[2,52,"וַ⁠יִּהְי֤וּ בָנִים֙ לְ⁠שׁוֹבָ֔ל אֲבִ֖י קִרְיַ֣ת יְעָרִ֑ים הָרֹאֶ֖ה חֲצִ֥י הַ⁠מְּנֻחֽוֹת׃","wa⁠yi̇hĕy֤ẇ bániym֙ lĕ⁠ş̌wòbá֔l ʼàbi֖y qirĕya֣ţ yĕʻári֑ym háròʼe֖h ẖàẕi֥y ha⁠mĕ̇nuẖֽwòţ׃"],[2,53,"וּ⁠מִשְׁפְּחוֹת֙ קִרְיַ֣ת יְעָרִ֔ים הַ⁠יִּתְרִי֙ וְ⁠הַ⁠פּוּתִ֔י וְ⁠הַ⁠שֻּׁמָתִ֖י וְ⁠הַ⁠מִּשְׁרָעִ֑י מֵ⁠אֵ֗לֶּה יָצְאוּ֙ הַ⁠צָּ֣רְעָתִ֔י וְ⁠הָ⁠אֶשְׁתָּ֖אֻֽלִֽי׃ס","ẇ⁠mişĕ̌pĕ̇ẖwòţ֙ qirĕya֣ţ yĕʻári֔ym ha⁠yi̇ţĕriy֙ wĕ⁠ha⁠ṗẇţi֔y wĕ⁠ha⁠şu̇̌máţi֖y wĕ⁠ha⁠mi̇şĕ̌ráʻi֑y mé⁠ʼé֗lėh yáẕĕʼẇ֙ ha⁠ẕá֣̇rĕʻáţi֔y wĕ⁠há⁠ʼeşĕ̌ţá֖̇ʼuֽliֽy׃s"],[2,54,"בְּנֵ֣י שַׂלְמָ֗א בֵּ֥ית לֶ֨חֶם֙ וּ⁠נְט֣וֹפָתִ֔י עַטְר֖וֹת בֵּ֣ית יוֹאָ֑ב וַ⁠חֲצִ֥י הַ⁠מָּנַחְתִּ֖י הַ⁠צָּרְעִֽי׃","bĕ̇né֣y şâlĕmá֗ʼ bé֥̇yţ le֨ẖem֙ ẇ⁠nĕt֣wòpáţi֔y ʻatĕr֖wòţ bé֣̇yţ ywòʼá֑b wa⁠ẖàẕi֥y ha⁠má̇naẖĕţi֖̇y ha⁠ẕá̇rĕʻiֽy׃"],[2,55,"וּ⁠מִשְׁפְּח֤וֹת סֹפְרִים֙ ישבו יַעְבֵּ֔ץ תִּרְעָתִ֥ים שִׁמְעָתִ֖ים שׂוּכָתִ֑ים הֵ֚מָּה הַ⁠קִּינִ֣ים הַ⁠בָּאִ֔ים מֵ⁠חַמַּ֖ת אֲבִ֥י בֵית־רֵכָֽב׃ס","ẇ⁠mişĕ̌pĕ̇ẖ֤wòţ sòpĕriym֙ yşbw yaʻĕbé̇֔ẕ ţi̇rĕʻáţi֥ym şǐmĕʻáţi֖ym ş̂ẇkáţi֑ym hé֚má̇h ha⁠qi̇yni֣ym ha⁠bá̇ʼi֔ym mé⁠ẖamȧ֖ţ ʼàbi֥y béyţ-rékáֽb׃s"],[3,1,"וְ⁠אֵ֤לֶּה הָיוּ֙ בְּנֵ֣י דָויִ֔ד אֲשֶׁ֥ר נֽוֹלַד־ל֖⁠וֹ בְּ⁠חֶבְר֑וֹן הַ⁠בְּכ֣וֹר ׀ אַמְנֹ֗ן לַ⁠אֲחִינֹ֨עַם֙ הַ⁠יִּזְרְעֵאלִ֔ית שֵׁנִי֙ דָּנִיֵּ֔אל לַ⁠אֲבִיגַ֖יִל הַֽ⁠כַּרְמְלִֽית׃","wĕ⁠ʼé֤lėh háyẇ֙ bĕ̇né֣y dáwyi֔d ʼàşě֥r nֽwòlad-l֖⁠wò bĕ̇⁠ẖebĕr֑wòn ha⁠bĕ̇k֣wòr ׀ ʼamĕnò֗n la⁠ʼàẖiynò֨ʻam֙ ha⁠yi̇zĕrĕʻéʼli֔yţ şé̌niy֙ dá̇niyé̇֔ʼl la⁠ʼàbiyga֖yil haֽ⁠kȧrĕmĕliֽyţ׃"],[3,2,"הַ⁠שְּׁלִשִׁי֙ לְ⁠אַבְשָׁל֣וֹם בֶּֽן־מַעֲכָ֔ה בַּת־תַּלְמַ֖י מֶ֣לֶךְ גְּשׁ֑וּר הָ⁠רְבִיעִ֖י אֲדֹנִיָּ֥ה בֶן־חַגִּֽית׃","ha⁠şĕ̇̌lişǐy֙ lĕ⁠ʼabĕşá̌l֣wòm bėֽn-maʻàká֔h bȧţ-ţȧlĕma֖y me֣lekĕ gĕ̇ş֑̌ẇr há⁠rĕbiyʻi֖y ʼàdòniyá֥̇h ben-ẖagiֽ̇yţ׃"],[3,3,"הַ⁠חֲמִישִׁ֥י שְׁפַטְיָ֖ה לַ⁠אֲבִיטָ֑ל הַ⁠שִּׁשִּׁ֥י יִתְרְעָ֖ם לְ⁠עֶגְלָ֥ה אִשְׁתּֽ⁠וֹ׃","ha⁠ẖàmiyşǐ֥y şĕ̌patĕyá֖h la⁠ʼàbiytá֑l ha⁠şi̇̌şi֥̇̌y yiţĕrĕʻá֖m lĕ⁠ʻegĕlá֥h ʼişĕ̌ţֽ̇⁠wò׃"],[3,4,"שִׁשָּׁה֙ נֽוֹלַד־ל֣⁠וֹ בְ⁠חֶבְר֔וֹן וַ⁠יִּ֨מְלָךְ־שָׁ֔ם שֶׁ֥בַע שָׁנִ֖ים וְ⁠שִׁשָּׁ֣ה חֳדָשִׁ֑ים וּ⁠שְׁלֹשִׁ֤ים וְ⁠שָׁלוֹשׁ֙ שָׁנָ֔ה מָלַ֖ךְ בִּ⁠ירוּשָׁלִָֽם׃ס","şǐşá̇̌h֙ nֽwòlad-l֣⁠wò bĕ⁠ẖebĕr֔wòn wa⁠yi̇֨mĕlákĕ-şá̌֔m şě֥baʻ şá̌ni֖ym wĕ⁠şǐşá֣̇̌h ẖodáşǐ֑ym ẇ⁠şĕ̌lòşǐ֤ym wĕ⁠şá̌lwòş̌֙ şá̌ná֔h mála֖kĕ bi̇⁠yrẇşá̌liáֽm׃s"],[3,5,"וְ⁠אֵ֥לֶּה נוּלְּדוּ־ל֖⁠וֹ בִּ⁠ירוּשָׁלָ֑יִם שִׁ֠מְעָא וְ⁠שׁוֹבָ֞ב וְ⁠נָתָ֤ן וּ⁠שְׁלֹמֹה֙ אַרְבָּעָ֔ה לְ⁠בַת־שׁ֖וּעַ בַּת־עַמִּיאֵֽל׃","wĕ⁠ʼé֥lėh nẇlĕ̇dẇ-l֖⁠wò bi̇⁠yrẇşá̌lá֑yim şǐ֠mĕʻáʼ wĕ⁠ş̌wòbá֞b wĕ⁠náţá֤n ẇ⁠şĕ̌lòmòh֙ ʼarĕbá̇ʻá֔h lĕ⁠baţ-ş֖̌ẇʻa bȧţ-ʻami̇yʼéֽl׃"],[3,6,"וְ⁠יִבְחָ֥ר וֶ⁠אֱלִישָׁמָ֖ע וֶ⁠אֱלִיפָֽלֶט׃","wĕ⁠yibĕẖá֥r we⁠ʼèliyşá̌má֖ʻ we⁠ʼèliypáֽlet׃"],[3,7,"וְ⁠נֹ֥גַהּ וְ⁠נֶ֖פֶג וְ⁠יָפִֽיעַ׃","wĕ⁠nò֥gaḣ wĕ⁠ne֖peg wĕ⁠yápiֽyʻa׃"],[3,8,"וֶ⁠אֱלִישָׁמָ֧ע וְ⁠אֶלְיָדָ֛ע וֶ⁠אֱלִיפֶ֖לֶט תִּשְׁעָֽה׃","we⁠ʼèliyşá̌má֧ʻ wĕ⁠ʼelĕyádá֛ʻ we⁠ʼèliype֖let ţi̇şĕ̌ʻáֽh׃"],[3,9,"כֹּ֖ל בְּנֵ֣י דָוִ֑יד מִ⁠לְּ⁠בַ֥ד בְּֽנֵי־פִֽילַגְשִׁ֖ים וְ⁠תָמָ֥ר אֲחוֹתָֽ⁠ם׃פ","kò֖̇l bĕ̇né֣y dáwi֑yd mi⁠lĕ̇⁠ba֥d bĕֽ̇néy-piֽylagĕşǐ֖ym wĕ⁠ţámá֥r ʼàẖwòţáֽ⁠m׃p"],[3,10,"וּ⁠בֶן־שְׁלֹמֹ֖ה רְחַבְעָ֑ם אֲבִיָּ֥ה בְנ֛⁠וֹ אָסָ֥א בְנ֖⁠וֹ יְהוֹשָׁפָ֥ט בְּנֽ⁠וֹ׃","ẇ⁠ben-şĕ̌lòmò֖h rĕẖabĕʻá֑m ʼàbiyá֥̇h bĕn֛⁠wò ʼásá֥ʼ bĕn֖⁠wò yĕhwòşá̌pá֥t bĕ̇nֽ⁠wò׃"],[3,11,"יוֹרָ֥ם בְּנ֛⁠וֹ אֲחַזְיָ֥הוּ בְנ֖⁠וֹ יוֹאָ֥שׁ בְּנֽ⁠וֹ׃","ywòrá֥m bĕ̇n֛⁠wò ʼàẖazĕyá֥hẇ bĕn֖⁠wò ywòʼá֥ş̌ bĕ̇nֽ⁠wò׃"],[3,12,"אֲמַצְיָ֧הוּ בְנ֛⁠וֹ עֲזַרְיָ֥ה בְנ֖⁠וֹ יוֹתָ֥ם בְּנֽ⁠וֹ׃","ʼàmaẕĕyá֧hẇ bĕn֛⁠wò ʻàzarĕyá֥h bĕn֖⁠wò ywòţá֥m bĕ̇nֽ⁠wò׃"],[3,13,"אָחָ֥ז בְּנ֛⁠וֹ חִזְקִיָּ֥הוּ בְנ֖⁠וֹ מְנַשֶּׁ֥ה בְנֽ⁠וֹ׃","ʼáẖá֥z bĕ̇n֛⁠wò ẖizĕqiyá֥̇hẇ bĕn֖⁠wò mĕnaşė֥̌h bĕnֽ⁠wò׃"],[3,14,"אָמ֥וֹן בְּנ֖⁠וֹ יֹאשִׁיָּ֥הוּ בְנֽ⁠וֹ׃","ʼám֥wòn bĕ̇n֖⁠wò yòʼşǐyá֥̇hẇ bĕnֽ⁠wò׃"],[3,15,"וּ⁠בְנֵי֙ יֹאשִׁיָּ֔הוּ הַ⁠בְּכוֹר֙ יוֹחָנָ֔ן הַ⁠שֵּׁנִ֖י יְהוֹיָקִ֑ים הַ⁠שְּׁלִשִׁי֙ צִדְקִיָּ֔הוּ הָ⁠רְבִיעִ֖י שַׁלּֽוּם׃","ẇ⁠bĕnéy֙ yòʼşǐyá̇֔hẇ ha⁠bĕ̇kwòr֙ ywòẖáná֔n ha⁠şé̇̌ni֖y yĕhwòyáqi֑ym ha⁠şĕ̇̌lişǐy֙ ẕidĕqiyá̇֔hẇ há⁠rĕbiyʻi֖y şǎlֽ̇ẇm׃"],[3,16,"וּ⁠בְנֵ֖י יְהוֹיָקִ֑ים יְכָנְיָ֥ה בְנ֖⁠וֹ צִדְקִיָּ֥ה בְנֽ⁠וֹ׃","ẇ⁠bĕné֖y yĕhwòyáqi֑ym yĕkánĕyá֥h bĕn֖⁠wò ẕidĕqiyá֥̇h bĕnֽ⁠wò׃"],[3,17,"וּ⁠בְנֵי֙ יְכָנְיָ֣ה אַסִּ֔ר שְׁאַלְתִּיאֵ֖ל בְּנֽ⁠וֹ׃","ẇ⁠bĕnéy֙ yĕkánĕyá֣h ʼasi̇֔r şĕ̌ʼalĕţi̇yʼé֖l bĕ̇nֽ⁠wò׃"],[3,18,"וּ⁠מַלְכִּירָ֥ם וּ⁠פְדָיָ֖ה וְ⁠שֶׁנְאַצַּ֑ר יְקַמְיָ֥ה הוֹשָׁמָ֖ע וּ⁠נְדַבְיָֽה׃","ẇ⁠malĕki̇yrá֥m ẇ⁠pĕdáyá֖h wĕ⁠şěnĕʼaẕȧ֑r yĕqamĕyá֥h hwòşá̌má֖ʻ ẇ⁠nĕdabĕyáֽh׃"],[3,19,"וּ⁠בְנֵ֣י פְדָיָ֔ה זְרֻבָּבֶ֖ל וְ⁠שִׁמְעִ֑י וּ⁠בֶן־זְרֻבָּבֶל֙ מְשֻׁלָּ֣ם וַ⁠חֲנַנְיָ֔ה וּ⁠שְׁלֹמִ֖ית אֲחוֹתָֽ⁠ם׃","ẇ⁠bĕné֣y pĕdáyá֔h zĕrubá̇be֖l wĕ⁠şǐmĕʻi֑y ẇ⁠ben-zĕrubá̇bel֙ mĕşǔlá֣̇m wa⁠ẖànanĕyá֔h ẇ⁠şĕ̌lòmi֖yţ ʼàẖwòţáֽ⁠m׃"],[3,20,"וַ⁠חֲשֻׁבָ֡ה וָ֠⁠אֹהֶל וּ⁠בֶרֶכְיָ֧ה וַֽ⁠חֲסַדְיָ֛ה י֥וּשַׁב חֶ֖סֶד חָמֵֽשׁ׃","wa⁠ẖàşǔbá֡h wá֠⁠ʼòhel ẇ⁠berekĕyá֧h wֽa⁠ẖàsadĕyá֛h y֥ẇşǎb ẖe֖sed ẖáméֽş̌׃"],[3,21,"וּ⁠בֶן־חֲנַנְיָ֖ה פְּלַטְיָ֣ה וִ⁠ישַֽׁעְיָ֑ה בְּנֵ֤י רְפָיָה֙ בְּנֵ֣י אַרְנָ֔ן בְּנֵ֥י עֹבַדְיָ֖ה בְּנֵ֥י שְׁכַנְיָֽה׃ס","ẇ⁠ben-ẖànanĕyá֖h pĕ̇latĕyá֣h wi⁠yşǎֽʻĕyá֑h bĕ̇né֤y rĕpáyáh֙ bĕ̇né֣y ʼarĕná֔n bĕ̇né֥y ʻòbadĕyá֖h bĕ̇né֥y şĕ̌kanĕyáֽh׃s"],[3,22,"וּ⁠בְנֵ֥י שְׁכַנְיָ֖ה שְׁמַעְיָ֑ה וּ⁠בְנֵ֣י שְׁמַעְיָ֗ה חַטּ֡וּשׁ וְ֠⁠יִגְאָל וּ⁠בָרִ֧יחַ וּ⁠נְעַרְיָ֛ה וְ⁠שָׁפָ֖ט שִׁשָּֽׁה׃","ẇ⁠bĕné֥y şĕ̌kanĕyá֖h şĕ̌maʻĕyá֑h ẇ⁠bĕné֣y şĕ̌maʻĕyá֗h ẖaṫ֡ẇş̌ wĕ֠⁠yigĕʼál ẇ⁠bári֧yẖa ẇ⁠nĕʻarĕyá֛h wĕ⁠şá̌pá֖t şǐşáֽ̇̌h׃"],[3,23,"וּ⁠בֶן־נְעַרְיָ֗ה אֶלְיוֹעֵינַ֧י וְ⁠חִזְקִיָּ֛ה וְ⁠עַזְרִיקָ֖ם שְׁלֹשָֽׁה׃","ẇ⁠ben-nĕʻarĕyá֗h ʼelĕywòʻéyna֧y wĕ⁠ẖizĕqiyá֛̇h wĕ⁠ʻazĕriyqá֖m şĕ̌lòşáֽ̌h׃"],[3,24,"וּ⁠בְנֵ֣י אֶלְיוֹעֵינַ֗י הדיוהו וְ⁠אֶלְיָשִׁ֡יב וּ⁠פְלָיָ֡ה וְ֠⁠עַקּוּב וְ⁠יוֹחָנָ֧ן וּ⁠דְלָיָ֛ה וַ⁠עֲנָ֖נִי שִׁבְעָֽה׃ס","ẇ⁠bĕné֣y ʼelĕywòʻéyna֗y hdywhw wĕ⁠ʼelĕyáşǐ֡yb ẇ⁠pĕláyá֡h wĕ֠⁠ʻaq̇ẇb wĕ⁠ywòẖáná֧n ẇ⁠dĕláyá֛h wa⁠ʻàná֖niy şǐbĕʻáֽh׃s"],[4,1,"בְּנֵ֖י יְהוּדָ֑ה פֶּ֧רֶץ חֶצְר֛וֹן וְ⁠כַרְמִ֖י וְ⁠ח֥וּר וְ⁠שׁוֹבָֽל׃","bĕ̇né֖y yĕhẇdá֑h pė֧reẕ ẖeẕĕr֛wòn wĕ⁠karĕmi֖y wĕ⁠ẖ֥ẇr wĕ⁠ş̌wòbáֽl׃"],[4,2,"וּ⁠רְאָיָ֤ה בֶן־שׁוֹבָל֙ הוֹלִ֣יד אֶת־יַ֔חַת וְ⁠יַ֣חַת הֹלִ֔יד אֶת־אֲחוּמַ֖י וְ⁠אֶת־לָ֑הַד אֵ֖לֶּה מִשְׁפְּח֥וֹת הַ⁠צָּֽרְעָתִֽי׃ס","ẇ⁠rĕʼáyá֤h ben-ş̌wòbál֙ hwòli֣yd ʼeţ-ya֔ẖaţ wĕ⁠ya֣ẖaţ hòli֔yd ʼeţ-ʼàẖẇma֖y wĕ⁠ʼeţ-lá֑had ʼé֖lėh mişĕ̌pĕ̇ẖ֥wòţ ha⁠ẕáֽ̇rĕʻáţiֽy׃s"],[4,3,"וְ⁠אֵ֨לֶּה֙ אֲבִ֣י עֵיטָ֔ם יִזְרְעֶ֥אל וְ⁠יִשְׁמָ֖א וְ⁠יִדְבָּ֑שׁ וְ⁠שֵׁ֥ם אֲחוֹתָ֖⁠ם הַצְלֶלְפּֽוֹנִי׃","wĕ⁠ʼé֨lėh֙ ʼàbi֣y ʻéytá֔m yizĕrĕʻe֥ʼl wĕ⁠yişĕ̌má֖ʼ wĕ⁠yidĕbá֑̇ş̌ wĕ⁠şé֥̌m ʼàẖwòţá֖⁠m haẕĕlelĕṗֽwòniy׃"],[4,4,"וּ⁠פְנוּאֵל֙ אֲבִ֣י גְדֹ֔ר וְ⁠עֵ֖זֶר אֲבִ֣י חוּשָׁ֑ה אֵ֤לֶּה בְנֵי־חוּר֙ בְּכ֣וֹר אֶפְרָ֔תָה אֲבִ֖י בֵּ֥ית לָֽחֶם׃","ẇ⁠pĕnẇʼél֙ ʼàbi֣y gĕdò֔r wĕ⁠ʻé֖zer ʼàbi֣y ẖẇşá֑̌h ʼé֤lėh bĕnéy-ẖẇr֙ bĕ̇k֣wòr ʼepĕrá֔ţáh ʼàbi֖y bé֥̇yţ láֽẖem׃"],[4,5,"וּ⁠לְ⁠אַשְׁחוּר֙ אֲבִ֣י תְק֔וֹעַ הָי֖וּ שְׁתֵּ֣י נָשִׁ֑ים חֶלְאָ֖ה וְ⁠נַעֲרָֽה׃","ẇ⁠lĕ⁠ʼaşĕ̌ẖẇr֙ ʼàbi֣y ţĕq֔wòʻa háy֖ẇ şĕ̌ţé֣̇y náşǐ֑ym ẖelĕʼá֖h wĕ⁠naʻàráֽh׃"],[4,6,"וַ⁠תֵּ֨לֶד ל֤⁠וֹ נַעֲרָה֙ אֶת־אֲחֻזָּ֣ם וְ⁠אֶת־חֵ֔פֶר וְ⁠אֶת־תֵּימְנִ֖י וְ⁠אֶת־הָ⁠אֲחַשְׁתָּרִ֑י אֵ֖לֶּה בְּנֵ֥י נַעֲרָֽה׃","wa⁠ţé̇֨led l֤⁠wò naʻàráh֙ ʼeţ-ʼàẖuzá֣̇m wĕ⁠ʼeţ-ẖé֔per wĕ⁠ʼeţ-ţé̇ymĕni֖y wĕ⁠ʼeţ-há⁠ʼàẖaşĕ̌ţá̇ri֑y ʼé֖lėh bĕ̇né֥y naʻàráֽh׃"],[4,7,"וּ⁠בְנֵ֖י חֶלְאָ֑ה צֶ֥רֶת יצחר וְ⁠אֶתְנָֽן׃","ẇ⁠bĕné֖y ẖelĕʼá֑h ẕe֥reţ yẕẖr wĕ⁠ʼeţĕnáֽn׃"],[4,8,"וְ⁠ק֣וֹץ הוֹלִ֔יד אֶת־עָנ֖וּב וְ⁠אֶת־הַ⁠צֹּבֵבָ֑ה וּ⁠מִשְׁפְּח֥וֹת אֲחַרְחֵ֖ל בֶּן־הָרֽוּם׃","wĕ⁠q֣wòẕ hwòli֔yd ʼeţ-ʻán֖ẇb wĕ⁠ʼeţ-ha⁠ẕò̇bébá֑h ẇ⁠mişĕ̌pĕ̇ẖ֥wòţ ʼàẖarĕẖé֖l bėn-hárֽẇm׃"],[4,9,"וַ⁠יְהִ֣י יַעְבֵּ֔ץ נִכְבָּ֖ד מֵ⁠אֶחָ֑י⁠ו וְ⁠אִמּ֗⁠וֹ קָרְאָ֨ה שְׁמ֤⁠וֹ יַעְבֵּץ֙ לֵ⁠אמֹ֔ר כִּ֥י יָלַ֖דְתִּי בְּ⁠עֹֽצֶב׃","wa⁠yĕhi֣y yaʻĕbé̇֔ẕ nikĕbá֖̇d mé⁠ʼeẖá֑y⁠w wĕ⁠ʼiṁ֗⁠wò qárĕʼá֨h şĕ̌m֤⁠wò yaʻĕbé̇ẕ֙ lé⁠ʼmò֔r ki֥̇y yála֖dĕţi̇y bĕ̇⁠ʻòֽẕeb׃"],[4,10,"וַ⁠יִּקְרָ֣א יַ֠עְבֵּץ לֵ⁠אלֹהֵ֨י יִשְׂרָאֵ֜ל לֵ⁠אמֹ֗ר אִם־בָּרֵ֨ךְ תְּבָרֲכֵ֜⁠נִי וְ⁠הִרְבִּ֤יתָ אֶת־גְּבוּלִ⁠י֙ וְ⁠הָיְתָ֤ה יָדְ⁠ךָ֙ עִמִּ֔⁠י וְ⁠עָשִׂ֥יתָ מֵּ⁠רָעָ֖ה לְ⁠בִלְתִּ֣י עָצְבִּ֑⁠י וַ⁠יָּבֵ֥א אֱלֹהִ֖ים אֵ֥ת אֲשֶׁר־שָׁאָֽל׃","wa⁠yi̇qĕrá֣ʼ ya֠ʻĕbé̇ẕ lé⁠ʼlòhé֨y yişĕ̂ráʼé֜l lé⁠ʼmò֗r ʼim-bá̇ré֨kĕ ţĕ̇báràké֜⁠niy wĕ⁠hirĕbi֤̇yţá ʼeţ-gĕ̇bẇli⁠y֙ wĕ⁠háyĕţá֤h yádĕ⁠ká֙ ʻimi̇֔⁠y wĕ⁠ʻáşî֥yţá mé̇⁠ráʻá֖h lĕ⁠bilĕţi֣̇y ʻáẕĕbi֑̇⁠y wa⁠yá̇bé֥ʼ ʼèlòhi֖ym ʼé֥ţ ʼàşěr-şá̌ʼáֽl׃"],[4,11,"וּ⁠כְל֥וּב אֲחִֽי־שׁוּחָ֖ה הוֹלִ֣יד אֶת־מְחִ֑יר ה֖וּא אֲבִ֥י אֶשְׁתּֽוֹן׃","ẇ⁠kĕl֥ẇb ʼàẖiֽy-ş̌ẇẖá֖h hwòli֣yd ʼeţ-mĕẖi֑yr h֖ẇʼ ʼàbi֥y ʼeşĕ̌ţֽ̇wòn׃"],[4,12,"וְ⁠אֶשְׁתּ֗וֹן הוֹלִ֞יד אֶת־בֵּ֤ית רָפָא֙ וְ⁠אֶת־פָּסֵ֔חַ וְ⁠אֶת־תְּחִנָּ֖ה אֲבִ֣י עִ֣יר נָחָ֑שׁ אֵ֖לֶּה אַנְשֵׁ֥י רֵכָֽה׃ס","wĕ⁠ʼeşĕ̌ţ̇֗wòn hwòli֞yd ʼeţ-bé֤̇yţ rápáʼ֙ wĕ⁠ʼeţ-pá̇sé֔ẖa wĕ⁠ʼeţ-ţĕ̇ẖiná֖̇h ʼàbi֣y ʻi֣yr náẖá֑ş̌ ʼé֖lėh ʼanĕşé֥̌y rékáֽh׃s"],[4,13,"וּ⁠בְנֵ֣י קְנַ֔ז עָתְנִיאֵ֖ל וּ⁠שְׂרָיָ֑ה וּ⁠בְנֵ֥י עָתְנִיאֵ֖ל חֲתַֽת׃","ẇ⁠bĕné֣y qĕna֔z ʻáţĕniyʼé֖l ẇ⁠şĕ̂ráyá֑h ẇ⁠bĕné֥y ʻáţĕniyʼé֖l ẖàţaֽţ׃"],[4,14,"וּ⁠מְעוֹנֹתַ֖י הוֹלִ֣יד אֶת־עָפְרָ֑ה וּ⁠שְׂרָיָ֗ה הוֹלִ֤יד אֶת־יוֹאָב֙ אֲבִי֙ גֵּ֣יא חֲרָשִׁ֔ים כִּ֥י חֲרָשִׁ֖ים הָיֽוּ׃פ","ẇ⁠mĕʻwònòţa֖y hwòli֣yd ʼeţ-ʻápĕrá֑h ẇ⁠şĕ̂ráyá֗h hwòli֤yd ʼeţ-ywòʼáb֙ ʼàbiy֙ gé֣̇yʼ ẖàráşǐ֔ym ki֥̇y ẖàráşǐ֖ym háyֽẇ׃p"],[4,15,"וּ⁠בְנֵי֙ כָּלֵ֣ב בֶּן־יְפֻנֶּ֔ה עִ֥ירוּ אֵלָ֖ה וָ⁠נָ֑עַם וּ⁠בְנֵ֥י אֵלָ֖ה וּ⁠קְנַֽז׃","ẇ⁠bĕnéy֙ ká̇lé֣b bėn-yĕpunė֔h ʻi֥yrẇ ʼélá֖h wá⁠ná֑ʻam ẇ⁠bĕné֥y ʼélá֖h ẇ⁠qĕnaֽz׃"],[4,16,"וּ⁠בְנֵ֖י יְהַלֶּלְאֵ֑ל זִ֣יף וְ⁠זִיפָ֔ה תִּירְיָ֖א וַ⁠אֲשַׂרְאֵֽל׃","ẇ⁠bĕné֖y yĕhalėlĕʼé֑l zi֣yp wĕ⁠ziypá֔h ţi̇yrĕyá֖ʼ wa⁠ʼàşârĕʼéֽl׃"],[4,17,"וּ⁠בֶן־עֶזְרָ֔ה יֶ֥תֶר וּ⁠מֶ֖רֶד וְ⁠עֵ֣פֶר וְ⁠יָל֑וֹן וַ⁠תַּ֨הַר֙ אֶת־מִרְיָ֣ם וְ⁠אֶת־שַׁמַּ֔י וְ⁠אֶת־יִשְׁבָּ֖ח אֲבִ֥י אֶשְׁתְּמֹֽעַ׃","ẇ⁠ben-ʻezĕrá֔h ye֥ţer ẇ⁠me֖red wĕ⁠ʻé֣per wĕ⁠yál֑wòn wa⁠ţȧ֨har֙ ʼeţ-mirĕyá֣m wĕ⁠ʼeţ-şǎmȧ֔y wĕ⁠ʼeţ-yişĕ̌bá֖̇ẖ ʼàbi֥y ʼeşĕ̌ţĕ̇mòֽʻa׃"],[4,18,"וְ⁠אִשְׁתּ֣⁠וֹ הַ⁠יְהֻדִיָּ֗ה יָלְדָ֞ה אֶת־יֶ֨רֶד אֲבִ֤י גְדוֹר֙ וְ⁠אֶת־חֶ֨בֶר֙ אֲבִ֣י שׂוֹכ֔וֹ וְ⁠אֶת־יְקֽוּתִיאֵ֖ל אֲבִ֣י זָנ֑וֹחַ וְ⁠אֵ֗לֶּה בְּנֵי֙ בִּתְיָ֣ה בַת־פַּרְעֹ֔ה אֲשֶׁ֥ר לָקַ֖ח מָֽרֶד׃ס","wĕ⁠ʼişĕ̌ţ֣̇⁠wò ha⁠yĕhudiyá̇֗h yálĕdá֞h ʼeţ-ye֨red ʼàbi֤y gĕdwòr֙ wĕ⁠ʼeţ-ẖe֨ber֙ ʼàbi֣y ş̂wòk֔wò wĕ⁠ʼeţ-yĕqֽẇţiyʼé֖l ʼàbi֣y zán֑wòẖa wĕ⁠ʼé֗lėh bĕ̇néy֙ bi̇ţĕyá֣h baţ-pȧrĕʻò֔h ʼàşě֥r láqa֖ẖ máֽred׃s"],[4,19,"וּ⁠בְנֵי֙ אֵ֣שֶׁת הֽוֹדִיָּ֔ה אֲח֣וֹת נַ֔חַם אֲבִ֥י קְעִילָ֖ה הַ⁠גַּרְמִ֑י וְ⁠אֶשְׁתְּמֹ֖עַ הַ⁠מַּעֲכָתִֽי׃","ẇ⁠bĕnéy֙ ʼé֣şěţ hֽwòdiyá̇֔h ʼàẖ֣wòţ na֔ẖam ʼàbi֥y qĕʻiylá֖h ha⁠gȧrĕmi֑y wĕ⁠ʼeşĕ̌ţĕ̇mò֖ʻa ha⁠mȧʻàkáţiֽy׃"],[4,20,"וּ⁠בְנֵ֣י שִׁימ֔וֹן אַמְנ֣וֹן וְ⁠רִנָּ֔ה בֶּן־חָנָ֖ן ו⁠תולון וּ⁠בְנֵ֣י יִשְׁעִ֔י זוֹחֵ֖ת וּ⁠בֶן־זוֹחֵֽת׃","ẇ⁠bĕné֣y şǐym֔wòn ʼamĕn֣wòn wĕ⁠riná̇֔h bėn-ẖáná֖n w⁠ţwlwn ẇ⁠bĕné֣y yişĕ̌ʻi֔y zwòẖé֖ţ ẇ⁠ben-zwòẖéֽţ׃"],[4,21,"בְּנֵי֙ שֵׁלָ֣ה בֶן־יְהוּדָ֔ה עֵ֚ר אֲבִ֣י לֵכָ֔ה וְ⁠לַעְדָּ֖ה אֲבִ֣י מָרֵשָׁ֑ה וּ⁠מִשְׁפְּח֛וֹת בֵּית־עֲבֹדַ֥ת הַ⁠בֻּ֖ץ לְ⁠בֵ֥ית אַשְׁבֵּֽעַ׃","bĕ̇néy֙ şé̌lá֣h ben-yĕhẇdá֔h ʻé֚r ʼàbi֣y léká֔h wĕ⁠laʻĕdá֖̇h ʼàbi֣y máréşá֑̌h ẇ⁠mişĕ̌pĕ̇ẖ֛wòţ bé̇yţ-ʻàbòda֥ţ ha⁠bu֖̇ẕ lĕ⁠bé֥yţ ʼaşĕ̌béֽ̇ʻa׃"],[4,22,"וְ⁠יוֹקִ֞ים וְ⁠אַנְשֵׁ֣י כֹזֵבָ֗א וְ⁠יוֹאָ֧שׁ וְ⁠שָׂרָ֛ף אֲשֶׁר־בָּעֲל֥וּ לְ⁠מוֹאָ֖ב וְ⁠יָשֻׁ֣בִי לָ֑חֶם וְ⁠הַ⁠דְּבָרִ֖ים עַתִּיקִֽים׃","wĕ⁠ywòqi֞ym wĕ⁠ʼanĕşé֣̌y kòzébá֗ʼ wĕ⁠ywòʼá֧ş̌ wĕ⁠şá̂rá֛p ʼàşěr-bá̇ʻàl֥ẇ lĕ⁠mwòʼá֖b wĕ⁠yáşǔ֣biy lá֑ẖem wĕ⁠ha⁠dĕ̇bári֖ym ʻaţi̇yqiֽym׃"],[4,23,"הֵ֚מָּה הַ⁠יּ֣וֹצְרִ֔ים וְ⁠יֹשְׁבֵ֥י נְטָעִ֖ים וּ⁠גְדֵרָ֑ה עִם־הַ⁠מֶּ֥לֶךְ בִּ⁠מְלַאכְתּ֖⁠וֹ יָ֥שְׁבוּ שָֽׁם׃ס","hé֚má̇h ha⁠ẏ֣wòẕĕri֔ym wĕ⁠yòşĕ̌bé֥y nĕtáʻi֖ym ẇ⁠gĕdérá֑h ʻim-ha⁠mė֥lekĕ bi̇⁠mĕlaʼkĕţ֖̇⁠wò yá֥şĕ̌bẇ şáֽ̌m׃s"],[4,24,"בְּנֵ֖י שִׁמְע֑וֹן נְמוּאֵ֣ל וְ⁠יָמִ֔ין יָרִ֖יב זֶ֥רַח שָׁאֽוּל׃","bĕ̇né֖y şǐmĕʻ֑wòn nĕmẇʼé֣l wĕ⁠yámi֔yn yári֖yb ze֥raẖ şá̌ʼֽẇl׃"],[4,25,"שַׁלֻּ֥ם בְּנ֛⁠וֹ מִבְשָׂ֥ם בְּנ֖⁠וֹ מִשְׁמָ֥ע בְּנֽ⁠וֹ׃","şǎlu֥̇m bĕ̇n֛⁠wò mibĕşá֥̂m bĕ̇n֖⁠wò mişĕ̌má֥ʻ bĕ̇nֽ⁠wò׃"],[4,26,"וּ⁠בְנֵ֖י מִשְׁמָ֑ע חַמּוּאֵ֥ל בְּנ֛⁠וֹ זַכּ֥וּר בְּנ֖⁠וֹ שִׁמְעִ֥י בְנֽ⁠וֹ׃","ẇ⁠bĕné֖y mişĕ̌má֑ʻ ẖaṁẇʼé֥l bĕ̇n֛⁠wò zak֥̇ẇr bĕ̇n֖⁠wò şǐmĕʻi֥y bĕnֽ⁠wò׃"],[4,27,"וּ⁠לְ⁠שִׁמְעִ֞י בָּנִ֨ים שִׁשָּׁ֤ה עָשָׂר֙ וּ⁠בָנ֣וֹת שֵׁ֔שׁ וּ⁠לְ⁠אֶחָ֕י⁠ו אֵ֖ין בָּנִ֣ים רַבִּ֑ים וְ⁠כֹל֙ מִשְׁפַּחְתָּ֔⁠ם לֹ֥א הִרְבּ֖וּ עַד־בְּנֵ֥י יְהוּדָֽה׃ס","ẇ⁠lĕ⁠şǐmĕʻi֞y bá̇ni֨ym şǐşá֤̇̌h ʻáşá̂r֙ ẇ⁠bán֣wòţ şé̌֔ş̌ ẇ⁠lĕ⁠ʼeẖá֕y⁠w ʼé֖yn bá̇ni֣ym rabi֑̇ym wĕ⁠kòl֙ mişĕ̌pȧẖĕţá̇֔⁠m lò֥ʼ hirĕḃ֖ẇ ʻad-bĕ̇né֥y yĕhẇdáֽh׃s"],[4,28,"וַ⁠יֵּֽשְׁב֛וּ בִּ⁠בְאֵֽר־שֶׁ֥בַע וּ⁠מוֹלָדָ֖ה וַ⁠חֲצַ֥ר שׁוּעָֽל׃","wa⁠yéֽ̇şĕ̌b֛ẇ bi̇⁠bĕʼéֽr-şě֥baʻ ẇ⁠mwòládá֖h wa⁠ẖàẕa֥r ş̌ẇʻáֽl׃"],[4,29,"וּ⁠בְ⁠בִלְהָ֥ה וּ⁠בְ⁠עֶ֖צֶם וּ⁠בְ⁠תוֹלָֽד׃","ẇ⁠bĕ⁠bilĕhá֥h ẇ⁠bĕ⁠ʻe֖ẕem ẇ⁠bĕ⁠ţwòláֽd׃"],[4,30,"וּ⁠בִ⁠בְתוּאֵ֥ל וּ⁠בְ⁠חָרְמָ֖ה וּ⁠בְ⁠צִֽיקְלָֽג׃","ẇ⁠bi⁠bĕţẇʼé֥l ẇ⁠bĕ⁠ẖárĕmá֖h ẇ⁠bĕ⁠ẕiֽyqĕláֽg׃"],[4,31,"וּ⁠בְ⁠בֵ֤ית מַרְכָּבוֹת֙ וּ⁠בַ⁠חֲצַ֣ר סוּסִ֔ים וּ⁠בְ⁠בֵ֥ית בִּרְאִ֖י וּֽ⁠בְ⁠שַׁעֲרָ֑יִם אֵ֥לֶּה עָרֵי⁠הֶ֖ם עַד־מְלֹ֥ךְ דָּוִֽיד׃","ẇ⁠bĕ⁠bé֤yţ marĕká̇bwòţ֙ ẇ⁠ba⁠ẖàẕa֣r sẇsi֔ym ẇ⁠bĕ⁠bé֥yţ bi̇rĕʼi֖y ẇֽ⁠bĕ⁠şǎʻàrá֑yim ʼé֥lėh ʻáréy⁠he֖m ʻad-mĕlò֥kĕ dá̇wiֽyd׃"],[4,32,"וְ⁠חַצְרֵי⁠הֶם֙ עֵיטָ֣ם וָ⁠עַ֔יִן רִמּ֥וֹן וְ⁠תֹ֖כֶן וְ⁠עָשָׁ֑ן עָרִ֖ים חָמֵֽשׁ׃","wĕ⁠ẖaẕĕréy⁠hem֙ ʻéytá֣m wá⁠ʻa֔yin riṁ֥wòn wĕ⁠ţò֖ken wĕ⁠ʻáşá֑̌n ʻári֖ym ẖáméֽş̌׃"],[4,33,"וְ⁠כָל־חַצְרֵי⁠הֶ֗ם אֲשֶׁ֧ר סְבִיב֛וֹת הֶ⁠עָרִ֥ים הָ⁠אֵ֖לֶּה עַד־בָּ֑עַל זֹ֚את מוֹשְׁבֹתָ֔⁠ם וְ⁠הִתְיַחְשָׂ֖⁠ם לָ⁠הֶֽם׃","wĕ⁠kál-ẖaẕĕréy⁠he֗m ʼàşě֧r sĕbiyb֛wòţ he⁠ʻári֥ym há⁠ʼé֖lėh ʻad-bá֑̇ʻal zò֚ʼţ mwòşĕ̌bòţá֔⁠m wĕ⁠hiţĕyaẖĕşá֖̂⁠m lá⁠heֽm׃"],[4,34,"וּ⁠מְשׁוֹבָ֣ב וְ⁠יַמְלֵ֔ךְ וְ⁠יוֹשָׁ֖ה בֶּן־אֲמַצְיָֽה׃","ẇ⁠mĕş̌wòbá֣b wĕ⁠yamĕlé֔kĕ wĕ⁠ywòşá֖̌h bėn-ʼàmaẕĕyáֽh׃"],[4,35,"וְ⁠יוֹאֵ֑ל וְ⁠יֵהוּא֙ בֶּן־י֣וֹשִׁבְיָ֔ה בֶּן־שְׂרָיָ֖ה בֶּן־עֲשִׂיאֵֽל׃","wĕ⁠ywòʼé֑l wĕ⁠yéhẇʼ֙ bėn-y֣wòşǐbĕyá֔h bėn-şĕ̂ráyá֖h bėn-ʻàşîyʼéֽl׃"],[4,36,"וְ⁠אֶלְיוֹעֵינַ֡י וְֽ⁠יַעֲקֹ֡בָה וִ֠⁠ישׁוֹחָיָה וַ⁠עֲשָׂיָ֧ה וַ⁠עֲדִיאֵ֛ל וִ⁠ישִׂימִאֵ֖ל וּ⁠בְנָיָֽה׃","wĕ⁠ʼelĕywòʻéyna֡y wĕֽ⁠yaʻàqò֡báh wi֠⁠yş̌wòẖáyáh wa⁠ʻàşá̂yá֧h wa⁠ʻàdiyʼé֛l wi⁠yşîymiʼé֖l ẇ⁠bĕnáyáֽh׃"],[4,37,"וְ⁠זִיזָ֨א בֶן־שִׁפְעִ֧י בֶן־אַלּ֛וֹן בֶּן־יְדָיָ֥ה בֶן־שִׁמְרִ֖י בֶּן־שְׁמַֽעְיָֽה׃","wĕ⁠ziyzá֨ʼ ben-şǐpĕʻi֧y ben-ʼal֛̇wòn bėn-yĕdáyá֥h ben-şǐmĕri֖y bėn-şĕ̌maֽʻĕyáֽh׃"],[4,38,"אֵ֚לֶּה הַ⁠בָּאִ֣ים בְּ⁠שֵׁמ֔וֹת נְשִׂיאִ֖ים בְּ⁠מִשְׁפְּחוֹתָ֑⁠ם וּ⁠בֵית֙ אֲב֣וֹתֵי⁠הֶ֔ם פָּרְצ֖וּ לָ⁠רֽוֹב׃","ʼé֚lėh ha⁠bá̇ʼi֣ym bĕ̇⁠şé̌m֔wòţ nĕşîyʼi֖ym bĕ̇⁠mişĕ̌pĕ̇ẖwòţá֑⁠m ẇ⁠béyţ֙ ʼàb֣wòţéy⁠he֔m pá̇rĕẕ֖ẇ lá⁠rֽwòb׃"],[4,39,"וַ⁠יֵּלְכוּ֙ לִ⁠מְב֣וֹא גְדֹ֔ר עַ֖ד לְ⁠מִזְרַ֣ח הַ⁠גָּ֑יְא לְ⁠בַקֵּ֥שׁ מִרְעֶ֖ה לְ⁠צֹאנָֽ⁠ם׃","wa⁠yé̇lĕkẇ֙ li⁠mĕb֣wòʼ gĕdò֔r ʻa֖d lĕ⁠mizĕra֣ẖ ha⁠gá֑̇yĕʼ lĕ⁠baqé֥̇ş̌ mirĕʻe֖h lĕ⁠ẕòʼnáֽ⁠m׃"],[4,40,"וַֽ⁠יִּמְצְא֤וּ מִרְעֶה֙ שָׁמֵ֣ן וָ⁠ט֔וֹב וְ⁠הָ⁠אָ֨רֶץ֙ רַחֲבַ֣ת יָדַ֔יִם וְ⁠שֹׁקֶ֖טֶת וּ⁠שְׁלֵוָ֑ה כִּ֣י מִן־חָ֔ם הַ⁠יֹּשְׁבִ֥ים שָׁ֖ם לְ⁠פָנִֽים׃","waֽ⁠yi̇mĕẕĕʼ֤ẇ mirĕʻeh֙ şá̌mé֣n wá⁠t֔wòb wĕ⁠há⁠ʼá֨reẕ֙ raẖàba֣ţ yáda֔yim wĕ⁠şò̌qe֖teţ ẇ⁠şĕ̌léwá֑h ki֣̇y min-ẖá֔m ha⁠yò̇şĕ̌bi֥ym şá֖̌m lĕ⁠pániֽym׃"],[4,41,"וַ⁠יָּבֹ֡אוּ אֵלֶּה֩ הַ⁠כְּתוּבִ֨ים בְּ⁠שֵׁמ֜וֹת בִּ⁠ימֵ֣י ׀ יְחִזְקִיָּ֣הוּ מֶֽלֶךְ־יְהוּדָ֗ה וַ⁠יַּכּ֨וּ אֶת־אָהֳלֵי⁠הֶ֜ם וְ⁠אֶת־ה⁠מעינים אֲשֶׁ֤ר נִמְצְאוּ־שָׁ֨מָּ⁠ה֙ וַ⁠יַּחֲרִימֻ⁠ם֙ עַד־הַ⁠יּ֣וֹם הַ⁠זֶּ֔ה וַ⁠יֵּשְׁב֖וּ תַּחְתֵּי⁠הֶ֑ם כִּֽי־מִרְעֶ֥ה לְ⁠צֹאנָ֖⁠ם שָֽׁם׃","wa⁠yá̇bò֡ʼẇ ʼélėh֩ ha⁠kĕ̇ţẇbi֨ym bĕ̇⁠şé̌m֜wòţ bi̇⁠ymé֣y ׀ yĕẖizĕqiyá֣̇hẇ meֽlekĕ-yĕhẇdá֗h wa⁠yȧk̇֨ẇ ʼeţ-ʼáholéy⁠he֜m wĕ⁠ʼeţ-h⁠mʻynym ʼàşě֤r nimĕẕĕʼẇ-şá̌֨má̇⁠h֙ wa⁠yȧẖàriymu⁠m֙ ʻad-ha⁠ẏ֣wòm ha⁠zė֔h wa⁠yé̇şĕ̌b֖ẇ ţȧẖĕţé̇y⁠he֑m kiֽ̇y-mirĕʻe֥h lĕ⁠ẕòʼná֖⁠m şáֽ̌m׃"],[4,42,"וּ⁠מֵ⁠הֶ֣ם ׀ מִן־בְּנֵ֣י שִׁמְע֗וֹן הָלְכוּ֙ לְ⁠הַ֣ר שֵׂעִ֔יר אֲנָשִׁ֖ים חֲמֵ֣שׁ מֵא֑וֹת וּ⁠פְלַטְיָ֡ה וּ֠⁠נְעַרְיָה וּ⁠רְפָיָ֧ה וְ⁠עֻזִּיאֵ֛ל בְּנֵ֥י יִשְׁעִ֖י בְּ⁠רֹאשָֽׁ⁠ם׃","ẇ⁠mé⁠he֣m ׀ min-bĕ̇né֣y şǐmĕʻ֗wòn hálĕkẇ֙ lĕ⁠ha֣r şé̂ʻi֔yr ʼànáşǐ֖ym ẖàmé֣ş̌ méʼ֑wòţ ẇ⁠pĕlatĕyá֡h ẇ֠⁠nĕʻarĕyáh ẇ⁠rĕpáyá֧h wĕ⁠ʻuzi̇yʼé֛l bĕ̇né֥y yişĕ̌ʻi֖y bĕ̇⁠ròʼşáֽ̌⁠m׃"],[4,43,"וַ⁠יַּכּ֕וּ אֶת־שְׁאֵרִ֥ית הַ⁠פְּלֵטָ֖ה לַ⁠עֲמָלֵ֑ק וַ⁠יֵּ֣שְׁבוּ שָׁ֔ם עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","wa⁠yȧk̇֕ẇ ʼeţ-şĕ̌ʼéri֥yţ ha⁠pĕ̇létá֖h la⁠ʻàmálé֑q wa⁠yé֣̇şĕ̌bẇ şá̌֔m ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃"],[5,1,"וּ⁠בְנֵ֨י רְאוּבֵ֥ן בְּכֽוֹר־יִשְׂרָאֵל֮ כִּ֣י ה֣וּא הַ⁠בְּכוֹר֒ וּֽ⁠בְ⁠חַלְּל⁠וֹ֙ יְצוּעֵ֣י אָבִ֔י⁠ו נִתְּנָה֙ בְּכֹ֣רָת֔⁠וֹ לִ⁠בְנֵ֥י יוֹסֵ֖ף בֶּן־יִשְׂרָאֵ֑ל וְ⁠לֹ֥א לְ⁠הִתְיַחֵ֖שׂ לַ⁠בְּכֹרָֽה׃","ẇ⁠bĕné֨y rĕʼẇbé֥n bĕ̇kֽwòr-yişĕ̂ráʼél֮ ki֣̇y h֣ẇʼ ha⁠bĕ̇kwòr֒ ẇֽ⁠bĕ⁠ẖalĕ̇l⁠wò֙ yĕẕẇʻé֣y ʼábi֔y⁠w niţĕ̇náh֙ bĕ̇kò֣ráţ֔⁠wò li⁠bĕné֥y ywòsé֖p bėn-yişĕ̂ráʼé֑l wĕ⁠lò֥ʼ lĕ⁠hiţĕyaẖé֖ş̂ la⁠bĕ̇kòráֽh׃"],[5,2,"כִּ֤י יְהוּדָה֙ גָּבַ֣ר בְּ⁠אֶחָ֔י⁠ו וּ⁠לְ⁠נָגִ֖יד מִמֶּ֑⁠נּוּ וְ⁠הַ⁠בְּכֹרָ֖ה לְ⁠יוֹסֵֽף׃ס","ki֤̇y yĕhẇdáh֙ gá̇ba֣r bĕ̇⁠ʼeẖá֔y⁠w ẇ⁠lĕ⁠nági֖yd mimė֑⁠ṅẇ wĕ⁠ha⁠bĕ̇kòrá֖h lĕ⁠ywòséֽp׃s"],[5,3,"בְּנֵ֥י רְאוּבֵ֖ן בְּכ֣וֹר יִשְׂרָאֵ֑ל חֲנ֥וֹךְ וּ⁠פַלּ֖וּא חֶצְר֥וֹן וְ⁠כַרְמִֽי׃","bĕ̇né֥y rĕʼẇbé֖n bĕ̇k֣wòr yişĕ̂ráʼé֑l ẖàn֥wòkĕ ẇ⁠pal֖̇ẇʼ ẖeẕĕr֥wòn wĕ⁠karĕmiֽy׃"],[5,4,"בְּנֵ֖י יוֹאֵ֑ל שְׁמַֽעְיָ֥ה בְנ֛⁠וֹ גּ֥וֹג בְּנ֖⁠וֹ שִׁמְעִ֥י בְנֽ⁠וֹ׃","bĕ̇né֖y ywòʼé֑l şĕ̌maֽʻĕyá֥h bĕn֛⁠wò ġ֥wòg bĕ̇n֖⁠wò şǐmĕʻi֥y bĕnֽ⁠wò׃"],[5,5,"מִיכָ֥ה בְנ֛⁠וֹ רְאָיָ֥ה בְנ֖⁠וֹ בַּ֥עַל בְּנֽ⁠וֹ׃","miyká֥h bĕn֛⁠wò rĕʼáyá֥h bĕn֖⁠wò bȧ֥ʻal bĕ̇nֽ⁠wò׃"],[5,6,"בְּאֵרָ֣ה בְנ֔⁠וֹ אֲשֶׁ֣ר הֶגְלָ֔ה תִּלְּגַ֥ת פִּלְנְאֶ֖סֶר מֶ֣לֶךְ אַשֻּׁ֑ר ה֥וּא נָשִׂ֖יא לָ⁠רֽאוּבֵנִֽי׃","bĕ̇ʼérá֣h bĕn֔⁠wò ʼàşě֣r hegĕlá֔h ţi̇lĕ̇ga֥ţ pi̇lĕnĕʼe֖ser me֣lekĕ ʼaşu֑̇̌r h֥ẇʼ náşî֖yʼ lá⁠rֽʼẇbéniֽy׃"],[5,7,"וְ⁠אֶחָי⁠ו֙ לְ⁠מִשְׁפְּחֹתָ֔י⁠ו בְּ⁠הִתְיַחֵ֖שׂ לְ⁠תֹלְדוֹתָ֑⁠ם הָ⁠רֹ֥אשׁ יְעִיאֵ֖ל וּ⁠זְכַרְיָֽהוּ׃","wĕ⁠ʼeẖáy⁠w֙ lĕ⁠mişĕ̌pĕ̇ẖòţá֔y⁠w bĕ̇⁠hiţĕyaẖé֖ş̂ lĕ⁠ţòlĕdwòţá֑⁠m há⁠rò֥ʼş̌ yĕʻiyʼé֖l ẇ⁠zĕkarĕyáֽhẇ׃"],[5,8,"וּ⁠בֶ֨לַע֙ בֶּן־עָזָ֔ז בֶּן־שֶׁ֖מַע בֶּן־יוֹאֵ֑ל ה֚וּא יוֹשֵׁ֣ב בַּ⁠עֲרֹעֵ֔ר וְ⁠עַד־נְב֖וֹ וּ⁠בַ֥עַל מְעֽוֹן׃","ẇ⁠be֨laʻ֙ bėn-ʻázá֔z bėn-şě֖maʻ bėn-ywòʼé֑l h֚ẇʼ ywòşé֣̌b bȧ⁠ʻàròʻé֔r wĕ⁠ʻad-nĕb֖wò ẇ⁠ba֥ʻal mĕʻֽwòn׃"],[5,9,"וְ⁠לַ⁠מִּזְרָ֗ח יָשַׁב֙ עַד־לְ⁠ב֣וֹא מִדְבָּ֔רָ⁠ה לְ⁠מִן־הַ⁠נָּהָ֖ר פְּרָ֑ת כִּ֧י מִקְנֵי⁠הֶ֛ם רָב֖וּ בְּ⁠אֶ֥רֶץ גִּלְעָֽד׃","wĕ⁠la⁠mi̇zĕrá֗ẖ yáşǎb֙ ʻad-lĕ⁠b֣wòʼ midĕbá̇֔rá⁠h lĕ⁠min-ha⁠ná̇há֖r pĕ̇rá֑ţ ki֧̇y miqĕnéy⁠he֛m ráb֖ẇ bĕ̇⁠ʼe֥reẕ gi̇lĕʻáֽd׃"],[5,10,"וּ⁠בִ⁠ימֵ֣י שָׁא֗וּל עָשׂ֤וּ מִלְחָמָה֙ עִם־הַֽ⁠הַגְרִאִ֔ים וַֽ⁠יִּפְּל֖וּ בְּ⁠יָדָ֑⁠ם וַ⁠יֵּשְׁבוּ֙ בְּ⁠אָ֣הֳלֵי⁠הֶ֔ם עַֽל־כָּל־פְּנֵ֖י מִזְרָ֥ח לַ⁠גִּלְעָֽד׃פ","ẇ⁠bi⁠ymé֣y şá̌ʼ֗ẇl ʻáş֤̂ẇ milĕẖámáh֙ ʻim-haֽ⁠hagĕriʼi֔ym waֽ⁠yi̇pĕ̇l֖ẇ bĕ̇⁠yádá֑⁠m wa⁠yé̇şĕ̌bẇ֙ bĕ̇⁠ʼá֣holéy⁠he֔m ʻaֽl-ká̇l-pĕ̇né֖y mizĕrá֥ẖ la⁠gi̇lĕʻáֽd׃p"],[5,11,"וּ⁠בְנֵי־גָ֣ד לְ⁠נֶגְדָּ֗⁠ם יָֽשְׁב֛וּ בְּ⁠אֶ֥רֶץ הַ⁠בָּשָׁ֖ן עַד־סַלְכָֽה׃","ẇ⁠bĕnéy-gá֣d lĕ⁠negĕdá̇֗⁠m yáֽşĕ̌b֛ẇ bĕ̇⁠ʼe֥reẕ ha⁠bá̇şá֖̌n ʻad-salĕkáֽh׃"],[5,12,"יוֹאֵ֣ל הָ⁠רֹ֔אשׁ וְ⁠שָׁפָ֖ם הַ⁠מִּשְׁנֶ֑ה וְ⁠יַעְנַ֥י וְ⁠שָׁפָ֖ט בַּ⁠בָּשָֽׁן׃","ywòʼé֣l há⁠rò֔ʼş̌ wĕ⁠şá̌pá֖m ha⁠mi̇şĕ̌ne֑h wĕ⁠yaʻĕna֥y wĕ⁠şá̌pá֖t bȧ⁠bá̇şáֽ̌n׃"],[5,13,"וַ⁠אֲחֵי⁠הֶ֞ם לְ⁠בֵ֣ית אֲבוֹתֵי⁠הֶ֗ם מִֽיכָאֵ֡ל וּ⁠מְשֻׁלָּ֡ם וְ֠⁠שֶׁבַע וְ⁠יוֹרַ֧י וְ⁠יַעְכָּ֛ן וְ⁠זִ֥יעַ וָ⁠עֵ֖בֶר שִׁבְעָֽה׃ס","wa⁠ʼàẖéy⁠he֞m lĕ⁠bé֣yţ ʼàbwòţéy⁠he֗m miֽykáʼé֡l ẇ⁠mĕşǔlá̇֡m wĕ֠⁠şěbaʻ wĕ⁠ywòra֧y wĕ⁠yaʻĕká֛̇n wĕ⁠zi֥yʻa wá⁠ʻé֖ber şǐbĕʻáֽh׃s"],[5,14,"אֵ֣לֶּה ׀ בְּנֵ֣י אֲבִיחַ֗יִל בֶּן־חוּרִ֡י בֶּן־יָ֠רוֹחַ בֶּן־גִּלְעָ֧ד בֶּן־מִיכָאֵ֛ל בֶּן־יְשִׁישַׁ֥י בֶּן־יַחְדּ֖וֹ בֶּן־בּֽוּז׃","ʼé֣lėh ׀ bĕ̇né֣y ʼàbiyẖa֗yil bėn-ẖẇri֡y bėn-yá֠rwòẖa bėn-gi̇lĕʻá֧d bėn-miykáʼé֛l bėn-yĕşǐyşǎ֥y bėn-yaẖĕḋ֖wò bėn-ḃֽẇz׃"],[5,15,"אֲחִי֙ בֶּן־עַבְדִּיאֵ֣ל בֶּן־גּוּנִ֔י רֹ֖אשׁ לְ⁠בֵ֥ית אֲבוֹתָֽ⁠ם׃","ʼàẖiy֙ bėn-ʻabĕdi̇yʼé֣l bėn-ġẇni֔y rò֖ʼş̌ lĕ⁠bé֥yţ ʼàbwòţáֽ⁠m׃"],[5,16,"וַ⁠יֵּֽשְׁב֛וּ בַּ⁠גִּלְעָ֥ד בַּ⁠בָּשָׁ֖ן וּ⁠בִ⁠בְנֹתֶ֑י⁠הָ וּ⁠בְ⁠כָֽל־מִגְרְשֵׁ֥י שָׁר֖וֹן עַל־תּוֹצְאוֹתָֽ⁠ם׃","wa⁠yéֽ̇şĕ̌b֛ẇ bȧ⁠gi̇lĕʻá֥d bȧ⁠bá̇şá֖̌n ẇ⁠bi⁠bĕnòţe֑y⁠há ẇ⁠bĕ⁠káֽl-migĕrĕşé֥̌y şá̌r֖wòn ʻal-ţ̇wòẕĕʼwòţáֽ⁠m׃"],[5,17,"כֻּלָּ⁠ם֙ הִתְיַחְשׂ֔וּ בִּ⁠ימֵ֖י יוֹתָ֣ם מֶֽלֶךְ־יְהוּדָ֑ה וּ⁠בִ⁠ימֵ֖י יָרָבְעָ֥ם מֶֽלֶךְ־יִשְׂרָאֵֽל׃פ","ku̇lá̇⁠m֙ hiţĕyaẖĕş̂֔ẇ bi̇⁠ymé֖y ywòţá֣m meֽlekĕ-yĕhẇdá֑h ẇ⁠bi⁠ymé֖y yárábĕʻá֥m meֽlekĕ-yişĕ̂ráʼéֽl׃p"],[5,18,"בְּנֵֽי־רְאוּבֵ֨ן וְ⁠גָדִ֜י וַ⁠חֲצִ֥י שֵֽׁבֶט־מְנַשֶּׁה֮ מִן־בְּנֵי־חַיִל֒ אֲ֠נָשִׁים נֹשְׂאֵ֨י מָגֵ֤ן וְ⁠חֶ֨רֶב֙ וְ⁠דֹ֣רְכֵי קֶ֔שֶׁת וּ⁠לְמוּדֵ֖י מִלְחָמָ֑ה אַרְבָּעִ֨ים וְ⁠אַרְבָּעָ֥ה אֶ֛לֶף וּ⁠שְׁבַע־מֵא֥וֹת וְ⁠שִׁשִּׁ֖ים יֹצְאֵ֥י צָבָֽא׃","bĕ̇néֽy-rĕʼẇbé֨n wĕ⁠gádi֜y wa⁠ẖàẕi֥y şéֽ̌bet-mĕnaşė̌h֮ min-bĕ̇néy-ẖayil֒ ʼà֠náşǐym nòşĕ̂ʼé֨y mágé֤n wĕ⁠ẖe֨reb֙ wĕ⁠dò֣rĕkéy qe֔şěţ ẇ⁠lĕmẇdé֖y milĕẖámá֑h ʼarĕbá̇ʻi֨ym wĕ⁠ʼarĕbá̇ʻá֥h ʼe֛lep ẇ⁠şĕ̌baʻ-méʼ֥wòţ wĕ⁠şǐşi֖̇̌ym yòẕĕʼé֥y ẕábáֽʼ׃"],[5,19,"וַ⁠יַּעֲשׂ֥וּ מִלְחָמָ֖ה עִם־הַֽ⁠הַגְרִיאִ֑ים וִ⁠יט֥וּר וְ⁠נָפִ֖ישׁ וְ⁠נוֹדָֽב׃","wa⁠yȧʻàş֥̂ẇ milĕẖámá֖h ʻim-haֽ⁠hagĕriyʼi֑ym wi⁠yt֥ẇr wĕ⁠nápi֖yş̌ wĕ⁠nwòdáֽb׃"],[5,20,"וַ⁠יֵּעָזְר֣וּ עֲלֵי⁠הֶ֔ם וַ⁠יִּנָּתְנ֤וּ בְ⁠יָדָ⁠ם֙ הַֽ⁠הַגְרִיאִ֔ים וְ⁠כֹ֖ל שֶׁ֣⁠עִמָּ⁠הֶ֑ם כִּ֠י לֵ⁠אלֹהִ֤ים זָעֲקוּ֙ בַּ⁠מִּלְחָמָ֔ה וְ⁠נַעְתּ֥וֹר לָ⁠הֶ֖ם כִּי־בָ֥טְחוּ בֽ⁠וֹ׃","wa⁠yé̇ʻázĕr֣ẇ ʻàléy⁠he֔m wa⁠yi̇ná̇ţĕn֤ẇ bĕ⁠yádá⁠m֙ haֽ⁠hagĕriyʼi֔ym wĕ⁠kò֖l şě֣⁠ʻimá̇⁠he֑m ki̇֠y lé⁠ʼlòhi֤ym záʻàqẇ֙ bȧ⁠mi̇lĕẖámá֔h wĕ⁠naʻĕţ֥̇wòr lá⁠he֖m ki̇y-bá֥tĕẖẇ bֽ⁠wò׃"],[5,21,"וַ⁠יִּשְׁבּ֣וּ מִקְנֵי⁠הֶ֗ם גְּֽמַלֵּי⁠הֶ֞ם חֲמִשִּׁ֥ים אֶ֨לֶף֙ וְ⁠צֹ֗אן מָאתַ֤יִם וַ⁠חֲמִשִּׁים֙ אֶ֔לֶף וַ⁠חֲמוֹרִ֖ים אַלְפָּ֑יִם וְ⁠נֶ֥פֶשׁ אָדָ֖ם מֵ֥אָה אָֽלֶף׃","wa⁠yi̇şĕ̌ḃ֣ẇ miqĕnéy⁠he֗m gĕֽ̇malé̇y⁠he֞m ẖàmişi֥̇̌ym ʼe֨lep֙ wĕ⁠ẕò֗ʼn máʼţa֤yim wa⁠ẖàmişi̇̌ym֙ ʼe֔lep wa⁠ẖàmwòri֖ym ʼalĕpá֑̇yim wĕ⁠ne֥peş̌ ʼádá֖m mé֥ʼáh ʼáֽlep׃"],[5,22,"כִּֽי־חֲלָלִ֤ים רַבִּים֙ נָפָ֔לוּ כִּ֥י מֵ⁠הָ⁠אֱלֹהִ֖ים הַ⁠מִּלְחָמָ֑ה וַ⁠יֵּשְׁב֥וּ תַחְתֵּי⁠הֶ֖ם עַד־הַ⁠גֹּלָֽה׃פ","kiֽ̇y-ẖàláli֤ym rabi̇ym֙ nápá֔lẇ ki֥̇y mé⁠há⁠ʼèlòhi֖ym ha⁠mi̇lĕẖámá֑h wa⁠yé̇şĕ̌b֥ẇ ţaẖĕţé̇y⁠he֖m ʻad-ha⁠gò̇láֽh׃p"],[5,23,"וּ⁠בְנֵ֗י חֲצִי֙ שֵׁ֣בֶט מְנַשֶּׁ֔ה יָשְׁב֖וּ בָּ⁠אָ֑רֶץ מִ⁠בָּשָׁ֞ן עַד־בַּ֧עַל חֶרְמ֛וֹן וּ⁠שְׂנִ֥יר וְ⁠הַר־חֶרְמ֖וֹן הֵ֥מָּה רָבֽוּ׃","ẇ⁠bĕné֗y ẖàẕiy֙ şé֣̌bet mĕnaşė̌֔h yáşĕ̌b֖ẇ bá̇⁠ʼá֑reẕ mi⁠bá̇şá̌֞n ʻad-bȧ֧ʻal ẖerĕm֛wòn ẇ⁠şĕ̂ni֥yr wĕ⁠har-ẖerĕm֖wòn hé֥má̇h rábֽẇ׃"],[5,24,"וְ⁠אֵ֖לֶּה רָאשֵׁ֣י בֵית־אֲבוֹתָ֑⁠ם וְ⁠עֵ֡פֶר וְ⁠יִשְׁעִ֡י וֶ⁠אֱלִיאֵ֡ל וְ֠⁠עַזְרִיאֵל וְ⁠יִרְמְיָ֨ה וְ⁠הוֹדַוְיָ֜ה וְ⁠יַחְדִּיאֵ֗ל אֲנָשִׁים֙ גִּבּ֣וֹרֵי חַ֔יִל אַנְשֵׁ֣י שֵׁמ֔וֹת רָאשִׁ֖ים לְ⁠בֵ֥ית אֲבוֹתָֽ⁠ם׃","wĕ⁠ʼé֖lėh ráʼşé֣̌y béyţ-ʼàbwòţá֑⁠m wĕ⁠ʻé֡per wĕ⁠yişĕ̌ʻi֡y we⁠ʼèliyʼé֡l wĕ֠⁠ʻazĕriyʼél wĕ⁠yirĕmĕyá֨h wĕ⁠hwòdawĕyá֜h wĕ⁠yaẖĕdi̇yʼé֗l ʼànáşǐym֙ gi̇ḃ֣wòréy ẖa֔yil ʼanĕşé֣̌y şé̌m֔wòţ ráʼşǐ֖ym lĕ⁠bé֥yţ ʼàbwòţáֽ⁠m׃"],[5,25,"וַ⁠יִּֽמְעֲל֔וּ בֵּ⁠אלֹהֵ֖י אֲבוֹתֵי⁠הֶ֑ם וַ⁠יִּזְנ֗וּ אַחֲרֵי֙ אֱלֹהֵ֣י עַמֵּי־הָ⁠אָ֔רֶץ אֲשֶׁר־הִשְׁמִ֥יד אֱלֹהִ֖ים מִ⁠פְּנֵי⁠הֶֽם׃","wa⁠yiֽ̇mĕʻàl֔ẇ bé̇⁠ʼlòhé֖y ʼàbwòţéy⁠he֑m wa⁠yi̇zĕn֗ẇ ʼaẖàréy֙ ʼèlòhé֣y ʻamé̇y-há⁠ʼá֔reẕ ʼàşěr-hişĕ̌mi֥yd ʼèlòhi֖ym mi⁠pĕ̇néy⁠heֽm׃"],[5,26,"וַ⁠יָּעַר֩ אֱלֹהֵ֨י יִשְׂרָאֵ֜ל אֶת־ר֣וּחַ ׀ פּ֣וּל מֶֽלֶךְ־אַשּׁ֗וּר וְ⁠אֶת־ר֨וּחַ֙ תִּלְּגַ֤ת פִּלְנֶ֨סֶר֙ מֶ֣לֶךְ אַשּׁ֔וּר וַ⁠יַּגְלֵ⁠ם֙ לָ⁠ראוּבֵנִ֣י וְ⁠לַ⁠גָּדִ֔י וְ⁠לַ⁠חֲצִ֖י שֵׁ֣בֶט מְנַשֶּׁ֑ה וַ֠⁠יְבִיאֵ⁠ם לַ⁠חְלַ֨ח וְ⁠חָב֤וֹר וְ⁠הָרָא֙ וּ⁠נְהַ֣ר גּוֹזָ֔ן עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃פ","wa⁠yá̇ʻar֩ ʼèlòhé֨y yişĕ̂ráʼé֜l ʼeţ-r֣ẇẖa ׀ ṗ֣ẇl meֽlekĕ-ʼaş̇̌֗ẇr wĕ⁠ʼeţ-r֨ẇẖa֙ ţi̇lĕ̇ga֤ţ pi̇lĕne֨ser֙ me֣lekĕ ʼaş̇̌֔ẇr wa⁠yȧgĕlé⁠m֙ lá⁠rʼẇbéni֣y wĕ⁠la⁠gá̇di֔y wĕ⁠la⁠ẖàẕi֖y şé֣̌bet mĕnaşė֑̌h wa֠⁠yĕbiyʼé⁠m la⁠ẖĕla֨ẖ wĕ⁠ẖáb֤wòr wĕ⁠háráʼ֙ ẇ⁠nĕha֣r ġwòzá֔n ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃p"],[6,1,"בְּנֵ֖י לֵוִ֑י גֵּרְשׁ֕וֹן קְהָ֖ת וּ⁠מְרָרִֽי׃","bĕ̇né֖y léwi֑y gé̇rĕş̌֕wòn qĕhá֖ţ ẇ⁠mĕráriֽy׃"],[6,2,"וּ⁠בְנֵ֖י קְהָ֑ת עַמְרָ֣ם יִצְהָ֔ר וְ⁠חֶבְר֖וֹן וְ⁠עֻזִּיאֵֽל׃ס","ẇ⁠bĕné֖y qĕhá֑ţ ʻamĕrá֣m yiẕĕhá֔r wĕ⁠ẖebĕr֖wòn wĕ⁠ʻuzi̇yʼéֽl׃s"],[6,3,"וּ⁠בְנֵ֣י עַמְרָ֔ם אַהֲרֹ֥ן וּ⁠מֹשֶׁ֖ה וּ⁠מִרְיָ֑ם ס וּ⁠בְנֵ֣י אַהֲרֹ֔ן נָדָב֙ וַ⁠אֲבִיה֔וּא אֶלְעָזָ֖ר וְ⁠אִיתָמָֽר׃ס","ẇ⁠bĕné֣y ʻamĕrá֔m ʼahàrò֥n ẇ⁠mòşě֖h ẇ⁠mirĕyá֑m s ẇ⁠bĕné֣y ʼahàrò֔n nádáb֙ wa⁠ʼàbiyh֔ẇʼ ʼelĕʻázá֖r wĕ⁠ʼiyţámáֽr׃s"],[6,4,"אֶלְעָזָר֙ הוֹלִ֣יד אֶת־פִּֽינְחָ֔ס פִּֽינְחָ֖ס הֹלִ֥יד אֶת־אֲבִישֽׁוּעַ׃","ʼelĕʻázár֙ hwòli֣yd ʼeţ-piֽ̇ynĕẖá֔s piֽ̇ynĕẖá֖s hòli֥yd ʼeţ-ʼàbiyşֽ̌ẇʻa׃"],[6,5,"וַ⁠אֲבִישׁ֨וּעַ֙ הוֹלִ֣יד אֶת־בֻּקִּ֔י וּ⁠בֻקִּ֖י הוֹלִ֥יד אֶת־עֻזִּֽי׃","wa⁠ʼàbiyş̌֨ẇʻa֙ hwòli֣yd ʼeţ-bu̇qi̇֔y ẇ⁠buqi֖̇y hwòli֥yd ʼeţ-ʻuziֽ̇y׃"],[6,6,"וְ⁠עֻזִּי֙ הוֹלִ֣יד אֶת־זְרַֽחְיָ֔ה וּֽ⁠זְרַֽחְיָ֖ה הוֹלִ֥יד אֶת־מְרָיֽוֹת׃","wĕ⁠ʻuzi̇y֙ hwòli֣yd ʼeţ-zĕraֽẖĕyá֔h ẇֽ⁠zĕraֽẖĕyá֖h hwòli֥yd ʼeţ-mĕráyֽwòţ׃"],[6,7,"מְרָיוֹת֙ הוֹלִ֣יד אֶת־אֲמַרְיָ֔ה וַ⁠אֲמַרְיָ֖ה הוֹלִ֥יד אֶת־אֲחִיטֽוּב׃","mĕráywòţ֙ hwòli֣yd ʼeţ-ʼàmarĕyá֔h wa⁠ʼàmarĕyá֖h hwòli֥yd ʼeţ-ʼàẖiytֽẇb׃"],[6,8,"וַ⁠אֲחִיטוּב֙ הוֹלִ֣יד אֶת־צָד֔וֹק וְ⁠צָד֖וֹק הוֹלִ֥יד אֶת־אֲחִימָֽעַץ׃","wa⁠ʼàẖiytẇb֙ hwòli֣yd ʼeţ-ẕád֔wòq wĕ⁠ẕád֖wòq hwòli֥yd ʼeţ-ʼàẖiymáֽʻaẕ׃"],[6,9,"וַ⁠אֲחִימַ֨עַץ֙ הוֹלִ֣יד אֶת־עֲזַרְיָ֔ה וַ⁠עֲזַרְיָ֖ה הוֹלִ֥יד אֶת־יוֹחָנָֽן׃","wa⁠ʼàẖiyma֨ʻaẕ֙ hwòli֣yd ʼeţ-ʻàzarĕyá֔h wa⁠ʻàzarĕyá֖h hwòli֥yd ʼeţ-ywòẖánáֽn׃"],[6,10,"וְ⁠יוֹחָנָ֖ן הוֹלִ֣יד אֶת־עֲזַרְיָ֑ה ה֚וּא אֲשֶׁ֣ר כִּהֵ֔ן בַּ⁠בַּ֕יִת אֲשֶׁר־בָּנָ֥ה שְׁלֹמֹ֖ה בִּ⁠ירוּשָׁלִָֽם׃","wĕ⁠ywòẖáná֖n hwòli֣yd ʼeţ-ʻàzarĕyá֑h h֚ẇʼ ʼàşě֣r ki̇hé֔n bȧ⁠bȧ֕yiţ ʼàşěr-bá̇ná֥h şĕ̌lòmò֖h bi̇⁠yrẇşá̌liáֽm׃"],[6,11,"וַ⁠יּ֥וֹלֶד עֲזַרְיָ֖ה אֶת־אֲמַרְיָ֑ה וַ⁠אֲמַרְיָ֖ה הוֹלִ֥יד אֶת־אֲחִיטֽוּב׃","wa⁠ẏ֥wòled ʻàzarĕyá֖h ʼeţ-ʼàmarĕyá֑h wa⁠ʼàmarĕyá֖h hwòli֥yd ʼeţ-ʼàẖiytֽẇb׃"],[6,12,"וַ⁠אֲחִיטוּב֙ הוֹלִ֣יד אֶת־צָד֔וֹק וְ⁠צָד֖וֹק הוֹלִ֥יד אֶת־שַׁלּֽוּם׃","wa⁠ʼàẖiytẇb֙ hwòli֣yd ʼeţ-ẕád֔wòq wĕ⁠ẕád֖wòq hwòli֥yd ʼeţ-şǎlֽ̇ẇm׃"],[6,13,"וְ⁠שַׁלּוּם֙ הוֹלִ֣יד אֶת־חִלְקִיָּ֔ה וְ⁠חִלְקִיָּ֖ה הוֹלִ֥יד אֶת־עֲזַרְיָֽה׃","wĕ⁠şǎl̇ẇm֙ hwòli֣yd ʼeţ-ẖilĕqiyá̇֔h wĕ⁠ẖilĕqiyá֖̇h hwòli֥yd ʼeţ-ʻàzarĕyáֽh׃"],[6,14,"וַ⁠עֲזַרְיָה֙ הוֹלִ֣יד אֶת־שְׂרָיָ֔ה וּ⁠שְׂרָיָ֖ה הוֹלִ֥יד אֶת־יְהוֹצָדָֽק׃","wa⁠ʻàzarĕyáh֙ hwòli֣yd ʼeţ-şĕ̂ráyá֔h ẇ⁠şĕ̂ráyá֖h hwòli֥yd ʼeţ-yĕhwòẕádáֽq׃"],[6,15,"וִ⁠יהוֹצָדָ֣ק הָלַ֔ךְ בְּ⁠הַגְל֣וֹת יְהוָ֔ה אֶת־יְהוּדָ֖ה וִ⁠ירוּשָׁלִָ֑ם בְּ⁠יַ֖ד נְבֻכַדְנֶאצַּֽר׃ס","wi⁠yhwòẕádá֣q hála֔kĕ bĕ̇⁠hagĕl֣wòţ yĕhwá֔h ʼeţ-yĕhẇdá֖h wi⁠yrẇşá̌liá֑m bĕ̇⁠ya֖d nĕbukadĕneʼẕȧֽr׃s"],[6,16,"בְּנֵ֖י לֵוִ֑י גֵּרְשֹׁ֕ם קְהָ֖ת וּ⁠מְרָרִֽי׃","bĕ̇né֖y léwi֑y gé̇rĕşò̌֕m qĕhá֖ţ ẇ⁠mĕráriֽy׃"],[6,17,"וְ⁠אֵ֛לֶּה שְׁמ֥וֹת בְּֽנֵי־גֵרְשׁ֖וֹם לִבְנִ֥י וְ⁠שִׁמְעִֽי׃","wĕ⁠ʼé֛lėh şĕ̌m֥wòţ bĕֽ̇néy-gérĕş֖̌wòm libĕni֥y wĕ⁠şǐmĕʻiֽy׃"],[6,18,"וּ⁠בְנֵ֖י קְהָ֑ת עַמְרָ֣ם וְ⁠יִצְהָ֔ר וְ⁠חֶבְר֖וֹן וְ⁠עֻזִּיאֵֽל׃","ẇ⁠bĕné֖y qĕhá֑ţ ʻamĕrá֣m wĕ⁠yiẕĕhá֔r wĕ⁠ẖebĕr֖wòn wĕ⁠ʻuzi̇yʼéֽl׃"],[6,19,"בְּנֵ֥י מְרָרִ֖י מַחְלִ֣י וּ⁠מֻשִׁ֑י וְ⁠אֵ֛לֶּה מִשְׁפְּח֥וֹת הַ⁠לֵּוִ֖י לַ⁠אֲבוֹתֵי⁠הֶֽם׃","bĕ̇né֥y mĕrári֖y maẖĕli֣y ẇ⁠muşǐ֑y wĕ⁠ʼé֛lėh mişĕ̌pĕ̇ẖ֥wòţ ha⁠lé̇wi֖y la⁠ʼàbwòţéy⁠heֽm׃"],[6,20,"לְֽ⁠גֵרְשׁ֑וֹם לִבְנִ֥י בְנ֛⁠וֹ יַ֥חַת בְּנ֖⁠וֹ זִמָּ֥ה בְנֽ⁠וֹ׃","lĕֽ⁠gérĕş֑̌wòm libĕni֥y bĕn֛⁠wò ya֥ẖaţ bĕ̇n֖⁠wò zimá֥̇h bĕnֽ⁠wò׃"],[6,21,"יוֹאָ֤ח בְּנ⁠וֹ֙ עִדּ֣וֹ בְנ֔⁠וֹ זֶ֥רַח בְּנ֖⁠וֹ יְאָתְרַ֥י בְּנֽ⁠וֹ׃","ywòʼá֤ẖ bĕ̇n⁠wò֙ ʻiḋ֣wò bĕn֔⁠wò ze֥raẖ bĕ̇n֖⁠wò yĕʼáţĕra֥y bĕ̇nֽ⁠wò׃"],[6,22,"בְּנֵ֖י קְהָ֑ת עַמִּינָדָ֣ב בְּנ֔⁠וֹ קֹ֥רַח בְּנ֖⁠וֹ אַסִּ֥יר בְּנֽ⁠וֹ׃","bĕ̇né֖y qĕhá֑ţ ʻami̇ynádá֣b bĕ̇n֔⁠wò qò֥raẖ bĕ̇n֖⁠wò ʼasi֥̇yr bĕ̇nֽ⁠wò׃"],[6,23,"אֶלְקָנָ֥ה בְנ֛⁠וֹ וְ⁠אֶבְיָסָ֥ף בְּנ֖⁠וֹ וְ⁠אַסִּ֥יר בְּנֽ⁠וֹ׃","ʼelĕqáná֥h bĕn֛⁠wò wĕ⁠ʼebĕyásá֥p bĕ̇n֖⁠wò wĕ⁠ʼasi֥̇yr bĕ̇nֽ⁠wò׃"],[6,24,"תַּ֤חַת בְּנ⁠וֹ֙ אוּרִיאֵ֣ל בְּנ֔⁠וֹ עֻזִּיָּ֥ה בְנ֖⁠וֹ וְ⁠שָׁא֥וּל בְּנֽ⁠וֹ׃","ţȧ֤ẖaţ bĕ̇n⁠wò֙ ʼẇriyʼé֣l bĕ̇n֔⁠wò ʻuzi̇yá֥̇h bĕn֖⁠wò wĕ⁠şá̌ʼ֥ẇl bĕ̇nֽ⁠wò׃"],[6,25,"וּ⁠בְנֵי֙ אֶלְקָנָ֔ה עֲמָשַׂ֖י וַ⁠אֲחִימֽוֹת׃","ẇ⁠bĕnéy֙ ʼelĕqáná֔h ʻàmáşâ֖y wa⁠ʼàẖiymֽwòţ׃"],[6,26,"אֶלְקָנָ֑ה בנ⁠ו אֶלְקָנָ֔ה צוֹפַ֥י בְּנ֖⁠וֹ וְ⁠נַ֥חַת בְּנֽ⁠וֹ׃","ʼelĕqáná֑h bn⁠w ʼelĕqáná֔h ẕwòpa֥y bĕ̇n֖⁠wò wĕ⁠na֥ẖaţ bĕ̇nֽ⁠wò׃"],[6,27,"אֱלִיאָ֥ב בְּנ֛⁠וֹ יְרֹחָ֥ם בְּנ֖⁠וֹ אֶלְקָנָ֥ה בְנֽ⁠וֹ׃","ʼèliyʼá֥b bĕ̇n֛⁠wò yĕròẖá֥m bĕ̇n֖⁠wò ʼelĕqáná֥h bĕnֽ⁠wò׃"],[6,28,"וּ⁠בְנֵ֧י שְׁמוּאֵ֛ל הַ⁠בְּכֹ֥ר וַשְׁנִ֖י וַ⁠אֲבִיָּֽה׃ס","ẇ⁠bĕné֧y şĕ̌mẇʼé֛l ha⁠bĕ̇kò֥r waşĕ̌ni֖y wa⁠ʼàbiyáֽ̇h׃s"],[6,29,"בְּנֵ֥י מְרָרִ֖י מַחְלִ֑י לִבְנִ֥י בְנ֛⁠וֹ שִׁמְעִ֥י בְנ֖⁠וֹ עֻזָּ֥ה בְנֽ⁠וֹ׃","bĕ̇né֥y mĕrári֖y maẖĕli֑y libĕni֥y bĕn֛⁠wò şǐmĕʻi֥y bĕn֖⁠wò ʻuzá֥̇h bĕnֽ⁠wò׃"],[6,30,"שִׁמְעָ֥א בְנ֛⁠וֹ חַגִּיָּ֥ה בְנ֖⁠וֹ עֲשָׂיָ֥ה בְנֽ⁠וֹ׃פ","şǐmĕʻá֥ʼ bĕn֛⁠wò ẖagi̇yá֥̇h bĕn֖⁠wò ʻàşá̂yá֥h bĕnֽ⁠wò׃p"],[6,31,"וְ⁠אֵ֗לֶּה אֲשֶׁ֨ר הֶעֱמִ֥יד דָּוִ֛יד עַל־יְדֵי־שִׁ֖יר בֵּ֣ית יְהוָ֑ה מִ⁠מְּנ֖וֹחַ הָ⁠אָרֽוֹן׃","wĕ⁠ʼé֗lėh ʼàşě֨r heʻèmi֥yd dá̇wi֛yd ʻal-yĕdéy-şǐ֖yr bé֣̇yţ yĕhwá֑h mi⁠mĕ̇n֖wòẖa há⁠ʼárֽwòn׃"],[6,32,"וַ⁠יִּהְי֨וּ מְשָׁרְתִ֜ים לִ⁠פְנֵ֨י מִשְׁכַּ֤ן אֹֽהֶל־מוֹעֵד֙ בַּ⁠שִּׁ֔יר עַד־בְּנ֧וֹת שְׁלֹמֹ֛ה אֶת־בֵּ֥ית יְהוָ֖ה בִּ⁠ירוּשָׁלִָ֑ם וַ⁠יַּעַמְד֥וּ כְ⁠מִשְׁפָּטָ֖⁠ם עַל־עֲבוֹדָתָֽ⁠ם׃","wa⁠yi̇hĕy֨ẇ mĕşá̌rĕţi֜ym li⁠pĕné֨y mişĕ̌kȧ֤n ʼòֽhel-mwòʻéd֙ bȧ⁠şi̇̌֔yr ʻad-bĕ̇n֧wòţ şĕ̌lòmò֛h ʼeţ-bé֥̇yţ yĕhwá֖h bi̇⁠yrẇşá̌liá֑m wa⁠yȧʻamĕd֥ẇ kĕ⁠mişĕ̌pá̇tá֖⁠m ʻal-ʻàbwòdáţáֽ⁠m׃"],[6,33,"וְ⁠אֵ֥לֶּה הָ⁠עֹמְדִ֖ים וּ⁠בְנֵי⁠הֶ֑ם מִ⁠בְּנֵי֙ הַ⁠קְּהָתִ֔י הֵימָן֙ הַ⁠מְשׁוֹרֵ֔ר בֶּן־יוֹאֵ֖ל בֶּן־שְׁמוּאֵֽל׃","wĕ⁠ʼé֥lėh há⁠ʻòmĕdi֖ym ẇ⁠bĕnéy⁠he֑m mi⁠bĕ̇néy֙ ha⁠qĕ̇háţi֔y héymán֙ ha⁠mĕş̌wòré֔r bėn-ywòʼé֖l bėn-şĕ̌mẇʼéֽl׃"],[6,34,"בֶּן־אֶלְקָנָה֙ בֶּן־יְרֹחָ֔ם בֶּן־אֱלִיאֵ֖ל בֶּן־תּֽוֹחַ׃","bėn-ʼelĕqánáh֙ bėn-yĕròẖá֔m bėn-ʼèliyʼé֖l bėn-ţֽ̇wòẖa׃"],[6,35,"בֶּן־ציף בֶּן־אֶלְקָנָ֔ה בֶּן־מַ֖חַת בֶּן־עֲמָשָֽׂי׃","bėn-ẕyp bėn-ʼelĕqáná֔h bėn-ma֖ẖaţ bėn-ʻàmáşáֽ̂y׃"],[6,36,"בֶּן־אֶלְקָנָה֙ בֶּן־יוֹאֵ֔ל בֶּן־עֲזַרְיָ֖ה בֶּן־צְפַנְיָֽה׃","bėn-ʼelĕqánáh֙ bėn-ywòʼé֔l bėn-ʻàzarĕyá֖h bėn-ẕĕpanĕyáֽh׃"],[6,37,"בֶּן־תַּ֨חַת֙ בֶּן־אַסִּ֔יר בֶּן־אֶבְיָסָ֖ף בֶּן־קֹֽרַח׃","bėn-ţȧ֨ẖaţ֙ bėn-ʼasi̇֔yr bėn-ʼebĕyásá֖p bėn-qòֽraẖ׃"],[6,38,"בֶּן־יִצְהָ֣ר בֶּן־קְהָ֔ת בֶּן־לֵוִ֖י בֶּן־יִשְׂרָאֵֽל׃","bėn-yiẕĕhá֣r bėn-qĕhá֔ţ bėn-léwi֖y bėn-yişĕ̂ráʼéֽl׃"],[6,39,"וְ⁠אָחִ֣י⁠ו אָסָ֔ף הָ⁠עֹמֵ֖ד עַל־יְמִינ֑⁠וֹ אָסָ֥ף בֶּן־בֶּרֶכְיָ֖הוּ בֶּן־שִׁמְעָֽא׃","wĕ⁠ʼáẖi֣y⁠w ʼásá֔p há⁠ʻòmé֖d ʻal-yĕmiyn֑⁠wò ʼásá֥p bėn-bėrekĕyá֖hẇ bėn-şǐmĕʻáֽʼ׃"],[6,40,"בֶּן־מִיכָאֵ֥ל בֶּן־בַּעֲשֵׂיָ֖ה בֶּן־מַלְכִּיָּֽה׃","bėn-miykáʼé֥l bėn-bȧʻàşé̂yá֖h bėn-malĕki̇yáֽ̇h׃"],[6,41,"בֶּן־אֶתְנִ֥י בֶן־זֶ֖רַח בֶּן־עֲדָיָֽה׃","bėn-ʼeţĕni֥y ben-ze֖raẖ bėn-ʻàdáyáֽh׃"],[6,42,"בֶּן־אֵיתָ֥ן בֶּן־זִמָּ֖ה בֶּן־שִׁמְעִֽי׃","bėn-ʼéyţá֥n bėn-zimá֖̇h bėn-şǐmĕʻiֽy׃"],[6,43,"בֶּן־יַ֥חַת בֶּן־גֵּרְשֹׁ֖ם בֶּן־לֵוִֽי׃ס","bėn-ya֥ẖaţ bėn-gé̇rĕşò֖̌m bėn-léwiֽy׃s"],[6,44,"וּ⁠בְנֵ֧י מְרָרִ֛י אֲחֵי⁠הֶ֖ם עַֽל־הַ⁠שְּׂמֹ֑אול אֵיתָן֙ בֶּן־קִישִׁ֔י בֶּן־עַבְדִּ֖י בֶּן־מַלּֽוּךְ׃","ẇ⁠bĕné֧y mĕrári֛y ʼàẖéy⁠he֖m ʻaֽl-ha⁠şĕ̇̂mò֑ʼwl ʼéyţán֙ bėn-qiyşǐ֔y bėn-ʻabĕdi֖̇y bėn-malֽ̇ẇkĕ׃"],[6,45,"בֶּן־חֲשַׁבְיָ֥ה בֶן־אֲמַצְיָ֖ה בֶּן־חִלְקִיָּֽה׃","bėn-ẖàşǎbĕyá֥h ben-ʼàmaẕĕyá֖h bėn-ẖilĕqiyáֽ̇h׃"],[6,46,"בֶּן־אַמְצִ֥י בֶן־בָּנִ֖י בֶּן־שָֽׁמֶר׃","bėn-ʼamĕẕi֥y ben-bá̇ni֖y bėn-şáֽ̌mer׃"],[6,47,"בֶּן־מַחְלִי֙ בֶּן־מוּשִׁ֔י בֶּן־מְרָרִ֖י בֶּן־לֵוִֽי׃ס","bėn-maẖĕliy֙ bėn-mẇşǐ֔y bėn-mĕrári֖y bėn-léwiֽy׃s"],[6,48,"וַ⁠אֲחֵי⁠הֶ֖ם הַ⁠לְוִיִּ֑ם נְתוּנִ֕ים לְ⁠כָ֨ל־עֲבוֹדַ֔ת מִשְׁכַּ֖ן בֵּ֥ית הָ⁠אֱלֹהִֽים׃","wa⁠ʼàẖéy⁠he֖m ha⁠lĕwiyi֑̇m nĕţẇni֕ym lĕ⁠ká֨l-ʻàbwòda֔ţ mişĕ̌kȧ֖n bé֥̇yţ há⁠ʼèlòhiֽym׃"],[6,49,"וְֽ⁠אַהֲרֹ֨ן וּ⁠בָנָ֜י⁠ו מַקְטִירִ֨ים עַל־מִזְבַּ֤ח הָֽ⁠עוֹלָה֙ וְ⁠עַל־מִזְבַּ֣ח הַ⁠קְּטֹ֔רֶת לְ⁠כֹ֕ל מְלֶ֖אכֶת קֹ֣דֶשׁ הַ⁠קֳּדָשִׁ֑ים וּ⁠לְ⁠כַפֵּר֙ עַל־יִשְׂרָאֵ֔ל כְּ⁠כֹל֙ אֲשֶׁ֣ר צִוָּ֔ה מֹשֶׁ֖ה עֶ֥בֶד הָ⁠אֱלֹהִֽים׃פ","wĕֽ⁠ʼahàrò֨n ẇ⁠báná֜y⁠w maqĕtiyri֨ym ʻal-mizĕbȧ֤ẖ háֽ⁠ʻwòláh֙ wĕ⁠ʻal-mizĕbȧ֣ẖ ha⁠qĕ̇tò֔reţ lĕ⁠kò֕l mĕle֖ʼkeţ qò֣deş̌ ha⁠qȯdáşǐ֑ym ẇ⁠lĕ⁠kapé̇r֙ ʻal-yişĕ̂ráʼé֔l kĕ̇⁠kòl֙ ʼàşě֣r ẕiwá̇֔h mòşě֖h ʻe֥bed há⁠ʼèlòhiֽym׃p"],[6,50,"וְ⁠אֵ֖לֶּה בְּנֵ֣י אַהֲרֹ֑ן אֶלְעָזָ֥ר בְּנ֛⁠וֹ פִּֽינְחָ֥ס בְּנ֖⁠וֹ אֲבִישׁ֥וּעַ בְּנֽ⁠וֹ׃","wĕ⁠ʼé֖lėh bĕ̇né֣y ʼahàrò֑n ʼelĕʻázá֥r bĕ̇n֛⁠wò piֽ̇ynĕẖá֥s bĕ̇n֖⁠wò ʼàbiyş֥̌ẇʻa bĕ̇nֽ⁠wò׃"],[6,51,"בֻּקִּ֥י בְנ֛⁠וֹ עֻזִּ֥י בְנ֖⁠וֹ זְרַֽחְיָ֥ה בְנֽ⁠וֹ׃","bu̇qi֥̇y bĕn֛⁠wò ʻuzi֥̇y bĕn֖⁠wò zĕraֽẖĕyá֥h bĕnֽ⁠wò׃"],[6,52,"מְרָי֥וֹת בְּנ֛⁠וֹ אֲמַרְיָ֥ה בְנ֖⁠וֹ אֲחִיט֥וּב בְּנֽ⁠וֹ׃","mĕráy֥wòţ bĕ̇n֛⁠wò ʼàmarĕyá֥h bĕn֖⁠wò ʼàẖiyt֥ẇb bĕ̇nֽ⁠wò׃"],[6,53,"צָד֥וֹק בְּנ֖⁠וֹ אֲחִימַ֥עַץ בְּנֽ⁠וֹ׃ס","ẕád֥wòq bĕ̇n֖⁠wò ʼàẖiyma֥ʻaẕ bĕ̇nֽ⁠wò׃s"],[6,54,"וְ⁠אֵ֨לֶּה֙ מוֹשְׁבוֹתָ֔⁠ם לְ⁠טִירוֹתָ֖⁠ם בִּ⁠גְבוּלָ֑⁠ם לִ⁠בְנֵ֤י אַהֲרֹן֙ לְ⁠מִשְׁפַּחַ֣ת הַ⁠קְּהָתִ֔י כִּ֥י לָ⁠הֶ֖ם הָיָ֥ה הַ⁠גּוֹרָֽל׃","wĕ⁠ʼé֨lėh֙ mwòşĕ̌bwòţá֔⁠m lĕ⁠tiyrwòţá֖⁠m bi̇⁠gĕbẇlá֑⁠m li⁠bĕné֤y ʼahàròn֙ lĕ⁠mişĕ̌pȧẖa֣ţ ha⁠qĕ̇háţi֔y ki֥̇y lá⁠he֖m háyá֥h ha⁠ġwòráֽl׃"],[6,55,"וַֽ⁠יִּתְּנ֥וּ לָ⁠הֶ֛ם אֶת־חֶבְר֖וֹן בְּ⁠אֶ֣רֶץ יְהוּדָ֑ה וְ⁠אֶת־מִגְרָשֶׁ֖י⁠הָ סְבִיבֹתֶֽי⁠הָ׃","waֽ⁠yi̇ţĕ̇n֥ẇ lá⁠he֛m ʼeţ-ẖebĕr֖wòn bĕ̇⁠ʼe֣reẕ yĕhẇdá֑h wĕ⁠ʼeţ-migĕráşě֖y⁠há sĕbiybòţeֽy⁠há׃"],[6,56,"וְ⁠אֶת־שְׂדֵ֥ה הָ⁠עִ֖יר וְ⁠אֶת־חֲצֵרֶ֑י⁠הָ נָתְנ֖וּ לְ⁠כָלֵ֥ב בֶּן־יְפֻנֶּֽה׃ס","wĕ⁠ʼeţ-şĕ̂dé֥h há⁠ʻi֖yr wĕ⁠ʼeţ-ẖàẕére֑y⁠há náţĕn֖ẇ lĕ⁠kálé֥b bėn-yĕpunėֽh׃s"],[6,57,"וְ⁠לִ⁠בְנֵ֣י אַהֲרֹ֗ן נָתְנוּ֙ אֶת־עָרֵ֣י הַ⁠מִּקְלָ֔ט אֶת־חֶבְר֥וֹן וְ⁠אֶת־לִבְנָ֖ה וְ⁠אֶת־מִגְרָשֶׁ֑י⁠הָ וְ⁠אֶת־יַתִּ֥ר וְ⁠אֶֽת־אֶשְׁתְּמֹ֖עַ וְ⁠אֶת־מִגְרָשֶֽׁי⁠הָ׃","wĕ⁠li⁠bĕné֣y ʼahàrò֗n náţĕnẇ֙ ʼeţ-ʻáré֣y ha⁠mi̇qĕlá֔t ʼeţ-ẖebĕr֥wòn wĕ⁠ʼeţ-libĕná֖h wĕ⁠ʼeţ-migĕráşě֑y⁠há wĕ⁠ʼeţ-yaţi֥̇r wĕ⁠ʼeֽţ-ʼeşĕ̌ţĕ̇mò֖ʻa wĕ⁠ʼeţ-migĕráşěֽy⁠há׃"],[6,58,"וְ⁠אֶת־חִילֵז֙ וְ⁠אֶת־מִגְרָשֶׁ֔י⁠הָ אֶת־דְּבִ֖יר וְ⁠אֶת־מִגְרָשֶֽׁי⁠הָ׃","wĕ⁠ʼeţ-ẖiyléz֙ wĕ⁠ʼeţ-migĕráşě֔y⁠há ʼeţ-dĕ̇bi֖yr wĕ⁠ʼeţ-migĕráşěֽy⁠há׃"],[6,59,"וְ⁠אֶת־עָשָׁן֙ וְ⁠אֶת־מִגְרָשֶׁ֔י⁠הָ וְ⁠אֶת־בֵּ֥ית שֶׁ֖מֶשׁ וְ⁠אֶת־מִגְרָשֶֽׁי⁠הָ׃ס","wĕ⁠ʼeţ-ʻáşá̌n֙ wĕ⁠ʼeţ-migĕráşě֔y⁠há wĕ⁠ʼeţ-bé֥̇yţ şě֖meş̌ wĕ⁠ʼeţ-migĕráşěֽy⁠há׃s"],[6,60,"וּ⁠מִ⁠מַּטֵּ֣ה בִנְיָמִ֗ן אֶת־גֶּ֤בַע וְ⁠אֶת־מִגְרָשֶׁ֨י⁠הָ֙ וְ⁠אֶת־עָלֶ֣מֶת וְ⁠אֶת־מִגְרָשֶׁ֔י⁠הָ וְ⁠אֶת־עֲנָת֖וֹת וְ⁠אֶת־מִגְרָשֶׁ֑י⁠הָ כָּל־עָרֵי⁠הֶ֛ם שְׁלֹשׁ־עֶשְׂרֵ֥ה עִ֖יר בְּ⁠מִשְׁפְּחוֹתֵי⁠הֶֽם׃ס","ẇ⁠mi⁠mȧté֣̇h binĕyámi֗n ʼeţ-gė֤baʻ wĕ⁠ʼeţ-migĕráşě֨y⁠há֙ wĕ⁠ʼeţ-ʻále֣meţ wĕ⁠ʼeţ-migĕráşě֔y⁠há wĕ⁠ʼeţ-ʻànáţ֖wòţ wĕ⁠ʼeţ-migĕráşě֑y⁠há ká̇l-ʻáréy⁠he֛m şĕ̌lòş̌-ʻeşĕ̂ré֥h ʻi֖yr bĕ̇⁠mişĕ̌pĕ̇ẖwòţéy⁠heֽm׃s"],[6,61,"וְ⁠לִ⁠בְנֵ֨י קְהָ֜ת הַ⁠נּוֹתָרִ֗ים מִ⁠מִּשְׁפַּ֣חַת הַ⁠מַּטֶּ֡ה מִֽ֠⁠מַּחֲצִית מַטֵּ֨ה חֲצִ֧י מְנַשֶּׁ֛ה בַּ⁠גּוֹרָ֖ל עָרִ֥ים עָֽשֶׂר׃ס","wĕ⁠li⁠bĕné֨y qĕhá֜ţ ha⁠ṅwòţári֗ym mi⁠mi̇şĕ̌pȧ֣ẖaţ ha⁠mȧtė֡h miֽ֠⁠mȧẖàẕiyţ maté̇֨h ẖàẕi֧y mĕnaşė֛̌h bȧ⁠ġwòrá֖l ʻári֥ym ʻáֽşêr׃s"],[6,62,"וְ⁠לִ⁠בְנֵ֨י גֵרְשׁ֜וֹם לְ⁠מִשְׁפְּחוֹתָ֗⁠ם מִ⁠מַּטֵּ֣ה יִ֠שָׂשכָר וּ⁠מִ⁠מַּטֵּ֨ה אָשֵׁ֜ר וּ⁠מִ⁠מַּטֵּ֣ה נַפְתָּלִ֗י וּ⁠מִ⁠מַּטֵּ֤ה מְנַשֶּׁה֙ בַּ⁠בָּשָׁ֔ן עָרִ֖ים שְׁלֹ֥שׁ עֶשְׂרֵֽה׃ס","wĕ⁠li⁠bĕné֨y gérĕş̌֜wòm lĕ⁠mişĕ̌pĕ̇ẖwòţá֗⁠m mi⁠mȧté֣̇h yi֠şá̂şkár ẇ⁠mi⁠mȧté̇֨h ʼáşé̌֜r ẇ⁠mi⁠mȧté֣̇h napĕţá̇li֗y ẇ⁠mi⁠mȧté֤̇h mĕnaşė̌h֙ bȧ⁠bá̇şá̌֔n ʻári֖ym şĕ̌lò֥ş̌ ʻeşĕ̂réֽh׃s"],[6,63,"לִ⁠בְנֵ֨י מְרָרִ֜י לְ⁠מִשְׁפְּחוֹתָ֗⁠ם מִ⁠מַּטֵּ֣ה רְ֠אוּבֵן וּֽ⁠מִ⁠מַּטֵּה־גָ֞ד וּ⁠מִ⁠מַּטֵּ֤ה זְבוּלֻן֙ בַּ⁠גּוֹרָ֔ל עָרִ֖ים שְׁתֵּ֥ים עֶשְׂרֵֽה׃","li⁠bĕné֨y mĕrári֜y lĕ⁠mişĕ̌pĕ̇ẖwòţá֗⁠m mi⁠mȧté֣̇h rĕ֠ʼẇbén ẇֽ⁠mi⁠mȧté̇h-gá֞d ẇ⁠mi⁠mȧté֤̇h zĕbẇlun֙ bȧ⁠ġwòrá֔l ʻári֖ym şĕ̌ţé֥̇ym ʻeşĕ̂réֽh׃"],[6,64,"וַ⁠יִּתְּנ֥וּ בְנֵי־יִשְׂרָאֵ֖ל לַ⁠לְוִיִּ֑ם אֶת־הֶ⁠עָרִ֖ים וְ⁠אֶת־מִגְרְשֵׁי⁠הֶֽם׃","wa⁠yi̇ţĕ̇n֥ẇ bĕnéy-yişĕ̂ráʼé֖l la⁠lĕwiyi֑̇m ʼeţ-he⁠ʻári֖ym wĕ⁠ʼeţ-migĕrĕşé̌y⁠heֽm׃"],[6,65,"וַ⁠יִּתְּנ֣וּ בַ⁠גּוֹרָ֗ל מִ⁠מַּטֵּ֤ה בְנֵי־יְהוּדָה֙ וּ⁠מִ⁠מַּטֵּ֣ה בְנֵי־שִׁמְע֔וֹן וּ⁠מִ⁠מַּטֵּ֖ה בְּנֵ֣י בִנְיָמִ֑ן אֵ֚ת הֶ⁠עָרִ֣ים הָ⁠אֵ֔לֶּה אֲשֶׁר־יִקְרְא֥וּ אֶתְ⁠הֶ֖ם בְּ⁠שֵׁמֽוֹת׃ס","wa⁠yi̇ţĕ̇n֣ẇ ba⁠ġwòrá֗l mi⁠mȧté֤̇h bĕnéy-yĕhẇdáh֙ ẇ⁠mi⁠mȧté֣̇h bĕnéy-şǐmĕʻ֔wòn ẇ⁠mi⁠mȧté֖̇h bĕ̇né֣y binĕyámi֑n ʼé֚ţ he⁠ʻári֣ym há⁠ʼé֔lėh ʼàşěr-yiqĕrĕʼ֥ẇ ʼeţĕ⁠he֖m bĕ̇⁠şé̌mֽwòţ׃s"],[6,66,"וּ⁠מִֽ⁠מִּשְׁפְּח֖וֹת בְּנֵ֣י קְהָ֑ת וַ⁠יְהִי֙ עָרֵ֣י גְבוּלָ֔⁠ם מִ⁠מַּטֵּ֖ה אֶפְרָֽיִם׃","ẇ⁠miֽ⁠mi̇şĕ̌pĕ̇ẖ֖wòţ bĕ̇né֣y qĕhá֑ţ wa⁠yĕhiy֙ ʻáré֣y gĕbẇlá֔⁠m mi⁠mȧté֖̇h ʼepĕráֽyim׃"],[6,67,"וַ⁠יִּתְּנ֨וּ לָ⁠הֶ֜ם אֶת־עָרֵ֧י הַ⁠מִּקְלָ֛ט אֶת־שְׁכֶ֥ם וְ⁠אֶת־מִגְרָשֶׁ֖י⁠הָ בְּ⁠הַ֣ר אֶפְרָ֑יִם וְ⁠אֶת־גֶּ֖זֶר וְ⁠אֶת־מִגְרָשֶֽׁי⁠הָ׃","wa⁠yi̇ţĕ̇n֨ẇ lá⁠he֜m ʼeţ-ʻáré֧y ha⁠mi̇qĕlá֛t ʼeţ-şĕ̌ke֥m wĕ⁠ʼeţ-migĕráşě֖y⁠há bĕ̇⁠ha֣r ʼepĕrá֑yim wĕ⁠ʼeţ-gė֖zer wĕ⁠ʼeţ-migĕráşěֽy⁠há׃"],[6,68,"וְ⁠אֶֽת־יָקְמְעָם֙ וְ⁠אֶת־מִגְרָשֶׁ֔י⁠הָ וְ⁠אֶת־בֵּ֥ית חוֹר֖וֹן וְ⁠אֶת־מִגְרָשֶֽׁי⁠הָ׃","wĕ⁠ʼeֽţ-yáqĕmĕʻám֙ wĕ⁠ʼeţ-migĕráşě֔y⁠há wĕ⁠ʼeţ-bé֥̇yţ ẖwòr֖wòn wĕ⁠ʼeţ-migĕráşěֽy⁠há׃"],[6,69,"וְ⁠אֶת־אַיָּלוֹן֙ וְ⁠אֶת־מִגְרָשֶׁ֔י⁠הָ וְ⁠אֶת־גַּת־רִמּ֖וֹן וְ⁠אֶת־מִגְרָשֶֽׁי⁠הָ׃פ","wĕ⁠ʼeţ-ʼayá̇lwòn֙ wĕ⁠ʼeţ-migĕráşě֔y⁠há wĕ⁠ʼeţ-gȧţ-riṁ֖wòn wĕ⁠ʼeţ-migĕráşěֽy⁠há׃p"],[6,70,"וּ⁠מִֽ⁠מַּחֲצִית֙ מַטֵּ֣ה מְנַשֶּׁ֔ה אֶת־עָנֵר֙ וְ⁠אֶת־מִגְרָשֶׁ֔י⁠הָ וְ⁠אֶת־בִּלְעָ֖ם וְ⁠אֶת־מִגְרָשֶׁ֑י⁠הָ לְ⁠מִשְׁפַּ֥חַת לִ⁠בְנֵי־קְהָ֖ת הַ⁠נּוֹתָרִֽים׃פ","ẇ⁠miֽ⁠mȧẖàẕiyţ֙ maté֣̇h mĕnaşė̌֔h ʼeţ-ʻánér֙ wĕ⁠ʼeţ-migĕráşě֔y⁠há wĕ⁠ʼeţ-bi̇lĕʻá֖m wĕ⁠ʼeţ-migĕráşě֑y⁠há lĕ⁠mişĕ̌pȧ֥ẖaţ li⁠bĕnéy-qĕhá֖ţ ha⁠ṅwòţáriֽym׃p"],[6,71,"לִ⁠בְנֵי֮ גֵּרְשׁוֹם֒ מִ⁠מִּשְׁפַּ֗חַת חֲצִי֙ מַטֵּ֣ה מְנַשֶּׁ֔ה אֶת־גּוֹלָ֥ן בַּ⁠בָּשָׁ֖ן וְ⁠אֶת־מִגְרָשֶׁ֑י⁠הָ וְ⁠אֶת־עַשְׁתָּר֖וֹת וְ⁠אֶת־מִגְרָשֶֽׁי⁠הָ׃ס","li⁠bĕnéy֮ gé̇rĕş̌wòm֒ mi⁠mi̇şĕ̌pȧ֗ẖaţ ẖàẕiy֙ maté֣̇h mĕnaşė̌֔h ʼeţ-ġwòlá֥n bȧ⁠bá̇şá֖̌n wĕ⁠ʼeţ-migĕráşě֑y⁠há wĕ⁠ʼeţ-ʻaşĕ̌ţá̇r֖wòţ wĕ⁠ʼeţ-migĕráşěֽy⁠há׃s"],[6,72,"וּ⁠מִ⁠מַּטֵּ֣ה יִשָׂשכָ֔ר אֶת־קֶ֖דֶשׁ וְ⁠אֶת־מִגְרָשֶׁ֑י⁠הָ אֶת־דָּבְרַ֖ת וְ⁠אֶת־מִגְרָשֶֽׁי⁠הָ׃","ẇ⁠mi⁠mȧté֣̇h yişá̂şká֔r ʼeţ-qe֖deş̌ wĕ⁠ʼeţ-migĕráşě֑y⁠há ʼeţ-dá̇bĕra֖ţ wĕ⁠ʼeţ-migĕráşěֽy⁠há׃"],[6,73,"וְ⁠אֶת־רָאמוֹת֙ וְ⁠אֶת־מִגְרָשֶׁ֔י⁠הָ וְ⁠אֶת־עָנֵ֖ם וְ⁠אֶת־מִגְרָשֶֽׁי⁠הָ׃ס","wĕ⁠ʼeţ-ráʼmwòţ֙ wĕ⁠ʼeţ-migĕráşě֔y⁠há wĕ⁠ʼeţ-ʻáné֖m wĕ⁠ʼeţ-migĕráşěֽy⁠há׃s"],[6,74,"וּ⁠מִ⁠מַּטֵּ֣ה אָשֵׁ֔ר אֶת־מָשָׁ֖ל וְ⁠אֶת־מִגְרָשֶׁ֑י⁠הָ וְ⁠אֶת־עַבְדּ֖וֹן וְ⁠אֶת־מִגְרָשֶֽׁי⁠הָ׃","ẇ⁠mi⁠mȧté֣̇h ʼáşé̌֔r ʼeţ-máşá֖̌l wĕ⁠ʼeţ-migĕráşě֑y⁠há wĕ⁠ʼeţ-ʻabĕḋ֖wòn wĕ⁠ʼeţ-migĕráşěֽy⁠há׃"],[6,75,"וְ⁠אֶת־חוּקֹק֙ וְ⁠אֶת־מִגְרָשֶׁ֔י⁠הָ וְ⁠אֶת־רְחֹ֖ב וְ⁠אֶת־מִגְרָשֶֽׁי⁠הָ׃","wĕ⁠ʼeţ-ẖẇqòq֙ wĕ⁠ʼeţ-migĕráşě֔y⁠há wĕ⁠ʼeţ-rĕẖò֖b wĕ⁠ʼeţ-migĕráşěֽy⁠há׃"],[6,76,"וּ⁠מִ⁠מַּטֵּ֣ה נַפְתָּלִ֗י אֶת־קֶ֤דֶשׁ בַּ⁠גָּלִיל֙ וְ⁠אֶת־מִגְרָשֶׁ֔י⁠הָ וְ⁠אֶת־חַמּ֖וֹן וְ⁠אֶת־מִגְרָשֶׁ֑י⁠הָ וְ⁠אֶת־קִרְיָתַ֖יִם וְ⁠אֶת־מִגְרָשֶֽׁי⁠הָ׃ס","ẇ⁠mi⁠mȧté֣̇h napĕţá̇li֗y ʼeţ-qe֤deş̌ bȧ⁠gá̇liyl֙ wĕ⁠ʼeţ-migĕráşě֔y⁠há wĕ⁠ʼeţ-ẖaṁ֖wòn wĕ⁠ʼeţ-migĕráşě֑y⁠há wĕ⁠ʼeţ-qirĕyáţa֖yim wĕ⁠ʼeţ-migĕráşěֽy⁠há׃s"],[6,77,"לִ⁠בְנֵ֣י מְרָרִי֮ הַ⁠נּוֹתָרִים֒ מִ⁠מַּטֵּ֣ה זְבוּלֻ֔ן אֶת־רִמּוֹנ֖וֹ וְ⁠אֶת־מִגְרָשֶׁ֑י⁠הָ אֶת־תָּב֖וֹר וְ⁠אֶת־מִגְרָשֶֽׁי⁠הָ׃","li⁠bĕné֣y mĕráriy֮ ha⁠ṅwòţáriym֒ mi⁠mȧté֣̇h zĕbẇlu֔n ʼeţ-riṁwòn֖wò wĕ⁠ʼeţ-migĕráşě֑y⁠há ʼeţ-ţá̇b֖wòr wĕ⁠ʼeţ-migĕráşěֽy⁠há׃"],[6,78,"וּ⁠מֵ⁠עֵ֜בֶר לְ⁠יַרְדֵּ֣ן יְרֵחוֹ֮ לְ⁠מִזְרַ֣ח הַ⁠יַּרְדֵּן֒ מִ⁠מַּטֵּ֣ה רְאוּבֵ֔ן אֶת־בֶּ֥צֶר בַּ⁠מִּדְבָּ֖ר וְ⁠אֶת־מִגְרָשֶׁ֑י⁠הָ וְ⁠אֶת־יַ֖הְצָ⁠ה וְ⁠אֶת־מִגְרָשֶֽׁי⁠הָ׃","ẇ⁠mé⁠ʻé֜ber lĕ⁠yarĕdé֣̇n yĕréẖwò֮ lĕ⁠mizĕra֣ẖ ha⁠yȧrĕdé̇n֒ mi⁠mȧté֣̇h rĕʼẇbé֔n ʼeţ-bė֥ẕer bȧ⁠mi̇dĕbá֖̇r wĕ⁠ʼeţ-migĕráşě֑y⁠há wĕ⁠ʼeţ-ya֖hĕẕá⁠h wĕ⁠ʼeţ-migĕráşěֽy⁠há׃"],[6,79,"וְ⁠אֶת־קְדֵמוֹת֙ וְ⁠אֶת־מִגְרָשֶׁ֔י⁠הָ וְ⁠אֶת־מֵיפַ֖עַת וְ⁠אֶת־מִגְרָשֶֽׁי⁠הָ׃","wĕ⁠ʼeţ-qĕdémwòţ֙ wĕ⁠ʼeţ-migĕráşě֔y⁠há wĕ⁠ʼeţ-méypa֖ʻaţ wĕ⁠ʼeţ-migĕráşěֽy⁠há׃"],[6,80,"וּ⁠מִ֨⁠מַּטֵּה־גָ֔ד אֶת־רָאמ֥וֹת בַּ⁠גִּלְעָ֖ד וְ⁠אֶת־מִגְרָשֶׁ֑י⁠הָ וְ⁠אֶֽת־מַחֲנַ֖יִם וְ⁠אֶת־מִגְרָשֶֽׁי⁠הָ׃","ẇ⁠mi֨⁠mȧté̇h-gá֔d ʼeţ-ráʼm֥wòţ bȧ⁠gi̇lĕʻá֖d wĕ⁠ʼeţ-migĕráşě֑y⁠há wĕ⁠ʼeֽţ-maẖàna֖yim wĕ⁠ʼeţ-migĕráşěֽy⁠há׃"],[6,81,"וְ⁠אֶת־חֶשְׁבּוֹן֙ וְ⁠אֶת־מִגְרָשֶׁ֔י⁠הָ וְ⁠אֶת־יַעְזֵ֖יר וְ⁠אֶת־מִגְרָשֶֽׁי⁠הָ׃ס","wĕ⁠ʼeţ-ẖeşĕ̌ḃwòn֙ wĕ⁠ʼeţ-migĕráşě֔y⁠há wĕ⁠ʼeţ-yaʻĕzé֖yr wĕ⁠ʼeţ-migĕráşěֽy⁠há׃s"],[7,1,"וְ⁠לִ⁠בְנֵ֣י יִשָׂשכָ֗ר תּוֹלָ֧ע וּ⁠פוּאָ֛ה ישיב וְ⁠שִׁמְר֖וֹן אַרְבָּעָֽה׃ס","wĕ⁠li⁠bĕné֣y yişá̂şká֗r ţ̇wòlá֧ʻ ẇ⁠pẇʼá֛h yşyb wĕ⁠şǐmĕr֖wòn ʼarĕbá̇ʻáֽh׃s"],[7,2,"וּ⁠בְנֵ֣י תוֹלָ֗ע עֻזִּ֡י וּ⁠רְפָיָ֡ה וִֽ֠⁠ירִיאֵל וְ⁠יַחְמַ֨י וְ⁠יִבְשָׂ֜ם וּ⁠שְׁמוּאֵ֗ל רָאשִׁ֤ים לְ⁠בֵית־אֲבוֹתָ⁠ם֙ לְ⁠תוֹלָ֔ע גִּבּ֥וֹרֵי חַ֖יִל לְ⁠תֹלְדוֹתָ֑⁠ם מִסְפָּרָ⁠ם֙ בִּ⁠ימֵ֣י דָוִ֔יד עֶשְׂרִֽים־וּ⁠שְׁנַ֥יִם אֶ֖לֶף וְ⁠שֵׁ֥שׁ מֵאֽוֹת׃ס","ẇ⁠bĕné֣y ţwòlá֗ʻ ʻuzi̇֡y ẇ⁠rĕpáyá֡h wiֽ֠⁠yriyʼél wĕ⁠yaẖĕma֨y wĕ⁠yibĕşá̂֜m ẇ⁠şĕ̌mẇʼé֗l ráʼşǐ֤ym lĕ⁠béyţ-ʼàbwòţá⁠m֙ lĕ⁠ţwòlá֔ʻ gi̇ḃ֥wòréy ẖa֖yil lĕ⁠ţòlĕdwòţá֑⁠m misĕpá̇rá⁠m֙ bi̇⁠ymé֣y dáwi֔yd ʻeşĕ̂riֽym-ẇ⁠şĕ̌na֥yim ʼe֖lep wĕ⁠şé֥̌ş̌ méʼֽwòţ׃s"],[7,3,"וּ⁠בְנֵ֥י עֻזִּ֖י יִֽזְרַֽחְיָ֑ה וּ⁠בְנֵ֣י יִֽזְרַֽחְיָ֗ה מִֽיכָאֵ֡ל וְ֠⁠עֹבַדְיָה וְ⁠יוֹאֵ֧ל יִשִּׁיָּ֛ה חֲמִשָּׁ֖ה רָאשִׁ֥ים כֻּלָּֽ⁠ם׃","ẇ⁠bĕné֥y ʻuzi֖̇y yiֽzĕraֽẖĕyá֑h ẇ⁠bĕné֣y yiֽzĕraֽẖĕyá֗h miֽykáʼé֡l wĕ֠⁠ʻòbadĕyáh wĕ⁠ywòʼé֧l yişi̇̌yá֛̇h ẖàmişá֖̇̌h ráʼşǐ֥ym ku̇láֽ̇⁠m׃"],[7,4,"וַ⁠עֲלֵי⁠הֶ֨ם לְ⁠תֹלְדוֹתָ֜⁠ם לְ⁠בֵ֣ית אֲבוֹתָ֗⁠ם גְּדוּדֵי֙ צְבָ֣א מִלְחָמָ֔ה שְׁלֹשִׁ֥ים וְ⁠שִׁשָּׁ֖ה אָ֑לֶף כִּֽי־הִרְבּ֥וּ נָשִׁ֖ים וּ⁠בָנִֽים׃","wa⁠ʻàléy⁠he֨m lĕ⁠ţòlĕdwòţá֜⁠m lĕ⁠bé֣yţ ʼàbwòţá֗⁠m gĕ̇dẇdéy֙ ẕĕbá֣ʼ milĕẖámá֔h şĕ̌lòşǐ֥ym wĕ⁠şǐşá֖̇̌h ʼá֑lep kiֽ̇y-hirĕḃ֥ẇ náşǐ֖ym ẇ⁠bániֽym׃"],[7,5,"וַ⁠אֲחֵי⁠הֶ֗ם לְ⁠כֹל֙ מִשְׁפְּח֣וֹת יִשָׂשכָ֔ר גִּבּוֹרֵ֖י חֲיָלִ֑ים שְׁמוֹנִ֤ים וְ⁠שִׁבְעָה֙ אֶ֔לֶף הִתְיַחְשָׂ֖⁠ם לַ⁠כֹּֽל׃פ","wa⁠ʼàẖéy⁠he֗m lĕ⁠kòl֙ mişĕ̌pĕ̇ẖ֣wòţ yişá̂şká֔r gi̇ḃwòré֖y ẖàyáli֑ym şĕ̌mwòni֤ym wĕ⁠şǐbĕʻáh֙ ʼe֔lep hiţĕyaẖĕşá֖̂⁠m la⁠kòֽ̇l׃p"],[7,6,"בִּנְיָמִ֗ן בֶּ֧לַע וָ⁠בֶ֛כֶר וִ⁠ידִֽיעֲאֵ֖ל שְׁלֹשָֽׁה׃","bi̇nĕyámi֗n bė֧laʻ wá⁠be֛ker wi⁠ydiֽyʻàʼé֖l şĕ̌lòşáֽ̌h׃"],[7,7,"וּ⁠בְנֵ֣י בֶ֗לַע אֶצְבּ֡וֹן וְ⁠עֻזִּ֡י וְ֠⁠עֻזִּיאֵל וִ⁠ירִימ֨וֹת וְ⁠עִירִ֜י חֲמִשָּׁ֗ה רָאשֵׁי֙ בֵּ֣ית אָב֔וֹת גִּבּוֹרֵ֖י חֲיָלִ֑ים וְ⁠הִתְיַחְשָׂ֗⁠ם עֶשְׂרִ֤ים וּ⁠שְׁנַ֨יִם֙ אֶ֔לֶף וּ⁠שְׁלֹשִׁ֖ים וְ⁠אַרְבָּעָֽה׃ס","ẇ⁠bĕné֣y be֗laʻ ʼeẕĕḃ֡wòn wĕ⁠ʻuzi̇֡y wĕ֠⁠ʻuzi̇yʼél wi⁠yriym֨wòţ wĕ⁠ʻiyri֜y ẖàmişá̇̌֗h ráʼşé̌y֙ bé֣̇yţ ʼáb֔wòţ gi̇ḃwòré֖y ẖàyáli֑ym wĕ⁠hiţĕyaẖĕşá̂֗⁠m ʻeşĕ̂ri֤ym ẇ⁠şĕ̌na֨yim֙ ʼe֔lep ẇ⁠şĕ̌lòşǐ֖ym wĕ⁠ʼarĕbá̇ʻáֽh׃s"],[7,8,"וּ⁠בְנֵ֣י בֶ֗כֶר זְמִירָ֡ה וְ⁠יוֹעָ֡שׁ וֶ֠⁠אֱלִיעֶזֶר וְ⁠אֶלְיוֹעֵינַ֤י וְ⁠עָמְרִי֙ וִ⁠ירֵמ֣וֹת וַ⁠אֲבִיָּ֔ה וַ⁠עֲנָת֖וֹת וְ⁠עָלָ֑מֶת כָּל־אֵ֖לֶּה בְּנֵי־בָֽכֶר׃","ẇ⁠bĕné֣y be֗ker zĕmiyrá֡h wĕ⁠ywòʻá֡ş̌ we֠⁠ʼèliyʻezer wĕ⁠ʼelĕywòʻéyna֤y wĕ⁠ʻámĕriy֙ wi⁠yrém֣wòţ wa⁠ʼàbiyá̇֔h wa⁠ʻànáţ֖wòţ wĕ⁠ʻálá֑meţ ká̇l-ʼé֖lėh bĕ̇néy-báֽker׃"],[7,9,"וְ⁠הִתְיַחְשָׂ֣⁠ם לְ⁠תֹלְדוֹתָ֗⁠ם רָאשֵׁי֙ בֵּ֣ית אֲבוֹתָ֔⁠ם גִּבּוֹרֵ֖י חָ֑יִל עֶשְׂרִ֥ים אֶ֖לֶף וּ⁠מָאתָֽיִם׃ס","wĕ⁠hiţĕyaẖĕşá֣̂⁠m lĕ⁠ţòlĕdwòţá֗⁠m ráʼşé̌y֙ bé֣̇yţ ʼàbwòţá֔⁠m gi̇ḃwòré֖y ẖá֑yil ʻeşĕ̂ri֥ym ʼe֖lep ẇ⁠máʼţáֽyim׃s"],[7,10,"וּ⁠בְנֵ֥י יְדִיעֲאֵ֖ל בִּלְהָ֑ן וּ⁠בְנֵ֣י בִלְהָ֗ן יעיש וּ֠⁠בִנְיָמִן וְ⁠אֵה֤וּד וּֽ⁠כְנַעֲנָה֙ וְ⁠זֵיתָ֔ן וְ⁠תַרְשִׁ֖ישׁ וַ⁠אֲחִישָֽׁחַר׃","ẇ⁠bĕné֥y yĕdiyʻàʼé֖l bi̇lĕhá֑n ẇ⁠bĕné֣y bilĕhá֗n yʻyş ẇ֠⁠binĕyámin wĕ⁠ʼéh֤ẇd ẇֽ⁠kĕnaʻànáh֙ wĕ⁠zéyţá֔n wĕ⁠ţarĕşǐ֖yş̌ wa⁠ʼàẖiyşáֽ̌ẖar׃"],[7,11,"כָּל־אֵ֜לֶּה בְּנֵ֤י יְדִֽיעֲאֵל֙ לְ⁠רָאשֵׁ֣י הָ⁠אָב֔וֹת גִּבּוֹרֵ֖י חֲיָלִ֑ים שִׁבְעָֽה־עָשָׂ֥ר אֶ֨לֶף֙ וּ⁠מָאתַ֔יִם יֹצְאֵ֥י צָבָ֖א לַ⁠מִּלְחָמָֽה׃","ká̇l-ʼé֜lėh bĕ̇né֤y yĕdiֽyʻàʼél֙ lĕ⁠ráʼşé֣̌y há⁠ʼáb֔wòţ gi̇ḃwòré֖y ẖàyáli֑ym şǐbĕʻáֽh-ʻáşá֥̂r ʼe֨lep֙ ẇ⁠máʼţa֔yim yòẕĕʼé֥y ẕábá֖ʼ la⁠mi̇lĕẖámáֽh׃"],[7,12,"וְ⁠שֻׁפִּ֤ם וְ⁠חֻפִּם֙ בְּנֵ֣י עִ֔יר חֻשִׁ֖ם בְּנֵ֥י אַחֵֽר׃","wĕ⁠şǔpi֤̇m wĕ⁠ẖupi̇m֙ bĕ̇né֣y ʻi֔yr ẖuşǐ֖m bĕ̇né֥y ʼaẖéֽr׃"],[7,13,"בְּנֵ֣י נַפְתָּלִ֗י יַחֲצִיאֵ֧ל וְ⁠גוּנִ֛י וְ⁠יֵ֥צֶר וְ⁠שַׁלּ֖וּם בְּנֵ֥י בִלְהָֽה׃פ","bĕ̇né֣y napĕţá̇li֗y yaẖàẕiyʼé֧l wĕ⁠gẇni֛y wĕ⁠yé֥ẕer wĕ⁠şǎl֖̇ẇm bĕ̇né֥y bilĕháֽh׃p"],[7,14,"בְּנֵ֣י מְנַשֶּׁ֔ה אַשְׂרִיאֵ֖ל אֲשֶׁ֣ר יָלָ֑דָה פִּֽילַגְשׁ⁠וֹ֙ הָֽ⁠אֲרַמִּיָּ֔ה יָלְדָ֕ה אֶת־מָכִ֖יר אֲבִ֥י גִלְעָֽד׃","bĕ̇né֣y mĕnaşė̌֔h ʼaşĕ̂riyʼé֖l ʼàşě֣r yálá֑dáh piֽ̇ylagĕş̌⁠wò֙ háֽ⁠ʼàrami̇yá̇֔h yálĕdá֕h ʼeţ-máki֖yr ʼàbi֥y gilĕʻáֽd׃"],[7,15,"וּ⁠מָכִ֞יר לָקַ֤ח אִשָּׁה֙ לְ⁠חֻפִּ֣ים וּ⁠לְ⁠שֻׁפִּ֔ים וְ⁠שֵׁ֤ם אֲחֹת⁠וֹ֙ מַעֲכָ֔ה וְ⁠שֵׁ֥ם הַ⁠שֵּׁנִ֖י צְלָפְחָ֑ד וַ⁠תִּהְיֶ֥נָה לִ⁠צְלָפְחָ֖ד בָּנֽוֹת׃","ẇ⁠máki֞yr láqa֤ẖ ʼişá̇̌h֙ lĕ⁠ẖupi֣̇ym ẇ⁠lĕ⁠şǔpi̇֔ym wĕ⁠şé֤̌m ʼàẖòţ⁠wò֙ maʻàká֔h wĕ⁠şé֥̌m ha⁠şé̇̌ni֖y ẕĕlápĕẖá֑d wa⁠ţi̇hĕye֥náh li⁠ẕĕlápĕẖá֖d bá̇nֽwòţ׃"],[7,16,"וַ⁠תֵּ֨לֶד מַעֲכָ֤ה אֵֽשֶׁת־מָכִיר֙ בֵּ֔ן וַ⁠תִּקְרָ֤א שְׁמ⁠וֹ֙ פֶּ֔רֶשׁ וְ⁠שֵׁ֥ם אָחִ֖י⁠ו שָׁ֑רֶשׁ וּ⁠בָנָ֖י⁠ו אוּלָ֥ם וָ⁠רָֽקֶם׃","wa⁠ţé̇֨led maʻàká֤h ʼéֽşěţ-mákiyr֙ bé̇֔n wa⁠ţi̇qĕrá֤ʼ şĕ̌m⁠wò֙ pė֔reş̌ wĕ⁠şé֥̌m ʼáẖi֖y⁠w şá֑̌reş̌ ẇ⁠báná֖y⁠w ʼẇlá֥m wá⁠ráֽqem׃"],[7,17,"וּ⁠בְנֵ֥י אוּלָ֖ם בְּדָ֑ן אֵ֚לֶּה בְּנֵ֣י גִלְעָ֔ד בֶּן־מָכִ֖יר בֶּן־מְנַשֶּֽׁה׃","ẇ⁠bĕné֥y ʼẇlá֖m bĕ̇dá֑n ʼé֚lėh bĕ̇né֣y gilĕʻá֔d bėn-máki֖yr bėn-mĕnaşėֽ̌h׃"],[7,18,"וַ⁠אֲחֹת֖⁠וֹ הַ⁠מֹּלֶ֑כֶת יָלְדָה֙ אֶת־אִישְׁה֔וֹד וְ⁠אֶת־אֲבִיעֶ֖זֶר וְ⁠אֶת־מַחְלָֽה׃","wa⁠ʼàẖòţ֖⁠wò ha⁠mò̇le֑keţ yálĕdáh֙ ʼeţ-ʼiyşĕ̌h֔wòd wĕ⁠ʼeţ-ʼàbiyʻe֖zer wĕ⁠ʼeţ-maẖĕláֽh׃"],[7,19,"וַ⁠יִּהְי֖וּ בְּנֵ֣י שְׁמִידָ֑ע אַחְיָ֣ן וָ⁠שֶׁ֔כֶם וְ⁠לִקְחִ֖י וַ⁠אֲנִיעָֽם׃פ","wa⁠yi̇hĕy֖ẇ bĕ̇né֣y şĕ̌miydá֑ʻ ʼaẖĕyá֣n wá⁠şě֔kem wĕ⁠liqĕẖi֖y wa⁠ʼàniyʻáֽm׃p"],[7,20,"וּ⁠בְנֵ֥י אֶפְרַ֖יִם שׁוּתָ֑לַח וּ⁠בֶ֤רֶד בְּנ⁠וֹ֙ וְ⁠תַ֣חַת בְּנ֔⁠וֹ וְ⁠אֶלְעָדָ֥ה בְנ֖⁠וֹ וְ⁠תַ֥חַת בְּנֽ⁠וֹ׃","ẇ⁠bĕné֥y ʼepĕra֖yim ş̌ẇţá֑laẖ ẇ⁠be֤red bĕ̇n⁠wò֙ wĕ⁠ţa֣ẖaţ bĕ̇n֔⁠wò wĕ⁠ʼelĕʻádá֥h bĕn֖⁠wò wĕ⁠ţa֥ẖaţ bĕ̇nֽ⁠wò׃"],[7,21,"וְ⁠זָבָ֥ד בְּנ֛⁠וֹ וְ⁠שׁוּתֶ֥לַח בְּנ֖⁠וֹ וְ⁠עֵ֣זֶר וְ⁠אֶלְעָ֑ד וַ⁠הֲרָג֗וּ⁠ם אַנְשֵׁי־גַת֙ הַ⁠נּוֹלָדִ֣ים בָּ⁠אָ֔רֶץ כִּ֣י יָרְד֔וּ לָ⁠קַ֖חַת אֶת־מִקְנֵי⁠הֶֽם׃","wĕ⁠zábá֥d bĕ̇n֛⁠wò wĕ⁠ş̌ẇţe֥laẖ bĕ̇n֖⁠wò wĕ⁠ʻé֣zer wĕ⁠ʼelĕʻá֑d wa⁠hàrág֗ẇ⁠m ʼanĕşé̌y-gaţ֙ ha⁠ṅwòládi֣ym bá̇⁠ʼá֔reẕ ki֣̇y yárĕd֔ẇ lá⁠qa֖ẖaţ ʼeţ-miqĕnéy⁠heֽm׃"],[7,22,"וַ⁠יִּתְאַבֵּ֛ל אֶפְרַ֥יִם אֲבִי⁠הֶ֖ם יָמִ֣ים רַבִּ֑ים וַ⁠יָּבֹ֥אוּ אֶחָ֖י⁠ו לְ⁠נַחֲמֽ⁠וֹ׃","wa⁠yi̇ţĕʼabé֛̇l ʼepĕra֥yim ʼàbiy⁠he֖m yámi֣ym rabi֑̇ym wa⁠yá̇bò֥ʼẇ ʼeẖá֖y⁠w lĕ⁠naẖàmֽ⁠wò׃"],[7,23,"וַ⁠יָּבֹא֙ אֶל־אִשְׁתּ֔⁠וֹ וַ⁠תַּ֖הַר וַ⁠תֵּ֣לֶד בֵּ֑ן וַ⁠יִּקְרָ֤א אֶת־שְׁמ⁠וֹ֙ בְּרִיעָ֔ה כִּ֥י בְ⁠רָעָ֖ה הָיְתָ֥ה בְּ⁠בֵיתֽ⁠וֹ׃","wa⁠yá̇bòʼ֙ ʼel-ʼişĕ̌ţ̇֔⁠wò wa⁠ţȧ֖har wa⁠ţé֣̇led bé֑̇n wa⁠yi̇qĕrá֤ʼ ʼeţ-şĕ̌m⁠wò֙ bĕ̇riyʻá֔h ki֥̇y bĕ⁠ráʻá֖h háyĕţá֥h bĕ̇⁠béyţֽ⁠wò׃"],[7,24,"וּ⁠בִתּ֣⁠וֹ שֶׁאֱרָ֔ה וַ⁠תִּ֧בֶן אֶת־בֵּית־חוֹר֛וֹן הַ⁠תַּחְתּ֖וֹן וְ⁠אֶת־הָ⁠עֶלְי֑וֹן וְ⁠אֵ֖ת אֻזֵּ֥ן שֶׁאֱרָֽה׃","ẇ⁠biţ֣̇⁠wò şěʼèrá֔h wa⁠ţi֧̇ben ʼeţ-bé̇yţ-ẖwòr֛wòn ha⁠ţȧẖĕţ֖̇wòn wĕ⁠ʼeţ-há⁠ʻelĕy֑wòn wĕ⁠ʼé֖ţ ʼuzé֥̇n şěʼèráֽh׃"],[7,25,"וְ⁠רֶ֣פַח בְּנ֗⁠וֹ וְ⁠רֶ֧שֶׁף וְ⁠תֶ֛לַח בְּנ֖⁠וֹ וְ⁠תַ֥חַן בְּנֽ⁠וֹ׃","wĕ⁠re֣paẖ bĕ̇n֗⁠wò wĕ⁠re֧şěp wĕ⁠ţe֛laẖ bĕ̇n֖⁠wò wĕ⁠ţa֥ẖan bĕ̇nֽ⁠wò׃"],[7,26,"לַעְדָּ֥ן בְּנ֛⁠וֹ עַמִּיה֥וּד בְּנ֖⁠וֹ אֱלִישָׁמָ֥ע בְּנֽ⁠וֹ׃","laʻĕdá֥̇n bĕ̇n֛⁠wò ʻami̇yh֥ẇd bĕ̇n֖⁠wò ʼèliyşá̌má֥ʻ bĕ̇nֽ⁠wò׃"],[7,27,"נ֥וֹן בְּנ֖⁠וֹ יְהוֹשֻׁ֥עַ בְּנֽ⁠וֹ׃","n֥wòn bĕ̇n֖⁠wò yĕhwòşǔ֥ʻa bĕ̇nֽ⁠wò׃"],[7,28,"וַ⁠אֲחֻזָּתָ⁠ם֙ וּ⁠מֹ֣שְׁבוֹתָ֔⁠ם בֵּֽית־אֵ֖ל וּ⁠בְנֹתֶ֑י⁠הָ וְ⁠לַ⁠מִּזְרָ֣ח נַעֲרָ֔ן וְ⁠לַֽ⁠מַּעֲרָ֗ב גֶּ֤זֶר וּ⁠בְנֹתֶ֨י⁠הָ֙ וּ⁠שְׁכֶ֣ם וּ⁠בְנֹתֶ֔י⁠הָ עַד־עַיָּ֖ה וּ⁠בְנֹתֶֽי⁠הָ׃","wa⁠ʼàẖuzá̇ţá⁠m֙ ẇ⁠mò֣şĕ̌bwòţá֔⁠m béֽ̇yţ-ʼé֖l ẇ⁠bĕnòţe֑y⁠há wĕ⁠la⁠mi̇zĕrá֣ẖ naʻàrá֔n wĕ⁠laֽ⁠mȧʻàrá֗b gė֤zer ẇ⁠bĕnòţe֨y⁠há֙ ẇ⁠şĕ̌ke֣m ẇ⁠bĕnòţe֔y⁠há ʻad-ʻayá֖̇h ẇ⁠bĕnòţeֽy⁠há׃"],[7,29,"וְ⁠עַל־יְדֵ֣י בְנֵי־מְנַשֶּׁ֗ה בֵּית־שְׁאָ֤ן וּ⁠בְנֹתֶ֨י⁠הָ֙ תַּעְנַ֣ךְ וּ⁠בְנֹתֶ֔י⁠הָ מְגִדּ֥וֹ וּ⁠בְנוֹתֶ֖י⁠הָ דּ֣וֹר וּ⁠בְנוֹתֶ֑י⁠הָ בְּ⁠אֵ֨לֶּה֙ יָשְׁב֔וּ בְּנֵ֥י יוֹסֵ֖ף בֶּן־יִשְׂרָאֵֽל׃פ","wĕ⁠ʻal-yĕdé֣y bĕnéy-mĕnaşė̌֗h bé̇yţ-şĕ̌ʼá֤n ẇ⁠bĕnòţe֨y⁠há֙ ţȧʻĕna֣kĕ ẇ⁠bĕnòţe֔y⁠há mĕgiḋ֥wò ẇ⁠bĕnwòţe֖y⁠há ḋ֣wòr ẇ⁠bĕnwòţe֑y⁠há bĕ̇⁠ʼé֨lėh֙ yáşĕ̌b֔ẇ bĕ̇né֥y ywòsé֖p bėn-yişĕ̂ráʼéֽl׃p"],[7,30,"בְּנֵ֣י אָשֵׁ֗ר יִמְנָ֧ה וְ⁠יִשְׁוָ֛ה וְ⁠יִשְׁוִ֥י וּ⁠בְרִיעָ֖ה וְ⁠שֶׂ֥רַח אֲחוֹתָֽ⁠ם׃","bĕ̇né֣y ʼáşé̌֗r yimĕná֧h wĕ⁠yişĕ̌wá֛h wĕ⁠yişĕ̌wi֥y ẇ⁠bĕriyʻá֖h wĕ⁠şê֥raẖ ʼàẖwòţáֽ⁠m׃"],[7,31,"וּ⁠בְנֵ֣י בְרִיעָ֔ה חֶ֖בֶר וּ⁠מַלְכִּיאֵ֑ל ה֖וּא אֲבִ֥י ברזות׃","ẇ⁠bĕné֣y bĕriyʻá֔h ẖe֖ber ẇ⁠malĕki̇yʼé֑l h֖ẇʼ ʼàbi֥y brzwţ׃"],[7,32,"וְ⁠חֶ֨בֶר֙ הוֹלִ֣יד אֶת־יַפְלֵ֔ט וְ⁠אֶת־שׁוֹמֵ֖ר וְ⁠אֶת־חוֹתָ֑ם וְ⁠אֵ֖ת שׁוּעָ֥א אֲחוֹתָֽ⁠ם׃","wĕ⁠ẖe֨ber֙ hwòli֣yd ʼeţ-yapĕlé֔t wĕ⁠ʼeţ-ş̌wòmé֖r wĕ⁠ʼeţ-ẖwòţá֑m wĕ⁠ʼé֖ţ ş̌ẇʻá֥ʼ ʼàẖwòţáֽ⁠m׃"],[7,33,"וּ⁠בְנֵ֣י יַפְלֵ֔ט פָּסַ֥ךְ וּ⁠בִמְהָ֖ל וְ⁠עַשְׁוָ֑ת אֵ֖לֶּה בְּנֵ֥י יַפְלֵֽט׃","ẇ⁠bĕné֣y yapĕlé֔t pá̇sa֥kĕ ẇ⁠bimĕhá֖l wĕ⁠ʻaşĕ̌wá֑ţ ʼé֖lėh bĕ̇né֥y yapĕléֽt׃"],[7,34,"וּ⁠בְנֵ֖י שָׁ֑מֶר אֲחִ֥י ו⁠רוהגה יחבה וַ⁠אֲרָֽם׃","ẇ⁠bĕné֖y şá֑̌mer ʼàẖi֥y w⁠rwhgh yẖbh wa⁠ʼàráֽm׃"],[7,35,"וּ⁠בֶן־הֵ֖לֶם אָחִ֑י⁠ו צוֹפַ֥ח וְ⁠יִמְנָ֖ע וְ⁠שֵׁ֥לֶשׁ וְ⁠עָמָֽל׃","ẇ⁠ben-hé֖lem ʼáẖi֑y⁠w ẕwòpa֥ẖ wĕ⁠yimĕná֖ʻ wĕ⁠şé֥̌leş̌ wĕ⁠ʻámáֽl׃"],[7,36,"בְּנֵ֖י צוֹפָ֑ח ס֧וּחַ וְ⁠חַרְנֶ֛פֶר וְ⁠שׁוּעָ֖ל וּ⁠בֵרִ֥י וְ⁠יִמְרָֽה׃","bĕ̇né֖y ẕwòpá֑ẖ s֧ẇẖa wĕ⁠ẖarĕne֛per wĕ⁠ş̌ẇʻá֖l ẇ⁠béri֥y wĕ⁠yimĕráֽh׃"],[7,37,"בֶּ֣צֶר וָ⁠ה֗וֹד וְ⁠שַׁמָּ֧א וְ⁠שִׁלְשָׁ֛ה וְ⁠יִתְרָ֖ן וּ⁠בְאֵרָֽא׃","bė֣ẕer wá⁠h֗wòd wĕ⁠şǎmá֧̇ʼ wĕ⁠şǐlĕşá֛̌h wĕ⁠yiţĕrá֖n ẇ⁠bĕʼéráֽʼ׃"],[7,38,"וּ⁠בְנֵ֖י יֶ֑תֶר יְפֻנֶּ֥ה וּ⁠פִסְפָּ֖ה וַ⁠אְרָֽא׃","ẇ⁠bĕné֖y ye֑ţer yĕpunė֥h ẇ⁠pisĕpá֖̇h wa⁠ʼĕráֽʼ׃"],[7,39,"וּ⁠בְנֵ֖י עֻלָּ֑א אָרַ֥ח וְ⁠חַנִּיאֵ֖ל וְ⁠רִצְיָֽא׃","ẇ⁠bĕné֖y ʻulá֑̇ʼ ʼára֥ẖ wĕ⁠ẖani̇yʼé֖l wĕ⁠riẕĕyáֽʼ׃"],[7,40,"כָּל־אֵ֣לֶּה בְנֵי־אָ֠שֵׁר רָאשֵׁ֨י בֵית־הָ⁠אָב֤וֹת בְּרוּרִים֙ גִּבּוֹרֵ֣י חֲיָלִ֔ים רָאשֵׁ֖י הַ⁠נְּשִׂיאִ֑ים וְ⁠הִתְיַחְשָׂ֤⁠ם בַּ⁠צָּבָא֙ בַּ⁠מִּלְחָמָ֔ה מִסְפָּרָ֣⁠ם אֲנָשִׁ֔ים עֶשְׂרִ֥ים וְ⁠שִׁשָּׁ֖ה אָֽלֶף׃ס","ká̇l-ʼé֣lėh bĕnéy-ʼá֠şé̌r ráʼşé̌֨y béyţ-há⁠ʼáb֤wòţ bĕ̇rẇriym֙ gi̇ḃwòré֣y ẖàyáli֔ym ráʼşé֖̌y ha⁠nĕ̇şîyʼi֑ym wĕ⁠hiţĕyaẖĕşá֤̂⁠m bȧ⁠ẕá̇báʼ֙ bȧ⁠mi̇lĕẖámá֔h misĕpá̇rá֣⁠m ʼànáşǐ֔ym ʻeşĕ̂ri֥ym wĕ⁠şǐşá֖̇̌h ʼáֽlep׃s"],[8,1,"וּ⁠בִ֨נְיָמִ֔ן הוֹלִ֖יד אֶת־בֶּ֣לַע בְּכֹר֑⁠וֹ אַשְׁבֵּל֙ הַ⁠שֵּׁנִ֔י וְ⁠אַחְרַ֖ח הַ⁠שְּׁלִישִֽׁי׃","ẇ⁠bi֨nĕyámi֔n hwòli֖yd ʼeţ-bė֣laʻ bĕ̇kòr֑⁠wò ʼaşĕ̌bé̇l֙ ha⁠şé̇̌ni֔y wĕ⁠ʼaẖĕra֖ẖ ha⁠şĕ̇̌liyşǐֽy׃"],[8,2,"נוֹחָה֙ הָֽ⁠רְבִיעִ֔י וְ⁠רָפָ֖א הַ⁠חֲמִישִֽׁי׃ס","nwòẖáh֙ háֽ⁠rĕbiyʻi֔y wĕ⁠rápá֖ʼ ha⁠ẖàmiyşǐֽy׃s"],[8,3,"וַ⁠יִּהְי֥וּ בָנִ֖ים לְ⁠בָ֑לַע אַדָּ֥ר וְ⁠גֵרָ֖א וַ⁠אֲבִיהֽוּד׃","wa⁠yi̇hĕy֥ẇ báni֖ym lĕ⁠bá֑laʻ ʼadá֥̇r wĕ⁠gérá֖ʼ wa⁠ʼàbiyhֽẇd׃"],[8,4,"וַ⁠אֲבִישׁ֥וּעַ וְ⁠נַעֲמָ֖ן וַ⁠אֲחֽוֹחַ׃","wa⁠ʼàbiyş֥̌ẇʻa wĕ⁠naʻàmá֖n wa⁠ʼàẖֽwòẖa׃"],[8,5,"וְ⁠גֵרָ֥א וּ⁠שְׁפוּפָ֖ן וְ⁠חוּרָֽם׃","wĕ⁠gérá֥ʼ ẇ⁠şĕ̌pẇpá֖n wĕ⁠ẖẇráֽm׃"],[8,6,"וְ⁠אֵ֖לֶּה בְּנֵ֣י אֵח֑וּד אֵ֣לֶּה הֵ֞ם רָאשֵׁ֤י אָבוֹת֙ לְ⁠י֣וֹשְׁבֵי גֶ֔בַע וַ⁠יַּגְל֖וּ⁠ם אֶל־מָנָֽחַת׃","wĕ⁠ʼé֖lėh bĕ̇né֣y ʼéẖ֑ẇd ʼé֣lėh hé֞m ráʼşé֤̌y ʼábwòţ֙ lĕ⁠y֣wòşĕ̌béy ge֔baʻ wa⁠yȧgĕl֖ẇ⁠m ʼel-mánáֽẖaţ׃"],[8,7,"וְ⁠נַעֲמָ֧ן וַ⁠אֲחִיָּ֛ה וְ⁠גֵרָ֖א ה֣וּא הֶגְלָ֑⁠ם וְ⁠הוֹלִ֥יד אֶת־עֻזָּ֖א וְ⁠אֶת־אֲחִיחֻֽד׃","wĕ⁠naʻàmá֧n wa⁠ʼàẖiyá֛̇h wĕ⁠gérá֖ʼ h֣ẇʼ hegĕlá֑⁠m wĕ⁠hwòli֥yd ʼeţ-ʻuzá֖̇ʼ wĕ⁠ʼeţ-ʼàẖiyẖuֽd׃"],[8,8,"וְ⁠שַׁחֲרַ֗יִם הוֹלִיד֙ בִּ⁠שְׂדֵ֣ה מוֹאָ֔ב מִן־שִׁלְח֖⁠וֹ אֹתָ֑⁠ם חוּשִׁ֥ים וְ⁠אֶֽת־בַּעֲרָ֖א נָשָֽׁי⁠ו׃","wĕ⁠şǎẖàra֗yim hwòliyd֙ bi̇⁠şĕ̂dé֣h mwòʼá֔b min-şǐlĕẖ֖⁠wò ʼòţá֑⁠m ẖẇşǐ֥ym wĕ⁠ʼeֽţ-bȧʻàrá֖ʼ náşáֽ̌y⁠w׃"],[8,9,"וַ⁠יּ֖וֹלֶד מִן־חֹ֣דֶשׁ אִשְׁתּ֑⁠וֹ אֶת־יוֹבָב֙ וְ⁠אֶת־צִבְיָ֔א וְ⁠אֶת־מֵישָׁ֖א וְ⁠אֶת־מַלְכָּֽם׃","wa⁠ẏ֖wòled min-ẖò֣deş̌ ʼişĕ̌ţ֑̇⁠wò ʼeţ-ywòbáb֙ wĕ⁠ʼeţ-ẕibĕyá֔ʼ wĕ⁠ʼeţ-méyşá֖̌ʼ wĕ⁠ʼeţ-malĕkáֽ̇m׃"],[8,10,"וְ⁠אֶת־יְע֥וּץ וְ⁠אֶת־שָֽׂכְיָ֖ה וְ⁠אֶת־מִרְמָ֑ה אֵ֥לֶּה בָנָ֖י⁠ו רָאשֵׁ֥י אָבֽוֹת׃","wĕ⁠ʼeţ-yĕʻ֥ẇẕ wĕ⁠ʼeţ-şáֽ̂kĕyá֖h wĕ⁠ʼeţ-mirĕmá֑h ʼé֥lėh báná֖y⁠w ráʼşé֥̌y ʼábֽwòţ׃"],[8,11,"וּ⁠מֵ⁠חֻשִׁ֛ים הוֹלִ֥יד אֶת־אֲבִיט֖וּב וְ⁠אֶת־אֶלְפָּֽעַל׃","ẇ⁠mé⁠ẖuşǐ֛ym hwòli֥yd ʼeţ-ʼàbiyt֖ẇb wĕ⁠ʼeţ-ʼelĕpáֽ̇ʻal׃"],[8,12,"וּ⁠בְנֵ֣י אֶלְפַּ֔עַל עֵ֥בֶר וּ⁠מִשְׁעָ֖ם וָ⁠שָׁ֑מֶד ה֚וּא בָּנָ֣ה אֶת־אוֹנ֔וֹ וְ⁠אֶת־לֹ֖ד וּ⁠בְנֹתֶֽי⁠הָ׃","ẇ⁠bĕné֣y ʼelĕpȧ֔ʻal ʻé֥ber ẇ⁠mişĕ̌ʻá֖m wá⁠şá֑̌med h֚ẇʼ bá̇ná֣h ʼeţ-ʼwòn֔wò wĕ⁠ʼeţ-lò֖d ẇ⁠bĕnòţeֽy⁠há׃"],[8,13,"וּ⁠בְרִעָ֣ה וָ⁠שֶׁ֔מַע הֵ֚מָּה רָאשֵׁ֣י הָ⁠אָב֔וֹת לְ⁠יוֹשְׁבֵ֖י אַיָּל֑וֹן הֵ֥מָּה הִבְרִ֖יחוּ אֶת־י֥וֹשְׁבֵי גַֽת׃","ẇ⁠bĕriʻá֣h wá⁠şě֔maʻ hé֚má̇h ráʼşé֣̌y há⁠ʼáb֔wòţ lĕ⁠ywòşĕ̌bé֖y ʼayá̇l֑wòn hé֥má̇h hibĕri֖yẖẇ ʼeţ-y֥wòşĕ̌béy gaֽţ׃"],[8,14,"וְ⁠אַחְי֥וֹ שָׁשָׁ֖ק וִ⁠ירֵמֽוֹת׃","wĕ⁠ʼaẖĕy֥wò şá̌şá֖̌q wi⁠yrémֽwòţ׃"],[8,15,"וּ⁠זְבַדְיָ֥ה וַ⁠עֲרָ֖ד וָ⁠עָֽדֶר׃","ẇ⁠zĕbadĕyá֥h wa⁠ʻàrá֖d wá⁠ʻáֽder׃"],[8,16,"וּ⁠מִיכָאֵ֧ל וְ⁠יִשְׁפָּ֛ה וְ⁠יוֹחָ֖א בְּנֵ֥י בְרִיעָֽה׃","ẇ⁠miykáʼé֧l wĕ⁠yişĕ̌pá֛̇h wĕ⁠ywòẖá֖ʼ bĕ̇né֥y bĕriyʻáֽh׃"],[8,17,"וּ⁠זְבַדְיָ֥ה וּ⁠מְשֻׁלָּ֖ם וְ⁠חִזְקִ֥י וָ⁠חָֽבֶר׃","ẇ⁠zĕbadĕyá֥h ẇ⁠mĕşǔlá֖̇m wĕ⁠ẖizĕqi֥y wá⁠ẖáֽber׃"],[8,18,"וְ⁠יִשְׁמְרַ֧י וְ⁠יִזְלִיאָ֛ה וְ⁠יוֹבָ֖ב בְּנֵ֥י אֶלְפָּֽעַל׃","wĕ⁠yişĕ̌mĕra֧y wĕ⁠yizĕliyʼá֛h wĕ⁠ywòbá֖b bĕ̇né֥y ʼelĕpáֽ̇ʻal׃"],[8,19,"וְ⁠יָקִ֥ים וְ⁠זִכְרִ֖י וְ⁠זַבְדִּֽי׃","wĕ⁠yáqi֥ym wĕ⁠zikĕri֖y wĕ⁠zabĕdiֽ̇y׃"],[8,20,"וֶ⁠אֱלִיעֵנַ֥י וְ⁠צִלְּתַ֖י וֶ⁠אֱלִיאֵֽל׃","we⁠ʼèliyʻéna֥y wĕ⁠ẕilĕ̇ţa֖y we⁠ʼèliyʼéֽl׃"],[8,21,"וַ⁠עֲדָיָ֧ה וּ⁠בְרָאיָ֛ה וְ⁠שִׁמְרָ֖ת בְּנֵ֥י שִׁמְעִֽי׃","wa⁠ʻàdáyá֧h ẇ⁠bĕráʼyá֛h wĕ⁠şǐmĕrá֖ţ bĕ̇né֥y şǐmĕʻiֽy׃"],[8,22,"וְ⁠יִשְׁפָּ֥ן וָ⁠עֵ֖בֶר וֶ⁠אֱלִיאֵֽל׃","wĕ⁠yişĕ̌pá֥̇n wá⁠ʻé֖ber we⁠ʼèliyʼéֽl׃"],[8,23,"וְ⁠עַבְדּ֥וֹן וְ⁠זִכְרִ֖י וְ⁠חָנָֽן׃","wĕ⁠ʻabĕḋ֥wòn wĕ⁠zikĕri֖y wĕ⁠ẖánáֽn׃"],[8,24,"וַ⁠חֲנַנְיָ֥ה וְ⁠עֵילָ֖ם וְ⁠עַנְתֹתִיָּֽה׃","wa⁠ẖànanĕyá֥h wĕ⁠ʻéylá֖m wĕ⁠ʻanĕţòţiyáֽ̇h׃"],[8,25,"וְ⁠יִפְדְיָ֥ה ו⁠פניאל בְּנֵ֥י שָׁשָֽׁק׃","wĕ⁠yipĕdĕyá֥h w⁠pnyʼl bĕ̇né֥y şá̌şáֽ̌q׃"],[8,26,"וְ⁠שַׁמְשְׁרַ֥י וּ⁠שְׁחַרְיָ֖ה וַ⁠עֲתַלְיָֽה׃","wĕ⁠şǎmĕşĕ̌ra֥y ẇ⁠şĕ̌ẖarĕyá֖h wa⁠ʻàţalĕyáֽh׃"],[8,27,"וְ⁠יַעֲרֶשְׁיָ֧ה וְ⁠אֵלִיָּ֛ה וְ⁠זִכְרִ֖י בְּנֵ֥י יְרֹחָֽם׃","wĕ⁠yaʻàreşĕ̌yá֧h wĕ⁠ʼéliyá֛̇h wĕ⁠zikĕri֖y bĕ̇né֥y yĕròẖáֽm׃"],[8,28,"אֵ֣לֶּה רָאשֵׁ֥י אָב֛וֹת לְ⁠תֹלְדוֹתָ֖⁠ם רָאשִׁ֑ים אֵ֖לֶּה יָשְׁב֥וּ בִ⁠ירוּשָׁלִָֽם׃ס","ʼé֣lėh ráʼşé֥̌y ʼáb֛wòţ lĕ⁠ţòlĕdwòţá֖⁠m ráʼşǐ֑ym ʼé֖lėh yáşĕ̌b֥ẇ bi⁠yrẇşá̌liáֽm׃s"],[8,29,"וּ⁠בְ⁠גִבְע֥וֹן יָשְׁב֖וּ אֲבִ֣י גִבְע֑וֹן וְ⁠שֵׁ֥ם אִשְׁתּ֖⁠וֹ מַעֲכָֽה׃","ẇ⁠bĕ⁠gibĕʻ֥wòn yáşĕ̌b֖ẇ ʼàbi֣y gibĕʻ֑wòn wĕ⁠şé֥̌m ʼişĕ̌ţ֖̇⁠wò maʻàkáֽh׃"],[8,30,"וּ⁠בְנ֥⁠וֹ הַ⁠בְּכ֖וֹר עַבְדּ֑וֹן וְ⁠צ֥וּר וְ⁠קִ֖ישׁ וּ⁠בַ֥עַל וְ⁠נָדָֽב׃","ẇ⁠bĕn֥⁠wò ha⁠bĕ̇k֖wòr ʻabĕḋ֑wòn wĕ⁠ẕ֥ẇr wĕ⁠qi֖yş̌ ẇ⁠ba֥ʻal wĕ⁠nádáֽb׃"],[8,31,"וּ⁠גְד֥וֹר וְ⁠אַחְי֖וֹ וָ⁠זָֽכֶר׃","ẇ⁠gĕd֥wòr wĕ⁠ʼaẖĕy֖wò wá⁠záֽker׃"],[8,32,"וּ⁠מִקְל֖וֹת הוֹלִ֣יד אֶת־שִׁמְאָ֑ה וְ⁠אַף־הֵ֗מָּה נֶ֧גֶד אֲחֵי⁠הֶ֛ם יָשְׁב֥וּ בִ⁠ירוּשָׁלִַ֖ם עִם־אֲחֵי⁠הֶֽם׃ס","ẇ⁠miqĕl֖wòţ hwòli֣yd ʼeţ-şǐmĕʼá֑h wĕ⁠ʼap-hé֗má̇h ne֧ged ʼàẖéy⁠he֛m yáşĕ̌b֥ẇ bi⁠yrẇşá̌lia֖m ʻim-ʼàẖéy⁠heֽm׃s"],[8,33,"וְ⁠נֵר֙ הוֹלִ֣יד אֶת־קִ֔ישׁ וְ⁠קִ֖ישׁ הוֹלִ֣יד אֶת־שָׁא֑וּל וְ⁠שָׁא֗וּל הוֹלִ֤יד אֶת־יְהֽוֹנָתָן֙ וְ⁠אֶת־מַלְכִּי־שׁ֔וּעַ וְ⁠אֶת־אֲבִֽינָדָ֖ב וְ⁠אֶת־אֶשְׁבָּֽעַל׃","wĕ⁠nér֙ hwòli֣yd ʼeţ-qi֔yş̌ wĕ⁠qi֖yş̌ hwòli֣yd ʼeţ-şá̌ʼ֑ẇl wĕ⁠şá̌ʼ֗ẇl hwòli֤yd ʼeţ-yĕhֽwònáţán֙ wĕ⁠ʼeţ-malĕki̇y-ş̌֔ẇʻa wĕ⁠ʼeţ-ʼàbiֽynádá֖b wĕ⁠ʼeţ-ʼeşĕ̌báֽ̇ʻal׃"],[8,34,"וּ⁠בֶן־יְהוֹנָתָ֖ן מְרִ֣יב בָּ֑עַל וּ⁠מְרִ֥יב בַּ֖עַל הוֹלִ֥יד אֶת־מִיכָֽה׃ס","ẇ⁠ben-yĕhwònáţá֖n mĕri֣yb bá֑̇ʻal ẇ⁠mĕri֥yb bȧ֖ʻal hwòli֥yd ʼeţ-miykáֽh׃s"],[8,35,"וּ⁠בְנֵ֖י מִיכָ֑ה פִּית֥וֹן וָ⁠מֶ֖לֶךְ וְ⁠תַאְרֵ֥עַ וְ⁠אָחָֽז׃","ẇ⁠bĕné֖y miyká֑h pi̇yţ֥wòn wá⁠me֖lekĕ wĕ⁠ţaʼĕré֥ʻa wĕ⁠ʼáẖáֽz׃"],[8,36,"וְ⁠אָחָז֙ הוֹלִ֣יד אֶת־יְהוֹעַדָּ֔ה וִ⁠יהֽוֹעַדָּ֗ה הוֹלִ֛יד אֶת־עָלֶ֥מֶת וְ⁠אֶת־עַזְמָ֖וֶת וְ⁠אֶת־זִמְרִ֑י וְ⁠זִמְרִ֖י הוֹלִ֥יד אֶת־מוֹצָֽא׃","wĕ⁠ʼáẖáz֙ hwòli֣yd ʼeţ-yĕhwòʻadá̇֔h wi⁠yhֽwòʻadá̇֗h hwòli֛yd ʼeţ-ʻále֥meţ wĕ⁠ʼeţ-ʻazĕmá֖weţ wĕ⁠ʼeţ-zimĕri֑y wĕ⁠zimĕri֖y hwòli֥yd ʼeţ-mwòẕáֽʼ׃"],[8,37,"וּ⁠מוֹצָ֖א הוֹלִ֣יד אֶת־בִּנְעָ֑א רָפָ֥ה בְנ֛⁠וֹ אֶלְעָשָׂ֥ה בְנ֖⁠וֹ אָצֵ֥ל בְּנֽ⁠וֹ׃","ẇ⁠mwòẕá֖ʼ hwòli֣yd ʼeţ-bi̇nĕʻá֑ʼ rápá֥h bĕn֛⁠wò ʼelĕʻáşá֥̂h bĕn֖⁠wò ʼáẕé֥l bĕ̇nֽ⁠wò׃"],[8,38,"וּ⁠לְ⁠אָצֵל֮ שִׁשָּׁ֣ה בָנִים֒ וְ⁠אֵ֣לֶּה שְׁמוֹתָ֗⁠ם עַזְרִיקָ֥ם ׀ בֹּ֨כְרוּ֙ וְ⁠יִשְׁמָעֵ֣אל וּ⁠שְׁעַרְיָ֔ה וְ⁠עֹבַדְיָ֖ה וְ⁠חָנָ֑ן כָּל־אֵ֖לֶּה בְּנֵ֥י אָצַֽל׃","ẇ⁠lĕ⁠ʼáẕél֮ şǐşá֣̇̌h bániym֒ wĕ⁠ʼé֣lėh şĕ̌mwòţá֗⁠m ʻazĕriyqá֥m ׀ bò̇֨kĕrẇ֙ wĕ⁠yişĕ̌máʻé֣ʼl ẇ⁠şĕ̌ʻarĕyá֔h wĕ⁠ʻòbadĕyá֖h wĕ⁠ẖáná֑n ká̇l-ʼé֖lėh bĕ̇né֥y ʼáẕaֽl׃"],[8,39,"וּ⁠בְנֵ֖י עֵ֣שֶׁק אָחִ֑י⁠ו אוּלָ֣ם בְּכֹר֔⁠וֹ יְעוּשׁ֙ הַ⁠שֵּׁנִ֔י וֶֽ⁠אֱלִיפֶ֖לֶט הַ⁠שְּׁלִשִֽׁי׃","ẇ⁠bĕné֖y ʻé֣şěq ʼáẖi֑y⁠w ʼẇlá֣m bĕ̇kòr֔⁠wò yĕʻẇş̌֙ ha⁠şé̇̌ni֔y wֽe⁠ʼèliype֖let ha⁠şĕ̇̌lişǐֽy׃"],[8,40,"וַֽ⁠יִּהְי֣וּ בְנֵי־א֠וּלָם אֲנָשִׁ֨ים גִּבֹּרֵי־חַ֜יִל דֹּ֣רְכֵי קֶ֗שֶׁת וּ⁠מַרְבִּ֤ים בָּנִים֙ וּ⁠בְנֵ֣י בָנִ֔ים מֵאָ֖ה וַ⁠חֲמִשִּׁ֑ים כָּל־אֵ֖לֶּה מִ⁠בְּנֵ֥י בִנְיָמִֽן׃פ","waֽ⁠yi̇hĕy֣ẇ bĕnéy-ʼ֠ẇlám ʼànáşǐ֨ym gi̇bò̇réy-ẖa֜yil dò֣̇rĕkéy qe֗şěţ ẇ⁠marĕbi֤̇ym bá̇niym֙ ẇ⁠bĕné֣y báni֔ym méʼá֖h wa⁠ẖàmişi֑̇̌ym ká̇l-ʼé֖lėh mi⁠bĕ̇né֥y binĕyámiֽn׃p"],[9,1,"וְ⁠כָל־יִשְׂרָאֵל֙ הִתְיַחְשׂ֔וּ וְ⁠הִנָּ֣⁠ם כְּתוּבִ֔ים עַל־סֵ֖פֶר מַלְכֵ֣י יִשְׂרָאֵ֑ל וִ⁠יהוּדָ֛ה הָגְל֥וּ לְ⁠בָבֶ֖ל בְּ⁠מַעֲלָֽ⁠ם׃ס","wĕ⁠kál-yişĕ̂ráʼél֙ hiţĕyaẖĕş̂֔ẇ wĕ⁠hiná֣̇⁠m kĕ̇ţẇbi֔ym ʻal-sé֖per malĕké֣y yişĕ̂ráʼé֑l wi⁠yhẇdá֛h hágĕl֥ẇ lĕ⁠bábe֖l bĕ̇⁠maʻàláֽ⁠m׃s"],[9,2,"וְ⁠הַ⁠יּוֹשְׁבִים֙ הָ⁠רִ֣אשֹׁנִ֔ים אֲשֶׁ֥ר בַּ⁠אֲחֻזָּתָ֖⁠ם בְּ⁠עָרֵי⁠הֶ֑ם יִשְׂרָאֵל֙ הַ⁠כֹּ֣הֲנִ֔ים הַ⁠לְוִיִּ֖ם וְ⁠הַ⁠נְּתִינִֽים׃","wĕ⁠ha⁠ẏwòşĕ̌biym֙ há⁠ri֣ʼşò̌ni֔ym ʼàşě֥r bȧ⁠ʼàẖuzá̇ţá֖⁠m bĕ̇⁠ʻáréy⁠he֑m yişĕ̂ráʼél֙ ha⁠kò֣̇hàni֔ym ha⁠lĕwiyi֖̇m wĕ⁠ha⁠nĕ̇ţiyniֽym׃"],[9,3,"וּ⁠בִ⁠ירוּשָׁלִַ֨ם֙ יָשְׁב֔וּ מִן־בְּנֵ֥י יְהוּדָ֖ה וּ⁠מִן־בְּנֵ֣י בִנְיָמִ֑ן וּ⁠מִן־בְּנֵ֥י אֶפְרַ֖יִם וּ⁠מְנַשֶּֽׁה׃","ẇ⁠bi⁠yrẇşá̌lia֨m֙ yáşĕ̌b֔ẇ min-bĕ̇né֥y yĕhẇdá֖h ẇ⁠min-bĕ̇né֣y binĕyámi֑n ẇ⁠min-bĕ̇né֥y ʼepĕra֖yim ẇ⁠mĕnaşėֽ̌h׃"],[9,4,"עוּתַ֨י בֶּן־עַמִּיה֤וּד בֶּן־עָמְרִי֙ בֶּן־אִמְרִ֣י בֶן־בני⁠מן־בְּנֵי־פֶ֖רֶץ בֶּן־יְהוּדָֽה׃","ʻẇţa֨y bėn-ʻami̇yh֤ẇd bėn-ʻámĕriy֙ bėn-ʼimĕri֣y ben-bny⁠mn-bĕ̇néy-pe֖reẕ bėn-yĕhẇdáֽh׃"],[9,5,"וּ⁠מִן־הַ⁠שִּׁ֣ילוֹנִ֔י עֲשָׂיָ֥ה הַ⁠בְּכ֖וֹר וּ⁠בָנָֽי⁠ו׃","ẇ⁠min-ha⁠şi֣̇̌ylwòni֔y ʻàşá̂yá֥h ha⁠bĕ̇k֖wòr ẇ⁠bánáֽy⁠w׃"],[9,6,"וּ⁠מִן־בְּנֵי־זֶ֖רַח יְעוּאֵ֑ל וַ⁠אֲחֵי⁠הֶ֖ם שֵׁשׁ־מֵא֥וֹת וְ⁠תִשְׁעִֽים׃","ẇ⁠min-bĕ̇néy-ze֖raẖ yĕʻẇʼé֑l wa⁠ʼàẖéy⁠he֖m şé̌ş̌-méʼ֥wòţ wĕ⁠ţişĕ̌ʻiֽym׃"],[9,7,"וּ⁠מִן־בְּנֵ֖י בִּנְיָמִ֑ן סַלּוּא֙ בֶּן־מְשֻׁלָּ֔ם בֶּן־הוֹדַוְיָ֖ה בֶּן־הַ⁠סְּנֻאָֽה׃","ẇ⁠min-bĕ̇né֖y bi̇nĕyámi֑n sal̇ẇʼ֙ bėn-mĕşǔlá̇֔m bėn-hwòdawĕyá֖h bėn-ha⁠sĕ̇nuʼáֽh׃"],[9,8,"וְ⁠יִבְנְיָה֙ בֶּן־יְרֹחָ֔ם וְ⁠אֵלָ֥ה בֶן־עֻזִּ֖י בֶּן־מִכְרִ֑י וּ⁠מְשֻׁלָּם֙ בֶּן־שְׁפַטְיָ֔ה בֶּן־רְעוּאֵ֖ל בֶּן־יִבְנִיָּֽה׃","wĕ⁠yibĕnĕyáh֙ bėn-yĕròẖá֔m wĕ⁠ʼélá֥h ben-ʻuzi֖̇y bėn-mikĕri֑y ẇ⁠mĕşǔlá̇m֙ bėn-şĕ̌patĕyá֔h bėn-rĕʻẇʼé֖l bėn-yibĕniyáֽ̇h׃"],[9,9,"וַ⁠אֲחֵי⁠הֶם֙ לְ⁠תֹ֣לְדוֹתָ֔⁠ם תְּשַׁ֥ע מֵא֖וֹת וַ⁠חֲמִשִּׁ֣ים וְ⁠שִׁשָּׁ֑ה כָּל־אֵ֣לֶּה אֲנָשִׁ֔ים רָאשֵׁ֥י אָב֖וֹת לְ⁠בֵ֥ית אֲבֹתֵי⁠הֶֽם׃ס","wa⁠ʼàẖéy⁠hem֙ lĕ⁠ţò֣lĕdwòţá֔⁠m ţĕ̇şǎ֥ʻ méʼ֖wòţ wa⁠ẖàmişi֣̇̌ym wĕ⁠şǐşá֑̇̌h ká̇l-ʼé֣lėh ʼànáşǐ֔ym ráʼşé֥̌y ʼáb֖wòţ lĕ⁠bé֥yţ ʼàbòţéy⁠heֽm׃s"],[9,10,"וּ⁠מִן־הַֽ⁠כֹּהֲנִ֑ים יְדַֽעְיָ֥ה וִ⁠יהוֹיָרִ֖יב וְ⁠יָכִֽין׃","ẇ⁠min-haֽ⁠kò̇hàni֑ym yĕdaֽʻĕyá֥h wi⁠yhwòyári֖yb wĕ⁠yákiֽyn׃"],[9,11,"וַ⁠עֲזַרְיָ֨ה בֶן־חִלְקִיָּ֜ה בֶּן־מְשֻׁלָּ֣ם בֶּן־צָד֗וֹק בֶּן־מְרָיוֹת֙ בֶּן־אֲחִיט֔וּב נְגִ֖יד בֵּ֥ית הָ⁠אֱלֹהִֽים׃ס","wa⁠ʻàzarĕyá֨h ben-ẖilĕqiyá̇֜h bėn-mĕşǔlá֣̇m bėn-ẕád֗wòq bėn-mĕráywòţ֙ bėn-ʼàẖiyt֔ẇb nĕgi֖yd bé֥̇yţ há⁠ʼèlòhiֽym׃s"],[9,12,"וַ⁠עֲדָיָה֙ בֶּן־יְרֹחָ֔ם בֶּן־פַּשְׁח֖וּר בֶּן־מַלְכִּיָּ֑ה וּ⁠מַעְשַׂ֨י בֶּן־עֲדִיאֵ֧ל בֶּן־יַחְזֵ֛רָה בֶּן־מְשֻׁלָּ֥ם בֶּן־מְשִׁלֵּמִ֖ית בֶּן־אִמֵּֽר׃","wa⁠ʻàdáyáh֙ bėn-yĕròẖá֔m bėn-pȧşĕ̌ẖ֖ẇr bėn-malĕki̇yá֑̇h ẇ⁠maʻĕşâ֨y bėn-ʻàdiyʼé֧l bėn-yaẖĕzé֛ráh bėn-mĕşǔlá֥̇m bėn-mĕşǐlé̇mi֖yţ bėn-ʼiméֽ̇r׃"],[9,13,"וַ⁠אֲחֵי⁠הֶ֗ם רָאשִׁים֙ לְ⁠בֵ֣ית אֲבוֹתָ֔⁠ם אֶ֕לֶף וּ⁠שְׁבַ֥ע מֵא֖וֹת וְ⁠שִׁשִּׁ֑ים גִּבּ֣וֹרֵי חֵ֔יל מְלֶ֖אכֶת עֲבוֹדַ֥ת בֵּית־הָ⁠אֱלֹהִֽים׃","wa⁠ʼàẖéy⁠he֗m ráʼşǐym֙ lĕ⁠bé֣yţ ʼàbwòţá֔⁠m ʼe֕lep ẇ⁠şĕ̌ba֥ʻ méʼ֖wòţ wĕ⁠şǐşi֑̇̌ym gi̇ḃ֣wòréy ẖé֔yl mĕle֖ʼkeţ ʻàbwòda֥ţ bé̇yţ-há⁠ʼèlòhiֽym׃"],[9,14,"וּ⁠מִֽן־הַ⁠לְוִיִּ֑ם שְׁמַֽעְיָ֧ה בֶן־חַשּׁ֛וּב בֶּן־עַזְרִיקָ֥ם בֶּן־חֲשַׁבְיָ֖ה מִן־בְּנֵ֥י מְרָרִֽי׃","ẇ⁠miֽn-ha⁠lĕwiyi֑̇m şĕ̌maֽʻĕyá֧h ben-ẖaş֛̇̌ẇb bėn-ʻazĕriyqá֥m bėn-ẖàşǎbĕyá֖h min-bĕ̇né֥y mĕráriֽy׃"],[9,15,"וּ⁠בַקְבַּקַּ֥ר חֶ֖רֶשׁ וְ⁠גָלָ֑ל וּ⁠מַתַּנְיָה֙ בֶּן־מִיכָ֔א בֶּן־זִכְרִ֖י בֶּן־אָסָֽף׃","ẇ⁠baqĕbȧqȧ֥r ẖe֖reş̌ wĕ⁠gálá֑l ẇ⁠maţȧnĕyáh֙ bėn-miyká֔ʼ bėn-zikĕri֖y bėn-ʼásáֽp׃"],[9,16,"וְ⁠עֹבַדְיָה֙ בֶּֽן־שְׁמַֽעְיָ֔ה בֶּן־גָּלָ֖ל בֶּן־יְדוּת֑וּן וּ⁠בֶרֶכְיָ֤ה בֶן־אָסָא֙ בֶּן־אֶלְקָנָ֔ה הַ⁠יּוֹשֵׁ֖ב בְּ⁠חַצְרֵ֥י נְטוֹפָתִֽי׃","wĕ⁠ʻòbadĕyáh֙ bėֽn-şĕ̌maֽʻĕyá֔h bėn-gá̇lá֖l bėn-yĕdẇţ֑ẇn ẇ⁠berekĕyá֤h ben-ʼásáʼ֙ bėn-ʼelĕqáná֔h ha⁠ẏwòşé֖̌b bĕ̇⁠ẖaẕĕré֥y nĕtwòpáţiֽy׃"],[9,17,"וְ⁠הַ⁠שֹּׁעֲרִים֙ שַׁלּ֣וּם וְ⁠עַקּ֔וּב וְ⁠טַלְמֹ֖ן וַ⁠אֲחִימָ֑ן וַ⁠אֲחִי⁠הֶ֥ם שַׁלּ֖וּם הָ⁠רֹֽאשׁ׃","wĕ⁠ha⁠şò̇̌ʻàriym֙ şǎl֣̇ẇm wĕ⁠ʻaq̇֔ẇb wĕ⁠talĕmò֖n wa⁠ʼàẖiymá֑n wa⁠ʼàẖiy⁠he֥m şǎl֖̇ẇm há⁠ròֽʼş̌׃"],[9,18,"וְֽ⁠עַד־הֵ֔נָּה בְּ⁠שַׁ֥עַר הַ⁠מֶּ֖לֶךְ מִזְרָ֑חָ⁠ה הֵ֚מָּה הַ⁠שֹּׁ֣עֲרִ֔ים לְ⁠מַחֲנ֖וֹת בְּנֵ֥י לֵוִֽי׃","wĕֽ⁠ʻad-hé֔ná̇h bĕ̇⁠şǎ֥ʻar ha⁠mė֖lekĕ mizĕrá֑ẖá⁠h hé֚má̇h ha⁠şò֣̇̌ʻàri֔ym lĕ⁠maẖàn֖wòţ bĕ̇né֥y léwiֽy׃"],[9,19,"וְ⁠שַׁלּ֣וּם בֶּן־ק֠וֹרֵא בֶּן־אֶבְיָסָ֨ף בֶּן־קֹ֜רַח וְֽ⁠אֶחָ֧י⁠ו לְ⁠בֵית־אָבִ֣י⁠ו הַ⁠קָּרְחִ֗ים עַ֚ל מְלֶ֣אכֶת הָ⁠עֲבוֹדָ֔ה שֹׁמְרֵ֥י הַ⁠סִּפִּ֖ים לָ⁠אֹ֑הֶל וַ⁠אֲבֹֽתֵי⁠הֶם֙ עַל־מַחֲנֵ֣ה יְהוָ֔ה שֹׁמְרֵ֖י הַ⁠מָּבֽוֹא׃","wĕ⁠şǎl֣̇ẇm bėn-q֠wòréʼ bėn-ʼebĕyásá֨p bėn-qò֜raẖ wĕֽ⁠ʼeẖá֧y⁠w lĕ⁠béyţ-ʼábi֣y⁠w ha⁠qá̇rĕẖi֗ym ʻa֚l mĕle֣ʼkeţ há⁠ʻàbwòdá֔h şò̌mĕré֥y ha⁠si̇pi֖̇ym lá⁠ʼò֑hel wa⁠ʼàbòֽţéy⁠hem֙ ʻal-maẖàné֣h yĕhwá֔h şò̌mĕré֖y ha⁠má̇bֽwòʼ׃"],[9,20,"וּ⁠פִֽינְחָ֣ס בֶּן־אֶלְעָזָ֗ר נָגִ֨יד הָיָ֧ה עֲלֵי⁠הֶ֛ם לְ⁠פָנִ֖ים יְהוָ֥ה ׀ עִמּֽ⁠וֹ׃","ẇ⁠piֽynĕẖá֣s bėn-ʼelĕʻázá֗r nági֨yd háyá֧h ʻàléy⁠he֛m lĕ⁠páni֖ym yĕhwá֥h ׀ ʻiṁֽ⁠wò׃"],[9,21,"זְכַרְיָה֙ בֶּ֣ן מְשֶֽׁלֶמְיָ֔ה שֹׁעֵ֥ר פֶּ֖תַח לְ⁠אֹ֥הֶל מוֹעֵֽד׃","zĕkarĕyáh֙ bė֣n mĕşěֽlemĕyá֔h şò̌ʻé֥r pė֖ţaẖ lĕ⁠ʼò֥hel mwòʻéֽd׃"],[9,22,"כֻּלָּ֤⁠ם הַ⁠בְּרוּרִים֙ לְ⁠שֹׁעֲרִ֣ים בַּ⁠סִּפִּ֔ים מָאתַ֖יִם וּ⁠שְׁנֵ֣ים עָשָׂ֑ר הֵ֤מָּה בְ⁠חַצְרֵי⁠הֶם֙ הִתְיַחְשָׂ֔⁠ם הֵ֣מָּה יִסַּ֥ד דָּוִ֛יד וּ⁠שְׁמוּאֵ֥ל הָ⁠רֹאֶ֖ה בֶּ⁠אֱמוּנָתָֽ⁠ם׃","ku̇lá֤̇⁠m ha⁠bĕ̇rẇriym֙ lĕ⁠şò̌ʻàri֣ym bȧ⁠si̇pi̇֔ym máʼţa֖yim ẇ⁠şĕ̌né֣ym ʻáşá֑̂r hé֤má̇h bĕ⁠ẖaẕĕréy⁠hem֙ hiţĕyaẖĕşá̂֔⁠m hé֣má̇h yisȧ֥d dá̇wi֛yd ẇ⁠şĕ̌mẇʼé֥l há⁠ròʼe֖h bė⁠ʼèmẇnáţáֽ⁠m׃"],[9,23,"וְ⁠הֵ֨ם וּ⁠בְנֵי⁠הֶ֜ם עַל־הַ⁠שְּׁעָרִ֧ים לְ⁠בֵית־יְהוָ֛ה לְ⁠בֵ֥ית־הָ⁠אֹ֖הֶל לְ⁠מִשְׁמָרֽוֹת׃","wĕ⁠hé֨m ẇ⁠bĕnéy⁠he֜m ʻal-ha⁠şĕ̇̌ʻári֧ym lĕ⁠béyţ-yĕhwá֛h lĕ⁠bé֥yţ-há⁠ʼò֖hel lĕ⁠mişĕ̌márֽwòţ׃"],[9,24,"לְ⁠אַרְבַּ֣ע רוּח֔וֹת יִהְי֖וּ הַ⁠שֹּׁעֲרִ֑ים מִזְרָ֥ח יָ֖מָּ⁠ה צָפ֥וֹנָ⁠ה וָ⁠נֶֽגְבָּ⁠ה׃","lĕ⁠ʼarĕbȧ֣ʻ rẇẖ֔wòţ yihĕy֖ẇ ha⁠şò̇̌ʻàri֑ym mizĕrá֥ẖ yá֖má̇⁠h ẕáp֥wòná⁠h wá⁠neֽgĕbá̇⁠h׃"],[9,25,"וַ⁠אֲחֵי⁠הֶ֨ם בְּ⁠חַצְרֵי⁠הֶ֜ם לָ⁠ב֨וֹא לְ⁠שִׁבְעַ֧ת הַ⁠יָּמִ֛ים מֵ⁠עֵ֥ת אֶל־עֵ֖ת עִם־אֵֽלֶּה׃","wa⁠ʼàẖéy⁠he֨m bĕ̇⁠ẖaẕĕréy⁠he֜m lá⁠b֨wòʼ lĕ⁠şǐbĕʻa֧ţ ha⁠yá̇mi֛ym mé⁠ʻé֥ţ ʼel-ʻé֖ţ ʻim-ʼéֽlėh׃"],[9,26,"כִּ֣י בֶ⁠אֱמוּנָ֞ה הֵ֗מָּה אַרְבַּ֨עַת֙ גִּבֹּרֵ֣י הַ⁠שֹּׁעֲרִ֔ים הֵ֖ם הַ⁠לְוִיִּ֑ם וְ⁠הָיוּ֙ עַל־הַ⁠לְּשָׁכ֔וֹת וְ⁠עַ֥ל הָ⁠אֹצְר֖וֹת בֵּ֥ית הָ⁠אֱלֹהִֽים׃","ki֣̇y be⁠ʼèmẇná֞h hé֗má̇h ʼarĕbȧ֨ʻaţ֙ gi̇bò̇ré֣y ha⁠şò̇̌ʻàri֔ym hé֖m ha⁠lĕwiyi֑̇m wĕ⁠háyẇ֙ ʻal-ha⁠lĕ̇şá̌k֔wòţ wĕ⁠ʻa֥l há⁠ʼòẕĕr֖wòţ bé֥̇yţ há⁠ʼèlòhiֽym׃"],[9,27,"וּ⁠סְבִיב֥וֹת בֵּית־הָ⁠אֱלֹהִ֖ים יָלִ֑ינוּ כִּֽי־עֲלֵי⁠הֶ֣ם מִשְׁמֶ֔רֶת וְ⁠הֵ֥ם עַל־הַ⁠מַּפְתֵּ֖חַ וְ⁠לַ⁠בֹּ֥קֶר לַ⁠בֹּֽקֶר׃","ẇ⁠sĕbiyb֥wòţ bé̇yţ-há⁠ʼèlòhi֖ym yáli֑ynẇ kiֽ̇y-ʻàléy⁠he֣m mişĕ̌me֔reţ wĕ⁠hé֥m ʻal-ha⁠mȧpĕţé֖̇ẖa wĕ⁠la⁠bò֥̇qer la⁠bòֽ̇qer׃"],[9,28,"וּ⁠מֵ⁠הֶ֖ם עַל־כְּלֵ֣י הָ⁠עֲבוֹדָ֑ה כִּֽי־בְ⁠מִסְפָּ֣ר יְבִיא֔וּ⁠ם וּ⁠בְ⁠מִסְפָּ֖ר יוֹצִיאֽוּ⁠ם׃","ẇ⁠mé⁠he֖m ʻal-kĕ̇lé֣y há⁠ʻàbwòdá֑h kiֽ̇y-bĕ⁠misĕpá֣̇r yĕbiyʼ֔ẇ⁠m ẇ⁠bĕ⁠misĕpá֖̇r ywòẕiyʼֽẇ⁠m׃"],[9,29,"וּ⁠מֵ⁠הֶ֗ם מְמֻנִּים֙ עַל־הַ⁠כֵּלִ֔ים וְ⁠עַ֖ל כָּל־כְּלֵ֣י הַ⁠קֹּ֑דֶשׁ וְ⁠עַל־הַ⁠סֹּ֨לֶת֙ וְ⁠הַ⁠יַּ֣יִן וְ⁠הַ⁠שֶּׁ֔מֶן וְ⁠הַ⁠לְּבוֹנָ֖ה וְ⁠הַ⁠בְּשָׂמִֽים׃","ẇ⁠mé⁠he֗m mĕmuni̇ym֙ ʻal-ha⁠ké̇li֔ym wĕ⁠ʻa֖l ká̇l-kĕ̇lé֣y ha⁠qò֑̇deş̌ wĕ⁠ʻal-ha⁠sò̇֨leţ֙ wĕ⁠ha⁠yȧ֣yin wĕ⁠ha⁠şė̌֔men wĕ⁠ha⁠lĕ̇bwòná֖h wĕ⁠ha⁠bĕ̇şá̂miֽym׃"],[9,30,"וּ⁠מִן־בְּנֵי֙ הַ⁠כֹּ֣הֲנִ֔ים רֹקְחֵ֥י הַ⁠מִּרְקַ֖חַת לַ⁠בְּשָׂמִֽים׃","ẇ⁠min-bĕ̇néy֙ ha⁠kò֣̇hàni֔ym ròqĕẖé֥y ha⁠mi̇rĕqa֖ẖaţ la⁠bĕ̇şá̂miֽym׃"],[9,31,"וּ⁠מַתִּתְיָה֙ מִן־הַ⁠לְוִיִּ֔ם ה֥וּא הַ⁠בְּכ֖וֹר לְ⁠שַׁלֻּ֣ם הַ⁠קָּרְחִ֑י בֶּ⁠אֱמוּנָ֕ה עַ֖ל מַעֲשֵׂ֥ה הַ⁠חֲבִתִּֽים׃","ẇ⁠maţi̇ţĕyáh֙ min-ha⁠lĕwiyi̇֔m h֥ẇʼ ha⁠bĕ̇k֖wòr lĕ⁠şǎlu֣̇m ha⁠qá̇rĕẖi֑y bė⁠ʼèmẇná֕h ʻa֖l maʻàşé֥̂h ha⁠ẖàbiţiֽ̇ym׃"],[9,32,"וּ⁠מִן־בְּנֵ֧י הַ⁠קְּהָתִ֛י מִן־אֲחֵי⁠הֶ֖ם עַל־לֶ֣חֶם הַֽ⁠מַּעֲרָ֑כֶת לְ⁠הָכִ֖ין שַׁבַּ֥ת שַׁבָּֽת׃ס","ẇ⁠min-bĕ̇né֧y ha⁠qĕ̇háţi֛y min-ʼàẖéy⁠he֖m ʻal-le֣ẖem haֽ⁠mȧʻàrá֑keţ lĕ⁠háki֖yn şǎbȧ֥ţ şǎbáֽ̇ţ׃s"],[9,33,"וְ⁠אֵ֣לֶּה הַ֠⁠מְשֹׁרְרִים רָאשֵׁ֨י אָב֧וֹת לַ⁠לְוִיִּ֛ם בַּ⁠לְּשָׁכֹ֖ת פטירים כִּֽי־יוֹמָ֥ם וָ⁠לַ֛יְלָה עֲלֵי⁠הֶ֖ם בַּ⁠מְּלָאכָֽה׃","wĕ⁠ʼé֣lėh ha֠⁠mĕşò̌rĕriym ráʼşé̌֨y ʼáb֧wòţ la⁠lĕwiyi֛̇m bȧ⁠lĕ̇şá̌kò֖ţ ptyrym kiֽ̇y-ywòmá֥m wá⁠la֛yĕláh ʻàléy⁠he֖m bȧ⁠mĕ̇láʼkáֽh׃"],[9,34,"אֵלֶּה֩ רָאשֵׁ֨י הָ⁠אָב֧וֹת לַ⁠לְוִיִּ֛ם לְ⁠תֹלְדוֹתָ֖⁠ם רָאשִׁ֑ים אֵ֖לֶּה יָשְׁב֥וּ בִ⁠ירוּשָׁלִָֽם׃פ","ʼélėh֩ ráʼşé̌֨y há⁠ʼáb֧wòţ la⁠lĕwiyi֛̇m lĕ⁠ţòlĕdwòţá֖⁠m ráʼşǐ֑ym ʼé֖lėh yáşĕ̌b֥ẇ bi⁠yrẇşá̌liáֽm׃p"],[9,35,"וּ⁠בְ⁠גִבְע֛וֹן יָשְׁב֥וּ אֲבִֽי־גִבְע֖וֹן יעואל וְ⁠שֵׁ֥ם אִשְׁתּ֖⁠וֹ מַעֲכָֽה׃","ẇ⁠bĕ⁠gibĕʻ֛wòn yáşĕ̌b֥ẇ ʼàbiֽy-gibĕʻ֖wòn yʻwʼl wĕ⁠şé֥̌m ʼişĕ̌ţ֖̇⁠wò maʻàkáֽh׃"],[9,36,"וּ⁠בְנ֥⁠וֹ הַ⁠בְּכ֖וֹר עַבְדּ֑וֹן וְ⁠צ֣וּר וְ⁠קִ֔ישׁ וּ⁠בַ֥עַל וְ⁠נֵ֖ר וְ⁠נָדָֽב׃","ẇ⁠bĕn֥⁠wò ha⁠bĕ̇k֖wòr ʻabĕḋ֑wòn wĕ⁠ẕ֣ẇr wĕ⁠qi֔yş̌ ẇ⁠ba֥ʻal wĕ⁠né֖r wĕ⁠nádáֽb׃"],[9,37,"וּ⁠גְד֣וֹר וְ⁠אַחְי֔וֹ וּ⁠זְכַרְיָ֖ה וּ⁠מִקְלֽוֹת׃","ẇ⁠gĕd֣wòr wĕ⁠ʼaẖĕy֔wò ẇ⁠zĕkarĕyá֖h ẇ⁠miqĕlֽwòţ׃"],[9,38,"וּ⁠מִקְל֖וֹת הוֹלִ֣יד אֶת־שִׁמְאָ֑ם וְ⁠אַף־הֵ֗ם נֶ֧גֶד אֲחֵי⁠הֶ֛ם יָשְׁב֥וּ בִ⁠ירֽוּשָׁלִַ֖ם עִם־אֲחֵי⁠הֶֽם׃ס","ẇ⁠miqĕl֖wòţ hwòli֣yd ʼeţ-şǐmĕʼá֑m wĕ⁠ʼap-hé֗m ne֧ged ʼàẖéy⁠he֛m yáşĕ̌b֥ẇ bi⁠yrֽẇşá̌lia֖m ʻim-ʼàẖéy⁠heֽm׃s"],[9,39,"וְ⁠נֵר֙ הוֹלִ֣יד אֶת־קִ֔ישׁ וְ⁠קִ֖ישׁ הוֹלִ֣יד אֶת־שָׁא֑וּל וְ⁠שָׁא֗וּל הוֹלִ֤יד אֶת־יְהֽוֹנָתָן֙ וְ⁠אֶת־מַלְכִּי־שׁ֔וּעַ וְ⁠אֶת־אֲבִינָדָ֖ב וְ⁠אֶת־אֶשְׁבָּֽעַל׃","wĕ⁠nér֙ hwòli֣yd ʼeţ-qi֔yş̌ wĕ⁠qi֖yş̌ hwòli֣yd ʼeţ-şá̌ʼ֑ẇl wĕ⁠şá̌ʼ֗ẇl hwòli֤yd ʼeţ-yĕhֽwònáţán֙ wĕ⁠ʼeţ-malĕki̇y-ş̌֔ẇʻa wĕ⁠ʼeţ-ʼàbiynádá֖b wĕ⁠ʼeţ-ʼeşĕ̌báֽ̇ʻal׃"],[9,40,"וּ⁠בֶן־יְהוֹנָתָ֖ן מְרִ֣יב בָּ֑עַל וּ⁠מְרִי־בַ֖עַל הוֹלִ֥יד אֶת־מִיכָֽה׃","ẇ⁠ben-yĕhwònáţá֖n mĕri֣yb bá֑̇ʻal ẇ⁠mĕriy-ba֖ʻal hwòli֥yd ʼeţ-miykáֽh׃"],[9,41,"וּ⁠בְנֵ֖י מִיכָ֑ה פִּית֥וֹן וָ⁠מֶ֖לֶךְ וְ⁠תַחְרֵֽעַ׃","ẇ⁠bĕné֖y miyká֑h pi̇yţ֥wòn wá⁠me֖lekĕ wĕ⁠ţaẖĕréֽʻa׃"],[9,42,"וְ⁠אָחָז֙ הוֹלִ֣יד אֶת־יַעְרָ֔ה וְ⁠יַעְרָ֗ה הוֹלִ֛יד אֶת־עָלֶ֥מֶת וְ⁠אֶת־עַזְמָ֖וֶת וְ⁠אֶת־זִמְרִ֑י וְ⁠זִמְרִ֖י הוֹלִ֥יד אֶת־מוֹצָֽא׃","wĕ⁠ʼáẖáz֙ hwòli֣yd ʼeţ-yaʻĕrá֔h wĕ⁠yaʻĕrá֗h hwòli֛yd ʼeţ-ʻále֥meţ wĕ⁠ʼeţ-ʻazĕmá֖weţ wĕ⁠ʼeţ-zimĕri֑y wĕ⁠zimĕri֖y hwòli֥yd ʼeţ-mwòẕáֽʼ׃"],[9,43,"וּ⁠מוֹצָ֖א הוֹלִ֣יד אֶת־בִּנְעָ֑א וּ⁠רְפָיָ֥ה בְנ֛⁠וֹ אֶלְעָשָׂ֥ה בְנ֖⁠וֹ אָצֵ֥ל בְּנֽ⁠וֹ׃","ẇ⁠mwòẕá֖ʼ hwòli֣yd ʼeţ-bi̇nĕʻá֑ʼ ẇ⁠rĕpáyá֥h bĕn֛⁠wò ʼelĕʻáşá֥̂h bĕn֖⁠wò ʼáẕé֥l bĕ̇nֽ⁠wò׃"],[9,44,"וּ⁠לְ⁠אָצֵל֮ שִׁשָּׁ֣ה בָנִים֒ וְ⁠אֵ֣לֶּה שְׁמוֹתָ֗⁠ם עַזְרִיקָ֥ם ׀ בֹּ֨כְרוּ֙ וְ⁠יִשְׁמָעֵ֣אל וּ⁠שְׁעַרְיָ֔ה וְ⁠עֹבַדְיָ֖ה וְ⁠חָנָ֑ן אֵ֖לֶּה בְּנֵ֥י אָצַֽל׃פ","ẇ⁠lĕ⁠ʼáẕél֮ şǐşá֣̇̌h bániym֒ wĕ⁠ʼé֣lėh şĕ̌mwòţá֗⁠m ʻazĕriyqá֥m ׀ bò̇֨kĕrẇ֙ wĕ⁠yişĕ̌máʻé֣ʼl ẇ⁠şĕ̌ʻarĕyá֔h wĕ⁠ʻòbadĕyá֖h wĕ⁠ẖáná֑n ʼé֖lėh bĕ̇né֥y ʼáẕaֽl׃p"],[10,1,"וּ⁠פְלִשְׁתִּ֖ים נִלְחֲמ֣וּ בְ⁠יִשְׂרָאֵ֑ל וַ⁠יָּ֑נָס אִֽישׁ־יִשְׂרָאֵל֙ מִ⁠פְּנֵ֣י פְלִשְׁתִּ֔ים וַ⁠יִּפְּל֥וּ חֲלָלִ֖ים בְּ⁠הַ֥ר גִּלְבֹּֽעַ׃","ẇ⁠pĕlişĕ̌ţi֖̇ym nilĕẖàm֣ẇ bĕ⁠yişĕ̂ráʼé֑l wa⁠yá֑̇nás ʼiֽyş̌-yişĕ̂ráʼél֙ mi⁠pĕ̇né֣y pĕlişĕ̌ţi̇֔ym wa⁠yi̇pĕ̇l֥ẇ ẖàláli֖ym bĕ̇⁠ha֥r gi̇lĕbòֽ̇ʻa׃"],[10,2,"וַ⁠יַּדְבְּק֣וּ פְלִשְׁתִּ֔ים אַחֲרֵ֥י שָׁא֖וּל וְ⁠אַחֲרֵ֣י בָנָ֑י⁠ו וַ⁠יַּכּ֣וּ פְלִשְׁתִּ֗ים אֶת־יוֹנָתָ֧ן וְ⁠אֶת־אֲבִינָדָ֛ב וְ⁠אֶת־מַלְכִּי־שׁ֖וּעַ בְּנֵ֥י שָׁאֽוּל׃","wa⁠yȧdĕbĕ̇q֣ẇ pĕlişĕ̌ţi̇֔ym ʼaẖàré֥y şá̌ʼ֖ẇl wĕ⁠ʼaẖàré֣y báná֑y⁠w wa⁠yȧk֣̇ẇ pĕlişĕ̌ţi̇֗ym ʼeţ-ywònáţá֧n wĕ⁠ʼeţ-ʼàbiynádá֛b wĕ⁠ʼeţ-malĕki̇y-ş֖̌ẇʻa bĕ̇né֥y şá̌ʼֽẇl׃"],[10,3,"וַ⁠תִּכְבַּ֤ד הַ⁠מִּלְחָמָה֙ עַל־שָׁא֔וּל וַ⁠יִּמְצָאֻ֖⁠הוּ הַ⁠מּוֹרִ֣ים בַּ⁠קָּ֑שֶׁת וַ⁠יָּ֖חֶל מִן־הַ⁠יּוֹרִֽים׃","wa⁠ţi̇kĕbȧ֤d ha⁠mi̇lĕẖámáh֙ ʻal-şá̌ʼ֔ẇl wa⁠yi̇mĕẕáʼu֖⁠hẇ ha⁠ṁwòri֣ym bȧ⁠qá֑̇şěţ wa⁠yá֖̇ẖel min-ha⁠ẏwòriֽym׃"],[10,4,"וַ⁠יֹּ֣אמֶר שָׁאוּל֩ אֶל־נֹשֵׂ֨א כֵלָ֜י⁠ו שְׁלֹ֥ף חַרְבְּ⁠ךָ֣ ׀ וְ⁠דָקְרֵ֣⁠נִי בָ֗⁠הּ פֶּן־יָבֹ֜אוּ הָ⁠עֲרֵלִ֤ים הָ⁠אֵ֨לֶּה֙ וְ⁠הִתְעַלְּלוּ־בִ֔⁠י וְ⁠לֹ֤א אָבָה֙ נֹשֵׂ֣א כֵלָ֔י⁠ו כִּ֥י יָרֵ֖א מְאֹ֑ד ס וַ⁠יִּקַּ֤ח שָׁאוּל֙ אֶת־הַ⁠חֶ֔רֶב וַ⁠יִּפֹּ֖ל עָלֶֽי⁠הָ׃","wa⁠yò֣̇ʼmer şá̌ʼẇl֩ ʼel-nòşé̂֨ʼ kélá֜y⁠w şĕ̌lò֥p ẖarĕbĕ̇⁠ká֣ ׀ wĕ⁠dáqĕré֣⁠niy bá֗⁠ḣ pėn-yábò֜ʼẇ há⁠ʻàréli֤ym há⁠ʼé֨lėh֙ wĕ⁠hiţĕʻalĕ̇lẇ-bi֔⁠y wĕ⁠lò֤ʼ ʼábáh֙ nòşé֣̂ʼ kélá֔y⁠w ki֥̇y yáré֖ʼ mĕʼò֑d s wa⁠yi̇qȧ֤ẖ şá̌ʼẇl֙ ʼeţ-ha⁠ẖe֔reb wa⁠yi̇pò֖̇l ʻáleֽy⁠há׃"],[10,5,"וַ⁠יַּ֥רְא נֹשֵֽׂא־כֵלָ֖י⁠ו כִּ֣י מֵ֣ת שָׁא֑וּל וַ⁠יִּפֹּ֥ל גַּם־ה֛וּא עַל־הַ⁠חֶ֖רֶב וַ⁠יָּמֹֽת׃ס","wa⁠yȧ֥rĕʼ nòşéֽ̂ʼ-kélá֖y⁠w ki֣̇y mé֣ţ şá̌ʼ֑ẇl wa⁠yi̇pò֥̇l gȧm-h֛ẇʼ ʻal-ha⁠ẖe֖reb wa⁠yá̇mòֽţ׃s"],[10,6,"וַ⁠יָּ֤מָת שָׁאוּל֙ וּ⁠שְׁלֹ֣שֶׁת בָּנָ֔י⁠ו וְ⁠כָל־בֵּית֖⁠וֹ יַחְדָּ֥ו מֵֽתוּ׃","wa⁠yá֤̇máţ şá̌ʼẇl֙ ẇ⁠şĕ̌lò֣şěţ bá̇ná֔y⁠w wĕ⁠kál-bé̇yţ֖⁠wò yaẖĕdá֥̇w méֽţẇ׃"],[10,7,"וַ֠⁠יִּרְאוּ כָּל־אִ֨ישׁ יִשְׂרָאֵ֤ל אֲשֶׁר־בָּ⁠עֵ֨מֶק֙ כִּ֣י נָ֔סוּ וְ⁠כִי־מֵ֖תוּ שָׁא֣וּל וּ⁠בָנָ֑י⁠ו וַ⁠יַּעַזְב֤וּ עָרֵי⁠הֶם֙ וַ⁠יָּנֻ֔סוּ וַ⁠יָּבֹ֣אוּ פְלִשְׁתִּ֔ים וַ⁠יֵּשְׁב֖וּ בָּ⁠הֶֽם׃ס","wa֠⁠yi̇rĕʼẇ ká̇l-ʼi֨yş̌ yişĕ̂ráʼé֤l ʼàşěr-bá̇⁠ʻé֨meq֙ ki֣̇y ná֔sẇ wĕ⁠kiy-mé֖ţẇ şá̌ʼ֣ẇl ẇ⁠báná֑y⁠w wa⁠yȧʻazĕb֤ẇ ʻáréy⁠hem֙ wa⁠yá̇nu֔sẇ wa⁠yá̇bò֣ʼẇ pĕlişĕ̌ţi̇֔ym wa⁠yé̇şĕ̌b֖ẇ bá̇⁠heֽm׃s"],[10,8,"וַ⁠יְהִי֙ מִֽ⁠מָּחֳרָ֔ת וַ⁠יָּבֹ֣אוּ פְלִשְׁתִּ֔ים לְ⁠פַשֵּׁ֖ט אֶת־הַֽ⁠חֲלָלִ֑ים וַֽ⁠יִּמְצְא֤וּ אֶת־שָׁאוּל֙ וְ⁠אֶת־בָּנָ֔י⁠ו נֹפְלִ֖ים בְּ⁠הַ֥ר גִּלְבֹּֽעַ׃","wa⁠yĕhiy֙ miֽ⁠má̇ẖorá֔ţ wa⁠yá̇bò֣ʼẇ pĕlişĕ̌ţi̇֔ym lĕ⁠paşé֖̇̌t ʼeţ-hֽa⁠ẖàláli֑ym waֽ⁠yi̇mĕẕĕʼ֤ẇ ʼeţ-şá̌ʼẇl֙ wĕ⁠ʼeţ-bá̇ná֔y⁠w nòpĕli֖ym bĕ̇⁠ha֥r gi̇lĕbòֽ̇ʻa׃"],[10,9,"וַ⁠יַּ֨פְשִׁיטֻ֔⁠הוּ וַ⁠יִּשְׂא֥וּ אֶת־רֹאשׁ֖⁠וֹ וְ⁠אֶת־כֵּלָ֑י⁠ו וַ⁠יְשַׁלְּח֨וּ בְ⁠אֶֽרֶץ־פְלִשְׁתִּ֜ים סָבִ֗יב לְ⁠בַשֵּׂ֛ר אֶת־עֲצַבֵּי⁠הֶ֖ם וְ⁠אֶת־הָ⁠עָֽם׃","wa⁠yȧ֨pĕşǐytu֔⁠hẇ wa⁠yi̇şĕ̂ʼ֥ẇ ʼeţ-ròʼş֖̌⁠wò wĕ⁠ʼeţ-ké̇lá֑y⁠w wa⁠yĕşǎlĕ̇ẖ֨ẇ bĕ⁠ʼeֽreẕ-pĕlişĕ̌ţi̇֜ym sábi֗yb lĕ⁠başé֛̇̂r ʼeţ-ʻàẕabé̇y⁠he֖m wĕ⁠ʼeţ-há⁠ʻáֽm׃"],[10,10,"וַ⁠יָּשִׂ֨ימוּ֙ אֶת־כֵּלָ֔י⁠ו בֵּ֖ית אֱלֹהֵי⁠הֶ֑ם וְ⁠אֶת־גֻּלְגָּלְתּ֥⁠וֹ תָקְע֖וּ בֵּ֥ית דָּגֽוֹן׃ס","wa⁠yá̇şî֨ymẇ֙ ʼeţ-ké̇lá֔y⁠w bé֖̇yţ ʼèlòhéy⁠he֑m wĕ⁠ʼeţ-gu̇lĕgá̇lĕţ֥̇⁠wò ţáqĕʻ֖ẇ bé֥̇yţ dá̇gֽwòn׃s"],[10,11,"וַֽ⁠יִּשְׁמְע֔וּ כֹּ֖ל יָבֵ֣ישׁ גִּלְעָ֑ד אֵ֛ת כָּל־אֲשֶׁר־עָשׂ֥וּ פְלִשְׁתִּ֖ים לְ⁠שָׁאֽוּל׃","waֽ⁠yi̇şĕ̌mĕʻ֔ẇ kò֖̇l yábé֣yş̌ gi̇lĕʻá֑d ʼé֛ţ ká̇l-ʼàşěr-ʻáş֥̂ẇ pĕlişĕ̌ţi֖̇ym lĕ⁠şá̌ʼֽẇl׃"],[10,12,"וַ⁠יָּקוּמוּ֮ כָּל־אִ֣ישׁ חַיִל֒ וַ⁠יִּשְׂא֞וּ אֶת־גּוּפַ֣ת שָׁא֗וּל וְ⁠אֵת֙ גּוּפֹ֣ת בָּנָ֔י⁠ו וַ⁠יְבִיא֖וּ⁠ם יָבֵ֑ישָׁ⁠ה וַ⁠יִּקְבְּר֨וּ אֶת־עַצְמוֹתֵי⁠הֶ֜ם תַּ֤חַת הָ⁠אֵלָה֙ בְּ⁠יָבֵ֔שׁ וַ⁠יָּצ֖וּמוּ שִׁבְעַ֥ת יָמִֽים׃","wa⁠yá̇qẇmẇ֮ ká̇l-ʼi֣yş̌ ẖayil֒ wa⁠yi̇şĕ̂ʼ֞ẇ ʼeţ-ġẇpa֣ţ şá̌ʼ֗ẇl wĕ⁠ʼéţ֙ ġẇpò֣ţ bá̇ná֔y⁠w wa⁠yĕbiyʼ֖ẇ⁠m yábé֑yşá̌⁠h wa⁠yi̇qĕbĕ̇r֨ẇ ʼeţ-ʻaẕĕmwòţéy⁠he֜m ţȧ֤ẖaţ há⁠ʼéláh֙ bĕ̇⁠yábé֔ş̌ wa⁠yá̇ẕ֖ẇmẇ şǐbĕʻa֥ţ yámiֽym׃"],[10,13,"וַ⁠יָּ֣מָת שָׁא֗וּל בְּ⁠מַֽעֲל⁠וֹ֙ אֲשֶׁ֣ר מָעַ֣ל בַּֽ⁠יהוָ֔ה עַל־דְּבַ֥ר יְהוָ֖ה אֲשֶׁ֣ר לֹא־שָׁמָ֑ר וְ⁠גַם־לִ⁠שְׁא֥וֹל בָּ⁠א֖וֹב לִ⁠דְרֽוֹשׁ׃","wa⁠yá֣̇máţ şá̌ʼ֗ẇl bĕ̇⁠maֽʻàl⁠wò֙ ʼàşě֣r máʻa֣l bȧֽ⁠yhwá֔h ʻal-dĕ̇ba֥r yĕhwá֖h ʼàşě֣r lòʼ-şá̌má֑r wĕ⁠gam-li⁠şĕ̌ʼ֥wòl bá̇⁠ʼ֖wòb li⁠dĕrֽwòş̌׃"],[10,14,"וְ⁠לֹֽא־דָרַ֥שׁ בַּֽ⁠יהוָ֖ה וַ⁠יְמִיתֵ֑⁠הוּ וַ⁠יַּסֵּב֙ אֶת־הַ⁠מְּלוּכָ֔ה לְ⁠דָוִ֖יד בֶּן־יִשָֽׁי׃פ","wĕ⁠lòֽʼ-dára֥ş̌ bȧֽ⁠yhwá֖h wa⁠yĕmiyţé֑⁠hẇ wa⁠yȧsé̇b֙ ʼeţ-ha⁠mĕ̇lẇká֔h lĕ⁠dáwi֖yd bėn-yişáֽ̌y׃p"],[11,1,"וַ⁠יִּקָּבְצ֧וּ כָֽל־יִשְׂרָאֵ֛ל אֶל־דָּוִ֖יד חֶבְר֣וֹנָ⁠ה לֵ⁠אמֹ֑ר הִנֵּ֛ה עַצְמְ⁠ךָ֥ וּֽ⁠בְשָׂרְ⁠ךָ֖ אֲנָֽחְנוּ׃","wa⁠yi̇qá̇bĕẕ֧ẇ káֽl-yişĕ̂ráʼé֛l ʼel-dá̇wi֖yd ẖebĕr֣wòná⁠h lé⁠ʼmò֑r hiné֛̇h ʻaẕĕmĕ⁠ká֥ ẇֽ⁠bĕşá̂rĕ⁠ká֖ ʼànáֽẖĕnẇ׃"],[11,2,"גַּם־תְּמ֣וֹל גַּם־שִׁלְשׁ֗וֹם גַּ֚ם בִּ⁠הְי֣וֹת שָׁא֣וּל מֶ֔לֶךְ אַתָּ֛ה הַ⁠מּוֹצִ֥יא וְ⁠הַ⁠מֵּבִ֖יא אֶת־יִשְׂרָאֵ֑ל וַ⁠יֹּאמֶר֩ יְהוָ֨ה אֱלֹהֶ֜י⁠ךָ לְ⁠ךָ֗ אַתָּ֨ה תִרְעֶ֤ה אֶת־עַמִּ⁠י֙ אֶת־יִשְׂרָאֵ֔ל וְ⁠אַתָּה֙ תִּהְיֶ֣ה נָגִ֔יד עַ֖ל עַמִּ֥⁠י יִשְׂרָאֵֽל׃","gȧm-ţĕ̇m֣wòl gȧm-şǐlĕş̌֗wòm gȧ֚m bi̇⁠hĕy֣wòţ şá̌ʼ֣ẇl me֔lekĕ ʼaţá֛̇h ha⁠ṁwòẕi֥yʼ wĕ⁠ha⁠mé̇bi֖yʼ ʼeţ-yişĕ̂ráʼé֑l wa⁠yò̇ʼmer֩ yĕhwá֨h ʼèlòhe֜y⁠ká lĕ⁠ká֗ ʼaţá̇֨h ţirĕʻe֤h ʼeţ-ʻami̇⁠y֙ ʼeţ-yişĕ̂ráʼé֔l wĕ⁠ʼaţá̇h֙ ţi̇hĕye֣h nági֔yd ʻa֖l ʻami֥̇⁠y yişĕ̂ráʼéֽl׃"],[11,3,"וַ֠⁠יָּבֹאוּ כָּל־זִקְנֵ֨י יִשְׂרָאֵ֤ל אֶל־הַ⁠מֶּ֨לֶךְ֙ חֶבְר֔וֹנָ⁠ה וַ⁠יִּכְרֹת֩ לָ⁠הֶ֨ם דָּוִ֥יד בְּרִ֛ית בְּ⁠חֶבְר֖וֹן לִ⁠פְנֵ֣י יְהוָ֑ה וַ⁠יִּמְשְׁח֨וּ אֶת־דָּוִ֤יד לְ⁠מֶ֨לֶךְ֙ עַל־יִשְׂרָאֵ֔ל כִּ⁠דְבַ֥ר יְהוָ֖ה בְּ⁠יַד־שְׁמוּאֵֽל׃ס","wa֠⁠yá̇bòʼẇ ká̇l-ziqĕné֨y yişĕ̂ráʼé֤l ʼel-ha⁠mė֨lekĕ֙ ẖebĕr֔wòná⁠h wa⁠yi̇kĕròţ֩ lá⁠he֨m dá̇wi֥yd bĕ̇ri֛yţ bĕ̇⁠ẖebĕr֖wòn li⁠pĕné֣y yĕhwá֑h wa⁠yi̇mĕşĕ̌ẖ֨ẇ ʼeţ-dá̇wi֤yd lĕ⁠me֨lekĕ֙ ʻal-yişĕ̂ráʼé֔l ki̇⁠dĕba֥r yĕhwá֖h bĕ̇⁠yad-şĕ̌mẇʼéֽl׃s"],[11,4,"וַ⁠יֵּ֨לֶךְ דָּוִ֧יד וְ⁠כָל־יִשְׂרָאֵ֛ל יְרוּשָׁלִַ֖ם הִ֣יא יְב֑וּס וְ⁠שָׁם֙ הַ⁠יְבוּסִ֔י יֹשְׁבֵ֖י הָ⁠אָֽרֶץ׃","wa⁠yé̇֨lekĕ dá̇wi֧yd wĕ⁠kál-yişĕ̂ráʼé֛l yĕrẇşá̌lia֖m hi֣yʼ yĕb֑ẇs wĕ⁠şá̌m֙ ha⁠yĕbẇsi֔y yòşĕ̌bé֖y há⁠ʼáֽreẕ׃"],[11,5,"וַ⁠יֹּ֨אמְר֜וּ יֹשְׁבֵ֤י יְבוּס֙ לְ⁠דָוִ֔יד לֹ֥א תָב֖וֹא הֵ֑נָּה וַ⁠יִּלְכֹּ֤ד דָּוִיד֙ אֶת־מְצֻדַ֣ת צִיּ֔וֹן הִ֖יא עִ֥יר דָּוִֽיד׃","wa⁠yò̇֨ʼmĕr֜ẇ yòşĕ̌bé֤y yĕbẇs֙ lĕ⁠dáwi֔yd lò֥ʼ ţáb֖wòʼ hé֑ná̇h wa⁠yi̇lĕkò֤̇d dá̇wiyd֙ ʼeţ-mĕẕuda֣ţ ẕiẏ֔wòn hi֖yʼ ʻi֥yr dá̇wiֽyd׃"],[11,6,"וַ⁠יֹּ֣אמֶר דָּוִ֔יד כָּל־מַכֵּ֤ה יְבוּסִי֙ בָּ⁠רִ֣אשׁוֹנָ֔ה יִהְיֶ֥ה לְ⁠רֹ֖אשׁ וּ⁠לְ⁠שָׂ֑ר וַ⁠יַּ֧עַל בָּ⁠רִאשׁוֹנָ֛ה יוֹאָ֥ב בֶּן־צְרוּיָ֖ה וַ⁠יְהִ֥י לְ⁠רֹֽאשׁ׃","wa⁠yò֣̇ʼmer dá̇wi֔yd ká̇l-maké֤̇h yĕbẇsiy֙ bá̇⁠ri֣ʼş̌wòná֔h yihĕye֥h lĕ⁠rò֖ʼş̌ ẇ⁠lĕ⁠şá֑̂r wa⁠yȧ֧ʻal bá̇⁠riʼş̌wòná֛h ywòʼá֥b bėn-ẕĕrẇyá֖h wa⁠yĕhi֥y lĕ⁠ròֽʼş̌׃"],[11,7,"וַ⁠יֵּ֥שֶׁב דָּוִ֖יד בַּ⁠מְצָ֑ד עַל־כֵּ֥ן קָרְאוּ־ל֖⁠וֹ עִ֥יר דָּוִֽיד׃","wa⁠yé֥̇şěb dá̇wi֖yd bȧ⁠mĕẕá֑d ʻal-ké֥̇n qárĕʼẇ-l֖⁠wò ʻi֥yr dá̇wiֽyd׃"],[11,8,"וַ⁠יִּ֤בֶן הָ⁠עִיר֙ מִ⁠סָּבִ֔יב מִן־הַ⁠מִּלּ֖וֹא וְ⁠עַד־הַ⁠סָּבִ֑יב וְ⁠יוֹאָ֕ב יְחַיֶּ֖ה אֶת־שְׁאָ֥ר הָ⁠עִֽיר׃","wa⁠yi֤̇ben há⁠ʻiyr֙ mi⁠sá̇bi֔yb min-ha⁠mi̇l֖̇wòʼ wĕ⁠ʻad-ha⁠sá̇bi֑yb wĕ⁠ywòʼá֕b yĕẖayė֖h ʼeţ-şĕ̌ʼá֥r há⁠ʻiֽyr׃"],[11,9,"וַ⁠יֵּ֥לֶךְ דָּוִ֖יד הָל֣וֹךְ וְ⁠גָד֑וֹל וַ⁠יהוָ֥ה צְבָא֖וֹת עִמּֽ⁠וֹ׃פ","wa⁠yé֥̇lekĕ dá̇wi֖yd hál֣wòkĕ wĕ⁠gád֑wòl wa⁠yhwá֥h ẕĕbáʼ֖wòţ ʻiṁֽ⁠wò׃p"],[11,10,"וְ⁠אֵ֨לֶּה רָאשֵׁ֤י הַ⁠גִּבּוֹרִים֙ אֲשֶׁ֣ר לְ⁠דָוִ֔יד הַ⁠מִּתְחַזְּקִ֨ים עִמּ֧⁠וֹ בְ⁠מַלְכוּת֛⁠וֹ עִם־כָּל־יִשְׂרָאֵ֖ל לְ⁠הַמְלִיכ֑⁠וֹ כִּ⁠דְבַ֥ר יְהוָ֖ה עַל־יִשְׂרָאֵֽל׃ס","wĕ⁠ʼé֨lėh ráʼşé֤̌y ha⁠gi̇ḃwòriym֙ ʼàşě֣r lĕ⁠dáwi֔yd ha⁠mi̇ţĕẖazĕ̇qi֨ym ʻiṁ֧⁠wò bĕ⁠malĕkẇţ֛⁠wò ʻim-ká̇l-yişĕ̂ráʼé֖l lĕ⁠hamĕliyk֑⁠wò ki̇⁠dĕba֥r yĕhwá֖h ʻal-yişĕ̂ráʼéֽl׃s"],[11,11,"וְ⁠אֵ֛לֶּה מִסְפַּ֥ר הַ⁠גִּבֹּרִ֖ים אֲשֶׁ֣ר לְ⁠דָוִ֑יד יָשָׁבְעָ֣ם בֶּן־חַכְמוֹנִ֗י רֹ֚אשׁ ה⁠שלושים הֽוּא־עוֹרֵ֧ר אֶת־חֲנִית֛⁠וֹ עַל־שְׁלֹשׁ־מֵא֥וֹת חָלָ֖ל בְּ⁠פַ֥עַם אֶחָֽת׃","wĕ⁠ʼé֛lėh misĕpȧ֥r ha⁠gi̇bò̇ri֖ym ʼàşě֣r lĕ⁠dáwi֑yd yáşá̌bĕʻá֣m bėn-ẖakĕmwòni֗y rò֚ʼş̌ h⁠şlwşym hֽẇʼ-ʻwòré֧r ʼeţ-ẖàniyţ֛⁠wò ʻal-şĕ̌lòş̌-méʼ֥wòţ ẖálá֖l bĕ̇⁠pa֥ʻam ʼeẖáֽţ׃"],[11,12,"וְ⁠אַחֲרָ֛י⁠ו אֶלְעָזָ֥ר בֶּן־דּוֹד֖וֹ הָ⁠אֲחוֹחִ֑י ה֖וּא בִּ⁠שְׁלוֹשָׁ֥ה הַ⁠גִּבֹּרִֽים׃","wĕ⁠ʼaẖàrá֛y⁠w ʼelĕʻázá֥r bėn-ḋwòd֖wò há⁠ʼàẖwòẖi֑y h֖ẇʼ bi̇⁠şĕ̌lwòşá֥̌h ha⁠gi̇bò̇riֽym׃"],[11,13,"הֽוּא־הָיָ֨ה עִם־דָּוִ֜יד בַּ⁠פַּ֣ס דַּמִּ֗ים וְ⁠הַ⁠פְּלִשְׁתִּים֙ נֶאֱסְפוּ־שָׁ֣ם לַ⁠מִּלְחָמָ֔ה וַ⁠תְּהִ֛י חֶלְקַ֥ת הַ⁠שָּׂדֶ֖ה מְלֵאָ֣ה שְׂעוֹרִ֑ים וְ⁠הָ⁠עָ֥ם נָ֖סוּ מִ⁠פְּנֵ֥י פְלִשְׁתִּֽים׃","hֽẇʼ-háyá֨h ʻim-dá̇wi֜yd bȧ⁠pȧ֣s dȧmi̇֗ym wĕ⁠ha⁠pĕ̇lişĕ̌ţi̇ym֙ neʼèsĕpẇ-şá֣̌m la⁠mi̇lĕẖámá֔h wa⁠ţĕ̇hi֛y ẖelĕqa֥ţ ha⁠şá̇̂de֖h mĕléʼá֣h şĕ̂ʻwòri֑ym wĕ⁠há⁠ʻá֥m ná֖sẇ mi⁠pĕ̇né֥y pĕlişĕ̌ţiֽ̇ym׃"],[11,14,"וַ⁠יִּֽתְיַצְּב֤וּ בְ⁠תוֹךְ־הַ⁠חֶלְקָה֙ וַ⁠יַּצִּיל֔וּ⁠הָ וַ⁠יַּכּ֖וּ אֶת־פְּלִשְׁתִּ֑ים וַ⁠יּ֥וֹשַׁע יְהוָ֖ה תְּשׁוּעָ֥ה גְדוֹלָֽה׃","wa⁠yiֽ̇ţĕyaẕĕ̇b֤ẇ bĕ⁠ţwòkĕ-ha⁠ẖelĕqáh֙ wa⁠yȧẕi̇yl֔ẇ⁠há wa⁠yȧk֖̇ẇ ʼeţ-pĕ̇lişĕ̌ţi֑̇ym wa⁠ẏ֥wòşǎʻ yĕhwá֖h ţĕ̇ş̌ẇʻá֥h gĕdwòláֽh׃"],[11,15,"וַ⁠יֵּרְד֡וּ שְֽׁלוֹשָׁה֩ מִן־הַ⁠שְּׁלוֹשִׁ֨ים רֹ֤אשׁ עַל־הַ⁠צֻּר֙ אֶל־דָּוִ֔יד אֶל־מְעָרַ֖ת עֲדֻלָּ֑ם וּ⁠מַחֲנֵ֣ה פְלִשְׁתִּ֔ים חֹנָ֖ה בְּ⁠עֵ֥מֶק רְפָאִֽים׃","wa⁠yé̇rĕd֡ẇ şĕֽ̌lwòşá̌h֩ min-ha⁠şĕ̇̌lwòşǐ֨ym rò֤ʼş̌ ʻal-ha⁠ẕu̇r֙ ʼel-dá̇wi֔yd ʼel-mĕʻára֖ţ ʻàdulá֑̇m ẇ⁠maẖàné֣h pĕlişĕ̌ţi̇֔ym ẖòná֖h bĕ̇⁠ʻé֥meq rĕpáʼiֽym׃"],[11,16,"וְ⁠דָוִ֖יד אָ֣ז בַּ⁠מְּצוּדָ֑ה וּ⁠נְצִ֣יב פְּלִשְׁתִּ֔ים אָ֖ז בְּ⁠בֵ֥ית לָֽחֶם׃","wĕ⁠dáwi֖yd ʼá֣z bȧ⁠mĕ̇ẕẇdá֑h ẇ⁠nĕẕi֣yb pĕ̇lişĕ̌ţi̇֔ym ʼá֖z bĕ̇⁠bé֥yţ láֽẖem׃"],[11,17,"ו⁠יתאו דָּוִ֖יד וַ⁠יֹּאמַ֑ר מִ֚י יַשְׁקֵ֣⁠נִי מַ֔יִם מִ⁠בּ֥וֹר בֵּֽית־לֶ֖חֶם אֲשֶׁ֥ר בַּ⁠שָּֽׁעַר׃","w⁠yţʼw dá̇wi֖yd wa⁠yò̇ʼma֑r mi֚y yaşĕ̌qé֣⁠niy ma֔yim mi⁠ḃ֥wòr béֽ̇yţ-le֖ẖem ʼàşě֥r bȧ⁠şáֽ̇̌ʻar׃"],[11,18,"וַ⁠יִּבְקְע֨וּ הַ⁠שְּׁלֹשָׁ֜ה בְּ⁠מַחֲנֵ֣ה פְלִשְׁתִּ֗ים וַ⁠יִּֽשְׁאֲבוּ־מַ֨יִם֙ מִ⁠בּ֤וֹר בֵּֽית־לֶ֨חֶם֙ אֲשֶׁ֣ר בַּ⁠שַּׁ֔עַר וַ⁠יִּשְׂא֖וּ וַ⁠יָּבִ֣אוּ אֶל־דָּוִ֑יד וְ⁠לֹֽא־אָבָ֤ה דָוִיד֙ לִ⁠שְׁתּוֹתָ֔⁠ם וַ⁠יְנַסֵּ֥ךְ אֹתָ֖⁠ם לַ⁠יהוָֽה׃","wa⁠yi̇bĕqĕʻ֨ẇ ha⁠şĕ̇̌lòşá̌֜h bĕ̇⁠maẖàné֣h pĕlişĕ̌ţi̇֗ym wa⁠yiֽ̇şĕ̌ʼàbẇ-ma֨yim֙ mi⁠ḃ֤wòr béֽ̇yţ-le֨ẖem֙ ʼàşě֣r bȧ⁠şȧ̌֔ʻar wa⁠yi̇şĕ̂ʼ֖ẇ wa⁠yá̇bi֣ʼẇ ʼel-dá̇wi֑yd wĕ⁠lòֽʼ-ʼábá֤h dáwiyd֙ li⁠şĕ̌ţ̇wòţá֔⁠m wa⁠yĕnasé֥̇kĕ ʼòţá֖⁠m la⁠yhwáֽh׃"],[11,19,"וַ⁠יֹּ֡אמֶר חָלִילָ⁠ה֩ לִּ֨⁠י מֵ⁠אֱלֹהַ֜⁠י מֵ⁠עֲשׂ֣וֹת זֹ֗את הֲ⁠דַ֣ם הָ⁠אֲנָשִׁים֩ הָ⁠אֵ֨לֶּה אֶשְׁתֶּ֤ה בְ⁠נַפְשׁוֹתָ⁠ם֙ כִּ֣י בְ⁠נַפְשׁוֹתָ֣⁠ם הֱבִיא֔וּ⁠ם וְ⁠לֹ֥א אָבָ֖ה לִ⁠שְׁתּוֹתָ֑⁠ם אֵ֣לֶּה עָשׂ֔וּ שְׁלֹ֖שֶׁת הַ⁠גִּבּוֹרִֽים׃","wa⁠yò̇֡ʼmer ẖáliylá⁠h֩ li̇֨⁠y mé⁠ʼèlòha֜⁠y mé⁠ʻàş֣̂wòţ zò֗ʼţ hà⁠da֣m há⁠ʼànáşǐym֩ há⁠ʼé֨lėh ʼeşĕ̌ţė֤h bĕ⁠napĕş̌wòţá⁠m֙ ki֣̇y bĕ⁠napĕş̌wòţá֣⁠m hèbiyʼ֔ẇ⁠m wĕ⁠lò֥ʼ ʼábá֖h li⁠şĕ̌ţ̇wòţá֑⁠m ʼé֣lėh ʻáş̂֔ẇ şĕ̌lò֖şěţ ha⁠gi̇ḃwòriֽym׃"],[11,20,"וְ⁠אַבְשַׁ֣י אֲחִֽי־יוֹאָ֗ב ה֤וּא הָיָה֙ רֹ֣אשׁ הַ⁠שְּׁלוֹשָׁ֔ה וְ⁠הוּא֙ עוֹרֵ֣ר אֶת־חֲנִית֔⁠וֹ עַל־שְׁלֹ֥שׁ מֵא֖וֹת חָלָ֑ל ו⁠לא־שֵׁ֖ם בַּ⁠שְּׁלוֹשָֽׁה׃","wĕ⁠ʼabĕşǎ֣y ʼàẖiֽy-ywòʼá֗b h֤ẇʼ háyáh֙ rò֣ʼş̌ ha⁠şĕ̇̌lwòşá̌֔h wĕ⁠hẇʼ֙ ʻwòré֣r ʼeţ-ẖàniyţ֔⁠wò ʻal-şĕ̌lò֥ş̌ méʼ֖wòţ ẖálá֑l w⁠lʼ-şé֖̌m bȧ⁠şĕ̇̌lwòşáֽ̌h׃"],[11,21,"מִן־הַ⁠שְּׁלוֹשָׁ֤ה בַ⁠שְּׁנַ֨יִם֙ נִכְבָּ֔ד וַ⁠יְהִ֥י לָ⁠הֶ֖ם לְ⁠שָׂ֑ר וְ⁠עַד־הַ⁠שְּׁלוֹשָׁ֖ה לֹֽא־בָֽא׃ס","min-ha⁠şĕ̇̌lwòşá֤̌h ba⁠şĕ̇̌na֨yim֙ nikĕbá̇֔d wa⁠yĕhi֥y lá⁠he֖m lĕ⁠şá֑̂r wĕ⁠ʻad-ha⁠şĕ̇̌lwòşá֖̌h lòֽʼ-báֽʼ׃s"],[11,22,"בְּנָיָ֨ה בֶן־יְהוֹיָדָ֧ע בֶּן־אִֽישׁ־חַ֛יִל רַב־פְּעָלִ֖ים מִֽן־קַבְצְאֵ֑ל ה֣וּא הִכָּ֗ה אֵ֣ת שְׁנֵ֤י אֲרִיאֵל֙ מוֹאָ֔ב וְ֠⁠הוּא יָרַ֞ד וְ⁠הִכָּ֧ה אֶֽת־הָ⁠אֲרִ֛י בְּ⁠ת֥וֹךְ הַ⁠בּ֖וֹר בְּ⁠י֥וֹם הַ⁠שָּֽׁלֶג׃","bĕ̇náyá֨h ben-yĕhwòyádá֧ʻ bėn-ʼiֽyş̌-ẖa֛yil rab-pĕ̇ʻáli֖ym miֽn-qabĕẕĕʼé֑l h֣ẇʼ hiká̇֗h ʼé֣ţ şĕ̌né֤y ʼàriyʼél֙ mwòʼá֔b wĕ֠⁠hẇʼ yára֞d wĕ⁠hiká֧̇h ʼeֽţ-há⁠ʼàri֛y bĕ̇⁠ţ֥wòkĕ ha⁠ḃ֖wòr bĕ̇⁠y֥wòm ha⁠şáֽ̇̌leg׃"],[11,23,"וְ⁠הֽוּא־הִכָּה֩ אֶת־הָ⁠אִ֨ישׁ הַ⁠מִּצְרִ֜י אִ֥ישׁ מִדָּ֣ה ׀ חָמֵ֣שׁ בָּ⁠אַמָּ֗ה וּ⁠בְ⁠יַ֨ד הַ⁠מִּצְרִ֤י חֲנִית֙ כִּ⁠מְנ֣וֹר אֹרְגִ֔ים וַ⁠יֵּ֥רֶד אֵלָ֖י⁠ו בַּ⁠שָּׁ֑בֶט וַ⁠יִּגְזֹ֤ל אֶֽת־הַ⁠חֲנִית֙ מִ⁠יַּ֣ד הַ⁠מִּצְרִ֔י וַ⁠יַּהַרְגֵ֖⁠הוּ בַּ⁠חֲנִיתֽ⁠וֹ׃","wĕ⁠hֽẇʼ-hiká̇h֩ ʼeţ-há⁠ʼi֨yş̌ ha⁠mi̇ẕĕri֜y ʼi֥yş̌ midá֣̇h ׀ ẖámé֣ş̌ bá̇⁠ʼamá̇֗h ẇ⁠bĕ⁠ya֨d ha⁠mi̇ẕĕri֤y ẖàniyţ֙ ki̇⁠mĕn֣wòr ʼòrĕgi֔ym wa⁠yé֥̇red ʼélá֖y⁠w bȧ⁠şá֑̇̌bet wa⁠yi̇gĕzò֤l ʼeֽţ-ha⁠ẖàniyţ֙ mi⁠yȧ֣d ha⁠mi̇ẕĕri֔y wa⁠yȧharĕgé֖⁠hẇ bȧ⁠ẖàniyţֽ⁠wò׃"],[11,24,"אֵ֣לֶּה עָשָׂ֔ה בְּנָיָ֖הוּ בֶּן־יְהוֹיָדָ֑ע וְ⁠ל⁠וֹ־שֵׁ֖ם בִּ⁠שְׁלוֹשָׁ֥ה הַ⁠גִּבֹּרִֽים׃","ʼé֣lėh ʻáşá̂֔h bĕ̇náyá֖hẇ bėn-yĕhwòyádá֑ʻ wĕ⁠l⁠wò-şé֖̌m bi̇⁠şĕ̌lwòşá֥̌h ha⁠gi̇bò̇riֽym׃"],[11,25,"מִן־הַ⁠שְּׁלוֹשִׁ֗ים הִנּ֤⁠וֹ נִכְבָּד֙ ה֔וּא וְ⁠אֶל־הַ⁠שְּׁלוֹשָׁ֖ה לֹא־בָ֑א וַ⁠יְשִׂימֵ֥⁠הוּ דָוִ֖יד עַל־מִשְׁמַעְתּֽ⁠וֹ׃ס","min-ha⁠şĕ̇̌lwòşǐ֗ym hiṅ֤⁠wò nikĕbá̇d֙ h֔ẇʼ wĕ⁠ʼel-ha⁠şĕ̇̌lwòşá֖̌h lòʼ-bá֑ʼ wa⁠yĕşîymé֥⁠hẇ dáwi֖yd ʻal-mişĕ̌maʻĕţֽ̇⁠wò׃s"],[11,26,"וְ⁠גִבּוֹרֵ֖י הַ⁠חֲיָלִ֑ים עֲשָׂה־אֵל֙ אֲחִ֣י יוֹאָ֔ב אֶלְחָנָ֥ן בֶּן־דּוֹד֖וֹ מִ⁠בֵּ֥ית לָֽחֶם׃ס","wĕ⁠giḃwòré֖y ha⁠ẖàyáli֑ym ʻàşá̂h-ʼél֙ ʼàẖi֣y ywòʼá֔b ʼelĕẖáná֥n bėn-ḋwòd֖wò mi⁠bé֥̇yţ láֽẖem׃s"],[11,27,"שַׁמּוֹת֙ הַ⁠הֲרוֹרִ֔י חֶ֖לֶץ הַ⁠פְּלוֹנִֽי׃ס","şǎṁwòţ֙ ha⁠hàrwòri֔y ẖe֖leẕ ha⁠pĕ̇lwòniֽy׃s"],[11,28,"עִירָ֤א בֶן־עִקֵּשׁ֙ הַ⁠תְּקוֹעִ֔י אֲבִיעֶ֖זֶר הָ⁠עֲנְּתוֹתִֽי׃ס","ʻiyrá֤ʼ ben-ʻiqé̇ş̌֙ ha⁠ţĕ̇qwòʻi֔y ʼàbiyʻe֖zer há⁠ʻànĕ̇ţwòţiֽy׃s"],[11,29,"סִבְּכַי֙ הַ⁠חֻ֣שָׁתִ֔י עִילַ֖י הָ⁠אֲחוֹחִֽי׃ס","sibĕ̇kay֙ ha⁠ẖu֣şá̌ţi֔y ʻiyla֖y há⁠ʼàẖwòẖiֽy׃s"],[11,30,"מַהְרַי֙ הַ⁠נְּטֹ֣פָתִ֔י חֵ֥לֶד בֶּֽן־בַּֽעֲנָ֖ה הַ⁠נְּטוֹפָתִֽי׃ס","mahĕray֙ ha⁠nĕ̇tò֣páţi֔y ẖé֥led bėֽn-bȧֽʻàná֖h ha⁠nĕ̇twòpáţiֽy׃s"],[11,31,"אִיתַ֣י בֶּן־רִיבַ֗י מִ⁠גִּבְעַת֙ בְּנֵ֣י בִנְיָמִ֔ן ס בְּנָיָ֖ה הַ⁠פִּרְעָתֹנִֽי׃","ʼiyţa֣y bėn-riyba֗y mi⁠gi̇bĕʻaţ֙ bĕ̇né֣y binĕyámi֔n s bĕ̇náyá֖h ha⁠pi̇rĕʻáţòniֽy׃"],[11,32,"חוּרַי֙ מִ⁠נַּ֣חֲלֵי גָ֔עַשׁ ס אֲבִיאֵ֖ל הָ⁠עַרְבָתִֽי׃ס","ẖẇray֙ mi⁠nȧ֣ẖàléy gá֔ʻaş̌ s ʼàbiyʼé֖l há⁠ʻarĕbáţiֽy׃s"],[11,33,"עַזְמָ֨וֶת֙ הַ⁠בַּ֣חֲרוּמִ֔י אֶלְיַחְבָּ֖א הַ⁠שַּׁעַלְבֹנִֽי׃ס","ʻazĕmá֨weţ֙ ha⁠bȧ֣ẖàrẇmi֔y ʼelĕyaẖĕbá֖̇ʼ ha⁠şȧ̌ʻalĕbòniֽy׃s"],[11,34,"בְּנֵ֗י הָשֵׁם֙ הַ⁠גִּ֣זוֹנִ֔י יוֹנָתָ֥ן בֶּן־שָׁגֵ֖ה הַ⁠הֲרָרִֽי׃ס","bĕ̇né֗y háşé̌m֙ ha⁠gi֣̇zwòni֔y ywònáţá֥n bėn-şá̌gé֖h ha⁠hàráriֽy׃s"],[11,35,"אֲחִיאָ֧ם בֶּן־שָׂכָ֛ר הַ⁠הֲרָרִ֖י אֱלִיפַ֥ל בֶּן־אֽוּר׃ס","ʼàẖiyʼá֧m bėn-şá̂ká֛r ha⁠hàrári֖y ʼèliypa֥l bėn-ʼֽẇr׃s"],[11,36,"חֵ֚פֶר הַ⁠מְּכֵ֣רָתִ֔י אֲחִיָּ֖ה הַ⁠פְּלֹנִֽי׃ס","ẖé֚per ha⁠mĕ̇ké֣ráţi֔y ʼàẖiyá֖̇h ha⁠pĕ̇lòniֽy׃s"],[11,37,"חֶצְרוֹ֙ הַֽ⁠כַּרְמְלִ֔י נַעֲרַ֖י בֶּן־אֶזְבָּֽי׃ס","ẖeẕĕrwò֙ haֽ⁠kȧrĕmĕli֔y naʻàra֖y bėn-ʼezĕbáֽ̇y׃s"],[11,38,"יוֹאֵל֙ אֲחִ֣י נָתָ֔ן מִבְחָ֖ר בֶּן־הַגְרִֽי׃ס","ywòʼél֙ ʼàẖi֣y náţá֔n mibĕẖá֖r bėn-hagĕriֽy׃s"],[11,39,"צֶ֖לֶק הָ⁠עַמּוֹנִ֑י נַחְרַי֙ הַ⁠בֵּ֣רֹתִ֔י נֹשֵׂ֕א כְּלֵ֖י יוֹאָ֥ב בֶּן־צְרוּיָֽה׃ס","ẕe֖leq há⁠ʻaṁwòni֑y naẖĕray֙ ha⁠bé֣̇ròţi֔y nòşé̂֕ʼ kĕ̇lé֖y ywòʼá֥b bėn-ẕĕrẇyáֽh׃s"],[11,40,"עִירָא֙ הַ⁠יִּתְרִ֔י גָּרֵ֖ב הַ⁠יִּתְרִֽי׃ס","ʻiyráʼ֙ ha⁠yi̇ţĕri֔y gá̇ré֖b ha⁠yi̇ţĕriֽy׃s"],[11,41,"אֽוּרִיָּה֙ הַ⁠חִתִּ֔י זָבָ֖ד בֶּן־אַחְלָֽי׃ס","ʼֽẇriyá̇h֙ ha⁠ẖiţi̇֔y zábá֖d bėn-ʼaẖĕláֽy׃s"],[11,42,"עֲדִינָ֨א בֶן־שִׁיזָ֜א הָ⁠רֽאוּבֵנִ֗י רֹ֛אשׁ לָ⁠רֽאוּבֵנִ֖י וְ⁠עָלָ֥י⁠ו שְׁלוֹשִֽׁים׃ס","ʻàdiyná֨ʼ ben-şǐyzá֜ʼ há⁠rֽʼẇbéni֗y rò֛ʼş̌ lá⁠rֽʼẇbéni֖y wĕ⁠ʻálá֥y⁠w şĕ̌lwòşǐֽym׃s"],[11,43,"חָנָן֙ בֶּֽן־מַעֲכָ֔ה וְ⁠יוֹשָׁפָ֖ט הַ⁠מִּתְנִֽי׃ס","ẖánán֙ bėֽn-maʻàká֔h wĕ⁠ywòşá̌pá֖t ha⁠mi̇ţĕniֽy׃s"],[11,44,"עֻזִיָּ֖א הָ⁠עֲשְׁתְּרָתִ֑י שָׁמָע֙ ו⁠יעואל ס בְּנֵ֖י חוֹתָ֥ם הָ⁠עֲרֹעֵרִֽי׃ס","ʻuziyá֖̇ʼ há⁠ʻàşĕ̌ţĕ̇ráţi֑y şá̌máʻ֙ w⁠yʻwʼl s bĕ̇né֖y ẖwòţá֥m há⁠ʻàròʻériֽy׃s"],[11,45,"יְדִֽיעֲאֵל֙ בֶּן־שִׁמְרִ֔י וְ⁠יֹחָ֥א אָחִ֖י⁠ו הַ⁠תִּיצִֽי׃ס","yĕdiֽyʻàʼél֙ bėn-şǐmĕri֔y wĕ⁠yòẖá֥ʼ ʼáẖi֖y⁠w ha⁠ţi̇yẕiֽy׃s"],[11,46,"אֱלִיאֵל֙ הַֽ⁠מַּחֲוִ֔ים וִ⁠ירִיבַ֥י וְ⁠יוֹשַׁוְיָ֖ה בְּנֵ֣י אֶלְנָ֑עַם וְ⁠יִתְמָ֖ה הַ⁠מּוֹאָבִֽי׃","ʼèliyʼél֙ haֽ⁠mȧẖàwi֔ym wi⁠yriyba֥y wĕ⁠ywòşǎwĕyá֖h bĕ̇né֣y ʼelĕná֑ʻam wĕ⁠yiţĕmá֖h ha⁠ṁwòʼábiֽy׃"],[11,47,"אֱלִיאֵ֣ל וְ⁠עוֹבֵ֔ד וְ⁠יַעֲשִׂיאֵ֖ל הַ⁠מְּצֹבָיָֽה׃פ","ʼèliyʼé֣l wĕ⁠ʻwòbé֔d wĕ⁠yaʻàşîyʼé֖l ha⁠mĕ̇ẕòbáyáֽh׃p"],[12,1,"וְ⁠אֵ֗לֶּה הַ⁠בָּאִ֤ים אֶל־דָּוִיד֙ לְ⁠צִ֣יקְלַ֔ג ע֣וֹד עָצ֔וּר מִ⁠פְּנֵ֖י שָׁא֣וּל בֶּן־קִ֑ישׁ וְ⁠הֵ֨מָּה֙ בַּ⁠גִּבּוֹרִ֔ים עֹזְרֵ֖י הַ⁠מִּלְחָמָֽה׃","wĕ⁠ʼé֗lėh ha⁠bá̇ʼi֤ym ʼel-dá̇wiyd֙ lĕ⁠ẕi֣yqĕla֔g ʻ֣wòd ʻáẕ֔ẇr mi⁠pĕ̇né֖y şá̌ʼ֣ẇl bėn-qi֑yş̌ wĕ⁠hé֨má̇h֙ bȧ⁠gi̇ḃwòri֔ym ʻòzĕré֖y ha⁠mi̇lĕẖámáֽh׃"],[12,2,"נֹ֣שְׁקֵי קֶ֗שֶׁת מַיְמִינִ֤ים וּ⁠מַשְׂמִאלִים֙ בָּֽ⁠אֲבָנִ֔ים וּ⁠בַ⁠חִצִּ֖ים בַּ⁠קָּ֑שֶׁת מֵ⁠אֲחֵ֥י שָׁא֖וּל מִ⁠בִּנְיָמִֽן׃","nò֣şĕ̌qéy qe֗şěţ mayĕmiyni֤ym ẇ⁠maşĕ̂miʼliym֙ báֽ̇⁠ʼàbáni֔ym ẇ⁠ba⁠ẖiẕi֖̇ym bȧ⁠qá֑̇şěţ mé⁠ʼàẖé֥y şá̌ʼ֖ẇl mi⁠bi̇nĕyámiֽn׃"],[12,3,"הָ⁠רֹ֨אשׁ אֲחִיעֶ֜זֶר וְ⁠יוֹאָ֗שׁ בְּנֵי֙ הַ⁠שְּׁמָעָ֣ה הַ⁠גִּבְעָתִ֔י ו⁠יזואל וָ⁠פֶ֖לֶט בְּנֵ֣י עַזְמָ֑וֶת וּ⁠בְרָכָ֕ה וְ⁠יֵה֖וּא הָ⁠עֲנְּתֹתִֽי׃","há⁠rò֨ʼş̌ ʼàẖiyʻe֜zer wĕ⁠ywòʼá֗ş̌ bĕ̇néy֙ ha⁠şĕ̇̌máʻá֣h ha⁠gi̇bĕʻáţi֔y w⁠yzwʼl wá⁠pe֖let bĕ̇né֣y ʻazĕmá֑weţ ẇ⁠bĕráká֕h wĕ⁠yéh֖ẇʼ há⁠ʻànĕ̇ţòţiֽy׃"],[12,4,"וְ⁠יִֽשְׁמַֽעְיָ֧ה הַ⁠גִּבְעוֹנִ֛י גִּבּ֥וֹר בַּ⁠שְּׁלֹשִׁ֖ים וְ⁠עַל־הַ⁠שְּׁלֹשִֽׁים׃ וְ⁠יִרְמְיָ֤ה וְ⁠יַחֲזִיאֵל֙ וְ⁠י֣וֹחָנָ֔ן וְ⁠יוֹזָבָ֖ד הַ⁠גְּדֵרָתִֽי׃","wĕ⁠yiֽşĕ̌maֽʻĕyá֧h ha⁠gi̇bĕʻwòni֛y gi̇ḃ֥wòr bȧ⁠şĕ̇̌lòşǐ֖ym wĕ⁠ʻal-ha⁠şĕ̇̌lòşǐֽym׃ wĕ⁠yirĕmĕyá֤h wĕ⁠yaẖàziyʼél֙ wĕ⁠y֣wòẖáná֔n wĕ⁠ywòzábá֖d ha⁠gĕ̇déráţiֽy׃"],[12,5,"אֶלְעוּזַ֤י וִ⁠ירִימוֹת֙ וּ⁠בְעַלְיָ֣ה וּ⁠שְׁמַרְיָ֔הוּ וּ⁠שְׁפַטְיָ֖הוּ ה⁠חריפי׃","ʼelĕʻẇza֤y wi⁠yriymwòţ֙ ẇ⁠bĕʻalĕyá֣h ẇ⁠şĕ̌marĕyá֔hẇ ẇ⁠şĕ̌patĕyá֖hẇ h⁠ẖrypy׃"],[12,6,"אֶלְקָנָ֡ה וְ֠⁠יִשִּׁיָּהוּ וַ⁠עֲזַרְאֵ֧ל וְ⁠יוֹעֶ֛זֶר וְ⁠יָשָׁבְעָ֖ם הַ⁠קָּרְחִֽים׃","ʼelĕqáná֡h wĕ֠⁠yişi̇̌yá̇hẇ wa⁠ʻàzarĕʼé֧l wĕ⁠ywòʻe֛zer wĕ⁠yáşá̌bĕʻá֖m ha⁠qá̇rĕẖiֽym׃"],[12,7,"וְ⁠יוֹעֵאלָ֧ה וּ⁠זְבַדְיָ֛ה בְּנֵ֥י יְרֹחָ֖ם מִן־הַ⁠גְּדֽוֹר׃","wĕ⁠ywòʻéʼlá֧h ẇ⁠zĕbadĕyá֛h bĕ̇né֥y yĕròẖá֖m min-ha⁠gĕ̇dֽwòr׃"],[12,8,"וּ⁠מִן־הַ⁠גָּדִ֡י נִבְדְּל֣וּ אֶל־דָּוִיד֩ לַ⁠מְצַ֨ד מִדְבָּ֜רָ⁠ה גִּבֹּרֵ֣י הַ⁠חַ֗יִל אַנְשֵׁ֤י צָבָא֙ לַ⁠מִּלְחָמָ֔ה עֹרְכֵ֥י צִנָּ֖ה וָ⁠רֹ֑מַח וּ⁠פְנֵ֤י אַרְיֵה֙ פְּנֵי⁠הֶ֔ם וְ⁠כִ⁠צְבָאיִ֥ם עַל־הֶ⁠הָרִ֖ים לְ⁠מַהֵֽר׃ס","ẇ⁠min-ha⁠gá̇di֡y nibĕdĕ̇l֣ẇ ʼel-dá̇wiyd֩ la⁠mĕẕa֨d midĕbá̇֜rá⁠h gi̇bò̇ré֣y ha⁠ẖa֗yil ʼanĕşé֤̌y ẕábáʼ֙ la⁠mi̇lĕẖámá֔h ʻòrĕké֥y ẕiná֖̇h wá⁠rò֑maẖ ẇ⁠pĕné֤y ʼarĕyéh֙ pĕ̇néy⁠he֔m wĕ⁠ki⁠ẕĕbáʼyi֥m ʻal-he⁠hári֖ym lĕ⁠mahéֽr׃s"],[12,9,"עֵ֖זֶר הָ⁠רֹ֑אשׁ עֹבַדְיָה֙ הַ⁠שֵּׁנִ֔י אֱלִיאָ֖ב הַ⁠שְּׁלִשִֽׁי׃","ʻé֖zer há⁠rò֑ʼş̌ ʻòbadĕyáh֙ ha⁠şé̇̌ni֔y ʼèliyʼá֖b ha⁠şĕ̇̌lişǐֽy׃"],[12,10,"מִשְׁמַנָּה֙ הָ⁠רְבִיעִ֔י יִרְמְיָ֖ה הַ⁠חֲמִשִֽׁי׃","mişĕ̌maná̇h֙ há⁠rĕbiyʻi֔y yirĕmĕyá֖h ha⁠ẖàmişǐֽy׃"],[12,11,"עַתַּי֙ הַ⁠שִּׁשִּׁ֔י אֱלִיאֵ֖ל הַ⁠שְּׁבִעִֽי׃","ʻaţȧy֙ ha⁠şi̇̌şi̇̌֔y ʼèliyʼé֖l ha⁠şĕ̇̌biʻiֽy׃"],[12,12,"יֽוֹחָנָן֙ הַ⁠שְּׁמִינִ֔י אֶלְזָבָ֖ד הַ⁠תְּשִׁיעִֽי׃","yֽwòẖánán֙ ha⁠şĕ̇̌miyni֔y ʼelĕzábá֖d ha⁠ţĕ̇şǐyʻiֽy׃"],[12,13,"יִרְמְיָ֨הוּ֙ הָ⁠עֲשִׂירִ֔י ס מַכְבַּנַּ֖י עַשְׁתֵּ֥י עָשָֽׂר׃","yirĕmĕyá֨hẇ֙ há⁠ʻàşîyri֔y s makĕbȧnȧ֖y ʻaşĕ̌ţé֥̇y ʻáşáֽ̂r׃"],[12,14,"אֵ֥לֶּה מִ⁠בְּנֵי־גָ֖ד רָאשֵׁ֣י הַ⁠צָּבָ֑א אֶחָ֤ד לְ⁠מֵאָה֙ הַ⁠קָּטָ֔ן וְ⁠הַ⁠גָּד֖וֹל לְ⁠אָֽלֶף׃","ʼé֥lėh mi⁠bĕ̇néy-gá֖d ráʼşé֣̌y ha⁠ẕá̇bá֑ʼ ʼeẖá֤d lĕ⁠méʼáh֙ ha⁠qá̇tá֔n wĕ⁠ha⁠gá̇d֖wòl lĕ⁠ʼáֽlep׃"],[12,15,"אֵ֣לֶּה הֵ֗ם אֲשֶׁ֨ר עָבְר֤וּ אֶת־הַ⁠יַּרְדֵּן֙ בַּ⁠חֹ֣דֶשׁ הָ⁠רִאשׁ֔וֹן וְ⁠ה֥וּא מְמַלֵּ֖א עַל־כָּל־גדיתי⁠ו וַ⁠יַּבְרִ֨יחוּ֙ אֶת־כָּל־הָ֣⁠עֲמָקִ֔ים לַ⁠מִּזְרָ֖ח וְ⁠לַֽ⁠מַּעֲרָֽב׃ס","ʼé֣lėh hé֗m ʼàşě֨r ʻábĕr֤ẇ ʼeţ-ha⁠yȧrĕdé̇n֙ bȧ⁠ẖò֣deş̌ há⁠riʼş̌֔wòn wĕ⁠h֥ẇʼ mĕmalé֖̇ʼ ʻal-ká̇l-gdyţy⁠w wa⁠yȧbĕri֨yẖẇ֙ ʼeţ-ká̇l-há֣⁠ʻàmáqi֔ym la⁠mi̇zĕrá֖ẖ wĕ⁠laֽ⁠mȧʻàráֽb׃s"],[12,16,"וַ⁠יָּבֹ֗אוּ מִן־בְּנֵ֤י בִנְיָמִן֙ וִֽ⁠יהוּדָ֔ה עַד־לַ⁠מְצָ֖ד לְ⁠דָוִֽיד׃","wa⁠yá̇bò֗ʼẇ min-bĕ̇né֤y binĕyámin֙ wiֽ⁠yhẇdá֔h ʻad-la⁠mĕẕá֖d lĕ⁠dáwiֽyd׃"],[12,17,"וַ⁠יֵּצֵ֣א דָוִיד֮ לִ⁠פְנֵי⁠הֶם֒ וַ⁠יַּ֨עַן֙ וַ⁠יֹּ֣אמֶר לָ⁠הֶ֔ם אִם־לְ⁠שָׁל֞וֹם בָּאתֶ֤ם אֵלַ⁠י֙ לְ⁠עָזְרֵ֔⁠נִי יִֽהְיֶה־לִּ֧⁠י עֲלֵי⁠כֶ֛ם לֵבָ֖ב לְ⁠יָ֑חַד וְ⁠אִֽם־לְ⁠רַמּוֹתַ֣⁠נִי לְ⁠צָרַ֗⁠י בְּ⁠לֹ֤א חָמָס֙ בְּ⁠כַפַּ֔⁠י יֵ֛רֶא אֱלֹהֵ֥י אֲבוֹתֵ֖י⁠נוּ וְ⁠יוֹכַֽח׃ס","wa⁠yé̇ẕé֣ʼ dáwiyd֮ li⁠pĕnéy⁠hem֒ wa⁠yȧ֨ʻan֙ wa⁠yò֣̇ʼmer lá⁠he֔m ʼim-lĕ⁠şá̌l֞wòm bá̇ʼţe֤m ʼéla⁠y֙ lĕ⁠ʻázĕré֔⁠niy yiֽhĕyeh-li֧̇⁠y ʻàléy⁠ke֛m lébá֖b lĕ⁠yá֑ẖad wĕ⁠ʼiֽm-lĕ⁠raṁwòţa֣⁠niy lĕ⁠ẕára֗⁠y bĕ̇⁠lò֤ʼ ẖámás֙ bĕ̇⁠kapȧ֔⁠y yé֛reʼ ʼèlòhé֥y ʼàbwòţé֖y⁠nẇ wĕ⁠ywòkaֽẖ׃s"],[12,18,"וְ⁠ר֣וּחַ לָבְשָׁ֗ה אֶת־עֲמָשַׂי֮ רֹ֣אשׁ ה⁠שלושים לְ⁠ךָ֤ דָוִיד֙ וְ⁠עִמְּ⁠ךָ֣ בֶן־יִשַׁ֔י שָׁל֨וֹם ׀ שָׁל֜וֹם לְ⁠ךָ֗ וְ⁠שָׁלוֹם֙ לְ⁠עֹ֣זְרֶ֔⁠ךָ כִּ֥י עֲזָרְ⁠ךָ֖ אֱלֹהֶ֑י⁠ךָ וַ⁠יְקַבְּלֵ֣⁠ם דָּוִ֔יד וַֽ⁠יִּתְּנֵ֖⁠ם בְּ⁠רָאשֵׁ֥י הַ⁠גְּדֽוּד׃פ","wĕ⁠r֣ẇẖa lábĕşá̌֗h ʼeţ-ʻàmáşây֮ rò֣ʼş̌ h⁠şlwşym lĕ⁠ká֤ dáwiyd֙ wĕ⁠ʻimĕ̇⁠ká֣ ben-yişǎ֔y şá̌l֨wòm ׀ şá̌l֜wòm lĕ⁠ká֗ wĕ⁠şá̌lwòm֙ lĕ⁠ʻò֣zĕre֔⁠ká ki֥̇y ʻàzárĕ⁠ká֖ ʼèlòhe֑y⁠ká wa⁠yĕqabĕ̇lé֣⁠m dá̇wi֔yd waֽ⁠yi̇ţĕ̇né֖⁠m bĕ̇⁠ráʼşé֥̌y ha⁠gĕ̇dֽẇd׃p"],[12,19,"וּ⁠מִֽ⁠מְּנַשֶּׁ֞ה נָפְל֣וּ עַל־דָּוִ֗יד בְּ⁠בֹא֨⁠וֹ עִם־פְּלִשְׁתִּ֧ים עַל־שָׁא֛וּל לַ⁠מִּלְחָמָ֖ה וְ⁠לֹ֣א עֲזָרֻ֑⁠ם כִּ֣י בְ⁠עֵצָ֗ה שִׁלְּחֻ֜⁠הוּ סַרְנֵ֤י פְלִשְׁתִּים֙ לֵ⁠אמֹ֔ר בְּ⁠רָאשֵׁ֕י⁠נוּ יִפּ֖וֹל אֶל־אֲדֹנָ֥י⁠ו שָׁאֽוּל׃","ẇ⁠miֽ⁠mĕ̇naşė̌֞h nápĕl֣ẇ ʻal-dá̇wi֗yd bĕ̇⁠bòʼ֨⁠wò ʻim-pĕ̇lişĕ̌ţi֧̇ym ʻal-şá̌ʼ֛ẇl la⁠mi̇lĕẖámá֖h wĕ⁠lò֣ʼ ʻàzáru֑⁠m ki֣̇y bĕ⁠ʻéẕá֗h şǐlĕ̇ẖu֜⁠hẇ sarĕné֤y pĕlişĕ̌ţi̇ym֙ lé⁠ʼmò֔r bĕ̇⁠ráʼşé̌֕y⁠nẇ yiṗ֖wòl ʼel-ʼàdòná֥y⁠w şá̌ʼֽẇl׃"],[12,20,"בְּ⁠לֶכְתּ֣⁠וֹ אֶל־צִֽיקְלַ֗ג נָפְל֣וּ עָלָ֣י⁠ו ׀ מִֽ⁠מְּנַשֶּׁ֡ה עַ֠דְנַח וְ⁠יוֹזָבָ֤ד וִ⁠ידִֽיעֲאֵל֙ וּ⁠מִיכָאֵ֣ל וְ⁠יוֹזָבָ֔ד וֶ⁠אֱלִיה֖וּא וְ⁠צִלְּתָ֑י רָאשֵׁ֥י הָ⁠אֲלָפִ֖ים אֲשֶׁ֥ר לִ⁠מְנַשֶּֽׁה׃","bĕ̇⁠lekĕţ֣̇⁠wò ʼel-ẕiֽyqĕla֗g nápĕl֣ẇ ʻálá֣y⁠w ׀ miֽ⁠mĕ̇naşė̌֡h ʻa֠dĕnaẖ wĕ⁠ywòzábá֤d wi⁠ydiֽyʻàʼél֙ ẇ⁠miykáʼé֣l wĕ⁠ywòzábá֔d we⁠ʼèliyh֖ẇʼ wĕ⁠ẕilĕ̇ţá֑y ráʼşé֥̌y há⁠ʼàlápi֖ym ʼàşě֥r li⁠mĕnaşėֽ̌h׃"],[12,21,"וְ⁠הֵ֗מָּה עָזְר֤וּ עִם־דָּוִיד֙ עַֽל־הַ⁠גְּד֔וּד כִּֽי־גִבּ֥וֹרֵי חַ֖יִל כֻּלָּ֑⁠ם וַ⁠יִּהְי֥וּ שָׂרִ֖ים בַּ⁠צָּבָֽא׃","wĕ⁠hé֗má̇h ʻázĕr֤ẇ ʻim-dá̇wiyd֙ ʻaֽl-ha⁠gĕ̇d֔ẇd kiֽ̇y-giḃ֥wòréy ẖa֖yil ku̇lá֑̇⁠m wa⁠yi̇hĕy֥ẇ şá̂ri֖ym bȧ⁠ẕá̇báֽʼ׃"],[12,22,"כִּ֚י לְ⁠עֶת־י֣וֹם בְּ⁠י֔וֹם יָבֹ֥אוּ עַל־דָּוִ֖יד לְ⁠עָזְר֑⁠וֹ עַד־לְ⁠מַחֲנֶ֥ה גָד֖וֹל כְּ⁠מַחֲנֵ֥ה אֱלֹהִֽים׃פ","ki֚̇y lĕ⁠ʻeţ-y֣wòm bĕ̇⁠y֔wòm yábò֥ʼẇ ʻal-dá̇wi֖yd lĕ⁠ʻázĕr֑⁠wò ʻad-lĕ⁠maẖàne֥h gád֖wòl kĕ̇⁠maẖàné֥h ʼèlòhiֽym׃p"],[12,23,"וְ֠⁠אֵלֶּה מִסְפְּרֵ֞י רָאשֵׁ֤י הֶֽ⁠חָלוּץ֙ לַ⁠צָּבָ֔א בָּ֥אוּ עַל־דָּוִ֖יד חֶבְר֑וֹנָ⁠ה לְ⁠הָסֵ֞ב מַלְכ֥וּת שָׁא֛וּל אֵלָ֖י⁠ו כְּ⁠פִ֥י יְהוָֽה׃ס","wĕ֠⁠ʼélėh misĕpĕ̇ré֞y ráʼşé֤̌y heֽ⁠ẖálẇẕ֙ la⁠ẕá̇bá֔ʼ bá֥̇ʼẇ ʻal-dá̇wi֖yd ẖebĕr֑wòná⁠h lĕ⁠hásé֞b malĕk֥ẇţ şá̌ʼ֛ẇl ʼélá֖y⁠w kĕ̇⁠pi֥y yĕhwáֽh׃s"],[12,24,"בְּנֵ֣י יְהוּדָ֔ה נֹשְׂאֵ֥י צִנָּ֖ה וָ⁠רֹ֑מַח שֵׁ֧שֶׁת אֲלָפִ֛ים וּ⁠שְׁמוֹנֶ֥ה מֵא֖וֹת חֲלוּצֵ֥י צָבָֽא׃ס","bĕ̇né֣y yĕhẇdá֔h nòşĕ̂ʼé֥y ẕiná֖̇h wá⁠rò֑maẖ şé֧̌şěţ ʼàlápi֛ym ẇ⁠şĕ̌mwòne֥h méʼ֖wòţ ẖàlẇẕé֥y ẕábáֽʼ׃s"],[12,25,"מִן־בְּנֵ֣י שִׁמְע֗וֹן גִּבּ֤וֹרֵי חַ֨יִל֙ לַ⁠צָּבָ֔א שִׁבְעַ֥ת אֲלָפִ֖ים וּ⁠מֵאָֽה׃ס","min-bĕ̇né֣y şǐmĕʻ֗wòn gi̇ḃ֤wòréy ẖa֨yil֙ la⁠ẕá̇bá֔ʼ şǐbĕʻa֥ţ ʼàlápi֖ym ẇ⁠méʼáֽh׃s"],[12,26,"מִן־בְּנֵי֙ הַ⁠לֵּוִ֔י אַרְבַּ֥עַת אֲלָפִ֖ים וְ⁠שֵׁ֥שׁ מֵאֽוֹת׃ס","min-bĕ̇néy֙ ha⁠lé̇wi֔y ʼarĕbȧ֥ʻaţ ʼàlápi֖ym wĕ⁠şé֥̌ş̌ méʼֽwòţ׃s"],[12,27,"וִ⁠יהוֹיָדָ֖ע הַ⁠נָּגִ֣יד לְ⁠אַהֲרֹ֑ן וְ⁠עִמּ֕⁠וֹ שְׁלֹ֥שֶׁת אֲלָפִ֖ים וּ⁠שְׁבַ֥ע מֵאֽוֹת׃ס","wi⁠yhwòyádá֖ʻ ha⁠ná̇gi֣yd lĕ⁠ʼahàrò֑n wĕ⁠ʻiṁ֕⁠wò şĕ̌lò֥şěţ ʼàlápi֖ym ẇ⁠şĕ̌ba֥ʻ méʼֽwòţ׃s"],[12,28,"וְ⁠צָד֥וֹק נַ֖עַר גִּבּ֣וֹר חָ֑יִל וּ⁠בֵית־אָבִ֥י⁠ו שָׂרִ֖ים עֶשְׂרִ֥ים וּ⁠שְׁנָֽיִם׃ס","wĕ⁠ẕád֥wòq na֖ʻar gi̇ḃ֣wòr ẖá֑yil ẇ⁠béyţ-ʼábi֥y⁠w şá̂ri֖ym ʻeşĕ̂ri֥ym ẇ⁠şĕ̌náֽyim׃s"],[12,29,"וּ⁠מִן־בְּנֵ֧י בִנְיָמִ֛ן אֲחֵ֥י שָׁא֖וּל שְׁלֹ֣שֶׁת אֲלָפִ֑ים וְ⁠עַד־הֵ֨נָּה֙ מַרְבִּיתָ֔⁠ם שֹׁמְרִ֕ים מִשְׁמֶ֖רֶת בֵּ֥ית שָׁאֽוּל׃ס","ẇ⁠min-bĕ̇né֧y binĕyámi֛n ʼàẖé֥y şá̌ʼ֖ẇl şĕ̌lò֣şěţ ʼàlápi֑ym wĕ⁠ʻad-hé֨ná̇h֙ marĕbi̇yţá֔⁠m şò̌mĕri֕ym mişĕ̌me֖reţ bé֥̇yţ şá̌ʼֽẇl׃s"],[12,30,"וּ⁠מִן־בְּנֵ֣י אֶפְרַ֔יִם עֶשְׂרִ֥ים אֶ֖לֶף וּ⁠שְׁמוֹנֶ֣ה מֵא֑וֹת גִּבּ֣וֹרֵי חַ֔יִל אַנְשֵׁ֥י שֵׁמ֖וֹת לְ⁠בֵ֥ית אֲבוֹתָֽ⁠ם׃ס","ẇ⁠min-bĕ̇né֣y ʼepĕra֔yim ʻeşĕ̂ri֥ym ʼe֖lep ẇ⁠şĕ̌mwòne֣h méʼ֑wòţ gi̇ḃ֣wòréy ẖa֔yil ʼanĕşé֥̌y şé̌m֖wòţ lĕ⁠bé֥yţ ʼàbwòţáֽ⁠m׃s"],[12,31,"וּ⁠מֵ⁠חֲצִי֙ מַטֵּ֣ה מְנַשֶּׁ֔ה שְׁמוֹנָ֥ה עָשָׂ֖ר אָ֑לֶף אֲשֶׁ֤ר נִקְּבוּ֙ בְּ⁠שֵׁמ֔וֹת לָ⁠ב֖וֹא לְ⁠הַמְלִ֥יךְ אֶת־דָּוִֽיד׃ס","ẇ⁠mé⁠ẖàẕiy֙ maté֣̇h mĕnaşė̌֔h şĕ̌mwòná֥h ʻáşá֖̂r ʼá֑lep ʼàşě֤r niqĕ̇bẇ֙ bĕ̇⁠şé̌m֔wòţ lá⁠b֖wòʼ lĕ⁠hamĕli֥ykĕ ʼeţ-dá̇wiֽyd׃s"],[12,32,"וּ⁠מִ⁠בְּנֵ֣י יִשָּׂשכָ֗ר יוֹדְעֵ֤י בִינָה֙ לַֽ⁠עִתִּ֔ים לָ⁠דַ֖עַת מַה־יַּעֲשֶׂ֣ה יִשְׂרָאֵ֑ל רָאשֵׁי⁠הֶ֣ם מָאתַ֔יִם וְ⁠כָל־אֲחֵי⁠הֶ֖ם עַל־פִּי⁠הֶֽם׃ס","ẇ⁠mi⁠bĕ̇né֣y yişá̇̂şká֗r ywòdĕʻé֤y biynáh֙ laֽ⁠ʻiţi̇֔ym lá⁠da֖ʻaţ mah-yȧʻàşê֣h yişĕ̂ráʼé֑l ráʼşé̌y⁠he֣m máʼţa֔yim wĕ⁠kál-ʼàẖéy⁠he֖m ʻal-pi̇y⁠heֽm׃s"],[12,33,"מִ⁠זְּבֻל֞וּן יוֹצְאֵ֣י צָבָ֗א עֹרְכֵ֧י מִלְחָמָ֛ה בְּ⁠כָל־כְּלֵ֥י מִלְחָמָ֖ה חֲמִשִּׁ֣ים אָ֑לֶף וְ⁠לַ⁠עֲדֹ֖ר בְּ⁠לֹא־לֵ֥ב וָ⁠לֵֽב׃ס","mi⁠zĕ̇bul֞ẇn ywòẕĕʼé֣y ẕábá֗ʼ ʻòrĕké֧y milĕẖámá֛h bĕ̇⁠kál-kĕ̇lé֥y milĕẖámá֖h ẖàmişi֣̇̌ym ʼá֑lep wĕ⁠la⁠ʻàdò֖r bĕ̇⁠lòʼ-lé֥b wá⁠léֽb׃s"],[12,34,"וּ⁠מִ⁠נַּפְתָּלִ֖י שָׂרִ֣ים אָ֑לֶף וְ⁠עִמָּ⁠הֶם֙ בְּ⁠צִנָּ֣ה וַ⁠חֲנִ֔ית שְׁלֹשִׁ֥ים וְ⁠שִׁבְעָ֖ה אָֽלֶף׃ס","ẇ⁠mi⁠nȧpĕţá̇li֖y şá̂ri֣ym ʼá֑lep wĕ⁠ʻimá̇⁠hem֙ bĕ̇⁠ẕiná֣̇h wa⁠ẖàni֔yţ şĕ̌lòşǐ֥ym wĕ⁠şǐbĕʻá֖h ʼáֽlep׃s"],[12,35,"וּ⁠מִן־הַ⁠דָּנִי֙ עֹרְכֵ֣י מִלְחָמָ֔ה עֶשְׂרִֽים־וּ⁠שְׁמוֹנָ֥ה אֶ֖לֶף וְ⁠שֵׁ֥שׁ מֵאֽוֹת׃ס","ẇ⁠min-ha⁠dá̇niy֙ ʻòrĕké֣y milĕẖámá֔h ʻeşĕ̂riֽym-ẇ⁠şĕ̌mwòná֥h ʼe֖lep wĕ⁠şé֥̌ş̌ méʼֽwòţ׃s"],[12,36,"וּ⁠מֵ⁠אָשֵׁ֗ר יוֹצְאֵ֥י צָבָ֛א לַ⁠עֲרֹ֥ךְ מִלְחָמָ֖ה אַרְבָּעִ֥ים אָֽלֶף׃ס","ẇ⁠mé⁠ʼáşé̌֗r ywòẕĕʼé֥y ẕábá֛ʼ la⁠ʻàrò֥kĕ milĕẖámá֖h ʼarĕbá̇ʻi֥ym ʼáֽlep׃s"],[12,37,"וּ⁠מֵ⁠עֵ֣בֶר לַ֠⁠יַּרְדֵּן מִן־הָ⁠ראוּבֵנִ֨י וְ⁠הַ⁠גָּדִ֜י וַ⁠חֲצִ֣י ׀ שֵׁ֣בֶט מְנַשֶּׁ֗ה בְּ⁠כֹל֙ כְּלֵי֙ צְבָ֣א מִלְחָמָ֔ה מֵאָ֥ה וְ⁠עֶשְׂרִ֖ים אָֽלֶף׃","ẇ⁠mé⁠ʻé֣ber la֠⁠yȧrĕdé̇n min-há⁠rʼẇbéni֨y wĕ⁠ha⁠gá̇di֜y wa⁠ẖàẕi֣y ׀ şé֣̌bet mĕnaşė̌֗h bĕ̇⁠kòl֙ kĕ̇léy֙ ẕĕbá֣ʼ milĕẖámá֔h méʼá֥h wĕ⁠ʻeşĕ̂ri֖ym ʼáֽlep׃"],[12,38,"כָּל־אֵ֜לֶּה אַנְשֵׁ֣י מִלְחָמָה֮ עֹדְרֵ֣י מַעֲרָכָה֒ בְּ⁠לֵבָ֤ב שָׁלֵם֙ בָּ֣אוּ חֶבְר֔וֹנָ⁠ה לְ⁠הַמְלִ֥יךְ אֶת־דָּוִ֖יד עַל־כָּל־יִשְׂרָאֵ֑ל וְ֠⁠גַם כָּל־שֵׁרִ֧ית יִשְׂרָאֵ֛ל לֵ֥ב אֶחָ֖ד לְ⁠הַמְלִ֥יךְ אֶת־דָּוִֽיד׃","ká̇l-ʼé֜lėh ʼanĕşé֣̌y milĕẖámáh֮ ʻòdĕré֣y maʻàrákáh֒ bĕ̇⁠lébá֤b şá̌lém֙ bá֣̇ʼẇ ẖebĕr֔wòná⁠h lĕ⁠hamĕli֥ykĕ ʼeţ-dá̇wi֖yd ʻal-ká̇l-yişĕ̂ráʼé֑l wĕ֠⁠gam ká̇l-şé̌ri֧yţ yişĕ̂ráʼé֛l lé֥b ʼeẖá֖d lĕ⁠hamĕli֥ykĕ ʼeţ-dá̇wiֽyd׃"],[12,39,"וַ⁠יִּהְיוּ־שָׁ֤ם עִם־דָּוִיד֙ יָמִ֣ים שְׁלוֹשָׁ֔ה אֹכְלִ֖ים וְ⁠שׁוֹתִ֑ים כִּֽי־הֵכִ֥ינוּ לָ⁠הֶ֖ם אֲחֵי⁠הֶֽם׃","wa⁠yi̇hĕyẇ-şá֤̌m ʻim-dá̇wiyd֙ yámi֣ym şĕ̌lwòşá̌֔h ʼòkĕli֖ym wĕ⁠ş̌wòţi֑ym kiֽ̇y-héki֥ynẇ lá⁠he֖m ʼàẖéy⁠heֽm׃"],[12,40,"וְ⁠גַ֣ם הַ⁠קְּרֽוֹבִים־אֲ֠לֵי⁠הֶם עַד־יִשָׂשכָ֨ר וּ⁠זְבֻל֜וּן וְ⁠נַפְתָּלִ֗י מְבִיאִ֣ים לֶ֡חֶם בַּ⁠חֲמוֹרִ֣ים וּ⁠בַ⁠גְּמַלִּ֣ים וּ⁠בַ⁠פְּרָדִ֣ים ׀ וּֽ⁠בַ⁠בָּקָ֡ר מַאֲכָ֡ל קֶ֠מַח דְּבֵלִ֨ים וְ⁠צִמּוּקִ֧ים וְ⁠יַֽיִן־וְ⁠שֶׁ֛מֶן וּ⁠בָקָ֥ר וְ⁠צֹ֖אן לָ⁠רֹ֑ב כִּ֥י שִׂמְחָ֖ה בְּ⁠יִשְׂרָאֵֽל׃פ","wĕ⁠ga֣m ha⁠qĕ̇rֽwòbiym-ʼà֠léy⁠hem ʻad-yişá̂şká֨r ẇ⁠zĕbul֜ẇn wĕ⁠napĕţá̇li֗y mĕbiyʼi֣ym le֡ẖem bȧ⁠ẖàmwòri֣ym ẇ⁠ba⁠gĕ̇mali֣̇ym ẇ⁠ba⁠pĕ̇rádi֣ym ׀ ẇֽ⁠ba⁠bá̇qá֡r maʼàká֡l qe֠maẖ dĕ̇béli֨ym wĕ⁠ẕiṁẇqi֧ym wĕ⁠yaֽyin-wĕ⁠şě֛men ẇ⁠báqá֥r wĕ⁠ẕò֖ʼn lá⁠rò֑b ki֥̇y şîmĕẖá֖h bĕ̇⁠yişĕ̂ráʼéֽl׃p"],[13,1,"וַ⁠יִּוָּעַ֣ץ דָּוִ֗יד עִם־שָׂרֵ֧י הָ⁠אֲלָפִ֛ים וְ⁠הַ⁠מֵּא֖וֹת לְ⁠כָל־נָגִֽיד׃","wa⁠yi̇wá̇ʻa֣ẕ dá̇wi֗yd ʻim-şá̂ré֧y há⁠ʼàlápi֛ym wĕ⁠ha⁠mé̇ʼ֖wòţ lĕ⁠kál-nágiֽyd׃"],[13,2,"וַ⁠יֹּ֨אמֶר דָּוִ֜יד לְ⁠כֹ֣ל ׀ קְהַ֣ל יִשְׂרָאֵ֗ל אִם־עֲלֵי⁠כֶ֨ם ט֜וֹב וּ⁠מִן־יְהוָ֣ה אֱלֹהֵ֗י⁠נוּ נִפְרְצָה֙ נִשְׁלְחָ֞ה עַל־אַחֵ֣י⁠נוּ הַ⁠נִּשְׁאָרִ֗ים בְּ⁠כֹל֙ אַרְצ֣וֹת יִשְׂרָאֵ֔ל וְ⁠עִמָּ⁠הֶ֛ם הַ⁠כֹּהֲנִ֥ים וְ⁠הַ⁠לְוִיִּ֖ם בְּ⁠עָרֵ֣י מִגְרְשֵׁי⁠הֶ֑ם וְ⁠יִקָּבְצ֖וּ אֵלֵֽי⁠נוּ׃","wa⁠yò̇֨ʼmer dá̇wi֜yd lĕ⁠kò֣l ׀ qĕha֣l yişĕ̂ráʼé֗l ʼim-ʻàléy⁠ke֨m t֜wòb ẇ⁠min-yĕhwá֣h ʼèlòhé֗y⁠nẇ nipĕrĕẕáh֙ nişĕ̌lĕẖá֞h ʻal-ʼaẖé֣y⁠nẇ ha⁠ni̇şĕ̌ʼári֗ym bĕ̇⁠kòl֙ ʼarĕẕ֣wòţ yişĕ̂ráʼé֔l wĕ⁠ʻimá̇⁠he֛m ha⁠kò̇hàni֥ym wĕ⁠ha⁠lĕwiyi֖̇m bĕ̇⁠ʻáré֣y migĕrĕşé̌y⁠he֑m wĕ⁠yiqá̇bĕẕ֖ẇ ʼéléֽy⁠nẇ׃"],[13,3,"וְ⁠נָסֵ֛בָּה אֶת־אֲר֥וֹן אֱלֹהֵ֖י⁠נוּ אֵלֵ֑י⁠נוּ כִּי־לֹ֥א דְרַשְׁנֻ֖⁠הוּ בִּ⁠ימֵ֥י שָׁאֽוּל׃","wĕ⁠násé֛bá̇h ʼeţ-ʼàr֥wòn ʼèlòhé֖y⁠nẇ ʼélé֑y⁠nẇ ki̇y-lò֥ʼ dĕraşĕ̌nu֖⁠hẇ bi̇⁠ymé֥y şá̌ʼֽẇl׃"],[13,4,"וַ⁠יֹּאמְר֥וּ כָֽל־הַ⁠קָּהָ֖ל לַ⁠עֲשׂ֣וֹת כֵּ֑ן כִּֽי־יָשַׁ֥ר הַ⁠דָּבָ֖ר בְּ⁠עֵינֵ֥י כָל־הָ⁠עָֽם׃","wa⁠yò̇ʼmĕr֥ẇ káֽl-ha⁠qá̇há֖l la⁠ʻàş֣̂wòţ ké֑̇n kiֽ̇y-yáşǎ֥r ha⁠dá̇bá֖r bĕ̇⁠ʻéyné֥y kál-há⁠ʻáֽm׃"],[13,5,"וַ⁠יַּקְהֵ֤ל דָּוִיד֙ אֶת־כָּל־יִשְׂרָאֵ֔ל מִן־שִׁיח֥וֹר מִצְרַ֖יִם וְ⁠עַד־לְב֣וֹא חֲמָ֑ת לְ⁠הָבִיא֙ אֶת־אֲר֣וֹן הָ⁠אֱלֹהִ֔ים מִ⁠קִּרְיַ֖ת יְעָרִֽים׃","wa⁠yȧqĕhé֤l dá̇wiyd֙ ʼeţ-ká̇l-yişĕ̂ráʼé֔l min-şǐyẖ֥wòr miẕĕra֖yim wĕ⁠ʻad-lĕb֣wòʼ ẖàmá֑ţ lĕ⁠hábiyʼ֙ ʼeţ-ʼàr֣wòn há⁠ʼèlòhi֔ym mi⁠qi̇rĕya֖ţ yĕʻáriֽym׃"],[13,6,"וַ⁠יַּ֨עַל דָּוִ֤יד וְ⁠כָל־יִשְׂרָאֵל֙ בַּעֲלָ֔תָ⁠ה אֶל־קִרְיַ֥ת יְעָרִ֖ים אֲשֶׁ֣ר לִ⁠יהוּדָ֑ה לְ⁠הַעֲל֣וֹת מִ⁠שָּׁ֗ם אֵת֩ אֲר֨וֹן הָ⁠אֱלֹהִ֧ים ׀ יְהוָ֛ה יוֹשֵׁ֥ב הַ⁠כְּרוּבִ֖ים אֲשֶׁר־נִקְרָ֥א שֵֽׁם׃","wa⁠yȧ֨ʻal dá̇wi֤yd wĕ⁠kál-yişĕ̂ráʼél֙ bȧʻàlá֔ţá⁠h ʼel-qirĕya֥ţ yĕʻári֖ym ʼàşě֣r li⁠yhẇdá֑h lĕ⁠haʻàl֣wòţ mi⁠şá̇̌֗m ʼéţ֩ ʼàr֨wòn há⁠ʼèlòhi֧ym ׀ yĕhwá֛h ywòşé֥̌b ha⁠kĕ̇rẇbi֖ym ʼàşěr-niqĕrá֥ʼ şéֽ̌m׃"],[13,7,"וַ⁠יַּרְכִּ֜יבוּ אֶת־אֲר֤וֹן הָ⁠אֱלֹהִים֙ עַל־עֲגָלָ֣ה חֲדָשָׁ֔ה מִ⁠בֵּ֖ית אֲבִינָדָ֑ב וְ⁠עֻזָּ֣א וְ⁠אַחְי֔וֹ נֹהֲגִ֖ים בָּ⁠עֲגָלָֽה׃","wa⁠yȧrĕki̇֜ybẇ ʼeţ-ʼàr֤wòn há⁠ʼèlòhiym֙ ʻal-ʻàgálá֣h ẖàdáşá̌֔h mi⁠bé֖̇yţ ʼàbiynádá֑b wĕ⁠ʻuzá֣̇ʼ wĕ⁠ʼaẖĕy֔wò nòhàgi֖ym bá̇⁠ʻàgáláֽh׃"],[13,8,"וְ⁠דָוִ֣יד וְ⁠כָל־יִשְׂרָאֵ֗ל מְשַׂחֲקִ֛ים לִ⁠פְנֵ֥י הָ⁠אֱלֹהִ֖ים בְּ⁠כָל־עֹ֑ז וּ⁠בְ⁠שִׁירִ֤ים וּ⁠בְ⁠כִנֹּרוֹת֙ וּ⁠בִ⁠נְבָלִ֣ים וּ⁠בְ⁠תֻפִּ֔ים וּ⁠בִ⁠מְצִלְתַּ֖יִם וּ⁠בַ⁠חֲצֹצְרֽוֹת׃","wĕ⁠dáwi֣yd wĕ⁠kál-yişĕ̂ráʼé֗l mĕşâẖàqi֛ym li⁠pĕné֥y há⁠ʼèlòhi֖ym bĕ̇⁠kál-ʻò֑z ẇ⁠bĕ⁠şǐyri֤ym ẇ⁠bĕ⁠kinò̇rwòţ֙ ẇ⁠bi⁠nĕbáli֣ym ẇ⁠bĕ⁠ţupi̇֔ym ẇ⁠bi⁠mĕẕilĕţȧ֖yim ẇ⁠ba⁠ẖàẕòẕĕrֽwòţ׃"],[13,9,"וַ⁠יָּבֹ֖אוּ עַד־גֹּ֣רֶן כִּידֹ֑ן וַ⁠יִּשְׁלַ֨ח עֻזָּ֜א אֶת־יָד֗⁠וֹ לֶ⁠אֱחֹז֙ אֶת־הָ֣⁠אָר֔וֹן כִּ֥י שָֽׁמְט֖וּ הַ⁠בָּקָֽר׃","wa⁠yá̇bò֖ʼẇ ʻad-gò֣̇ren ki̇ydò֑n wa⁠yi̇şĕ̌la֨ẖ ʻuzá̇֜ʼ ʼeţ-yád֗⁠wò le⁠ʼèẖòz֙ ʼeţ-há֣⁠ʼár֔wòn ki֥̇y şáֽ̌mĕt֖ẇ ha⁠bá̇qáֽr׃"],[13,10,"וַ⁠יִּֽחַר־אַ֤ף יְהוָה֙ בְּ⁠עֻזָּ֔א וַ⁠יַּכֵּ֕⁠הוּ עַ֛ל אֲשֶׁר־שָׁלַ֥ח יָד֖⁠וֹ עַל־הָ⁠אָר֑וֹן וַ⁠יָּ֥מָת שָׁ֖ם לִ⁠פְנֵ֥י אֱלֹהִֽים׃","wa⁠yiֽ̇ẖar-ʼa֤p yĕhwáh֙ bĕ̇⁠ʻuzá̇֔ʼ wa⁠yȧké̇֕⁠hẇ ʻa֛l ʼàşěr-şá̌la֥ẖ yád֖⁠wò ʻal-há⁠ʼár֑wòn wa⁠yá֥̇máţ şá֖̌m li⁠pĕné֥y ʼèlòhiֽym׃"],[13,11,"וַ⁠יִּ֣חַר לְ⁠דָוִ֔יד כִּֽי־פָרַ֧ץ יְהוָ֛ה פֶּ֖רֶץ בְּ⁠עֻזָּ֑א וַ⁠יִּקְרָ֞א לַ⁠מָּק֤וֹם הַ⁠הוּא֙ פֶּ֣רֶץ עֻזָּ֔א עַ֖ד הַ⁠יּ֥וֹם הַ⁠זֶּֽה׃","wa⁠yi֣̇ẖar lĕ⁠dáwi֔yd kiֽ̇y-pára֧ẕ yĕhwá֛h pė֖reẕ bĕ̇⁠ʻuzá֑̇ʼ wa⁠yi̇qĕrá֞ʼ la⁠má̇q֤wòm ha⁠hẇʼ֙ pė֣reẕ ʻuzá̇֔ʼ ʻa֖d ha⁠ẏ֥wòm ha⁠zėֽh׃"],[13,12,"וַ⁠יִּירָ֤א דָוִיד֙ אֶת־הָ֣⁠אֱלֹהִ֔ים בַּ⁠יּ֥וֹם הַ⁠ה֖וּא לֵ⁠אמֹ֑ר הֵ֚יךְ אָבִ֣יא אֵלַ֔⁠י אֵ֖ת אֲר֥וֹן הָ⁠אֱלֹהִֽים׃","wa⁠yi̇yrá֤ʼ dáwiyd֙ ʼeţ-há֣⁠ʼèlòhi֔ym bȧ⁠ẏ֥wòm ha⁠h֖ẇʼ lé⁠ʼmò֑r hé֚ykĕ ʼábi֣yʼ ʼéla֔⁠y ʼé֖ţ ʼàr֥wòn há⁠ʼèlòhiֽym׃"],[13,13,"וְ⁠לֹֽא־הֵסִ֨יר דָּוִ֧יד אֶת־הָ⁠אָר֛וֹן אֵלָ֖י⁠ו אֶל־עִ֣יר דָּוִ֑יד וַ⁠יַּטֵּ֕⁠הוּ אֶל־בֵּ֥ית עֹבֵֽד־אֱדֹ֖ם הַ⁠גִּתִּֽי׃","wĕ⁠lòֽʼ-hési֨yr dá̇wi֧yd ʼeţ-há⁠ʼár֛wòn ʼélá֖y⁠w ʼel-ʻi֣yr dá̇wi֑yd wa⁠yȧté̇֕⁠hẇ ʼel-bé֥̇yţ ʻòbéֽd-ʼèdò֖m ha⁠gi̇ţiֽ̇y׃"],[13,14,"וַ⁠יֵּשֶׁב֩ אֲר֨וֹן הָ⁠אֱלֹהִ֜ים עִם־בֵּ֨ית עֹבֵ֥ד אֱדֹ֛ם בְּ⁠בֵית֖⁠וֹ שְׁלֹשָׁ֣ה חֳדָשִׁ֑ים וַ⁠יְבָ֧רֶךְ יְהוָ֛ה אֶת־בֵּ֥ית עֹבֵֽד־אֱדֹ֖ם וְ⁠אֶת־כָּל־אֲשֶׁר־לֽ⁠וֹ׃פ","wa⁠yé̇şěb֩ ʼàr֨wòn há⁠ʼèlòhi֜ym ʻim-bé̇֨yţ ʻòbé֥d ʼèdò֛m bĕ̇⁠béyţ֖⁠wò şĕ̌lòşá֣̌h ẖodáşǐ֑ym wa⁠yĕbá֧rekĕ yĕhwá֛h ʼeţ-bé֥̇yţ ʻòbéֽd-ʼèdò֖m wĕ⁠ʼeţ-ká̇l-ʼàşěr-lֽ⁠wò׃p"],[14,1,"וַ֠⁠יִּשְׁלַח חירם מֶֽלֶךְ־צֹ֥ר מַלְאָכִים֮ אֶל־דָּוִיד֒ וַ⁠עֲצֵ֣י אֲרָזִ֔ים וְ⁠חָרָשֵׁ֣י קִ֔יר וְ⁠חָרָשֵׁ֖י עֵצִ֑ים לִ⁠בְנ֥וֹת ל֖⁠וֹ בָּֽיִת׃","wa֠⁠yi̇şĕ̌laẖ ẖyrm meֽlekĕ-ẕò֥r malĕʼákiym֮ ʼel-dá̇wiyd֒ wa⁠ʻàẕé֣y ʼàrázi֔ym wĕ⁠ẖáráşé֣̌y qi֔yr wĕ⁠ẖáráşé֖̌y ʻéẕi֑ym li⁠bĕn֥wòţ l֖⁠wò báֽ̇yiţ׃"],[14,2,"וַ⁠יֵּ֣דַע דָּוִ֔יד כִּֽי־הֱכִינ֧⁠וֹ יְהוָ֛ה לְ⁠מֶ֖לֶךְ עַל־יִשְׂרָאֵ֑ל כִּֽי־נִשֵּׂ֤את לְ⁠מַ֨עְלָ⁠ה֙ מַלְכוּת֔⁠וֹ בַּ⁠עֲב֖וּר עַמּ֥⁠וֹ יִשְׂרָאֵֽל׃פ","wa⁠yé֣̇daʻ dá̇wi֔yd kiֽ̇y-hèkiyn֧⁠wò yĕhwá֛h lĕ⁠me֖lekĕ ʻal-yişĕ̂ráʼé֑l kiֽ̇y-nişé֤̇̂ʼţ lĕ⁠ma֨ʻĕlá⁠h֙ malĕkẇţ֔⁠wò bȧ⁠ʻàb֖ẇr ʻaṁ֥⁠wò yişĕ̂ráʼéֽl׃p"],[14,3,"וַ⁠יִּקַּ֨ח דָּוִ֥יד ע֛וֹד נָשִׁ֖ים בִּ⁠ירוּשָׁלִָ֑ם וַ⁠יּ֧וֹלֶד דָּוִ֛יד ע֖וֹד בָּנִ֥ים וּ⁠בָנֽוֹת׃","wa⁠yi̇qȧ֨ẖ dá̇wi֥yd ʻ֛wòd náşǐ֖ym bi̇⁠yrẇşá̌liá֑m wa⁠ẏ֧wòled dá̇wi֛yd ʻ֖wòd bá̇ni֥ym ẇ⁠bánֽwòţ׃"],[14,4,"וְ⁠אֵ֨לֶּה֙ שְׁמ֣וֹת הַ⁠יְלוּדִ֔ים אֲשֶׁ֥ר הָיוּ־ל֖⁠וֹ בִּ⁠ירוּשָׁלִָ֑ם שַׁמּ֣וּעַ וְ⁠שׁוֹבָ֔ב נָתָ֖ן וּ⁠שְׁלֹמֹֽה׃","wĕ⁠ʼé֨lėh֙ şĕ̌m֣wòţ ha⁠yĕlẇdi֔ym ʼàşě֥r háyẇ-l֖⁠wò bi̇⁠yrẇşá̌liá֑m şǎṁ֣ẇʻa wĕ⁠ş̌wòbá֔b náţá֖n ẇ⁠şĕ̌lòmòֽh׃"],[14,5,"וְ⁠יִבְחָ֥ר וֶ⁠אֱלִישׁ֖וּעַ וְ⁠אֶלְפָּֽלֶט׃","wĕ⁠yibĕẖá֥r we⁠ʼèliyş֖̌ẇʻa wĕ⁠ʼelĕpáֽ̇let׃"],[14,6,"וְ⁠נֹ֥גַהּ וְ⁠נֶ֖פֶג וְ⁠יָפִֽיעַ׃","wĕ⁠nò֥gaḣ wĕ⁠ne֖peg wĕ⁠yápiֽyʻa׃"],[14,7,"וֶ⁠אֱלִישָׁמָ֥ע וּ⁠בְעֶלְיָדָ֖ע וֶ⁠אֱלִיפָֽלֶט׃","we⁠ʼèliyşá̌má֥ʻ ẇ⁠bĕʻelĕyádá֖ʻ we⁠ʼèliypáֽlet׃"],[14,8,"וַ⁠יִּשְׁמְע֣וּ פְלִשְׁתִּ֗ים כִּי־נִמְשַׁ֨ח דָּוִ֤יד לְ⁠מֶ֨לֶךְ֙ עַל־כָּל־יִשְׂרָאֵ֔ל וַ⁠יַּעֲל֥וּ כָל־פְּלִשְׁתִּ֖ים לְ⁠בַקֵּ֣שׁ אֶת־דָּוִ֑יד וַ⁠יִּשְׁמַ֣ע דָּוִ֔יד וַ⁠יֵּצֵ֖א לִ⁠פְנֵי⁠הֶֽם׃","wa⁠yi̇şĕ̌mĕʻ֣ẇ pĕlişĕ̌ţi̇֗ym ki̇y-nimĕşǎ֨ẖ dá̇wi֤yd lĕ⁠me֨lekĕ֙ ʻal-ká̇l-yişĕ̂ráʼé֔l wa⁠yȧʻàl֥ẇ kál-pĕ̇lişĕ̌ţi֖̇ym lĕ⁠baqé֣̇ş̌ ʼeţ-dá̇wi֑yd wa⁠yi̇şĕ̌ma֣ʻ dá̇wi֔yd wa⁠yé̇ẕé֖ʼ li⁠pĕnéy⁠heֽm׃"],[14,9,"וּ⁠פְלִשְׁתִּ֖ים בָּ֑אוּ וַֽ⁠יִּפְשְׁט֖וּ בְּ⁠עֵ֥מֶק רְפָאִֽים׃","ẇ⁠pĕlişĕ̌ţi֖̇ym bá֑̇ʼẇ waֽ⁠yi̇pĕşĕ̌t֖ẇ bĕ̇⁠ʻé֥meq rĕpáʼiֽym׃"],[14,10,"וַ⁠יִּשְׁאַ֨ל דָּוִ֤יד בֵּ⁠אלֹהִים֙ לֵ⁠אמֹ֔ר הַ⁠אֶֽעֱלֶה֙ עַל־פלשתיים וּ⁠נְתַתָּ֖⁠ם בְּ⁠יָדִ֑⁠י וַ⁠יֹּ֨אמֶר ל֤⁠וֹ יְהוָה֙ עֲלֵ֔ה וּ⁠נְתַתִּ֖י⁠ם בְּ⁠יָדֶֽ⁠ךָ׃","wa⁠yi̇şĕ̌ʼa֨l dá̇wi֤yd bé̇⁠ʼlòhiym֙ lé⁠ʼmò֔r ha⁠ʼeֽʻèleh֙ ʻal-plşţyym ẇ⁠nĕţaţá֖̇⁠m bĕ̇⁠yádi֑⁠y wa⁠yò̇֨ʼmer l֤⁠wò yĕhwáh֙ ʻàlé֔h ẇ⁠nĕţaţi֖̇y⁠m bĕ̇⁠yádeֽ⁠ká׃"],[14,11,"וַ⁠יַּעֲל֥וּ בְּ⁠בַֽעַל־פְּרָצִים֮ וַ⁠יַּכֵּ֣⁠ם שָׁ֣ם דָּוִיד֒ וַ⁠יֹּ֣אמֶר דָּוִ֔יד פָּרַ֨ץ הָֽ⁠אֱלֹהִ֧ים אֶת־אוֹיְבַ֛⁠י בְּ⁠יָדִ֖⁠י כְּ⁠פֶ֣רֶץ מָ֑יִם עַל־כֵּ֗ן קָֽרְא֛וּ שֵֽׁם־הַ⁠מָּק֥וֹם הַ⁠ה֖וּא בַּ֥עַל פְּרָצִֽים׃","wa⁠yȧʻàl֥ẇ bĕ̇⁠baֽʻal-pĕ̇ráẕiym֮ wa⁠yȧké֣̇⁠m şá֣̌m dá̇wiyd֒ wa⁠yò֣̇ʼmer dá̇wi֔yd pá̇ra֨ẕ háֽ⁠ʼèlòhi֧ym ʼeţ-ʼwòyĕba֛⁠y bĕ̇⁠yádi֖⁠y kĕ̇⁠pe֣reẕ má֑yim ʻal-ké̇֗n qáֽrĕʼ֛ẇ şéֽ̌m-ha⁠má̇q֥wòm ha⁠h֖ẇʼ bȧ֥ʻal pĕ̇ráẕiֽym׃"],[14,12,"וַ⁠יַּעַזְבוּ־שָׁ֖ם אֶת־אֱלֹֽהֵי⁠הֶ֑ם וַ⁠יֹּ֣אמֶר דָּוִ֔יד וַ⁠יִּשָּׂרְפ֖וּ בָּ⁠אֵֽשׁ׃פ","wa⁠yȧʻazĕbẇ-şá֖̌m ʼeţ-ʼèlòֽhéy⁠he֑m wa⁠yò֣̇ʼmer dá̇wi֔yd wa⁠yi̇şá̇̂rĕp֖ẇ bá̇⁠ʼéֽş̌׃p"],[14,13,"וַ⁠יֹּסִ֤יפוּ עוֹד֙ פְּלִשְׁתִּ֔ים וַֽ⁠יִּפְשְׁט֖וּ בָּ⁠עֵֽמֶק׃","wa⁠yò̇si֤ypẇ ʻwòd֙ pĕ̇lişĕ̌ţi̇֔ym waֽ⁠yi̇pĕşĕ̌t֖ẇ bá̇⁠ʻéֽmeq׃"],[14,14,"וַ⁠יִּשְׁאַ֨ל ע֤וֹד דָּוִיד֙ בֵּֽ⁠אלֹהִ֔ים וַ⁠יֹּ֤אמֶר ל⁠וֹ֙ הָֽ⁠אֱלֹהִ֔ים לֹ֥א תַֽעֲלֶ֖ה אַֽחֲרֵי⁠הֶ֑ם הָסֵב֙ מֵֽ⁠עֲלֵי⁠הֶ֔ם וּ⁠בָ֥אתָ לָ⁠הֶ֖ם מִ⁠מּ֥וּל הַ⁠בְּכָאִֽים׃","wa⁠yi̇şĕ̌ʼa֨l ʻ֤wòd dá̇wiyd֙ béֽ̇⁠ʼlòhi֔ym wa⁠yò֤̇ʼmer l⁠wò֙ háֽ⁠ʼèlòhi֔ym lò֥ʼ ţֽaʻàle֖h ʼֽaẖàréy⁠he֑m háséb֙ méֽ⁠ʻàléy⁠he֔m ẇ⁠bá֥ʼţá lá⁠he֖m mi⁠ṁ֥ẇl ha⁠bĕ̇káʼiֽym׃"],[14,15,"וִ֠⁠יהִי כְּֽ⁠שָׁמְעֲ⁠ךָ֞ אֶת־ק֤וֹל הַ⁠צְּעָדָה֙ בְּ⁠רָאשֵׁ֣י הַ⁠בְּכָאִ֔ים אָ֖ז תֵּצֵ֣א בַ⁠מִּלְחָמָ֑ה כִּֽי־יָצָ֤א הָֽ⁠אֱלֹהִים֙ לְ⁠פָנֶ֔י⁠ךָ לְ⁠הַכּ֖וֹת אֶת־מַחֲנֵ֥ה פְלִשְׁתִּֽים׃","wi֠⁠yhiy kĕֽ̇⁠şá̌mĕʻà⁠ká֞ ʼeţ-q֤wòl ha⁠ẕĕ̇ʻádáh֙ bĕ̇⁠ráʼşé֣̌y ha⁠bĕ̇káʼi֔ym ʼá֖z ţé̇ẕé֣ʼ ba⁠mi̇lĕẖámá֑h kiֽ̇y-yáẕá֤ʼ háֽ⁠ʼèlòhiym֙ lĕ⁠páne֔y⁠ká lĕ⁠hak֖̇wòţ ʼeţ-maẖàné֥h pĕlişĕ̌ţiֽ̇ym׃"],[14,16,"וַ⁠יַּ֣עַשׂ דָּוִ֔יד כַּֽ⁠אֲשֶׁ֥ר צִוָּ֖⁠הוּ הָֽ⁠אֱלֹהִ֑ים וַ⁠יַּכּוּ֙ אֶת־מַחֲנֵ֣ה פְלִשְׁתִּ֔ים מִ⁠גִּבְע֖וֹן וְ⁠עַד־גָּֽזְרָ⁠ה׃","wa⁠yȧ֣ʻaş̂ dá̇wi֔yd kֽ̇a⁠ʼàşě֥r ẕiwá֖̇⁠hẇ hֽá⁠ʼèlòhi֑ym wa⁠yȧk̇ẇ֙ ʼeţ-maẖàné֣h pĕlişĕ̌ţi̇֔ym mi⁠gi̇bĕʻ֖wòn wĕ⁠ʻad-gáֽ̇zĕrá⁠h׃"],[14,17,"וַ⁠יֵּצֵ֥א שֵׁם־דָּוִ֖יד בְּ⁠כָל־הָֽ⁠אֲרָצ֑וֹת וַֽ⁠יהוָ֛ה נָתַ֥ן אֶת־פַּחְדּ֖⁠וֹ עַל־כָּל־הַ⁠גּוֹיִֽם׃","wa⁠yé̇ẕé֥ʼ şé̌m-dá̇wi֖yd bĕ̇⁠kál-háֽ⁠ʼàráẕ֑wòţ waֽ⁠yhwá֛h náţa֥n ʼeţ-pȧẖĕḋ֖⁠wò ʻal-ká̇l-ha⁠ġwòyiֽm׃"],[15,1,"וַ⁠יַּֽעַשׂ־ל֥⁠וֹ בָתִּ֖ים בְּ⁠עִ֣יר דָּוִ֑יד וַ⁠יָּ֤כֶן מָקוֹם֙ לַֽ⁠אֲר֣וֹן הָֽ⁠אֱלֹהִ֔ים וַ⁠יֶּט־ל֖⁠וֹ אֹֽהֶל׃","wa⁠yȧֽʻaş̂-l֥⁠wò báţi֖̇ym bĕ̇⁠ʻi֣yr dá̇wi֑yd wa⁠yá֤̇ken máqwòm֙ lֽa⁠ʼàr֣wòn hֽá⁠ʼèlòhi֔ym wa⁠yėt-l֖⁠wò ʼòֽhel׃"],[15,2,"אָ֚ז אָמַ֣ר דָּוִ֔יד לֹ֤א לָ⁠שֵׂאת֙ אֶת־אֲר֣וֹן הָֽ⁠אֱלֹהִ֔ים כִּ֖י אִם־הַ⁠לְוִיִּ֑ם כִּי־בָ֣⁠ם ׀ בָּחַ֣ר יְהוָ֗ה לָ⁠שֵׂ֞את אֶת־אֲר֧וֹן יְהוָ֛ה וּֽ⁠לְ⁠שָׁרְת֖⁠וֹ עַד־עוֹלָֽם׃ס","ʼá֚z ʼáma֣r dá̇wi֔yd lò֤ʼ lá⁠şé̂ʼţ֙ ʼeţ-ʼàr֣wòn hֽá⁠ʼèlòhi֔ym ki֖̇y ʼim-ha⁠lĕwiyi֑̇m ki̇y-bá֣⁠m ׀ bá̇ẖa֣r yĕhwá֗h lá⁠şé̂֞ʼţ ʼeţ-ʼàr֧wòn yĕhwá֛h ẇֽ⁠lĕ⁠şá̌rĕţ֖⁠wò ʻad-ʻwòláֽm׃s"],[15,3,"וַ⁠יַּקְהֵ֥ל דָּוִ֛יד אֶת־כָּל־יִשְׂרָאֵ֖ל אֶל־יְרֽוּשָׁלִָ֑ם לְ⁠הַעֲלוֹת֙ אֶת־אֲר֣וֹן יְהוָ֔ה אֶל־מְקוֹמ֖⁠וֹ אֲשֶׁר־הֵכִ֥ין לֽ⁠וֹ׃","wa⁠yȧqĕhé֥l dá̇wi֛yd ʼeţ-ká̇l-yişĕ̂ráʼé֖l ʼel-yĕrֽẇşá̌liá֑m lĕ⁠haʻàlwòţ֙ ʼeţ-ʼàr֣wòn yĕhwá֔h ʼel-mĕqwòm֖⁠wò ʼàşěr-héki֥yn lֽ⁠wò׃"],[15,4,"וַ⁠יֶּאֱסֹ֥ף דָּוִ֛יד אֶת־בְּנֵ֥י אַֽהֲרֹ֖ן וְ⁠אֶת־הַ⁠לְוִיִּֽם׃","wa⁠yėʼèsò֥p dá̇wi֛yd ʼeţ-bĕ̇né֥y ʼֽahàrò֖n wĕ⁠ʼeţ-ha⁠lĕwiyiֽ̇m׃"],[15,5,"לִ⁠בְנֵ֖י קְהָ֑ת אוּרִיאֵ֣ל הַ⁠שָּׂ֔ר וְ⁠אֶחָ֖י⁠ו מֵאָ֥ה וְ⁠עֶשְׂרִֽים׃ס","li⁠bĕné֖y qĕhá֑ţ ʼẇriyʼé֣l ha⁠şá̇̂֔r wĕ⁠ʼeẖá֖y⁠w méʼá֥h wĕ⁠ʻeşĕ̂riֽym׃s"],[15,6,"לִ⁠בְנֵ֖י מְרָרִ֑י עֲשָׂיָ֣ה הַ⁠שָּׂ֔ר וְ⁠אֶחָ֖י⁠ו מָאתַ֥יִם וְ⁠עֶשְׂרִֽים׃ס","li⁠bĕné֖y mĕrári֑y ʻàşá̂yá֣h ha⁠şá̇̂֔r wĕ⁠ʼeẖá֖y⁠w máʼţa֥yim wĕ⁠ʻeşĕ̂riֽym׃s"],[15,7,"לִ⁠בְנֵ֖י גֵּרְשׁ֑וֹם יוֹאֵ֣ל הַ⁠שָּׂ֔ר וְ⁠אֶחָ֖י⁠ו מֵאָ֥ה וּ⁠שְׁלֹשִֽׁים׃ס","li⁠bĕné֖y gé̇rĕş֑̌wòm ywòʼé֣l ha⁠şá̇̂֔r wĕ⁠ʼeẖá֖y⁠w méʼá֥h ẇ⁠şĕ̌lòşǐֽym׃s"],[15,8,"לִ⁠בְנֵ֖י אֱלִֽיצָפָ֑ן שְׁמַֽעְיָ֥ה הַ⁠שָּׂ֖ר וְ⁠אֶחָ֥י⁠ו מָאתָֽיִם׃ס","li⁠bĕné֖y ʼèliֽyẕápá֑n şĕ̌maֽʻĕyá֥h ha⁠şá֖̇̂r wĕ⁠ʼeẖá֥y⁠w máʼţáֽyim׃s"],[15,9,"לִ⁠בְנֵ֖י חֶבְר֑וֹן אֱלִיאֵ֥ל הַ⁠שָּׂ֖ר וְ⁠אֶחָ֥י⁠ו שְׁמוֹנִֽים׃ס","li⁠bĕné֖y ẖebĕr֑wòn ʼèliyʼé֥l ha⁠şá֖̇̂r wĕ⁠ʼeẖá֥y⁠w şĕ̌mwòniֽym׃s"],[15,10,"לִ⁠בְנֵ֖י עֻזִּיאֵ֑ל עַמִּינָדָ֣ב הַ⁠שָּׂ֔ר וְ⁠אֶחָ֕י⁠ו מֵאָ֖ה וּ⁠שְׁנֵ֥ים עָשָֽׂר׃ס","li⁠bĕné֖y ʻuzi̇yʼé֑l ʻami̇ynádá֣b ha⁠şá̇̂֔r wĕ⁠ʼeẖá֕y⁠w méʼá֖h ẇ⁠şĕ̌né֥ym ʻáşáֽ̂r׃s"],[15,11,"וַ⁠יִּקְרָ֣א דָוִ֔יד לְ⁠צָד֥וֹק וּ⁠לְ⁠אֶבְיָתָ֖ר הַ⁠כֹּֽהֲנִ֑ים וְ⁠לַ⁠לְוִיִּ֗ם לְ⁠אֽוּרִיאֵ֤ל עֲשָׂיָה֙ וְ⁠יוֹאֵ֣ל שְׁמַֽעְיָ֔ה וֶ⁠אֱלִיאֵ֖ל וְ⁠עַמִּינָדָֽב׃","wa⁠yi̇qĕrá֣ʼ dáwi֔yd lĕ⁠ẕád֥wòq ẇ⁠lĕ⁠ʼebĕyáţá֖r ha⁠kòֽ̇hàni֑ym wĕ⁠la⁠lĕwiyi̇֗m lĕ⁠ʼֽẇriyʼé֤l ʻàşá̂yáh֙ wĕ⁠ywòʼé֣l şĕ̌maֽʻĕyá֔h we⁠ʼèliyʼé֖l wĕ⁠ʻami̇ynádáֽb׃"],[15,12,"וַ⁠יֹּ֣אמֶר לָ⁠הֶ֔ם אַתֶּ֛ם רָאשֵׁ֥י הָ⁠אָב֖וֹת לַ⁠לְוִיִּ֑ם הִֽתְקַדְּשׁוּ֙ אַתֶּ֣ם וַ⁠אֲחֵי⁠כֶ֔ם וְ⁠הַֽעֲלִיתֶ֗ם אֵ֣ת אֲר֤וֹן יְהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל אֶל־הֲכִינ֖וֹתִי לֽ⁠וֹ׃","wa⁠yò֣̇ʼmer lá⁠he֔m ʼaţė֛m ráʼşé֥̌y há⁠ʼáb֖wòţ la⁠lĕwiyi֑̇m hiֽţĕqadĕ̇ş̌ẇ֙ ʼaţė֣m wa⁠ʼàẖéy⁠ke֔m wĕ⁠haֽʻàliyţe֗m ʼé֣ţ ʼàr֤wòn yĕhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l ʼel-hàkiyn֖wòţiy lֽ⁠wò׃"],[15,13,"כִּ֛י לְ⁠מַ בָּ⁠רִ֥אשׁוֹנָ֖ה לֹ֣א אַתֶּ֑ם פָּרַ֨ץ יְהוָ֤ה אֱלֹהֵ֨י⁠נוּ֙ בָּ֔⁠נוּ כִּי־לֹ֥א דְרַשְׁנֻ֖⁠הוּ כַּ⁠מִּשְׁפָּֽט׃","ki֛̇y lĕ⁠ma bá̇⁠ri֥ʼş̌wòná֖h lò֣ʼ ʼaţė֑m pá̇ra֨ẕ yĕhwá֤h ʼèlòhé֨y⁠nẇ֙ bá̇֔⁠nẇ ki̇y-lò֥ʼ dĕraşĕ̌nu֖⁠hẇ kȧ⁠mi̇şĕ̌páֽ̇t׃"],[15,14,"וַ⁠יִּֽתְקַדְּשׁ֔וּ הַ⁠כֹּהֲנִ֖ים וְ⁠הַ⁠לְוִיִּ֑ם לְ⁠הַעֲל֕וֹת אֶת־אֲר֥וֹן יְהוָ֖ה אֱלֹהֵ֥י יִשְׂרָאֵֽל׃","wa⁠yiֽ̇ţĕqadĕ̇ş̌֔ẇ ha⁠kò̇hàni֖ym wĕ⁠ha⁠lĕwiyi֑̇m lĕ⁠haʻàl֕wòţ ʼeţ-ʼàr֥wòn yĕhwá֖h ʼèlòhé֥y yişĕ̂ráʼéֽl׃"],[15,15,"וַ⁠יִּשְׂא֣וּ בְנֵֽי־הַ⁠לְוִיִּ֗ם אֵ֚ת אֲר֣וֹן הָֽ⁠אֱלֹהִ֔ים כַּ⁠אֲשֶׁ֛ר צִוָּ֥ה מֹשֶׁ֖ה כִּ⁠דְבַ֣ר יְהוָ֑ה בִּ⁠כְתֵפָ֥⁠ם בַּ⁠מֹּט֖וֹת עֲלֵי⁠הֶֽם׃פ","wa⁠yi̇şĕ̂ʼ֣ẇ bĕnéֽy-ha⁠lĕwiyi̇֗m ʼé֚ţ ʼàr֣wòn háֽ⁠ʼèlòhi֔ym kȧ⁠ʼàşě֛r ẕiwá֥̇h mòşě֖h ki̇⁠dĕba֣r yĕhwá֑h bi̇⁠kĕţépá֥⁠m bȧ⁠mò̇t֖wòţ ʻàléy⁠heֽm׃p"],[15,16,"וַ⁠יֹּ֣אמֶר דָּוִיד֮ לְ⁠שָׂרֵ֣י הַ⁠לְוִיִּם֒ לְ⁠הַֽעֲמִ֗יד אֶת־אֲחֵי⁠הֶם֙ הַ⁠מְשֹׁ֣רְרִ֔ים בִּ⁠כְלֵי־שִׁ֛יר נְבָלִ֥ים וְ⁠כִנֹּר֖וֹת וּ⁠מְצִלְתָּ֑יִם מַשְׁמִיעִ֥ים לְ⁠הָרִֽים־בְּ⁠ק֖וֹל לְ⁠שִׂמְחָֽה׃פ","wa⁠yò֣̇ʼmer dá̇wiyd֮ lĕ⁠şá̂ré֣y ha⁠lĕwiyi̇m֒ lĕ⁠haֽʻàmi֗yd ʼeţ-ʼàẖéy⁠hem֙ ha⁠mĕşò֣̌rĕri֔ym bi̇⁠kĕléy-şǐ֛yr nĕbáli֥ym wĕ⁠kinò̇r֖wòţ ẇ⁠mĕẕilĕţá֑̇yim maşĕ̌miyʻi֥ym lĕ⁠háriֽym-bĕ̇⁠q֖wòl lĕ⁠şîmĕẖáֽh׃p"],[15,17,"וַ⁠יַּעֲמִ֣ידוּ הַ⁠לְוִיִּ֗ם אֵ֚ת הֵימָ֣ן בֶּן־יוֹאֵ֔ל וּ⁠מִ֨ן־אֶחָ֔י⁠ו אָסָ֖ף בֶּן־בֶּֽרֶכְיָ֑הוּ ס וּ⁠מִן־בְּנֵ֤י מְרָרִי֙ אֲחֵי⁠הֶ֔ם אֵיתָ֖ן בֶּן־קֽוּשָׁיָֽהוּ׃","wa⁠yȧʻàmi֣ydẇ ha⁠lĕwiyi̇֗m ʼé֚ţ héymá֣n bėn-ywòʼé֔l ẇ⁠mi֨n-ʼeẖá֔y⁠w ʼásá֖p bėn-bėֽrekĕyá֑hẇ s ẇ⁠min-bĕ̇né֤y mĕráriy֙ ʼàẖéy⁠he֔m ʼéyţá֖n bėn-qֽẇşá̌yáֽhẇ׃"],[15,18,"וְ⁠עִמָּ⁠הֶ֖ם אֲחֵי⁠הֶ֣ם הַ⁠מִּשְׁנִ֑ים זְכַרְיָ֡הוּ בֵּ֡ן וְ⁠יַֽעֲזִיאֵ֡ל וּ⁠שְׁמִֽירָמ֡וֹת וִ⁠יחִיאֵ֣ל ׀ וְ⁠עֻנִּ֡י אֱלִיאָ֡ב וּ⁠בְנָיָ֡הוּ וּ⁠מַֽעֲשֵׂיָ֡הוּ וּ⁠מַתִּתְיָהוּ֩ וֶ⁠אֱלִ֨יפְלֵ֜הוּ וּ⁠מִקְנֵיָ֨הוּ וְ⁠עֹבֵ֥ד אֱדֹ֛ם וִֽ⁠יעִיאֵ֖ל הַ⁠שֹּׁעֲרִֽים׃","wĕ⁠ʻimá̇⁠he֖m ʼàẖéy⁠he֣m ha⁠mi̇şĕ̌ni֑ym zĕkarĕyá֡hẇ bé̇֡n wĕ⁠yaֽʻàziyʼé֡l ẇ⁠şĕ̌mֽiyrám֡wòţ wi⁠yẖiyʼé֣l ׀ wĕ⁠ʻuni̇֡y ʼèliyʼá֡b ẇ⁠bĕnáyá֡hẇ ẇ⁠maֽʻàşé̂yá֡hẇ ẇ⁠maţi̇ţĕyáhẇ֩ we⁠ʼèli֨ypĕlé֜hẇ ẇ⁠miqĕnéyá֨hẇ wĕ⁠ʻòbé֥d ʼèdò֛m wiֽ⁠yʻiyʼé֖l ha⁠şò̇̌ʻàriֽym׃"],[15,19,"וְ⁠הַ⁠מְשֹׁ֣רְרִ֔ים הֵימָ֥ן אָסָ֖ף וְ⁠אֵיתָ֑ן בִּ⁠מְצִלְתַּ֥יִם נְחֹ֖שֶׁת לְ⁠הַשְׁמִֽיעַ׃","wĕ⁠ha⁠mĕşò֣̌rĕri֔ym héymá֥n ʼásá֖p wĕ⁠ʼéyţá֑n bi̇⁠mĕẕilĕţȧ֥yim nĕẖò֖şěţ lĕ⁠haşĕ̌miֽyʻa׃"],[15,20,"וּ⁠זְכַרְיָ֨ה וַ⁠עֲזִיאֵ֜ל וּ⁠שְׁמִֽירָמ֤וֹת וִֽ⁠יחִיאֵל֙ וְ⁠עֻנִּ֣י וֶֽ⁠אֱלִיאָ֔ב וּ⁠מַעֲשֵׂיָ֖הוּ וּ⁠בְנָיָ֑הוּ בִּ⁠נְבָלִ֖ים עַל־עֲלָמֽוֹת׃","ẇ⁠zĕkarĕyá֨h wa⁠ʻàziyʼé֜l ẇ⁠şĕ̌miֽyrám֤wòţ wiֽ⁠yẖiyʼél֙ wĕ⁠ʻuni֣̇y wֽe⁠ʼèliyʼá֔b ẇ⁠maʻàşé̂yá֖hẇ ẇ⁠bĕnáyá֑hẇ bi̇⁠nĕbáli֖ym ʻal-ʻàlámֽwòţ׃"],[15,21,"וּ⁠מַתִּתְיָ֣הוּ וֶ⁠אֱלִֽיפְלֵ֗הוּ וּ⁠מִקְנֵיָ֨הוּ֙ וְ⁠עֹבֵ֣ד אֱדֹ֔ם וִֽ⁠יעִיאֵ֖ל וַ⁠עֲזַזְיָ֑הוּ בְּ⁠כִנֹּר֥וֹת עַל־הַ⁠שְּׁמִינִ֖ית לְ⁠נַצֵּֽחַ׃","ẇ⁠maţi̇ţĕyá֣hẇ we⁠ʼèliֽypĕlé֗hẇ ẇ⁠miqĕnéyá֨hẇ֙ wĕ⁠ʻòbé֣d ʼèdò֔m wiֽ⁠yʻiyʼé֖l wa⁠ʻàzazĕyá֑hẇ bĕ̇⁠kinò̇r֥wòţ ʻal-ha⁠şĕ̇̌miyni֖yţ lĕ⁠naẕéֽ̇ẖa׃"],[15,22,"וּ⁠כְנַנְיָ֥הוּ שַֽׂר־הַ⁠לְוִיִּ֖ם בְּ⁠מַשָּׂ֑א יָסֹר֙ בַּ⁠מַּשָּׂ֔א כִּ֥י מֵבִ֖ין הֽוּא׃","ẇ⁠kĕnanĕyá֥hẇ şâֽr-ha⁠lĕwiyi֖̇m bĕ̇⁠maşá֑̇̂ʼ yásòr֙ bȧ⁠mȧşá̇̂֔ʼ ki֥̇y mébi֖yn hֽẇʼ׃"],[15,23,"וּ⁠בֶֽרֶכְיָה֙ וְ⁠אֶלְקָנָ֔ה שֹׁעֲרִ֖ים לָ⁠אָרֽוֹן׃","ẇ⁠beֽrekĕyáh֙ wĕ⁠ʼelĕqáná֔h şò̌ʻàri֖ym lá⁠ʼárֽwòn׃"],[15,24,"וּ⁠שְׁבַנְיָ֡הוּ וְ⁠יֽוֹשָׁפָ֡ט וּ⁠נְתַנְאֵ֡ל וַ⁠עֲמָשַׂ֡י וּ֠⁠זְכַרְיָהוּ וּ⁠בְנָיָ֤הוּ וֶֽ⁠אֱלִיעֶ֨זֶר֙ הַ⁠כֹּ֣הֲנִ֔ים מחצצרים בַּ⁠חֲצֹ֣צְר֔וֹת לִ⁠פְנֵ֖י אֲר֣וֹן הָֽ⁠אֱלֹהִ֑ים וְ⁠עֹבֵ֤ד אֱדֹם֙ וִֽ⁠יחִיָּ֔ה שֹׁעֲרִ֖ים לָ⁠אָרֽוֹן׃","ẇ⁠şĕ̌banĕyá֡hẇ wĕ⁠yֽwòşá̌pá֡t ẇ⁠nĕţanĕʼé֡l wa⁠ʻàmáşâ֡y ẇ֠⁠zĕkarĕyáhẇ ẇ⁠bĕnáyá֤hẇ wֽe⁠ʼèliyʻe֨zer֙ ha⁠kò֣̇hàni֔ym mẖẕẕrym bȧ⁠ẖàẕò֣ẕĕr֔wòţ li⁠pĕné֖y ʼàr֣wòn hֽá⁠ʼèlòhi֑ym wĕ⁠ʻòbé֤d ʼèdòm֙ wiֽ⁠yẖiyá̇֔h şò̌ʻàri֖ym lá⁠ʼárֽwòn׃"],[15,25,"וַ⁠יְהִ֥י דָוִ֛יד וְ⁠זִקְנֵ֥י יִשְׂרָאֵ֖ל וְ⁠שָׂרֵ֣י הָ⁠אֲלָפִ֑ים הַ⁠הֹֽלְכִ֗ים לְֽ⁠הַעֲל֞וֹת אֶת־אֲר֧וֹן בְּרִית־יְהוָ֛ה מִן־בֵּ֥ית עֹבֵֽד־אֱדֹ֖ם בְּ⁠שִׂמְחָֽה׃ס","wa⁠yĕhi֥y dáwi֛yd wĕ⁠ziqĕné֥y yişĕ̂ráʼé֖l wĕ⁠şá̂ré֣y há⁠ʼàlápi֑ym ha⁠hòֽlĕki֗ym lĕֽ⁠haʻàl֞wòţ ʼeţ-ʼàr֧wòn bĕ̇riyţ-yĕhwá֛h min-bé֥̇yţ ʻòbéֽd-ʼèdò֖m bĕ̇⁠şîmĕẖáֽh׃s"],[15,26,"וַֽ⁠יְהִי֙ בֶּ⁠עְזֹ֣ר הָֽ⁠אֱלֹהִ֔ים אֶ֨ת־הַ⁠לְוִיִּ֔ם נֹשְׂאֵ֖י אֲר֣וֹן בְּרִית־יְהוָ֑ה וַ⁠יִּזְבְּח֥וּ שִׁבְעָֽה־פָרִ֖ים וְ⁠שִׁבְעָ֥ה אֵילִֽים׃","wֽa⁠yĕhiy֙ bė⁠ʻĕzò֣r hֽá⁠ʼèlòhi֔ym ʼe֨ţ-ha⁠lĕwiyi̇֔m nòşĕ̂ʼé֖y ʼàr֣wòn bĕ̇riyţ-yĕhwá֑h wa⁠yi̇zĕbĕ̇ẖ֥ẇ şǐbĕʻáֽh-pári֖ym wĕ⁠şǐbĕʻá֥h ʼéyliֽym׃"],[15,27,"וְ⁠דָוִ֞יד מְכֻרְבָּ֣ל ׀ בִּ⁠מְעִ֣יל בּ֗וּץ וְ⁠כָל־הַ⁠לְוִיִּם֙ הַ⁠נֹּשְׂאִ֣ים אֶת־הָ⁠אָר֔וֹן וְ⁠הַ⁠מְשֹׁ֣רְרִ֔ים וּ⁠כְנַנְיָ֛ה הַ⁠שַּׂ֥ר הַ⁠מַּשָּׂ֖א הַ⁠מְשֹֽׁרְרִ֑ים וְ⁠עַל־דָּוִ֖יד אֵפ֥וֹד בָּֽד׃","wĕ⁠dáwi֞yd mĕkurĕbá֣̇l ׀ bi̇⁠mĕʻi֣yl ḃ֗ẇẕ wĕ⁠kál-ha⁠lĕwiyi̇m֙ ha⁠nò̇şĕ̂ʼi֣ym ʼeţ-há⁠ʼár֔wòn wĕ⁠ha⁠mĕşò֣̌rĕri֔ym ẇ⁠kĕnanĕyá֛h ha⁠şȧ֥̂r ha⁠mȧşá֖̇̂ʼ ha⁠mĕşòֽ̌rĕri֑ym wĕ⁠ʻal-dá̇wi֖yd ʼép֥wòd báֽ̇d׃"],[15,28,"וְ⁠כָל־יִשְׂרָאֵ֗ל מַעֲלִים֙ אֶת־אֲר֣וֹן בְּרִית־יְהוָ֔ה בִּ⁠תְרוּעָה֙ וּ⁠בְ⁠ק֣וֹל שׁוֹפָ֔ר וּ⁠בַ⁠חֲצֹצְר֖וֹת וּ⁠בִ⁠מְצִלְתָּ֑יִם מַשְׁמִעִ֕ים בִּ⁠נְבָלִ֖ים וְ⁠כִנֹּרֽוֹת׃","wĕ⁠kál-yişĕ̂ráʼé֗l maʻàliym֙ ʼeţ-ʼàr֣wòn bĕ̇riyţ-yĕhwá֔h bi̇⁠ţĕrẇʻáh֙ ẇ⁠bĕ⁠q֣wòl ş̌wòpá֔r ẇ⁠ba⁠ẖàẕòẕĕr֖wòţ ẇ⁠bi⁠mĕẕilĕţá֑̇yim maşĕ̌miʻi֕ym bi̇⁠nĕbáli֖ym wĕ⁠kinò̇rֽwòţ׃"],[15,29,"וַ⁠יְהִ֗י אֲרוֹן֙ בְּרִ֣ית יְהוָ֔ה בָּ֖א עַד־עִ֣יר דָּוִ֑יד וּ⁠מִיכַ֨ל בַּת־שָׁא֜וּל נִשְׁקְפָ֣ה ׀ בְּעַ֣ד הַ⁠חַלּ֗וֹן וַ⁠תֵּ֨רֶא אֶת־הַ⁠מֶּ֤לֶךְ דָּוִיד֙ מְרַקֵּ֣ד וּ⁠מְשַׂחֵ֔ק וַ⁠תִּ֥בֶז ל֖⁠וֹ בְּ⁠לִבָּֽ⁠הּ׃פ","wa⁠yĕhi֗y ʼàrwòn֙ bĕ̇ri֣yţ yĕhwá֔h bá֖̇ʼ ʻad-ʻi֣yr dá̇wi֑yd ẇ⁠miyka֨l bȧţ-şá̌ʼ֜ẇl nişĕ̌qĕpá֣h ׀ bĕ̇ʻa֣d ha⁠ẖal̇֗wòn wa⁠ţé̇֨reʼ ʼeţ-ha⁠mė֤lekĕ dá̇wiyd֙ mĕraqé֣̇d ẇ⁠mĕşâẖé֔q wa⁠ţi֥̇bez l֖⁠wò bĕ̇⁠libáֽ̇⁠ḣ׃p"],[16,1,"וַ⁠יָּבִ֨יאוּ֙ אֶת־אֲר֣וֹן הָֽ⁠אֱלֹהִ֔ים וַ⁠יַּצִּ֣יגוּ אֹת֔⁠וֹ בְּ⁠ת֣וֹךְ הָ⁠אֹ֔הֶל אֲשֶׁ֥ר נָֽטָה־ל֖⁠וֹ דָּוִ֑יד וַ⁠יַּקְרִ֛יבוּ עֹל֥וֹת וּ⁠שְׁלָמִ֖ים לִ⁠פְנֵ֥י הָ⁠אֱלֹהִֽים׃","wa⁠yá̇bi֨yʼẇ֙ ʼeţ-ʼàr֣wòn hֽá⁠ʼèlòhi֔ym wa⁠yȧẕi֣̇ygẇ ʼòţ֔⁠wò bĕ̇⁠ţ֣wòkĕ há⁠ʼò֔hel ʼàşě֥r náֽtáh-l֖⁠wò dá̇wi֑yd wa⁠yȧqĕri֛ybẇ ʻòl֥wòţ ẇ⁠şĕ̌lámi֖ym li⁠pĕné֥y há⁠ʼèlòhiֽym׃"],[16,2,"וַ⁠יְכַ֣ל דָּוִ֔יד מֵ⁠הַעֲל֥וֹת הָ⁠עֹלָ֖ה וְ⁠הַ⁠שְּׁלָמִ֑ים וַ⁠יְבָ֥רֶךְ אֶת־הָ⁠עָ֖ם בְּ⁠שֵׁ֥ם יְהוָֽה׃","wa⁠yĕka֣l dá̇wi֔yd mé⁠haʻàl֥wòţ há⁠ʻòlá֖h wĕ⁠ha⁠şĕ̇̌lámi֑ym wa⁠yĕbá֥rekĕ ʼeţ-há⁠ʻá֖m bĕ̇⁠şé֥̌m yĕhwáֽh׃"],[16,3,"וַ⁠יְחַלֵּק֙ לְ⁠כָל־אִ֣ישׁ יִשְׂרָאֵ֔ל מֵ⁠אִ֖ישׁ וְ⁠עַד־אִשָּׁ֑ה לְ⁠אִישׁ֙ כִּכַּר־לֶ֔חֶם וְ⁠אֶשְׁפָּ֖ר וַ⁠אֲשִׁישָֽׁה׃","wa⁠yĕẖalé̇q֙ lĕ⁠kál-ʼi֣yş̌ yişĕ̂ráʼé֔l mé⁠ʼi֖yş̌ wĕ⁠ʻad-ʼişá֑̇̌h lĕ⁠ʼiyş̌֙ ki̇kȧr-le֔ẖem wĕ⁠ʼeşĕ̌pá֖̇r wa⁠ʼàşǐyşáֽ̌h׃"],[16,4,"וַ⁠יִּתֵּ֞ן לִ⁠פְנֵ֨י אֲר֧וֹן יְהוָ֛ה מִן־הַ⁠לְוִיִּ֖ם מְשָׁרְתִ֑ים וּ⁠לְ⁠הַזְכִּיר֙ וּ⁠לְ⁠הוֹד֣וֹת וּ⁠לְ⁠הַלֵּ֔ל לַ⁠יהוָ֖ה אֱלֹהֵ֥י יִשְׂרָאֵֽל׃פ","wa⁠yi̇ţé̇֞n li⁠pĕné֨y ʼàr֧wòn yĕhwá֛h min-ha⁠lĕwiyi֖̇m mĕşá̌rĕţi֑ym ẇ⁠lĕ⁠hazĕki̇yr֙ ẇ⁠lĕ⁠hwòd֣wòţ ẇ⁠lĕ⁠halé̇֔l la⁠yhwá֖h ʼèlòhé֥y yişĕ̂ráʼéֽl׃p"],[16,5,"אָסָ֥ף הָ⁠רֹ֖אשׁ וּ⁠מִשְׁנֵ֣⁠הוּ זְכַרְיָ֑ה יְעִיאֵ֡ל וּ⁠שְׁמִֽירָמ֡וֹת וִֽ⁠יחִיאֵ֡ל וּ⁠מַתִּתְיָ֡ה וֶ⁠אֱלִיאָ֡ב וּ⁠בְנָיָהוּ֩ וְ⁠עֹבֵ֨ד אֱדֹ֜ם וִֽ⁠יעִיאֵ֗ל בִּ⁠כְלֵ֤י נְבָלִים֙ וּ⁠בְ⁠כִנֹּר֔וֹת וְ⁠אָסָ֖ף בַּֽ⁠מְצִלְתַּ֥יִם מַשְׁמִֽיעַ׃","ʼásá֥p há⁠rò֖ʼş̌ ẇ⁠mişĕ̌né֣⁠hẇ zĕkarĕyá֑h yĕʻiyʼé֡l ẇ⁠şĕ̌miֽyrám֡wòţ wiֽ⁠yẖiyʼé֡l ẇ⁠maţi̇ţĕyá֡h we⁠ʼèliyʼá֡b ẇ⁠bĕnáyáhẇ֩ wĕ⁠ʻòbé֨d ʼèdò֜m wֽi⁠yʻiyʼé֗l bi̇⁠kĕlé֤y nĕbáliym֙ ẇ⁠bĕ⁠kinò̇r֔wòţ wĕ⁠ʼásá֖p bȧֽ⁠mĕẕilĕţȧ֥yim maşĕ̌miֽyʻa׃"],[16,6,"וּ⁠בְנָיָ֥הוּ וְ⁠יַחֲזִיאֵ֖ל הַ⁠כֹּהֲנִ֑ים בַּ⁠חֲצֹצְר֣וֹת תָּמִ֔יד לִ⁠פְנֵ֖י אֲר֥וֹן בְּרִית־הָ⁠אֱלֹהִֽים׃","ẇ⁠bĕnáyá֥hẇ wĕ⁠yaẖàziyʼé֖l ha⁠kò̇hàni֑ym bȧ⁠ẖàẕòẕĕr֣wòţ ţá̇mi֔yd li⁠pĕné֖y ʼàr֥wòn bĕ̇riyţ-há⁠ʼèlòhiֽym׃"],[16,7,"בַּ⁠יּ֣וֹם הַ⁠ה֗וּא אָ֣ז נָתַ֤ן דָּוִיד֙ בָּ⁠רֹ֔אשׁ לְ⁠הֹד֖וֹת לַ⁠יהוָ֑ה בְּ⁠יַד־אָסָ֖ף וְ⁠אֶחָֽי⁠ו׃פ","bȧ⁠ẏ֣wòm ha⁠h֗ẇʼ ʼá֣z náţa֤n dá̇wiyd֙ bá̇⁠rò֔ʼş̌ lĕ⁠hòd֖wòţ la⁠yhwá֑h bĕ̇⁠yad-ʼásá֖p wĕ⁠ʼeẖáֽy⁠w׃p"],[16,8,"הוֹד֤וּ לַֽ⁠יהוָה֙ קִרְא֣וּ בִ⁠שְׁמ֔⁠וֹ הוֹדִ֥יעוּ בָ⁠עַמִּ֖ים עֲלִילֹתָֽי⁠ו׃","hwòd֤ẇ laֽ⁠yhwáh֙ qirĕʼ֣ẇ bi⁠şĕ̌m֔⁠wò hwòdi֥yʻẇ bá⁠ʻami֖̇ym ʻàliylòţáֽy⁠w׃"],[16,9,"שִׁ֤ירוּ ל⁠וֹ֙ זַמְּרוּ־ל֔⁠וֹ שִׂ֖יחוּ בְּ⁠כָל־נִפְלְאֹתָֽי⁠ו׃","şǐ֤yrẇ l⁠wò֙ zamĕ̇rẇ-l֔⁠wò şî֖yẖẇ bĕ̇⁠kál-nipĕlĕʼòţáֽy⁠w׃"],[16,10,"הִֽתְהַֽלְלוּ֙ בְּ⁠שֵׁ֣ם קָדְשׁ֔⁠וֹ יִשְׂמַ֕ח לֵ֖ב מְבַקְשֵׁ֥י יְהוָֽה׃","hiֽţĕhֽalĕlẇ֙ bĕ̇⁠şé֣̌m qádĕş̌֔⁠wò yişĕ̂ma֕ẖ lé֖b mĕbaqĕşé֥̌y yĕhwáֽh׃"],[16,11,"דִּרְשׁ֤וּ יְהוָה֙ וְ⁠עֻזּ֔⁠וֹ בַּקְּשׁ֥וּ פָנָ֖י⁠ו תָּמִֽיד׃","di̇rĕş֤̌ẇ yĕhwáh֙ wĕ⁠ʻuż֔⁠wò bȧqĕ̇ş֥̌ẇ páná֖y⁠w ţá̇miֽyd׃"],[16,12,"זִכְר֗וּ נִפְלְאֹתָי⁠ו֙ אֲשֶׁ֣ר עָשָׂ֔ה מֹפְתָ֖י⁠ו וּ⁠מִשְׁפְּטֵי־פִֽי⁠הוּ׃","zikĕr֗ẇ nipĕlĕʼòţáy⁠w֙ ʼàşě֣r ʻáşá̂֔h mòpĕţá֖y⁠w ẇ⁠mişĕ̌pĕ̇téy-piֽy⁠hẇ׃"],[16,13,"זֶ֚רַע יִשְׂרָאֵ֣ל עַבְדּ֔⁠וֹ בְּנֵ֥י יַעֲקֹ֖ב בְּחִירָֽי⁠ו׃","ze֚raʻ yişĕ̂ráʼé֣l ʻabĕḋ֔⁠wò bĕ̇né֥y yaʻàqò֖b bĕ̇ẖiyráֽy⁠w׃"],[16,14,"ה֚וּא יְהוָ֣ה אֱלֹהֵ֔י⁠נוּ בְּ⁠כָל־הָ⁠אָ֖רֶץ מִשְׁפָּטָֽי⁠ו׃","h֚ẇʼ yĕhwá֣h ʼèlòhé֔y⁠nẇ bĕ̇⁠kál-há⁠ʼá֖reẕ mişĕ̌pá̇táֽy⁠w׃"],[16,15,"זִכְר֤וּ לְ⁠עוֹלָם֙ בְּרִית֔⁠וֹ דָּבָ֥ר צִוָּ֖ה לְ⁠אֶ֥לֶף דּֽוֹר׃","zikĕr֤ẇ lĕ⁠ʻwòlám֙ bĕ̇riyţ֔⁠wò dá̇bá֥r ẕiwá֖̇h lĕ⁠ʼe֥lep ḋֽwòr׃"],[16,16,"אֲשֶׁ֤ר כָּרַת֙ אֶת־אַבְרָהָ֔ם וּ⁠שְׁבוּעָת֖⁠וֹ לְ⁠יִצְחָֽק׃","ʼàşě֤r ká̇raţ֙ ʼeţ-ʼabĕráhá֔m ẇ⁠şĕ̌bẇʻáţ֖⁠wò lĕ⁠yiẕĕẖáֽq׃"],[16,17,"וַ⁠יַּעֲמִידֶ֤⁠הָ לְ⁠יַעֲקֹב֙ לְ⁠חֹ֔ק לְ⁠יִשְׂרָאֵ֖ל בְּרִ֥ית עוֹלָֽם׃","wa⁠yȧʻàmiyde֤⁠há lĕ⁠yaʻàqòb֙ lĕ⁠ẖò֔q lĕ⁠yişĕ̂ráʼé֖l bĕ̇ri֥yţ ʻwòláֽm׃"],[16,18,"לֵ⁠אמֹ֗ר לְ⁠ךָ֙ אֶתֵּ֣ן אֶֽרֶץ־כְּנָ֔עַן חֶ֖בֶל נַחֲלַתְ⁠כֶֽם׃","lé⁠ʼmò֗r lĕ⁠ká֙ ʼeţé֣̇n ʼeֽreẕ-kĕ̇ná֔ʻan ẖe֖bel naẖàlaţĕ⁠keֽm׃"],[16,19,"בִּֽ⁠הְיֽוֹתְ⁠כֶם֙ מְתֵ֣י מִסְפָּ֔ר כִּ⁠מְעַ֖ט וְ⁠גָרִ֥ים בָּֽ⁠הּ׃","biֽ̇⁠hĕyֽwòţĕ⁠kem֙ mĕţé֣y misĕpá̇֔r ki̇⁠mĕʻa֖t wĕ⁠gári֥ym báֽ̇⁠ḣ׃"],[16,20,"וַ⁠יִּֽתְהַלְּכוּ֙ מִ⁠גּ֣וֹי אֶל־גּ֔וֹי וּ⁠מִ⁠מַּמְלָכָ֖ה אֶל־עַ֥ם אַחֵֽר׃","wa⁠yiֽ̇ţĕhalĕ̇kẇ֙ mi⁠ġ֣wòy ʼel-ġ֔wòy ẇ⁠mi⁠mȧmĕláká֖h ʼel-ʻa֥m ʼaẖéֽr׃"],[16,21,"לֹא־הִנִּ֤יחַ לְ⁠אִישׁ֙ לְ⁠עָשְׁקָ֔⁠ם וַ⁠יּ֥וֹכַח עֲלֵי⁠הֶ֖ם מְלָכִֽים׃","lòʼ-hini֤̇yẖa lĕ⁠ʼiyş̌֙ lĕ⁠ʻáşĕ̌qá֔⁠m wa⁠ẏ֥wòkaẖ ʻàléy⁠he֖m mĕlákiֽym׃"],[16,22,"אַֽל־תִּגְּעוּ֙ בִּ⁠מְשִׁיחָ֔⁠י וּ⁠בִ⁠נְבִיאַ֖⁠י אַל־תָּרֵֽעוּ׃פ","ʼaֽl-ţi̇gĕ̇ʻẇ֙ bi̇⁠mĕşǐyẖá֔⁠y ẇ⁠bi⁠nĕbiyʼa֖⁠y ʼal-ţá̇réֽʻẇ׃p"],[16,23,"שִׁ֤ירוּ לַֽ⁠יהוָה֙ כָּל־הָ⁠אָ֔רֶץ בַּשְּׂר֥וּ מִ⁠יּֽוֹם־אֶל־י֖וֹם יְשׁוּעָתֽ⁠וֹ׃","şǐ֤yrẇ laֽ⁠yhwáh֙ ká̇l-há⁠ʼá֔reẕ bȧşĕ̇̂r֥ẇ mi⁠ẏֽwòm-ʼel-y֖wòm yĕş̌ẇʻáţֽ⁠wò׃"],[16,24,"סַפְּר֤וּ בַ⁠גּוֹיִם֙ אֶת־כְּבוֹד֔⁠וֹ בְּ⁠כָל־הָ⁠עַמִּ֖ים נִפְלְאֹתָֽי⁠ו׃","sapĕ̇r֤ẇ ba⁠ġwòyim֙ ʼeţ-kĕ̇bwòd֔⁠wò bĕ̇⁠kál-há⁠ʻami֖̇ym nipĕlĕʼòţáֽy⁠w׃"],[16,25,"כִּי֩ גָד֨וֹל יְהוָ֤ה וּ⁠מְהֻלָּל֙ מְאֹ֔ד וְ⁠נוֹרָ֥א ה֖וּא עַל־כָּל־אֱלֹהִֽים׃","ki̇y֩ gád֨wòl yĕhwá֤h ẇ⁠mĕhulá̇l֙ mĕʼò֔d wĕ⁠nwòrá֥ʼ h֖ẇʼ ʻal-ká̇l-ʼèlòhiֽym׃"],[16,26,"כִּ֠י כָּל־אֱלֹהֵ֤י הָ⁠עַמִּים֙ אֱלִילִ֔ים וַ⁠יהוָ֖ה שָׁמַ֥יִם עָשָֽׂה׃","ki̇֠y ká̇l-ʼèlòhé֤y há⁠ʻami̇ym֙ ʼèliyli֔ym wa⁠yhwá֖h şá̌ma֥yim ʻáşáֽ̂h׃"],[16,27,"ה֤וֹד וְ⁠הָדָר֙ לְ⁠פָנָ֔י⁠ו עֹ֥ז וְ⁠חֶדְוָ֖ה בִּ⁠מְקֹמֽ⁠וֹ׃","h֤wòd wĕ⁠hádár֙ lĕ⁠páná֔y⁠w ʻò֥z wĕ⁠ẖedĕwá֖h bi̇⁠mĕqòmֽ⁠wò׃"],[16,28,"הָב֤וּ לַֽ⁠יהוָה֙ מִשְׁפְּח֣וֹת עַמִּ֔ים הָב֥וּ לַ⁠יהוָ֖ה כָּב֥וֹד וָ⁠עֹֽז׃","háb֤ẇ laֽ⁠yhwáh֙ mişĕ̌pĕ̇ẖ֣wòţ ʻami̇֔ym háb֥ẇ la⁠yhwá֖h ká̇b֥wòd wá⁠ʻòֽz׃"],[16,29,"הָב֥וּ לַ⁠יהוָ֖ה כְּב֣וֹד שְׁמ֑⁠וֹ שְׂא֤וּ מִנְחָה֙ וּ⁠בֹ֣אוּ לְ⁠פָנָ֔י⁠ו הִשְׁתַּחֲו֥וּ לַ⁠יהוָ֖ה בְּ⁠הַדְרַת־קֹֽדֶשׁ׃","háb֥ẇ la⁠yhwá֖h kĕ̇b֣wòd şĕ̌m֑⁠wò şĕ̂ʼ֤ẇ minĕẖáh֙ ẇ⁠bò֣ʼẇ lĕ⁠páná֔y⁠w hişĕ̌ţȧẖàw֥ẇ la⁠yhwá֖h bĕ̇⁠hadĕraţ-qòֽdeş̌׃"],[16,30,"חִ֤ילוּ מִ⁠לְּ⁠פָנָי⁠ו֙ כָּל־הָ⁠אָ֔רֶץ אַף־תִּכּ֥וֹן תֵּבֵ֖ל בַּל־תִּמּֽוֹט׃","ẖi֤ylẇ mi⁠lĕ̇⁠pánáy⁠w֙ ká̇l-há⁠ʼá֔reẕ ʼap-ţi̇k֥̇wòn ţé̇bé֖l bȧl-ţi̇ṁֽwòt׃"],[16,31,"יִשְׂמְח֤וּ הַ⁠שָּׁמַ֨יִם֙ וְ⁠תָגֵ֣ל הָ⁠אָ֔רֶץ וְ⁠יֹאמְר֥וּ בַ⁠גּוֹיִ֖ם יְהוָ֥ה מָלָֽךְ׃","yişĕ̂mĕẖ֤ẇ ha⁠şá̇̌ma֨yim֙ wĕ⁠ţágé֣l há⁠ʼá֔reẕ wĕ⁠yòʼmĕr֥ẇ ba⁠ġwòyi֖m yĕhwá֥h máláֽkĕ׃"],[16,32,"יִרְעַ֤ם הַ⁠יָּם֙ וּ⁠מְלוֹא֔⁠וֹ יַעֲלֹ֥ץ הַ⁠שָּׂדֶ֖ה וְ⁠כָל־אֲשֶׁר־בּֽ⁠וֹ׃","yirĕʻa֤m ha⁠yá̇m֙ ẇ⁠mĕlwòʼ֔⁠wò yaʻàlò֥ẕ ha⁠şá̇̂de֖h wĕ⁠kál-ʼàşěr-ḃֽ⁠wò׃"],[16,33,"אָ֥ז יְרַנְּנ֖וּ עֲצֵ֣י הַ⁠יָּ֑עַר מִ⁠לִּ⁠פְנֵ֣י יְהוָ֔ה כִּי־בָ֖א לִ⁠שְׁפּ֥וֹט אֶת־הָ⁠אָֽרֶץ׃","ʼá֥z yĕranĕ̇n֖ẇ ʻàẕé֣y ha⁠yá֑̇ʻar mi⁠li̇⁠pĕné֣y yĕhwá֔h ki̇y-bá֖ʼ li⁠şĕ̌ṗ֥wòt ʼeţ-há⁠ʼáֽreẕ׃"],[16,34,"הוֹד֤וּ לַ⁠יהוָה֙ כִּ֣י ט֔וֹב כִּ֥י לְ⁠עוֹלָ֖ם חַסְדּֽ⁠וֹ׃","hwòd֤ẇ la⁠yhwáh֙ ki֣̇y t֔wòb ki֥̇y lĕ⁠ʻwòlá֖m ẖasĕḋֽ⁠wò׃"],[16,35,"וְ⁠אִמְר֕וּ הוֹשִׁיעֵ֨⁠נוּ֙ אֱלֹהֵ֣י יִשְׁעֵ֔⁠נוּ וְ⁠קַבְּצֵ֥⁠נוּ וְ⁠הַצִּילֵ֖⁠נוּ מִן־הַ⁠גּוֹיִ֑ם לְ⁠הֹדוֹת֙ לְ⁠שֵׁ֣ם קָדְשֶׁ֔⁠ךָ לְ⁠הִשְׁתַּבֵּ֖חַ בִּ⁠תְהִלָּתֶֽ⁠ךָ׃","wĕ⁠ʼimĕr֕ẇ hwòşǐyʻé֨⁠nẇ֙ ʼèlòhé֣y yişĕ̌ʻé֔⁠nẇ wĕ⁠qabĕ̇ẕé֥⁠nẇ wĕ⁠haẕi̇ylé֖⁠nẇ min-ha⁠ġwòyi֑m lĕ⁠hòdwòţ֙ lĕ⁠şé֣̌m qádĕşě֔⁠ká lĕ⁠hişĕ̌ţȧbé֖̇ẖa bi̇⁠ţĕhilá̇ţeֽ⁠ká׃"],[16,36,"בָּר֤וּךְ יְהוָה֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל מִן־הָ⁠עוֹלָ֖ם וְ⁠עַ֣ד הָ⁠עֹלָ֑ם וַ⁠יֹּאמְר֤וּ כָל־הָ⁠עָם֙ אָמֵ֔ן וְ⁠הַלֵּ֖ל לַֽ⁠יהוָֽה׃פ","bá̇r֤ẇkĕ yĕhwáh֙ ʼèlòhé֣y yişĕ̂ráʼé֔l min-há⁠ʻwòlá֖m wĕ⁠ʻa֣d há⁠ʻòlá֑m wa⁠yò̇ʼmĕr֤ẇ kál-há⁠ʻám֙ ʼámé֔n wĕ⁠halé֖̇l laֽ⁠yhwáֽh׃p"],[16,37,"וַ⁠יַּֽעֲזָב־שָׁ֗ם לִ⁠פְנֵי֙ אֲר֣וֹן בְּרִית־יְהוָ֔ה לְ⁠אָסָ֖ף וּ⁠לְ⁠אֶחָ֑י⁠ו לְ⁠שָׁרֵ֞ת לִ⁠פְנֵ֧י הָ⁠אָר֛וֹן תָּמִ֖יד לִ⁠דְבַר־י֥וֹם בְּ⁠יוֹמֽ⁠וֹ׃","wa⁠yȧֽʻàzáb-şá̌֗m li⁠pĕnéy֙ ʼàr֣wòn bĕ̇riyţ-yĕhwá֔h lĕ⁠ʼásá֖p ẇ⁠lĕ⁠ʼeẖá֑y⁠w lĕ⁠şá̌ré֞ţ li⁠pĕné֧y há⁠ʼár֛wòn ţá̇mi֖yd li⁠dĕbar-y֥wòm bĕ̇⁠ywòmֽ⁠wò׃"],[16,38,"וְ⁠עֹבֵ֥ד אֱדֹ֛ם וַ⁠אֲחֵי⁠הֶ֖ם שִׁשִּׁ֣ים וּ⁠שְׁמוֹנָ֑ה וְ⁠עֹבֵ֨ד אֱדֹ֧ם בֶּן־יְדִית֛וּן וְ⁠חֹסָ֖ה לְ⁠שֹׁעֲרִֽים׃","wĕ⁠ʻòbé֥d ʼèdò֛m wa⁠ʼàẖéy⁠he֖m şǐşi֣̇̌ym ẇ⁠şĕ̌mwòná֑h wĕ⁠ʻòbé֨d ʼèdò֧m bėn-yĕdiyţ֛ẇn wĕ⁠ẖòsá֖h lĕ⁠şò̌ʻàriֽym׃"],[16,39,"וְ⁠אֵ֣ת ׀ צָד֣וֹק הַ⁠כֹּהֵ֗ן וְ⁠אֶחָי⁠ו֙ הַ⁠כֹּ֣הֲנִ֔ים לִ⁠פְנֵ֖י מִשְׁכַּ֣ן יְהוָ֑ה בַּ⁠בָּמָ֖ה אֲשֶׁ֥ר בְּ⁠גִבְעֽוֹן׃","wĕ⁠ʼé֣ţ ׀ ẕád֣wòq ha⁠kò̇hé֗n wĕ⁠ʼeẖáy⁠w֙ ha⁠kò֣̇hàni֔ym li⁠pĕné֖y mişĕ̌kȧ֣n yĕhwá֑h bȧ⁠bá̇má֖h ʼàşě֥r bĕ̇⁠gibĕʻֽwòn׃"],[16,40,"לְֽ⁠הַעֲלוֹת֩ עֹל֨וֹת לַ⁠יהוָ֜ה עַל־מִזְבַּ֧ח הָ⁠עֹלָ֛ה תָּמִ֖יד לַ⁠בֹּ֣קֶר וְ⁠לָ⁠עָ֑רֶב וּ⁠לְ⁠כָל־הַ⁠כָּתוּב֙ בְּ⁠תוֹרַ֣ת יְהוָ֔ה אֲשֶׁ֥ר צִוָּ֖ה עַל־יִשְׂרָאֵֽל׃","lֽĕ⁠haʻàlwòţ֩ ʻòl֨wòţ la⁠yhwá֜h ʻal-mizĕbȧ֧ẖ há⁠ʻòlá֛h ţá̇mi֖yd la⁠bò֣̇qer wĕ⁠lá⁠ʻá֑reb ẇ⁠lĕ⁠kál-ha⁠ká̇ţẇb֙ bĕ̇⁠ţwòra֣ţ yĕhwá֔h ʼàşě֥r ẕiwá֖̇h ʻal-yişĕ̂ráʼéֽl׃"],[16,41,"וְ⁠עִמָּ⁠הֶם֙ הֵימָ֣ן וִֽ⁠ידוּת֔וּן וּ⁠שְׁאָר֙ הַ⁠בְּרוּרִ֔ים אֲשֶׁ֥ר נִקְּב֖וּ בְּ⁠שֵׁמ֑וֹת לְ⁠הֹדוֹת֙ לַֽ⁠יהוָ֔ה כִּ֥י לְ⁠עוֹלָ֖ם חַסְדּֽ⁠וֹ׃","wĕ⁠ʻimá̇⁠hem֙ héymá֣n wiֽ⁠ydẇţ֔ẇn ẇ⁠şĕ̌ʼár֙ ha⁠bĕ̇rẇri֔ym ʼàşě֥r niqĕ̇b֖ẇ bĕ̇⁠şé̌m֑wòţ lĕ⁠hòdwòţ֙ laֽ⁠yhwá֔h ki֥̇y lĕ⁠ʻwòlá֖m ẖasĕḋֽ⁠wò׃"],[16,42,"וְ⁠עִמָּ⁠הֶם֩ הֵימָ֨ן וִֽ⁠ידוּת֜וּן חֲצֹצְר֤וֹת וּ⁠מְצִלְתַּ֨יִם֙ לְ⁠מַשְׁמִיעִ֔ים וּ⁠כְלֵ֖י שִׁ֣יר הָ⁠אֱלֹהִ֑ים וּ⁠בְנֵ֥י יְדוּת֖וּן לַ⁠שָּֽׁעַר׃","wĕ⁠ʻimá̇⁠hem֩ héymá֨n wiֽ⁠ydẇţ֜ẇn ẖàẕòẕĕr֤wòţ ẇ⁠mĕẕilĕţȧ֨yim֙ lĕ⁠maşĕ̌miyʻi֔ym ẇ⁠kĕlé֖y şǐ֣yr há⁠ʼèlòhi֑ym ẇ⁠bĕné֥y yĕdẇţ֖ẇn la⁠şáֽ̇̌ʻar׃"],[16,43,"וַ⁠יֵּלְכ֥וּ כָל־הָ⁠עָ֖ם אִ֣ישׁ לְ⁠בֵית֑⁠וֹ וַ⁠יִּסֹּ֥ב דָּוִ֖יד לְ⁠בָרֵ֥ךְ אֶת־בֵּיתֽ⁠וֹ׃פ","wa⁠yé̇lĕk֥ẇ kál-há⁠ʻá֖m ʼi֣yş̌ lĕ⁠béyţ֑⁠wò wa⁠yi̇sò֥̇b dá̇wi֖yd lĕ⁠báré֥kĕ ʼeţ-bé̇yţֽ⁠wò׃p"],[17,1,"וַ⁠יְהִ֕י כַּ⁠אֲשֶׁ֛ר יָשַׁ֥ב דָּוִ֖יד בְּ⁠בֵית֑⁠וֹ וַ⁠יֹּ֨אמֶר דָּוִ֜יד אֶל־נָתָ֣ן הַ⁠נָּבִ֗יא הִנֵּ֨ה אָנֹכִ֤י יוֹשֵׁב֙ בְּ⁠בֵ֣ית הָֽ⁠אֲרָזִ֔ים וַ⁠אֲר֥וֹן בְּרִית־יְהוָ֖ה תַּ֥חַת יְרִיעֽוֹת׃","wa⁠yĕhi֕y kȧ⁠ʼàşě֛r yáşǎ֥b dá̇wi֖yd bĕ̇⁠béyţ֑⁠wò wa⁠yò̇֨ʼmer dá̇wi֜yd ʼel-náţá֣n ha⁠ná̇bi֗yʼ hiné̇֨h ʼánòki֤y ywòşé̌b֙ bĕ̇⁠bé֣yţ hֽá⁠ʼàrázi֔ym wa⁠ʼàr֥wòn bĕ̇riyţ-yĕhwá֖h ţȧ֥ẖaţ yĕriyʻֽwòţ׃"],[17,2,"וַ⁠יֹּ֤אמֶר נָתָן֙ אֶל־דָּוִ֔יד כֹּ֛ל אֲשֶׁ֥ר בִּֽ⁠לְבָבְ⁠ךָ֖ עֲשֵׂ֑ה כִּ֥י הָ⁠אֱלֹהִ֖ים עִמָּֽ⁠ךְ׃ס","wa⁠yò֤̇ʼmer náţán֙ ʼel-dá̇wi֔yd kò֛̇l ʼàşě֥r biֽ̇⁠lĕbábĕ⁠ká֖ ʻàşé֑̂h ki֥̇y há⁠ʼèlòhi֖ym ʻimáֽ̇⁠kĕ׃s"],[17,3,"וַֽ⁠יְהִ֖י בַּ⁠לַּ֣יְלָה הַ⁠ה֑וּא וַ⁠יְהִי֙ דְּבַר־אֱלֹהִ֔ים אֶל־נָתָ֖ן לֵ⁠אמֹֽר׃","waֽ⁠yĕhi֖y bȧ⁠lȧ֣yĕláh ha⁠h֑ẇʼ wa⁠yĕhiy֙ dĕ̇bar-ʼèlòhi֔ym ʼel-náţá֖n lé⁠ʼmòֽr׃"],[17,4,"לֵ֤ךְ וְ⁠אָמַרְתָּ֙ אֶל־דָּוִ֣יד עַבְדִּ֔⁠י כֹּ֖ה אָמַ֣ר יְהוָ֑ה לֹ֥א אַתָּ֛ה תִּבְנֶה־לִּ֥⁠י הַ⁠בַּ֖יִת לָ⁠שָֽׁבֶת׃","lé֤kĕ wĕ⁠ʼámarĕţá̇֙ ʼel-dá̇wi֣yd ʻabĕdi̇֔⁠y kò֖̇h ʼáma֣r yĕhwá֑h lò֥ʼ ʼaţá֛̇h ţi̇bĕneh-li֥̇⁠y ha⁠bȧ֖yiţ lá⁠şáֽ̌beţ׃"],[17,5,"כִּ֣י לֹ֤א יָשַׁ֨בְתִּי֙ בְּ⁠בַ֔יִת מִן־הַ⁠יּ֗וֹם אֲשֶׁ֤ר הֶעֱלֵ֨יתִי֙ אֶת־יִשְׂרָאֵ֔ל עַ֖ד הַ⁠יּ֣וֹם הַ⁠זֶּ֑ה וָֽ⁠אֶהְיֶ֛ה מֵ⁠אֹ֥הֶל אֶל־אֹ֖הֶל וּ⁠מִ⁠מִּשְׁכָּֽן׃","ki֣̇y lò֤ʼ yáşǎ֨bĕţi̇y֙ bĕ̇⁠ba֔yiţ min-ha⁠ẏ֗wòm ʼàşě֤r heʻèlé֨yţiy֙ ʼeţ-yişĕ̂ráʼé֔l ʻa֖d ha⁠ẏ֣wòm ha⁠zė֑h wáֽ⁠ʼehĕye֛h mé⁠ʼò֥hel ʼel-ʼò֖hel ẇ⁠mi⁠mi̇şĕ̌káֽ̇n׃"],[17,6,"בְּ⁠כֹ֥ל אֲשֶֽׁר־הִתְהַלַּכְתִּי֮ בְּ⁠כָל־יִשְׂרָאֵל֒ הֲ⁠דָבָ֣ר דִּבַּ֗רְתִּי אֶת־אַחַד֙ שֹׁפְטֵ֣י יִשְׂרָאֵ֔ל אֲשֶׁ֥ר צִוִּ֛יתִי לִ⁠רְע֥וֹת אֶת־עַמִּ֖⁠י לֵ⁠אמֹ֑ר לָ֛⁠מָּה לֹא־בְנִיתֶ֥ם לִ֖⁠י בֵּ֥ית אֲרָזִֽים׃","bĕ̇⁠kò֥l ʼàşěֽr-hiţĕhalȧkĕţi̇y֮ bĕ̇⁠kál-yişĕ̂ráʼél֒ hà⁠dábá֣r di̇bȧ֗rĕţi̇y ʼeţ-ʼaẖad֙ şò̌pĕté֣y yişĕ̂ráʼé֔l ʼàşě֥r ẕiwi֛̇yţiy li⁠rĕʻ֥wòţ ʼeţ-ʻami֖̇⁠y lé⁠ʼmò֑r lá֛⁠má̇h lòʼ-bĕniyţe֥m li֖⁠y bé֥̇yţ ʼàráziֽym׃"],[17,7,"וְ֠⁠עַתָּה כֹּֽה־תֹאמַ֞ר לְ⁠עַבְדִּ֣⁠י לְ⁠דָוִ֗יד ס כֹּ֤ה אָמַר֙ יְהוָ֣ה צְבָא֔וֹת אֲנִ֤י לְקַחְתִּ֨י⁠ךָ֙ מִן־הַ⁠נָּוֶ֔ה מִֽן־אַחֲרֵ֖י הַ⁠צֹּ֑אן לִ⁠הְי֣וֹת נָגִ֔יד עַ֖ל עַמִּ֥⁠י יִשְׂרָאֵֽל׃","wĕ֠⁠ʻaţá̇h kòֽ̇h-ţòʼma֞r lĕ⁠ʻabĕdi֣̇⁠y lĕ⁠dáwi֗yd s kò֤̇h ʼámar֙ yĕhwá֣h ẕĕbáʼ֔wòţ ʼàni֤y lĕqaẖĕţi̇֨y⁠ká֙ min-ha⁠ná̇we֔h miֽn-ʼaẖàré֖y ha⁠ẕò֑̇ʼn li⁠hĕy֣wòţ nági֔yd ʻa֖l ʻami֥̇⁠y yişĕ̂ráʼéֽl׃"],[17,8,"וָֽ⁠אֶהְיֶ֣ה עִמְּ⁠ךָ֗ בְּ⁠כֹל֙ אֲשֶׁ֣ר הָלַ֔כְתָּ וָ⁠אַכְרִ֥ית אֶת־כָּל־אוֹיְבֶ֖י⁠ךָ מִ⁠פָּנֶ֑י⁠ךָ וְ⁠עָשִׂ֤יתִֽי לְ⁠ךָ֙ שֵׁ֔ם כְּ⁠שֵׁ֥ם הַ⁠גְּדוֹלִ֖ים אֲשֶׁ֥ר בָּ⁠אָֽרֶץ׃","wáֽ⁠ʼehĕye֣h ʻimĕ̇⁠ká֗ bĕ̇⁠kòl֙ ʼàşě֣r hála֔kĕţá̇ wá⁠ʼakĕri֥yţ ʼeţ-ká̇l-ʼwòyĕbe֖y⁠ká mi⁠pá̇ne֑y⁠ká wĕ⁠ʻáşî֤yţiֽy lĕ⁠ká֙ şé̌֔m kĕ̇⁠şé֥̌m ha⁠gĕ̇dwòli֖ym ʼàşě֥r bá̇⁠ʼáֽreẕ׃"],[17,9,"וְ⁠שַׂמְתִּ֣י מָ֠קוֹם לְ⁠עַמִּ֨⁠י יִשְׂרָאֵ֤ל וּ⁠נְטַעְתִּ֨י⁠הוּ֙ וְ⁠שָׁכַ֣ן תַּחְתָּ֔י⁠ו וְ⁠לֹ֥א יִרְגַּ֖ז ע֑וֹד וְ⁠לֹא־יוֹסִ֤יפוּ בְנֵי־עַוְלָה֙ לְ⁠בַלֹּת֔⁠וֹ כַּ⁠אֲשֶׁ֖ר בָּ⁠רִאשׁוֹנָֽה׃","wĕ⁠şâmĕţi֣̇y má֠qwòm lĕ⁠ʻami̇֨⁠y yişĕ̂ráʼé֤l ẇ⁠nĕtaʻĕţi̇֨y⁠hẇ֙ wĕ⁠şá̌ka֣n ţȧẖĕţá̇֔y⁠w wĕ⁠lò֥ʼ yirĕgȧ֖z ʻ֑wòd wĕ⁠lòʼ-ywòsi֤ypẇ bĕnéy-ʻawĕláh֙ lĕ⁠balò̇ţ֔⁠wò kȧ⁠ʼàşě֖r bá̇⁠riʼş̌wònáֽh׃"],[17,10,"וּ⁠לְ⁠מִ⁠יָּמִ֗ים אֲשֶׁ֨ר צִוִּ֤יתִי שֹֽׁפְטִים֙ עַל־עַמִּ֣⁠י יִשְׂרָאֵ֔ל וְ⁠הִכְנַ֖עְתִּי אֶת־כָּל־אוֹיְבֶ֑י⁠ךָ וָ⁠אַגִּ֣ד לָ֔⁠ךְ וּ⁠בַ֖יִת יִֽבְנֶה־לְּ⁠ךָ֥ יְהוָֽה׃","ẇ⁠lĕ⁠mi⁠yá̇mi֗ym ʼàşě֨r ẕiwi֤̇yţiy şòֽ̌pĕtiym֙ ʻal-ʻami֣̇⁠y yişĕ̂ráʼé֔l wĕ⁠hikĕna֖ʻĕţi̇y ʼeţ-ká̇l-ʼwòyĕbe֑y⁠ká wá⁠ʼagi֣̇d lá֔⁠kĕ ẇ⁠ba֖yiţ yiֽbĕneh-lĕ̇⁠ká֥ yĕhwáֽh׃"],[17,11,"וְ⁠הָיָ֗ה כִּֽי־מָלְא֤וּ יָמֶ֨י⁠ךָ֙ לָ⁠לֶ֣כֶת עִם־אֲבֹתֶ֔י⁠ךָ וַ⁠הֲקִֽימוֹתִ֤י אֶֽת־זַרְעֲ⁠ךָ֙ אַחֲרֶ֔י⁠ךָ אֲשֶׁ֥ר יִהְיֶ֖ה מִ⁠בָּנֶ֑י⁠ךָ וַ⁠הֲכִינוֹתִ֖י אֶת־מַלְכוּתֽ⁠וֹ׃","wĕ⁠háyá֗h kiֽ̇y-málĕʼ֤ẇ yáme֨y⁠ká֙ lá⁠le֣keţ ʻim-ʼàbòţe֔y⁠ká wa⁠hàqiֽymwòţi֤y ʼeֽţ-zarĕʻà⁠ká֙ ʼaẖàre֔y⁠ká ʼàşě֥r yihĕye֖h mi⁠bá̇ne֑y⁠ká wa⁠hàkiynwòţi֖y ʼeţ-malĕkẇţֽ⁠wò׃"],[17,12,"ה֥וּא יִבְנֶה־לִּ֖⁠י בָּ֑יִת וְ⁠כֹנַנְתִּ֥י אֶת־כִּסְא֖⁠וֹ עַד־עוֹלָֽם׃","h֥ẇʼ yibĕneh-li֖̇⁠y bá֑̇yiţ wĕ⁠kònanĕţi֥̇y ʼeţ-ki̇sĕʼ֖⁠wò ʻad-ʻwòláֽm׃"],[17,13,"אֲנִי֙ אֶֽהְיֶה־לּ֣⁠וֹ לְ⁠אָ֔ב וְ⁠ה֖וּא יִֽהְיֶה־לִּ֣⁠י לְ⁠בֵ֑ן וְ⁠חַסְדִּ⁠י֙ לֹא־אָסִ֣יר מֵֽ⁠עִמּ֔⁠וֹ כַּ⁠אֲשֶׁ֣ר הֲסִיר֔וֹתִי מֵ⁠אֲשֶׁ֥ר הָיָ֖ה לְ⁠פָנֶֽי⁠ךָ׃","ʼàniy֙ ʼeֽhĕyeh-l֣̇⁠wò lĕ⁠ʼá֔b wĕ⁠h֖ẇʼ yiֽhĕyeh-li֣̇⁠y lĕ⁠bé֑n wĕ⁠ẖasĕdi̇⁠y֙ lòʼ-ʼási֣yr méֽ⁠ʻiṁ֔⁠wò kȧ⁠ʼàşě֣r hàsiyr֔wòţiy mé⁠ʼàşě֥r háyá֖h lĕ⁠páneֽy⁠ká׃"],[17,14,"וְ⁠הַֽעֲמַדְתִּ֛י⁠הוּ בְּ⁠בֵיתִ֥⁠י וּ⁠בְ⁠מַלְכוּתִ֖⁠י עַד־הָ⁠עוֹלָ֑ם וְ⁠כִסְא֕⁠וֹ יִהְיֶ֥ה נָכ֖וֹן עַד־עוֹלָֽם׃","wĕ⁠haֽʻàmadĕţi֛̇y⁠hẇ bĕ̇⁠béyţi֥⁠y ẇ⁠bĕ⁠malĕkẇţi֖⁠y ʻad-há⁠ʻwòlá֑m wĕ⁠kisĕʼ֕⁠wò yihĕye֥h nák֖wòn ʻad-ʻwòláֽm׃"],[17,15,"כְּ⁠כֹל֙ הַ⁠דְּבָרִ֣ים הָ⁠אֵ֔לֶּה וּ⁠כְ⁠כֹ֖ל הֶ⁠חָז֣וֹן הַ⁠זֶּ֑ה כֵּ֛ן דִּבֶּ֥ר נָתָ֖ן אֶל־דָּוִֽיד׃פ","kĕ̇⁠kòl֙ ha⁠dĕ̇bári֣ym há⁠ʼé֔lėh ẇ⁠kĕ⁠kò֖l he⁠ẖáz֣wòn ha⁠zė֑h ké֛̇n di̇bė֥r náţá֖n ʼel-dá̇wiֽyd׃p"],[17,16,"וַ⁠יָּבֹא֙ הַ⁠מֶּ֣לֶךְ דָּוִ֔יד וַ⁠יֵּ֖שֶׁב לִ⁠פְנֵ֣י יְהוָ֑ה וַ⁠יֹּ֗אמֶר מִֽי־אֲנִ֞י יְהוָ֤ה אֱלֹהִים֙ וּ⁠מִ֣י בֵיתִ֔⁠י כִּ֥י הֲבִיאֹתַ֖⁠נִי עַד־הֲלֹֽם׃","wa⁠yá̇bòʼ֙ ha⁠mė֣lekĕ dá̇wi֔yd wa⁠yé֖̇şěb li⁠pĕné֣y yĕhwá֑h wa⁠yò̇֗ʼmer miֽy-ʼàni֞y yĕhwá֤h ʼèlòhiym֙ ẇ⁠mi֣y béyţi֔⁠y ki֥̇y hàbiyʼòţa֖⁠niy ʻad-hàlòֽm׃"],[17,17,"וַ⁠תִּקְטַ֨ן זֹ֤את בְּ⁠עֵינֶ֨י⁠ךָ֙ אֱלֹהִ֔ים וַ⁠תְּדַבֵּ֥ר עַל־בֵּֽית־עַבְדְּ⁠ךָ֖ לְ⁠מֵ⁠רָח֑וֹק וּ⁠רְאִיתַ֗⁠נִי כְּ⁠ת֧וֹר הָ⁠אָדָ֛ם הַֽ⁠מַּעֲלָ֖ה יְהוָ֥ה אֱלֹהִֽים׃","wa⁠ţi̇qĕta֨n zò֤ʼţ bĕ̇⁠ʻéyne֨y⁠ká֙ ʼèlòhi֔ym wa⁠ţĕ̇dabé֥̇r ʻal-béֽ̇yţ-ʻabĕdĕ̇⁠ká֖ lĕ⁠mé⁠ráẖ֑wòq ẇ⁠rĕʼiyţa֗⁠niy kĕ̇⁠ţ֧wòr há⁠ʼádá֛m haֽ⁠mȧʻàlá֖h yĕhwá֥h ʼèlòhiֽym׃"],[17,18,"מַה־יּוֹסִ֨יף ע֥וֹד דָּוִ֛יד אֵלֶ֖י⁠ךָ לְ⁠כָב֣וֹד אֶת־עַבְדֶּ֑⁠ךָ וְ⁠אַתָּ֖ה אֶֽת־עַבְדְּ⁠ךָ֥ יָדָֽעְתָּ׃","mah-ẏwòsi֨yp ʻ֥wòd dá̇wi֛yd ʼéle֖y⁠ká lĕ⁠káb֣wòd ʼeţ-ʻabĕdė֑⁠ká wĕ⁠ʼaţá֖̇h ʼeֽţ-ʻabĕdĕ̇⁠ká֥ yádáֽʻĕţá̇׃"],[17,19,"יְהוָ֕ה בַּ⁠עֲב֤וּר עַבְדְּ⁠ךָ֙ וּֽ⁠כְ⁠לִבְּ⁠ךָ֔ עָשִׂ֕יתָ אֵ֥ת כָּל־הַ⁠גְּדוּלָּ֖ה הַ⁠זֹּ֑את לְ⁠הֹדִ֖יעַ אֶת־כָּל־הַ⁠גְּדֻלּֽוֹת׃","yĕhwá֕h bȧ⁠ʻàb֤ẇr ʻabĕdĕ̇⁠ká֙ ẇֽ⁠kĕ⁠libĕ̇⁠ká֔ ʻáşî֕yţá ʼé֥ţ ká̇l-ha⁠gĕ̇dẇlá֖̇h ha⁠zò֑̇ʼţ lĕ⁠hòdi֖yʻa ʼeţ-ká̇l-ha⁠gĕ̇dulֽ̇wòţ׃"],[17,20,"יְהוָה֙ אֵ֣ין כָּמ֔וֹ⁠ךָ וְ⁠אֵ֥ין אֱלֹהִ֖ים זוּלָתֶ֑⁠ךָ בְּ⁠כֹ֥ל אֲשֶׁר־שָׁמַ֖עְנוּ בְּ⁠אָזְנֵֽי⁠נוּ׃","yĕhwáh֙ ʼé֣yn ká̇m֔wò⁠ká wĕ⁠ʼé֥yn ʼèlòhi֖ym zẇláţe֑⁠ká bĕ̇⁠kò֥l ʼàşěr-şá̌ma֖ʻĕnẇ bĕ̇⁠ʼázĕnéֽy⁠nẇ׃"],[17,21,"וּ⁠מִי֙ כְּ⁠עַמְּ⁠ךָ֣ יִשְׂרָאֵ֔ל גּ֥וֹי אֶחָ֖ד בָּ⁠אָ֑רֶץ אֲשֶׁר֩ הָלַ֨ךְ הָ⁠אֱלֹהִ֜ים לִ⁠פְדּ֧וֹת ל֣⁠וֹ עָ֗ם לָ⁠שׂ֤וּם לְ⁠ךָ֙ שֵׁ֚ם גְּדֻלּ֣וֹת וְ⁠נֹרָא֔וֹת לְ⁠גָרֵ֗שׁ מִ⁠פְּנֵ֧י עַמְּ⁠ךָ֛ אֲשֶׁר־פָּדִ֥יתָ מִ⁠מִּצְרַ֖יִם גּוֹיִֽם׃","ẇ⁠miy֙ kĕ̇⁠ʻamĕ̇⁠ká֣ yişĕ̂ráʼé֔l ġ֥wòy ʼeẖá֖d bá̇⁠ʼá֑reẕ ʼàşěr֩ hála֨kĕ há⁠ʼèlòhi֜ym li⁠pĕḋ֧wòţ l֣⁠wò ʻá֗m lá⁠ş֤̂ẇm lĕ⁠ká֙ şé֚̌m gĕ̇dul֣̇wòţ wĕ⁠nòráʼ֔wòţ lĕ⁠gáré֗ş̌ mi⁠pĕ̇né֧y ʻamĕ̇⁠ká֛ ʼàşěr-pá̇di֥yţá mi⁠mi̇ẕĕra֖yim ġwòyiֽm׃"],[17,22,"וַ֠⁠תִּתֵּן אֶת־עַמְּ⁠ךָ֨ יִשְׂרָאֵ֧ל ׀ לְ⁠ךָ֛ לְ⁠עָ֖ם עַד־עוֹלָ֑ם וְ⁠אַתָּ֣ה יְהוָ֔ה הָיִ֥יתָ לָ⁠הֶ֖ם לֵ⁠אלֹהִֽים׃","wa֠⁠ţi̇ţé̇n ʼeţ-ʻamĕ̇⁠ká֨ yişĕ̂ráʼé֧l ׀ lĕ⁠ká֛ lĕ⁠ʻá֖m ʻad-ʻwòlá֑m wĕ⁠ʼaţá֣̇h yĕhwá֔h háyi֥yţá lá⁠he֖m lé⁠ʼlòhiֽym׃"],[17,23,"וְ⁠עַתָּ֣ה יְהוָ֔ה הַ⁠דָּבָ֗ר אֲשֶׁ֨ר דִּבַּ֤רְתָּ עַֽל־עַבְדְּ⁠ךָ֙ וְ⁠עַל־בֵּית֔⁠וֹ יֵאָמֵ֖ן עַד־עוֹלָ֑ם וַ⁠עֲשֵׂ֖ה כַּ⁠אֲשֶׁ֥ר דִּבַּֽרְתָּ׃","wĕ⁠ʻaţá֣̇h yĕhwá֔h ha⁠dá̇bá֗r ʼàşě֨r di̇bȧ֤rĕţá̇ ʻaֽl-ʻabĕdĕ̇⁠ká֙ wĕ⁠ʻal-bé̇yţ֔⁠wò yéʼámé֖n ʻad-ʻwòlá֑m wa⁠ʻàşé֖̂h kȧ⁠ʼàşě֥r di̇bȧֽrĕţá̇׃"],[17,24,"וְ֠⁠יֵֽאָמֵן וְ⁠יִגְדַּ֨ל שִׁמְ⁠ךָ֤ עַד־עוֹלָם֙ לֵ⁠אמֹ֔ר יְהוָ֤ה צְבָאוֹת֙ אֱלֹהֵ֣י יִשְׂרָאֵ֔ל אֱלֹהִ֖ים לְ⁠יִשְׂרָאֵ֑ל וּ⁠בֵית־דָּוִ֥יד עַבְדְּ⁠ךָ֖ נָכ֥וֹן לְ⁠פָנֶֽי⁠ךָ׃","wĕ֠⁠yéֽʼámén wĕ⁠yigĕdȧ֨l şǐmĕ⁠ká֤ ʻad-ʻwòlám֙ lé⁠ʼmò֔r yĕhwá֤h ẕĕbáʼwòţ֙ ʼèlòhé֣y yişĕ̂ráʼé֔l ʼèlòhi֖ym lĕ⁠yişĕ̂ráʼé֑l ẇ⁠béyţ-dá̇wi֥yd ʻabĕdĕ̇⁠ká֖ nák֥wòn lĕ⁠páneֽy⁠ká׃"],[17,25,"כִּ֣י ׀ אַתָּ֣ה אֱלֹהַ֗⁠י גָּלִ֨יתָ֙ אֶת־אֹ֣זֶן עַבְדְּ⁠ךָ֔ לִ⁠בְנ֥וֹת ל֖⁠וֹ בָּ֑יִת עַל־כֵּן֙ מָצָ֣א עַבְדְּ⁠ךָ֔ לְ⁠הִתְפַּלֵּ֖ל לְ⁠פָנֶֽי⁠ךָ׃","ki֣̇y ׀ ʼaţá֣̇h ʼèlòha֗⁠y gá̇li֨yţá֙ ʼeţ-ʼò֣zen ʻabĕdĕ̇⁠ká֔ li⁠bĕn֥wòţ l֖⁠wò bá֑̇yiţ ʻal-ké̇n֙ máẕá֣ʼ ʻabĕdĕ̇⁠ká֔ lĕ⁠hiţĕpȧlé֖̇l lĕ⁠páneֽy⁠ká׃"],[17,26,"וְ⁠עַתָּ֣ה יְהוָ֔ה אַתָּה־ה֖וּא הָ⁠אֱלֹהִ֑ים וַ⁠תְּדַבֵּר֙ עַֽל־עַבְדְּ⁠ךָ֔ הַ⁠טּוֹבָ֖ה הַ⁠זֹּֽאת׃","wĕ⁠ʻaţá֣̇h yĕhwá֔h ʼaţá̇h-h֖ẇʼ há⁠ʼèlòhi֑ym wa⁠ţĕ̇dabé̇r֙ ʻaֽl-ʻabĕdĕ̇⁠ká֔ ha⁠ṫwòbá֖h ha⁠zòֽ̇ʼţ׃"],[17,27,"וְ⁠עַתָּ֗ה הוֹאַ֨לְתָּ֙ לְ⁠בָרֵךְ֙ אֶת־בֵּ֣ית עַבְדְּ⁠ךָ֔ לִ⁠הְי֥וֹת לְ⁠עוֹלָ֖ם לְ⁠פָנֶ֑י⁠ךָ כִּֽי־אַתָּ֤ה יְהוָה֙ בֵּרַ֔כְתָּ וּ⁠מְבֹרָ֖ךְ לְ⁠עוֹלָֽם׃פ","wĕ⁠ʻaţá̇֗h hwòʼa֨lĕţá̇֙ lĕ⁠bárékĕ֙ ʼeţ-bé֣̇yţ ʻabĕdĕ̇⁠ká֔ li⁠hĕy֥wòţ lĕ⁠ʻwòlá֖m lĕ⁠páne֑y⁠ká kiֽ̇y-ʼaţá֤̇h yĕhwáh֙ bé̇ra֔kĕţá̇ ẇ⁠mĕbòrá֖kĕ lĕ⁠ʻwòláֽm׃p"],[18,1,"וַ⁠יְהִי֙ אַחֲרֵי־כֵ֔ן וַ⁠יַּ֥ךְ דָּוִ֛יד אֶת־פְּלִשְׁתִּ֖ים וַ⁠יַּכְנִיעֵ֑⁠ם וַ⁠יִּקַּ֛ח אֶת־גַּ֥ת וּ⁠בְנֹתֶ֖י⁠הָ מִ⁠יַּ֥ד פְּלִשְׁתִּֽים׃","wa⁠yĕhiy֙ ʼaẖàréy-ké֔n wa⁠yȧ֥kĕ dá̇wi֛yd ʼeţ-pĕ̇lişĕ̌ţi֖̇ym wa⁠yȧkĕniyʻé֑⁠m wa⁠yi̇qȧ֛ẖ ʼeţ-gȧ֥ţ ẇ⁠bĕnòţe֖y⁠há mi⁠yȧ֥d pĕ̇lişĕ̌ţiֽ̇ym׃"],[18,2,"וַ⁠יַּ֖ךְ אֶת־מוֹאָ֑ב וַ⁠יִּהְי֤וּ מוֹאָב֙ עֲבָדִ֣ים לְ⁠דָוִ֔יד נֹשְׂאֵ֖י מִנְחָֽה׃","wa⁠yȧ֖kĕ ʼeţ-mwòʼá֑b wa⁠yi̇hĕy֤ẇ mwòʼáb֙ ʻàbádi֣ym lĕ⁠dáwi֔yd nòşĕ̂ʼé֖y minĕẖáֽh׃"],[18,3,"וַ⁠יַּ֥ךְ דָּוִ֛יד אֶת־הֲדַדְעֶ֥זֶר מֶֽלֶךְ־צוֹבָ֖ה חֲמָ֑תָ⁠ה בְּ⁠לֶכְתּ֕⁠וֹ לְ⁠הַצִּ֥יב יָד֖⁠וֹ בִּֽ⁠נְהַר־פְּרָֽת׃","wa⁠yȧ֥kĕ dá̇wi֛yd ʼeţ-hàdadĕʻe֥zer meֽlekĕ-ẕwòbá֖h ẖàmá֑ţá⁠h bĕ̇⁠lekĕţ̇֕⁠wò lĕ⁠haẕi֥̇yb yád֖⁠wò biֽ̇⁠nĕhar-pĕ̇ráֽţ׃"],[18,4,"וַ⁠יִּלְכֹּד֩ דָּוִ֨יד מִמֶּ֜⁠נּוּ אֶ֣לֶף רֶ֗כֶב וְ⁠שִׁבְעַ֤ת אֲלָפִים֙ פָּֽרָשִׁ֔ים וְ⁠עֶשְׂרִ֥ים אֶ֖לֶף אִ֣ישׁ רַגְלִ֑י וַ⁠יְעַקֵּ֤ר דָּוִיד֙ אֶת־כָּל־הָ⁠רֶ֔כֶב וַ⁠יּוֹתֵ֥ר מִמֶּ֖⁠נּוּ מֵ֥אָה רָֽכֶב׃","wa⁠yi̇lĕkò̇d֩ dá̇wi֨yd mimė֜⁠ṅẇ ʼe֣lep re֗keb wĕ⁠şǐbĕʻa֤ţ ʼàlápiym֙ páֽ̇ráşǐ֔ym wĕ⁠ʻeşĕ̂ri֥ym ʼe֖lep ʼi֣yş̌ ragĕli֑y wa⁠yĕʻaqé֤̇r dá̇wiyd֙ ʼeţ-ká̇l-há⁠re֔keb wa⁠ẏwòţé֥r mimė֖⁠ṅẇ mé֥ʼáh ráֽkeb׃"],[18,5,"וַ⁠יָּבֹא֙ אֲרַ֣ם דַּרְמֶ֔שֶׂק לַ⁠עְז֕וֹר לַ⁠הֲדַדְעֶ֖זֶר מֶ֣לֶךְ צוֹבָ֑ה וַ⁠יַּ֤ךְ דָּוִיד֙ בַּ⁠אֲרָ֔ם עֶשְׂרִֽים־וּ⁠שְׁנַ֥יִם אֶ֖לֶף אִֽישׁ׃","wa⁠yá̇bòʼ֙ ʼàra֣m dȧrĕme֔şêq la⁠ʻĕz֕wòr la⁠hàdadĕʻe֖zer me֣lekĕ ẕwòbá֑h wa⁠yȧ֤kĕ dá̇wiyd֙ bȧ⁠ʼàrá֔m ʻeşĕ̂riֽym-ẇ⁠şĕ̌na֥yim ʼe֖lep ʼiֽyş̌׃"],[18,6,"וַ⁠יָּ֤שֶׂם דָּוִיד֙ בַּ⁠אֲרַ֣ם דַּרְמֶ֔שֶׂק וַ⁠יְהִ֤י אֲרָם֙ לְ⁠דָוִ֔יד עֲבָדִ֖ים נֹשְׂאֵ֣י מִנְחָ֑ה וַ⁠יּ֤וֹשַׁע יְהוָה֙ לְ⁠דָוִ֔יד בְּ⁠כֹ֖ל אֲשֶׁ֥ר הָלָֽךְ׃","wa⁠yá֤̇şêm dá̇wiyd֙ bȧ⁠ʼàra֣m dȧrĕme֔şêq wa⁠yĕhi֤y ʼàrám֙ lĕ⁠dáwi֔yd ʻàbádi֖ym nòşĕ̂ʼé֣y minĕẖá֑h wa⁠ẏ֤wòşǎʻ yĕhwáh֙ lĕ⁠dáwi֔yd bĕ̇⁠kò֖l ʼàşě֥r háláֽkĕ׃"],[18,7,"וַ⁠יִּקַּ֣ח דָּוִ֗יד אֵ֚ת שִׁלְטֵ֣י הַ⁠זָּהָ֔ב אֲשֶׁ֣ר הָי֔וּ עַ֖ל עַבְדֵ֣י הֲדַדְעָ֑זֶר וַ⁠יְבִיאֵ֖⁠ם יְרוּשָׁלִָֽם׃","wa⁠yi̇qȧ֣ẖ dá̇wi֗yd ʼé֚ţ şǐlĕté֣y ha⁠zá̇há֔b ʼàşě֣r háy֔ẇ ʻa֖l ʻabĕdé֣y hàdadĕʻá֑zer wa⁠yĕbiyʼé֖⁠m yĕrẇşá̌liáֽm׃"],[18,8,"וּ⁠מִ⁠טִּבְחַ֤ת וּ⁠מִ⁠כּוּן֙ עָרֵ֣י הֲדַדְעֶ֔זֶר לָקַ֥ח דָּוִ֛יד נְחֹ֖שֶׁת רַבָּ֣ה מְאֹ֑ד בָּ֣⁠הּ ׀ עָשָׂ֣ה שְׁלֹמֹ֗ה אֶת־יָ֤ם הַ⁠נְּחֹ֨שֶׁת֙ וְ⁠אֶת־הָֽ⁠עַמּוּדִ֔ים וְ⁠אֵ֖ת כְּלֵ֥י הַ⁠נְּחֹֽשֶׁת׃פ","ẇ⁠mi⁠ti̇bĕẖa֤ţ ẇ⁠mi⁠k̇ẇn֙ ʻáré֣y hàdadĕʻe֔zer láqa֥ẖ dá̇wi֛yd nĕẖò֖şěţ rabá֣̇h mĕʼò֑d bá֣̇⁠ḣ ׀ ʻáşá֣̂h şĕ̌lòmò֗h ʼeţ-yá֤m ha⁠nĕ̇ẖò֨şěţ֙ wĕ⁠ʼeţ-háֽ⁠ʻaṁẇdi֔ym wĕ⁠ʼé֖ţ kĕ̇lé֥y ha⁠nĕ̇ẖòֽşěţ׃p"],[18,9,"וַ⁠יִּשְׁמַ֕ע תֹּ֖עוּ מֶ֣לֶךְ חֲמָ֑ת כִּ֚י הִכָּ֣ה דָוִ֔יד אֶת־כָּל־חֵ֖יל הֲדַדְעֶ֥זֶר מֶֽלֶךְ־צוֹבָֽה׃","wa⁠yi̇şĕ̌ma֕ʻ ţò֖̇ʻẇ me֣lekĕ ẖàmá֑ţ ki֚̇y hiká֣̇h dáwi֔yd ʼeţ-ká̇l-ẖé֖yl hàdadĕʻe֥zer meֽlekĕ-ẕwòbáֽh׃"],[18,10,"וַ⁠יִּשְׁלַ֣ח אֶת־הֲדֽוֹרָם־בְּנ֣⁠וֹ אֶל־הַ⁠מֶּֽלֶךְ־דָּ֠וִיד ל⁠שאול־ל֨⁠וֹ לְ⁠שָׁל֜וֹם וּֽ⁠לְ⁠בָרֲכ֗⁠וֹ עַל֩ אֲשֶׁ֨ר נִלְחַ֤ם בַּ⁠הֲדַדְעֶ֨זֶר֙ וַ⁠יַּכֵּ֔⁠הוּ כִּי־אִ֛ישׁ מִלְחֲמ֥וֹת תֹּ֖עוּ הָיָ֣ה הֲדַדְעָ֑זֶר וְ⁠כֹ֗ל כְּלֵ֛י זָהָ֥ב וָ⁠כֶ֖סֶף וּ⁠נְחֹֽשֶׁת׃","wa⁠yi̇şĕ̌la֣ẖ ʼeţ-hàdֽwòrám-bĕ̇n֣⁠wò ʼel-ha⁠mėֽlekĕ-dá̇֠wiyd l⁠şʼwl-l֨⁠wò lĕ⁠şá̌l֜wòm ẇֽ⁠lĕ⁠báràk֗⁠wò ʻal֩ ʼàşě֨r nilĕẖa֤m bȧ⁠hàdadĕʻe֨zer֙ wa⁠yȧké̇֔⁠hẇ ki̇y-ʼi֛yş̌ milĕẖàm֥wòţ ţò֖̇ʻẇ háyá֣h hàdadĕʻá֑zer wĕ⁠kò֗l kĕ̇lé֛y záhá֥b wá⁠ke֖sep ẇ⁠nĕẖòֽşěţ׃"],[18,11,"גַּם־אֹתָ֗⁠ם הִקְדִּ֞ישׁ הַ⁠מֶּ֤לֶךְ דָּוִיד֙ לַ⁠יהוָ֔ה עִם־הַ⁠כֶּ֨סֶף֙ וְ⁠הַ⁠זָּהָ֔ב אֲשֶׁ֥ר נָשָׂ֖א מִ⁠כָּל־הַ⁠גּוֹיִ֑ם מֵֽ⁠אֱד֤וֹם וּ⁠מִ⁠מּוֹאָב֙ וּ⁠מִ⁠בְּנֵ֣י עַמּ֔וֹן וּ⁠מִ⁠פְּלִשְׁתִּ֖ים וּ⁠מֵֽ⁠עֲמָלֵֽק׃","gȧm-ʼòţá֗⁠m hiqĕdi̇֞yş̌ ha⁠mė֤lekĕ dá̇wiyd֙ la⁠yhwá֔h ʻim-ha⁠kė֨sep֙ wĕ⁠ha⁠zá̇há֔b ʼàşě֥r náşá֖̂ʼ mi⁠ká̇l-ha⁠ġwòyi֑m méֽ⁠ʼèd֤wòm ẇ⁠mi⁠ṁwòʼáb֙ ẇ⁠mi⁠bĕ̇né֣y ʻaṁ֔wòn ẇ⁠mi⁠pĕ̇lişĕ̌ţi֖̇ym ẇ⁠méֽ⁠ʻàmáléֽq׃"],[18,12,"וְ⁠אַבְשַׁ֣י בֶּן־צְרוּיָ֗ה הִכָּ֤ה אֶת־אֱדוֹם֙ בְּ⁠גֵ֣יא הַמֶּ֔לַח שְׁמוֹנָ֥ה עָשָׂ֖ר אָֽלֶף׃","wĕ⁠ʼabĕşǎ֣y bėn-ẕĕrẇyá֗h hiká֤̇h ʼeţ-ʼèdwòm֙ bĕ̇⁠gé֣yʼ hamė֔laẖ şĕ̌mwòná֥h ʻáşá֖̂r ʼáֽlep׃"],[18,13,"וַ⁠יָּ֤שֶׂם בֶּֽ⁠אֱדוֹם֙ נְצִיבִ֔ים וַ⁠יִּהְי֥וּ כָל־אֱד֖וֹם עֲבָדִ֣ים לְ⁠דָוִ֑יד וַ⁠יּ֤וֹשַׁע יְהוָה֙ אֶת־דָּוִ֔יד בְּ⁠כֹ֖ל אֲשֶׁ֥ר הָלָֽךְ׃","wa⁠yá֤̇şêm bėֽ⁠ʼèdwòm֙ nĕẕiybi֔ym wa⁠yi̇hĕy֥ẇ kál-ʼèd֖wòm ʻàbádi֣ym lĕ⁠dáwi֑yd wa⁠ẏ֤wòşǎʻ yĕhwáh֙ ʼeţ-dá̇wi֔yd bĕ̇⁠kò֖l ʼàşě֥r háláֽkĕ׃"],[18,14,"וַ⁠יִּמְלֹ֥ךְ דָּוִ֖יד עַל־כָּל־יִשְׂרָאֵ֑ל וַ⁠יְהִ֗י עֹשֶׂ֛ה מִשְׁפָּ֥ט וּ⁠צְדָקָ֖ה לְ⁠כָל־עַמּֽ⁠וֹ׃","wa⁠yi̇mĕlò֥kĕ dá̇wi֖yd ʻal-ká̇l-yişĕ̂ráʼé֑l wa⁠yĕhi֗y ʻòşê֛h mişĕ̌pá֥̇t ẇ⁠ẕĕdáqá֖h lĕ⁠kál-ʻaṁֽ⁠wò׃"],[18,15,"וְ⁠יוֹאָ֥ב בֶּן־צְרוּיָ֖ה עַל־הַ⁠צָּבָ֑א וִ⁠יהוֹשָׁפָ֥ט בֶּן־אֲחִיל֖וּד מַזְכִּֽיר׃","wĕ⁠ywòʼá֥b bėn-ẕĕrẇyá֖h ʻal-ha⁠ẕá̇bá֑ʼ wi⁠yhwòşá̌pá֥t bėn-ʼàẖiyl֖ẇd mazĕkiֽ̇yr׃"],[18,16,"וְ⁠צָד֧וֹק בֶּן־אֲחִיט֛וּב וַ⁠אֲבִימֶ֥לֶךְ בֶּן־אֶבְיָתָ֖ר כֹּהֲנִ֑ים וְ⁠שַׁוְשָׁ֖א סוֹפֵֽר׃","wĕ⁠ẕád֧wòq bėn-ʼàẖiyt֛ẇb wa⁠ʼàbiyme֥lekĕ bėn-ʼebĕyáţá֖r kò̇hàni֑ym wĕ⁠şǎwĕşá֖̌ʼ swòpéֽr׃"],[18,17,"וּ⁠בְנָיָ֨הוּ֙ בֶּן־יְה֣וֹיָדָ֔ע עַל־הַ⁠כְּרֵתִ֖י וְ⁠הַ⁠פְּלֵתִ֑י וּ⁠בְנֵי־דָוִ֥יד הָ⁠רִאשֹׁנִ֖ים לְ⁠יַ֥ד הַ⁠מֶּֽלֶךְ׃פ","ẇ⁠bĕnáyá֨hẇ֙ bėn-yĕh֣wòyádá֔ʻ ʻal-ha⁠kĕ̇réţi֖y wĕ⁠ha⁠pĕ̇léţi֑y ẇ⁠bĕnéy-dáwi֥yd há⁠riʼşò̌ni֖ym lĕ⁠ya֥d ha⁠mėֽlekĕ׃p"],[19,1,"וַ⁠יְהִי֙ אַחֲרֵי־כֵ֔ן וַ⁠יָּ֕מָת נָחָ֖שׁ מֶ֣לֶךְ בְּנֵי־עַמּ֑וֹן וַ⁠יִּמְלֹ֥ךְ בְּנ֖⁠וֹ תַּחְתָּֽי⁠ו׃","wa⁠yĕhiy֙ ʼaẖàréy-ké֔n wa⁠yá̇֕máţ náẖá֖ş̌ me֣lekĕ bĕ̇néy-ʻaṁ֑wòn wa⁠yi̇mĕlò֥kĕ bĕ̇n֖⁠wò ţȧẖĕţáֽ̇y⁠w׃"],[19,2,"וַ⁠יֹּ֨אמֶר דָּוִ֜יד אֶֽעֱשֶׂה־חֶ֣סֶד ׀ עִם־חָנ֣וּן בֶּן־נָחָ֗שׁ כִּֽי־עָשָׂ֨ה אָבִ֤י⁠ו עִמִּ⁠י֙ חֶ֔סֶד וַ⁠יִּשְׁלַ֥ח דָּוִ֛יד מַלְאָכִ֖ים לְ⁠נַחֲמ֣⁠וֹ עַל־אָבִ֑י⁠ו וַ⁠יָּבֹאוּ֩ עַבְדֵ֨י דָוִ֜יד אֶל־אֶ֧רֶץ בְּנֵי־עַמּ֛וֹן אֶל־חָנ֖וּן לְ⁠נַחֲמֽ⁠וֹ׃","wa⁠yò̇֨ʼmer dá̇wi֜yd ʼeֽʻèşêh-ẖe֣sed ׀ ʻim-ẖán֣ẇn bėn-náẖá֗ş̌ kiֽ̇y-ʻáşá̂֨h ʼábi֤y⁠w ʻimi̇⁠y֙ ẖe֔sed wa⁠yi̇şĕ̌la֥ẖ dá̇wi֛yd malĕʼáki֖ym lĕ⁠naẖàm֣⁠wò ʻal-ʼábi֑y⁠w wa⁠yá̇bòʼẇ֩ ʻabĕdé֨y dáwi֜yd ʼel-ʼe֧reẕ bĕ̇néy-ʻaṁ֛wòn ʼel-ẖán֖ẇn lĕ⁠naẖàmֽ⁠wò׃"],[19,3,"וַ⁠יֹּאמְרוּ֩ שָׂרֵ֨י בְנֵי־עַמּ֜וֹן לְ⁠חָנ֗וּן הַֽ⁠מְכַבֵּ֨ד דָּוִ֤יד אֶת־אָבִ֨י⁠ךָ֙ בְּ⁠עֵינֶ֔י⁠ךָ כִּֽי־שָׁלַ֥ח לְ⁠ךָ֖ מְנַחֲמִ֑ים הֲ⁠לֹ֡א בַּ֠⁠עֲבוּר לַ⁠חְקֹ֨ר וְ⁠לַ⁠הֲפֹ֤ךְ וּ⁠לְ⁠רַגֵּל֙ הָ⁠אָ֔רֶץ בָּ֥אוּ עֲבָדָ֖י⁠ו אֵלֶֽי⁠ךָ׃פ","wa⁠yò̇ʼmĕrẇ֩ şá̂ré֨y bĕnéy-ʻaṁ֜wòn lĕ⁠ẖán֗ẇn haֽ⁠mĕkabé̇֨d dá̇wi֤yd ʼeţ-ʼábi֨y⁠ká֙ bĕ̇⁠ʻéyne֔y⁠ká kiֽ̇y-şá̌la֥ẖ lĕ⁠ká֖ mĕnaẖàmi֑ym hà⁠lò֡ʼ bȧ֠⁠ʻàbẇr la⁠ẖĕqò֨r wĕ⁠la⁠hàpò֤kĕ ẇ⁠lĕ⁠ragé̇l֙ há⁠ʼá֔reẕ bá֥̇ʼẇ ʻàbádá֖y⁠w ʼéleֽy⁠ká׃p"],[19,4,"וַ⁠יִּקַּ֨ח חָנ֜וּן אֶת־עַבְדֵ֤י דָוִיד֙ וַֽ⁠יְגַלְּחֵ֔⁠ם וַ⁠יִּכְרֹ֧ת אֶת־מַדְוֵי⁠הֶ֛ם בַּ⁠חֵ֖צִי עַד־הַ⁠מִּפְשָׂעָ֑ה וַֽ⁠יְשַׁלְּחֵֽ⁠ם׃","wa⁠yi̇qȧ֨ẖ ẖán֜ẇn ʼeţ-ʻabĕdé֤y dáwiyd֙ waֽ⁠yĕgalĕ̇ẖé֔⁠m wa⁠yi̇kĕrò֧ţ ʼeţ-madĕwéy⁠he֛m bȧ⁠ẖé֖ẕiy ʻad-ha⁠mi̇pĕşá̂ʻá֑h waֽ⁠yĕşǎlĕ̇ẖéֽ⁠m׃"],[19,5,"וַ⁠יֵּלְכוּ֩ וַ⁠יַּגִּ֨ידוּ לְ⁠דָוִ֤יד עַל־הָֽ⁠אֲנָשִׁים֙ וַ⁠יִּשְׁלַ֣ח לִ⁠קְרָאתָ֔⁠ם כִּי־הָי֥וּ הָ⁠אֲנָשִׁ֖ים נִכְלָמִ֣ים מְאֹ֑ד וַ⁠יֹּ֤אמֶר הַ⁠מֶּ֨לֶךְ֙ שְׁב֣וּ בִֽ⁠ירֵח֔וֹ עַ֛ד אֲשֶׁר־יְצַמַּ֥ח זְקַנְ⁠כֶ֖ם וְ⁠שַׁבְתֶּֽם׃","wa⁠yé̇lĕkẇ֩ wa⁠yȧgi̇֨ydẇ lĕ⁠dáwi֤yd ʻal-háֽ⁠ʼànáşǐym֙ wa⁠yi̇şĕ̌la֣ẖ li⁠qĕráʼţá֔⁠m ki̇y-háy֥ẇ há⁠ʼànáşǐ֖ym nikĕlámi֣ym mĕʼò֑d wa⁠yò֤̇ʼmer ha⁠mė֨lekĕ֙ şĕ̌b֣ẇ biֽ⁠yréẖ֔wò ʻa֛d ʼàşěr-yĕẕamȧ֥ẖ zĕqanĕ⁠ke֖m wĕ⁠şǎbĕţėֽm׃"],[19,6,"וַ⁠יִּרְאוּ֙ בְּנֵ֣י עַמּ֔וֹן כִּ֥י הִֽתְבָּאֲשׁ֖וּ עִם־דָּוִ֑יד וַ⁠יִּשְׁלַ֣ח חָ֠נוּן וּ⁠בְנֵ֨י עַמּ֜וֹן אֶ֣לֶף כִּכַּר־כֶּ֗סֶף לִ⁠שְׂכֹּ֣ר לָ֠⁠הֶם מִן־אֲרַ֨ם נַהֲרַ֜יִם וּ⁠מִן־אֲרַ֤ם מַעֲכָה֙ וּ⁠מִ⁠צּוֹבָ֔ה רֶ֖כֶב וּ⁠פָרָשִֽׁים׃","wa⁠yi̇rĕʼẇ֙ bĕ̇né֣y ʻaṁ֔wòn ki֥̇y hiֽţĕbá̇ʼàş֖̌ẇ ʻim-dá̇wi֑yd wa⁠yi̇şĕ̌la֣ẖ ẖá֠nẇn ẇ⁠bĕné֨y ʻaṁ֜wòn ʼe֣lep ki̇kȧr-kė֗sep li⁠şĕ̂kò֣̇r lá֠⁠hem min-ʼàra֨m nahàra֜yim ẇ⁠min-ʼàra֤m maʻàkáh֙ ẇ⁠mi⁠ẕ̇wòbá֔h re֖keb ẇ⁠páráşǐֽym׃"],[19,7,"וַ⁠יִּשְׂכְּר֣וּ לָ⁠הֶ֡ם שְׁנַיִם֩ וּ⁠שְׁלֹשִׁ֨ים אֶ֜לֶף רֶ֗כֶב וְ⁠אֶת־מֶ֤לֶךְ מַעֲכָה֙ וְ⁠אֶת־עַמּ֔⁠וֹ וַ⁠יָּבֹ֕אוּ וַֽ⁠יַּחֲנ֖וּ לִ⁠פְנֵ֣י מֵידְבָ֑א וּ⁠בְנֵ֣י עַמּ֗וֹן נֶאֶסְפוּ֙ מֵ⁠עָ֣רֵי⁠הֶ֔ם וַ⁠יָּבֹ֖אוּ לַ⁠מִּלְחָמָֽה׃פ","wa⁠yi̇şĕ̂kĕ̇r֣ẇ lá⁠he֡m şĕ̌nayim֩ ẇ⁠şĕ̌lòşǐ֨ym ʼe֜lep re֗keb wĕ⁠ʼeţ-me֤lekĕ maʻàkáh֙ wĕ⁠ʼeţ-ʻaṁ֔⁠wò wa⁠yá̇bò֕ʼẇ waֽ⁠yȧẖàn֖ẇ li⁠pĕné֣y méydĕbá֑ʼ ẇ⁠bĕné֣y ʻaṁ֗wòn neʼesĕpẇ֙ mé⁠ʻá֣réy⁠he֔m wa⁠yá̇bò֖ʼẇ la⁠mi̇lĕẖámáֽh׃p"],[19,8,"וַ⁠יִּשְׁמַ֖ע דָּוִ֑יד וַ⁠יִּשְׁלַח֙ אֶת־יוֹאָ֔ב וְ⁠אֵ֥ת כָּל־צָבָ֖א הַ⁠גִּבּוֹרִֽים׃","wa⁠yi̇şĕ̌ma֖ʻ dá̇wi֑yd wa⁠yi̇şĕ̌laẖ֙ ʼeţ-ywòʼá֔b wĕ⁠ʼé֥ţ ká̇l-ẕábá֖ʼ ha⁠gi̇ḃwòriֽym׃"],[19,9,"וַ⁠יֵּצְאוּ֙ בְּנֵ֣י עַמּ֔וֹן וַ⁠יַּֽעַרְכ֥וּ מִלְחָמָ֖ה פֶּ֣תַח הָ⁠עִ֑יר וְ⁠הַ⁠מְּלָכִ֣ים אֲשֶׁר־בָּ֔אוּ לְ⁠בַדָּ֖⁠ם בַּ⁠שָּׂדֶֽה׃","wa⁠yé̇ẕĕʼẇ֙ bĕ̇né֣y ʻaṁ֔wòn wa⁠yȧֽʻarĕk֥ẇ milĕẖámá֖h pė֣ţaẖ há⁠ʻi֑yr wĕ⁠ha⁠mĕ̇láki֣ym ʼàşěr-bá̇֔ʼẇ lĕ⁠badá֖̇⁠m bȧ⁠şá̇̂deֽh׃"],[19,10,"וַ⁠יַּ֣רְא יוֹאָ֗ב כִּֽי־הָיְתָ֧ה פְנֵי־הַ⁠מִּלְחָמָ֛ה אֵלָ֖י⁠ו פָּנִ֣ים וְ⁠אָח֑וֹר וַ⁠יִּבְחַ֗ר מִ⁠כָּל־בָּחוּר֙ בְּ⁠יִשְׂרָאֵ֔ל וַֽ⁠יַּעֲרֹ֖ךְ לִ⁠קְרַ֥את אֲרָֽם׃","wa⁠yȧ֣rĕʼ ywòʼá֗b kiֽ̇y-háyĕţá֧h pĕnéy-ha⁠mi̇lĕẖámá֛h ʼélá֖y⁠w pá̇ni֣ym wĕ⁠ʼáẖ֑wòr wa⁠yi̇bĕẖa֗r mi⁠ká̇l-bá̇ẖẇr֙ bĕ̇⁠yişĕ̂ráʼé֔l waֽ⁠yȧʻàrò֖kĕ li⁠qĕra֥ʼţ ʼàráֽm׃"],[19,11,"וְ⁠אֵת֙ יֶ֣תֶר הָ⁠עָ֔ם נָתַ֕ן בְּ⁠יַ֖ד אַבְשַׁ֣י אָחִ֑י⁠ו וַ⁠יַּ֣עַרְכ֔וּ לִ⁠קְרַ֖את בְּנֵ֥י עַמּֽוֹן׃","wĕ⁠ʼéţ֙ ye֣ţer há⁠ʻá֔m náţa֕n bĕ̇⁠ya֖d ʼabĕşǎ֣y ʼáẖi֑y⁠w wa⁠yȧ֣ʻarĕk֔ẇ li⁠qĕra֖ʼţ bĕ̇né֥y ʻaṁֽwòn׃"],[19,12,"וַ⁠יֹּ֗אמֶר אִם־תֶּחֱזַ֤ק מִמֶּ֨⁠נִּי֙ אֲרָ֔ם וְ⁠הָיִ֥יתָ לִּ֖⁠י לִ⁠תְשׁוּעָ֑ה ס וְ⁠אִם־בְּנֵ֥י עַמּ֛וֹן יֶֽחֶזְק֥וּ מִמְּ⁠ךָ֖ וְ⁠הוֹשַׁעְתִּֽי⁠ךָ׃","wa⁠yò̇֗ʼmer ʼim-ţėẖèza֤q mimė֨⁠ni̇y֙ ʼàrá֔m wĕ⁠háyi֥yţá li֖̇⁠y li⁠ţĕş̌ẇʻá֑h s wĕ⁠ʼim-bĕ̇né֥y ʻaṁ֛wòn yeֽẖezĕq֥ẇ mimĕ̇⁠ká֖ wĕ⁠hwòşǎʻĕţiֽ̇y⁠ká׃"],[19,13,"חֲזַ֤ק וְ⁠נִֽתְחַזְּקָה֙ בְּעַד־עַמֵּ֔⁠נוּ וּ⁠בְעַ֖ד עָרֵ֣י אֱלֹהֵ֑י⁠נוּ וַֽ⁠יהוָ֔ה הַ⁠טּ֥וֹב בְּ⁠עֵינָ֖י⁠ו יַעֲשֶֽׂה׃","ẖàza֤q wĕ⁠niֽţĕẖazĕ̇qáh֙ bĕ̇ʻad-ʻamé̇֔⁠nẇ ẇ⁠bĕʻa֖d ʻáré֣y ʼèlòhé֑y⁠nẇ waֽ⁠yhwá֔h ha⁠ṫ֥wòb bĕ̇⁠ʻéyná֖y⁠w yaʻàşêֽh׃"],[19,14,"וַ⁠יִּגַּ֨שׁ יוֹאָ֜ב וְ⁠הָ⁠עָ֧ם אֲשֶׁר־עִמּ֛⁠וֹ לִ⁠פְנֵ֥י אֲרָ֖ם לַ⁠מִּלְחָמָ֑ה וַ⁠יָּנ֖וּסוּ מִ⁠פָּנָֽי⁠ו׃","wa⁠yi̇gȧ֨ş̌ ywòʼá֜b wĕ⁠há⁠ʻá֧m ʼàşěr-ʻiṁ֛⁠wò li⁠pĕné֥y ʼàrá֖m la⁠mi̇lĕẖámá֑h wa⁠yá̇n֖ẇsẇ mi⁠pá̇náֽy⁠w׃"],[19,15,"וּ⁠בְנֵ֨י עַמּ֤וֹן רָאוּ֙ כִּי־נָ֣ס אֲרָ֔ם וַ⁠יָּנ֣וּסוּ גַם־הֵ֗ם מִ⁠פְּנֵי֙ אַבְשַׁ֣י אָחִ֔י⁠ו וַ⁠יָּבֹ֖אוּ הָ⁠עִ֑ירָ⁠ה וַ⁠יָּבֹ֥א יוֹאָ֖ב יְרוּשָׁלִָֽם׃פ","ẇ⁠bĕné֨y ʻaṁ֤wòn ráʼẇ֙ ki̇y-ná֣s ʼàrá֔m wa⁠yá̇n֣ẇsẇ gam-hé֗m mi⁠pĕ̇néy֙ ʼabĕşǎ֣y ʼáẖi֔y⁠w wa⁠yá̇bò֖ʼẇ há⁠ʻi֑yrá⁠h wa⁠yá̇bò֥ʼ ywòʼá֖b yĕrẇşá̌liáֽm׃p"],[19,16,"וַ⁠יַּ֣רְא אֲרָ֗ם כִּ֣י נִגְּפוּ֮ לִ⁠פְנֵ֣י יִשְׂרָאֵל֒ וַֽ⁠יִּשְׁלְחוּ֙ מַלְאָכִ֔ים וַ⁠יּוֹצִ֣יאוּ אֶת־אֲרָ֔ם אֲשֶׁ֖ר מֵ⁠עֵ֣בֶר הַ⁠נָּהָ֑ר וְ⁠שׁוֹפַ֛ךְ שַׂר־צְבָ֥א הֲדַדְעֶ֖זֶר לִ⁠פְנֵי⁠הֶֽם׃","wa⁠yȧ֣rĕʼ ʼàrá֗m ki֣̇y nigĕ̇pẇ֮ li⁠pĕné֣y yişĕ̂ráʼél֒ waֽ⁠yi̇şĕ̌lĕẖẇ֙ malĕʼáki֔ym wa⁠ẏwòẕi֣yʼẇ ʼeţ-ʼàrá֔m ʼàşě֖r mé⁠ʻé֣ber ha⁠ná̇há֑r wĕ⁠ş̌wòpa֛kĕ şâr-ẕĕbá֥ʼ hàdadĕʻe֖zer li⁠pĕnéy⁠heֽm׃"],[19,17,"וַ⁠יֻּגַּ֣ד לְ⁠דָוִ֗יד וַ⁠יֶּאֱסֹ֤ף אֶת־כָּל־יִשְׂרָאֵל֙ וַ⁠יַּעֲבֹ֣ר הַ⁠יַּרְדֵּ֔ן וַ⁠יָּבֹ֣א אֲלֵ⁠הֶ֔ם וַֽ⁠יַּעֲרֹ֖ךְ אֲלֵ⁠הֶ֑ם וַ⁠יַּעֲרֹ֨ךְ דָּוִ֜יד לִ⁠קְרַ֤את אֲרָם֙ מִלְחָמָ֔ה וַ⁠יִּֽלָּחֲמ֖וּ עִמּֽ⁠וֹ׃","wa⁠yu̇gȧ֣d lĕ⁠dáwi֗yd wa⁠yėʼèsò֤p ʼeţ-ká̇l-yişĕ̂ráʼél֙ wa⁠yȧʻàbò֣r ha⁠yȧrĕdé̇֔n wa⁠yá̇bò֣ʼ ʼàlé⁠he֔m waֽ⁠yȧʻàrò֖kĕ ʼàlé⁠he֑m wa⁠yȧʻàrò֨kĕ dá̇wi֜yd li⁠qĕra֤ʼţ ʼàrám֙ milĕẖámá֔h wa⁠yiֽ̇lá̇ẖàm֖ẇ ʻiṁֽ⁠wò׃"],[19,18,"וַ⁠יָּ֣נָס אֲרָם֮ מִ⁠לִּ⁠פְנֵ֣י יִשְׂרָאֵל֒ וַ⁠יַּהֲרֹ֨ג דָּוִ֜יד מֵ⁠אֲרָ֗ם שִׁבְעַ֤ת אֲלָפִים֙ רֶ֔כֶב וְ⁠אַרְבָּעִ֥ים אֶ֖לֶף אִ֣ישׁ רַגְלִ֑י וְ⁠אֵ֛ת שׁוֹפַ֥ךְ שַֽׂר־הַ⁠צָּבָ֖א הֵמִֽית׃","wa⁠yá֣̇nás ʼàrám֮ mi⁠li̇⁠pĕné֣y yişĕ̂ráʼél֒ wa⁠yȧhàrò֨g dá̇wi֜yd mé⁠ʼàrá֗m şǐbĕʻa֤ţ ʼàlápiym֙ re֔keb wĕ⁠ʼarĕbá̇ʻi֥ym ʼe֖lep ʼi֣yş̌ ragĕli֑y wĕ⁠ʼé֛ţ ş̌wòpa֥kĕ şâֽr-ha⁠ẕá̇bá֖ʼ hémiֽyţ׃"],[19,19,"וַ⁠יִּרְא֞וּ עַבְדֵ֣י הֲדַדְעֶ֗זֶר כִּ֤י נִגְּפוּ֙ לִ⁠פְנֵ֣י יִשְׂרָאֵ֔ל וַ⁠יַּשְׁלִ֥ימוּ עִם־דָּוִ֖יד וַ⁠יַּֽעַבְדֻ֑⁠הוּ וְ⁠לֹא־אָבָ֣ה אֲרָ֔ם לְ⁠הוֹשִׁ֥יעַ אֶת־בְּנֵי־עַמּ֖וֹן עֽוֹד׃פ","wa⁠yi̇rĕʼ֞ẇ ʻabĕdé֣y hàdadĕʻe֗zer ki֤̇y nigĕ̇pẇ֙ li⁠pĕné֣y yişĕ̂ráʼé֔l wa⁠yȧşĕ̌li֥ymẇ ʻim-dá̇wi֖yd wa⁠yȧֽʻabĕdu֑⁠hẇ wĕ⁠lòʼ-ʼábá֣h ʼàrá֔m lĕ⁠hwòşǐ֥yʻa ʼeţ-bĕ̇néy-ʻaṁ֖wòn ʻֽwòd׃p"],[20,1,"וַ⁠יְהִ֡י לְ⁠עֵת֩ תְּשׁוּבַ֨ת הַ⁠שָּׁנָ֜ה לְ⁠עֵ֣ת ׀ צֵ֣את הַ⁠מְּלָכִ֗ים וַ⁠יִּנְהַ֣ג יוֹאָב֩ אֶת־חֵ֨יל הַ⁠צָּבָ֜א וַ⁠יַּשְׁחֵ֣ת ׀ אֶת־אֶ֣רֶץ בְּנֵֽי־עַמּ֗וֹן וַ⁠יָּבֹא֙ וַ⁠יָּ֣צַר אֶת־רַבָּ֔ה וְ⁠דָוִ֖יד יֹשֵׁ֣ב בִּ⁠ירֽוּשָׁלִָ֑ם וַ⁠יַּ֥ךְ יוֹאָ֛ב אֶת־רַבָּ֖ה וַ⁠יֶּֽהֶרְסֶֽ⁠הָ׃","wa⁠yĕhi֡y lĕ⁠ʻéţ֩ ţĕ̇ş̌ẇba֨ţ ha⁠şá̇̌ná֜h lĕ⁠ʻé֣ţ ׀ ẕé֣ʼţ ha⁠mĕ̇láki֗ym wa⁠yi̇nĕha֣g ywòʼáb֩ ʼeţ-ẖé֨yl ha⁠ẕá̇bá֜ʼ wa⁠yȧşĕ̌ẖé֣ţ ׀ ʼeţ-ʼe֣reẕ bĕ̇néֽy-ʻaṁ֗wòn wa⁠yá̇bòʼ֙ wa⁠yá֣̇ẕar ʼeţ-rabá̇֔h wĕ⁠dáwi֖yd yòşé֣̌b bi̇⁠yrֽẇşá̌liá֑m wa⁠yȧ֥kĕ ywòʼá֛b ʼeţ-rabá֖̇h wa⁠yėֽherĕseֽ⁠há׃"],[20,2,"וַ⁠יִּקַּ֣ח דָּוִ֣יד אֶת־עֲטֶֽרֶת־מַלְכָּ⁠ם֩ מֵ⁠עַ֨ל רֹאשׁ֜⁠וֹ וַֽ⁠יִּמְצָאָ֣⁠הּ ׀ מִשְׁקַ֣ל כִּכַּר־זָהָ֗ב וּ⁠בָ⁠הּ֙ אֶ֣בֶן יְקָרָ֔ה וַ⁠תְּהִ֖י עַל־רֹ֣אשׁ דָּוִ֑יד וּ⁠שְׁלַ֥ל הָ⁠עִ֛יר הוֹצִ֖יא הַרְבֵּ֥ה מְאֹֽד׃","wa⁠yi̇qȧ֣ẖ dá̇wi֣yd ʼeţ-ʻàteֽreţ-malĕká̇⁠m֩ mé⁠ʻa֨l ròʼş̌֜⁠wò waֽ⁠yi̇mĕẕáʼá֣⁠ḣ ׀ mişĕ̌qa֣l ki̇kȧr-záhá֗b ẇ⁠bá⁠ḣ֙ ʼe֣ben yĕqárá֔h wa⁠ţĕ̇hi֖y ʻal-rò֣ʼş̌ dá̇wi֑yd ẇ⁠şĕ̌la֥l há⁠ʻi֛yr hwòẕi֖yʼ harĕbé֥̇h mĕʼòֽd׃"],[20,3,"וְ⁠אֶת־הָ⁠עָ֨ם אֲשֶׁר־בָּ֜⁠הּ הוֹצִ֗יא וַ⁠יָּ֨שַׂר בַּ⁠מְּגֵרָ֜ה וּ⁠בַ⁠חֲרִיצֵ֤י הַ⁠בַּרְזֶל֙ וּ⁠בַ⁠מְּגֵר֔וֹת וְ⁠כֵן֙ יַעֲשֶׂ֣ה דָוִ֔יד לְ⁠כֹ֖ל עָרֵ֣י בְנֵי־עַמּ֑וֹן וַ⁠יָּ֧שָׁב דָּוִ֛יד וְ⁠כָל־הָ⁠עָ֖ם יְרוּשָׁלִָֽם׃פ","wĕ⁠ʼeţ-há⁠ʻá֨m ʼàşěr-bá̇֜⁠ḣ hwòẕi֗yʼ wa⁠yá̇֨şâr bȧ⁠mĕ̇gérá֜h ẇ⁠ba⁠ẖàriyẕé֤y ha⁠bȧrĕzel֙ ẇ⁠ba⁠mĕ̇gér֔wòţ wĕ⁠kén֙ yaʻàşê֣h dáwi֔yd lĕ⁠kò֖l ʻáré֣y bĕnéy-ʻaṁ֑wòn wa⁠yá֧̇şá̌b dá̇wi֛yd wĕ⁠kál-há⁠ʻá֖m yĕrẇşá̌liáֽm׃p"],[20,4,"וַ⁠יְהִי֙ אַחֲרֵי כֵ֔ן וַ⁠תַּעֲמֹ֧ד מִלְחָמָ֛ה בְּ⁠גֶ֖זֶר עִם־פְּלִשְׁתִּ֑ים אָ֣ז הִכָּ֞ה סִבְּכַ֣י הַ⁠חֻֽשָׁתִ֗י אֶת־סִפַּ֛י מִ⁠ילִדֵ֥י הָ⁠רְפָאִ֖ים וַ⁠יִּכָּנֵֽעוּ׃","wa⁠yĕhiy֙ ʼaẖàréy ké֔n wa⁠ţȧʻàmò֧d milĕẖámá֛h bĕ̇⁠ge֖zer ʻim-pĕ̇lişĕ̌ţi֑̇ym ʼá֣z hiká̇֞h sibĕ̇ka֣y ha⁠ẖuֽşá̌ţi֗y ʼeţ-sipȧ֛y mi⁠ylidé֥y há⁠rĕpáʼi֖ym wa⁠yi̇ká̇néֽʻẇ׃"],[20,5,"וַ⁠תְּהִי־ע֥וֹד מִלְחָמָ֖ה אֶת־פְּלִשְׁתִּ֑ים וַ⁠יַּ֞ךְ אֶלְחָנָ֣ן בֶּן־יעור אֶת־לַחְמִי֙ אֲחִי֙ גָּלְיָ֣ת הַ⁠גִּתִּ֔י וְ⁠עֵ֣ץ חֲנִית֔⁠וֹ כִּ⁠מְנ֖וֹר אֹרְגִֽים׃","wa⁠ţĕ̇hiy-ʻ֥wòd milĕẖámá֖h ʼeţ-pĕ̇lişĕ̌ţi֑̇ym wa⁠yȧ֞kĕ ʼelĕẖáná֣n bėn-yʻwr ʼeţ-laẖĕmiy֙ ʼàẖiy֙ gá̇lĕyá֣ţ ha⁠gi̇ţi̇֔y wĕ⁠ʻé֣ẕ ẖàniyţ֔⁠wò ki̇⁠mĕn֖wòr ʼòrĕgiֽym׃"],[20,6,"וַ⁠תְּהִי־ע֥וֹד מִלְחָמָ֖ה בְּ⁠גַ֑ת וַ⁠יְהִ֣י ׀ אִ֣ישׁ מִדָּ֗ה וְ⁠אֶצְבְּעֹתָ֤י⁠ו שֵׁשׁ־וָ⁠שֵׁשׁ֙ עֶשְׂרִ֣ים וְ⁠אַרְבַּ֔ע וְ⁠גַם־ה֖וּא נוֹלַ֥ד לְ⁠הָ⁠רָפָֽא׃","wa⁠ţĕ̇hiy-ʻ֥wòd milĕẖámá֖h bĕ̇⁠ga֑ţ wa⁠yĕhi֣y ׀ ʼi֣yş̌ midá̇֗h wĕ⁠ʼeẕĕbĕ̇ʻòţá֤y⁠w şé̌ş̌-wá⁠şé̌ş̌֙ ʻeşĕ̂ri֣ym wĕ⁠ʼarĕbȧ֔ʻ wĕ⁠gam-h֖ẇʼ nwòla֥d lĕ⁠há⁠rápáֽʼ׃"],[20,7,"וַ⁠יְחָרֵ֖ף אֶת־יִשְׂרָאֵ֑ל וַ⁠יַּכֵּ֨⁠הוּ֙ יְה֣וֹנָתָ֔ן בֶּן־שִׁמְעָ֖א אֲחִ֥י דָוִֽיד׃","wa⁠yĕẖáré֖p ʼeţ-yişĕ̂ráʼé֑l wa⁠yȧké̇֨⁠hẇ֙ yĕh֣wònáţá֔n bėn-şǐmĕʻá֖ʼ ʼàẖi֥y dáwiֽyd׃"],[20,8,"אֵ֛ל נוּלְּד֥וּ לְ⁠הָ⁠רָפָ֖א בְּ⁠גַ֑ת וַ⁠יִּפְּל֥וּ בְ⁠יַד־דָּוִ֖יד וּ⁠בְ⁠יַד־עֲבָדָֽי⁠ו׃פ","ʼé֛l nẇlĕ̇d֥ẇ lĕ⁠há⁠rápá֖ʼ bĕ̇⁠ga֑ţ wa⁠yi̇pĕ̇l֥ẇ bĕ⁠yad-dá̇wi֖yd ẇ⁠bĕ⁠yad-ʻàbádáֽy⁠w׃p"],[21,1,"וַ⁠יַּֽעֲמֹ֥ד שָׂטָ֖ן עַל־יִשְׂרָאֵ֑ל וַ⁠יָּ֨סֶת֙ אֶת־דָּוִ֔יד לִ⁠מְנ֖וֹת אֶת־יִשְׂרָאֵֽל׃","wa⁠yȧֽʻàmò֥d şá̂tá֖n ʻal-yişĕ̂ráʼé֑l wa⁠yá̇֨seţ֙ ʼeţ-dá̇wi֔yd li⁠mĕn֖wòţ ʼeţ-yişĕ̂ráʼéֽl׃"],[21,2,"וַ⁠יֹּ֨אמֶר דָּוִ֤יד אֶל־יוֹאָב֙ וְ⁠אֶל־שָׂרֵ֣י הָ⁠עָ֔ם לְכ֗וּ סִפְרוּ֙ אֶת־יִשְׂרָאֵ֔ל מִ⁠בְּאֵ֥ר שֶׁ֖בַע וְ⁠עַד־דָּ֑ן וְ⁠הָבִ֣יאוּ אֵלַ֔⁠י וְ⁠אֵדְעָ֖ה אֶת־מִסְפָּרָֽ⁠ם׃","wa⁠yò̇֨ʼmer dá̇wi֤yd ʼel-ywòʼáb֙ wĕ⁠ʼel-şá̂ré֣y há⁠ʻá֔m lĕk֗ẇ sipĕrẇ֙ ʼeţ-yişĕ̂ráʼé֔l mi⁠bĕ̇ʼé֥r şě֖baʻ wĕ⁠ʻad-dá֑̇n wĕ⁠hábi֣yʼẇ ʼéla֔⁠y wĕ⁠ʼédĕʻá֖h ʼeţ-misĕpá̇ráֽ⁠m׃"],[21,3,"וַ⁠יֹּ֣אמֶר יוֹאָ֗ב יוֹסֵף֩ יְהוָ֨ה עַל־עַמּ֤⁠וֹ ׀ כָּ⁠הֵם֙ מֵאָ֣ה פְעָמִ֔ים הֲ⁠לֹא֙ אֲדֹנִ֣⁠י הַ⁠מֶּ֔לֶךְ כֻּלָּ֥⁠ם לַ⁠אדֹנִ֖⁠י לַ⁠עֲבָדִ֑ים לָ֣⁠מָּה יְבַקֵּ֥שׁ זֹאת֙ אֲדֹנִ֔⁠י לָ֛⁠מָּה יִהְיֶ֥ה לְ⁠אַשְׁמָ֖ה לְ⁠יִשְׂרָאֵֽל׃","wa⁠yò֣̇ʼmer ywòʼá֗b ywòsép֩ yĕhwá֨h ʻal-ʻaṁ֤⁠wò ׀ ká̇⁠hém֙ méʼá֣h pĕʻámi֔ym hà⁠lòʼ֙ ʼàdòni֣⁠y ha⁠mė֔lekĕ ku̇lá֥̇⁠m la⁠ʼdòni֖⁠y la⁠ʻàbádi֑ym lá֣⁠má̇h yĕbaqé֥̇ş̌ zòʼţ֙ ʼàdòni֔⁠y lá֛⁠má̇h yihĕye֥h lĕ⁠ʼaşĕ̌má֖h lĕ⁠yişĕ̂ráʼéֽl׃"],[21,4,"וּ⁠דְבַר־הַ⁠מֶּ֖לֶךְ חָזַ֣ק עַל־יוֹאָ֑ב וַ⁠יֵּצֵ֣א יוֹאָ֗ב וַ⁠יִּתְהַלֵּךְ֙ בְּ⁠כָל־יִשְׂרָאֵ֔ל וַ⁠יָּבֹ֖א יְרוּשָׁלִָֽם׃","ẇ⁠dĕbar-ha⁠mė֖lekĕ ẖáza֣q ʻal-ywòʼá֑b wa⁠yé̇ẕé֣ʼ ywòʼá֗b wa⁠yi̇ţĕhalé̇kĕ֙ bĕ̇⁠kál-yişĕ̂ráʼé֔l wa⁠yá̇bò֖ʼ yĕrẇşá̌liáֽm׃"],[21,5,"וַ⁠יִּתֵּ֥ן יוֹאָ֛ב אֶת־מִסְפַּ֥ר מִפְקַד־הָ⁠עָ֖ם אֶל־דָּוִ֑יד וַ⁠יְהִ֣י כָֽל־יִשְׂרָאֵ֡ל אֶ֣לֶף אֲלָפִים֩ וּ⁠מֵאָ֨ה אֶ֤לֶף אִישׁ֙ שֹׁ֣לֵֽף חֶ֔רֶב וִֽ⁠יהוּדָ֕ה אַרְבַּע֩ מֵא֨וֹת וְ⁠שִׁבְעִ֥ים אֶ֛לֶף אִ֖ישׁ שֹׁ֥לֵֽף חָֽרֶב׃","wa⁠yi̇ţé֥̇n ywòʼá֛b ʼeţ-misĕpȧ֥r mipĕqad-há⁠ʻá֖m ʼel-dá̇wi֑yd wa⁠yĕhi֣y káֽl-yişĕ̂ráʼé֡l ʼe֣lep ʼàlápiym֩ ẇ⁠méʼá֨h ʼe֤lep ʼiyş̌֙ şò֣̌léֽp ẖe֔reb wiֽ⁠yhẇdá֕h ʼarĕbȧʻ֩ méʼ֨wòţ wĕ⁠şǐbĕʻi֥ym ʼe֛lep ʼi֖yş̌ şò֥̌léֽp ẖáֽreb׃"],[21,6,"וְ⁠לֵוִי֙ וּ⁠בִנְיָמִ֔ן לֹ֥א פָקַ֖ד בְּ⁠תוֹכָ֑⁠ם כִּֽי־נִתְעַ֥ב דְּבַר־הַ⁠מֶּ֖לֶךְ אֶת־יוֹאָֽב׃","wĕ⁠léwiy֙ ẇ⁠binĕyámi֔n lò֥ʼ páqa֖d bĕ̇⁠ţwòká֑⁠m kiֽ̇y-niţĕʻa֥b dĕ̇bar-ha⁠mė֖lekĕ ʼeţ-ywòʼáֽb׃"],[21,7,"וַ⁠יֵּ֨רַע֙ בְּ⁠עֵינֵ֣י הָ⁠אֱלֹהִ֔ים עַל־הַ⁠דָּבָ֖ר הַ⁠זֶּ֑ה וַ⁠יַּ֖ךְ אֶת־יִשְׂרָאֵֽל׃פ","wa⁠yé̇֨raʻ֙ bĕ̇⁠ʻéyné֣y há⁠ʼèlòhi֔ym ʻal-ha⁠dá̇bá֖r ha⁠zė֑h wa⁠yȧ֖kĕ ʼeţ-yişĕ̂ráʼéֽl׃p"],[21,8,"וַ⁠יֹּ֤אמֶר דָּוִיד֙ אֶל־הָ֣⁠אֱלֹהִ֔ים חָטָ֣אתִֽי מְאֹ֔ד אֲשֶׁ֥ר עָשִׂ֖יתִי אֶת־הַ⁠דָּבָ֣ר הַ⁠זֶּ֑ה וְ⁠עַתָּ֗ה הַֽעֲבֶר־נָא֙ אֶת־עֲו֣וֹן עַבְדְּ⁠ךָ֔ כִּ֥י נִסְכַּ֖לְתִּי מְאֹֽד׃פ","wa⁠yò֤̇ʼmer dá̇wiyd֙ ʼel-há֣⁠ʼèlòhi֔ym ẖátá֣ʼţiֽy mĕʼò֔d ʼàşě֥r ʻáşî֖yţiy ʼeţ-ha⁠dá̇bá֣r ha⁠zė֑h wĕ⁠ʻaţá̇֗h haֽʻàber-náʼ֙ ʼeţ-ʻàw֣wòn ʻabĕdĕ̇⁠ká֔ ki֥̇y nisĕkȧ֖lĕţi̇y mĕʼòֽd׃p"],[21,9,"וַ⁠יְדַבֵּ֤ר יְהוָה֙ אֶל־גָּ֔ד חֹזֵ֥ה דָוִ֖יד לֵ⁠אמֹֽר׃","wa⁠yĕdabé֤̇r yĕhwáh֙ ʼel-gá̇֔d ẖòzé֥h dáwi֖yd lé⁠ʼmòֽr׃"],[21,10,"לֵךְ֩ וְ⁠דִבַּרְתָּ֨ אֶל־דָּוִ֜יד לֵ⁠אמֹ֗ר כֹּ֚ה אָמַ֣ר יְהוָ֔ה שָׁל֕וֹשׁ אֲנִ֖י נֹטֶ֣ה עָלֶ֑י⁠ךָ בְּחַר־לְ⁠ךָ֛ אַחַ֥ת מֵ⁠הֵ֖נָּה וְ⁠אֶֽעֱשֶׂה־לָּֽ⁠ךְ׃","lékĕ֩ wĕ⁠dibȧrĕţá̇֨ ʼel-dá̇wi֜yd lé⁠ʼmò֗r kò֚̇h ʼáma֣r yĕhwá֔h şá̌l֕wòş̌ ʼàni֖y nòte֣h ʻále֑y⁠ká bĕ̇ẖar-lĕ⁠ká֛ ʼaẖa֥ţ mé⁠hé֖ná̇h wĕ⁠ʼeֽʻèşêh-láֽ̇⁠kĕ׃"],[21,11,"וַ⁠יָּ֥בֹא גָ֖ד אֶל־דָּוִ֑יד וַ⁠יֹּ֥אמֶר ל֛⁠וֹ כֹּֽה־אָמַ֥ר יְהוָ֖ה קַבֶּל־לָֽ⁠ךְ׃","wa⁠yá֥̇bòʼ gá֖d ʼel-dá̇wi֑yd wa⁠yò֥̇ʼmer l֛⁠wò kòֽ̇h-ʼáma֥r yĕhwá֖h qabėl-láֽ⁠kĕ׃"],[21,12,"אִם־שָׁל֨וֹשׁ שָׁנִ֜ים רָעָ֗ב וְ⁠אִם־שְׁלֹשָׁ֨ה חֳדָשִׁ֜ים נִסְפֶּ֥ה מִ⁠פְּנֵי־צָרֶי⁠ךָ֮ וְ⁠חֶ֣רֶב אוֹיְבֶ֣⁠ךָ ׀ לְ⁠מַשֶּׂגֶת֒ וְ⁠אִם־שְׁלֹ֣שֶׁת יָ֠מִים חֶ֣רֶב יְהוָ֤ה וְ⁠דֶ֨בֶר֙ בָּ⁠אָ֔רֶץ וּ⁠מַלְאַ֣ךְ יְהוָ֔ה מַשְׁחִ֖ית בְּ⁠כָל־גְּב֣וּל יִשְׂרָאֵ֑ל וְ⁠עַתָּ֣ה רְאֵ֔ה מָֽה־אָשִׁ֥יב אֶת־שֹׁלְחִ֖⁠י דָּבָֽר׃פ","ʼim-şá̌l֨wòş̌ şá̌ni֜ym ráʻá֗b wĕ⁠ʼim-şĕ̌lòşá̌֨h ẖodáşǐ֜ym nisĕpė֥h mi⁠pĕ̇néy-ẕárey⁠ká֮ wĕ⁠ẖe֣reb ʼwòyĕbe֣⁠ká ׀ lĕ⁠maşė̂geţ֒ wĕ⁠ʼim-şĕ̌lò֣şěţ yá֠miym ẖe֣reb yĕhwá֤h wĕ⁠de֨ber֙ bá̇⁠ʼá֔reẕ ẇ⁠malĕʼa֣kĕ yĕhwá֔h maşĕ̌ẖi֖yţ bĕ̇⁠kál-gĕ̇b֣ẇl yişĕ̂ráʼé֑l wĕ⁠ʻaţá֣̇h rĕʼé֔h máֽh-ʼáşǐ֥yb ʼeţ-şò̌lĕẖi֖⁠y dá̇báֽr׃p"],[21,13,"וַ⁠יֹּ֧אמֶר דָּוִ֛יד אֶל־גָּ֖ד צַר־לִ֣⁠י מְאֹ֑ד אֶפְּלָה־נָּ֣א בְ⁠יַד־יְהוָ֗ה כִּֽי־רַבִּ֤ים רַחֲמָי⁠ו֙ מְאֹ֔ד וּ⁠בְ⁠יַד־אָדָ֖ם אַל־אֶפֹּֽל׃","wa⁠yò֧̇ʼmer dá̇wi֛yd ʼel-gá֖̇d ẕar-li֣⁠y mĕʼò֑d ʼepĕ̇láh-ná֣̇ʼ bĕ⁠yad-yĕhwá֗h kiֽ̇y-rabi֤̇ym raẖàmáy⁠w֙ mĕʼò֔d ẇ⁠bĕ⁠yad-ʼádá֖m ʼal-ʼepòֽ̇l׃"],[21,14,"וַ⁠יִּתֵּ֧ן יְהוָ֛ה דֶּ֖בֶר בְּ⁠יִשְׂרָאֵ֑ל וַ⁠יִּפֹּל֙ מִ⁠יִּשְׂרָאֵ֔ל שִׁבְעִ֥ים אֶ֖לֶף אִֽישׁ׃","wa⁠yi̇ţé֧̇n yĕhwá֛h dė֖ber bĕ̇⁠yişĕ̂ráʼé֑l wa⁠yi̇pò̇l֙ mi⁠yi̇şĕ̂ráʼé֔l şǐbĕʻi֥ym ʼe֖lep ʼiֽyş̌׃"],[21,15,"וַ⁠יִּשְׁלַח֩ הָ⁠אֱלֹהִ֨ים ׀ מַלְאָ֥ךְ ׀ לִֽ⁠ירוּשָׁלִַם֮ לְ⁠הַשְׁחִיתָ⁠הּ֒ וּ⁠כְ⁠הַשְׁחִ֗ית רָאָ֤ה יְהוָה֙ וַ⁠יִּנָּ֣חֶם עַל־הָֽ⁠רָעָ֔ה וַ⁠יֹּ֨אמֶר לַ⁠מַּלְאָ֤ךְ הַ⁠מַּשְׁחִית֙ רַ֔ב עַתָּ֖ה הֶ֣רֶף יָדֶ֑⁠ךָ וּ⁠מַלְאַ֤ךְ יְהוָה֙ עֹמֵ֔ד עִם־גֹּ֖רֶן אָרְנָ֥ן הַ⁠יְבוּסִֽי׃ס","wa⁠yi̇şĕ̌laẖ֩ há⁠ʼèlòhi֨ym ׀ malĕʼá֥kĕ ׀ liֽ⁠yrẇşá̌liam֮ lĕ⁠haşĕ̌ẖiyţá⁠ḣ֒ ẇ⁠kĕ⁠haşĕ̌ẖi֗yţ ráʼá֤h yĕhwáh֙ wa⁠yi̇ná֣̇ẖem ʻal-hֽá⁠ráʻá֔h wa⁠yò̇֨ʼmer la⁠mȧlĕʼá֤kĕ ha⁠mȧşĕ̌ẖiyţ֙ ra֔b ʻaţá֖̇h he֣rep yáde֑⁠ká ẇ⁠malĕʼa֤kĕ yĕhwáh֙ ʻòmé֔d ʻim-gò֖̇ren ʼárĕná֥n ha⁠yĕbẇsiֽy׃s"],[21,16,"וַ⁠יִּשָּׂ֨א דָוִ֜יד אֶת־עֵינָ֗י⁠ו וַ⁠יַּ֞רְא אֶת־מַלְאַ֤ךְ יְהוָה֙ עֹמֵ֗ד בֵּ֤ין הָ⁠אָ֨רֶץ֙ וּ⁠בֵ֣ין הַ⁠שָּׁמַ֔יִם וְ⁠חַרְבּ֤⁠וֹ שְׁלוּפָה֙ בְּ⁠יָד֔⁠וֹ נְטוּיָ֖ה עַל־יְרוּשָׁלִָ֑ם וַ⁠יִּפֹּ֨ל דָּוִ֧יד וְ⁠הַ⁠זְּקֵנִ֛ים מְכֻסִּ֥ים בַּ⁠שַּׂקִּ֖ים עַל־פְּנֵי⁠הֶֽם׃","wa⁠yi̇şá̇̂֨ʼ dáwi֜yd ʼeţ-ʻéyná֗y⁠w wa⁠yȧ֞rĕʼ ʼeţ-malĕʼa֤kĕ yĕhwáh֙ ʻòmé֗d bé֤̇yn há⁠ʼá֨reẕ֙ ẇ⁠bé֣yn ha⁠şá̇̌ma֔yim wĕ⁠ẖarĕḃ֤⁠wò şĕ̌lẇpáh֙ bĕ̇⁠yád֔⁠wò nĕtẇyá֖h ʻal-yĕrẇşá̌liá֑m wa⁠yi̇pò̇֨l dá̇wi֧yd wĕ⁠ha⁠zĕ̇qéni֛ym mĕkusi֥̇ym bȧ⁠şȧ̂qi֖̇ym ʻal-pĕ̇néy⁠heֽm׃"],[21,17,"וַ⁠יֹּ֣אמֶר דָּוִ֣יד אֶֽל־הָ⁠אֱלֹהִ֡ים הֲ⁠לֹא֩ אֲנִ֨י אָמַ֜רְתִּי לִ⁠מְנ֣וֹת בָּ⁠עָ֗ם וַ⁠אֲנִי־ה֤וּא אֲשֶׁר־חָטָ֨אתִי֙ וְ⁠הָרֵ֣עַ הֲרֵע֔וֹתִי וְ⁠אֵ֥לֶּה הַ⁠צֹּ֖אן מֶ֣ה עָשׂ֑וּ יְהוָ֣ה אֱלֹהַ֗⁠י תְּהִ֨י נָ֤א יָֽדְ⁠ךָ֙ בִּ֚⁠י וּ⁠בְ⁠בֵ֣ית אָבִ֔⁠י וּֽ⁠בְ⁠עַמְּ⁠ךָ֖ לֹ֥א לְ⁠מַגֵּפָֽה׃ס","wa⁠yò֣̇ʼmer dá̇wi֣yd ʼeֽl-há⁠ʼèlòhi֡ym hà⁠lòʼ֩ ʼàni֨y ʼáma֜rĕţi̇y li⁠mĕn֣wòţ bá̇⁠ʻá֗m wa⁠ʼàniy-h֤ẇʼ ʼàşěr-ẖátá֨ʼţiy֙ wĕ⁠háré֣ʻa hàréʻ֔wòţiy wĕ⁠ʼé֥lėh ha⁠ẕò֖̇ʼn me֣h ʻáş֑̂ẇ yĕhwá֣h ʼèlòha֗⁠y ţĕ̇hi֨y ná֤ʼ yáֽdĕ⁠ká֙ bi֚̇⁠y ẇ⁠bĕ⁠bé֣yţ ʼábi֔⁠y ẇֽ⁠bĕ⁠ʻamĕ̇⁠ká֖ lò֥ʼ lĕ⁠magé̇páֽh׃s"],[21,18,"וּ⁠מַלְאַ֧ךְ יְהוָ֛ה אָמַ֥ר אֶל־גָּ֖ד לֵ⁠אמֹ֣ר לְ⁠דָוִ֑יד כִּ֣י ׀ יַעֲלֶ֣ה דָוִ֗יד לְ⁠הָקִ֤ים מִזְבֵּ֨חַ֙ לַ⁠יהוָ֔ה בְּ⁠גֹ֖רֶן אָרְנָ֥ן הַ⁠יְבֻסִֽי׃","ẇ⁠malĕʼa֧kĕ yĕhwá֛h ʼáma֥r ʼel-gá֖̇d lé⁠ʼmò֣r lĕ⁠dáwi֑yd ki֣̇y ׀ yaʻàle֣h dáwi֗yd lĕ⁠háqi֤ym mizĕbé̇֨ẖa֙ la⁠yhwá֔h bĕ̇⁠gò֖ren ʼárĕná֥n ha⁠yĕbusiֽy׃"],[21,19,"וַ⁠יַּ֤עַל דָּוִיד֙ בִּ⁠דְבַר־גָּ֔ד אֲשֶׁ֥ר דִּבֶּ֖ר בְּ⁠שֵׁ֥ם יְהוָֽה׃","wa⁠yȧ֤ʻal dá̇wiyd֙ bi̇⁠dĕbar-gá̇֔d ʼàşě֥r di̇bė֖r bĕ̇⁠şé֥̌m yĕhwáֽh׃"],[21,20,"וַ⁠יָּ֣שָׁב אָרְנָ֗ן וַ⁠יַּרְא֙ אֶת־הַ⁠מַּלְאָ֔ךְ וְ⁠אַרְבַּ֧עַת בָּנָ֛י⁠ו עִמּ֖⁠וֹ מִֽתְחַבְּאִ֑ים וְ⁠אָרְנָ֖ן דָּ֥שׁ חִטִּֽים׃","wa⁠yá֣̇şá̌b ʼárĕná֗n wa⁠yȧrĕʼ֙ ʼeţ-ha⁠mȧlĕʼá֔kĕ wĕ⁠ʼarĕbȧ֧ʻaţ bá̇ná֛y⁠w ʻiṁ֖⁠wò miֽţĕẖabĕ̇ʼi֑ym wĕ⁠ʼárĕná֖n dá֥̇ş̌ ẖitiֽ̇ym׃"],[21,21,"וַ⁠יָּבֹ֥א דָוִ֖יד עַד־אָרְנָ֑ן וַ⁠יַּבֵּ֤ט אָרְנָן֙ וַ⁠יַּ֣רְא אֶת־דָּוִ֔יד וַ⁠יֵּצֵא֙ מִן־הַ⁠גֹּ֔רֶן וַ⁠יִּשְׁתַּ֧חוּ לְ⁠דָוִ֛יד אַפַּ֖יִם אָֽרְצָ⁠ה׃","wa⁠yá̇bò֥ʼ dáwi֖yd ʻad-ʼárĕná֑n wa⁠yȧbé֤̇t ʼárĕnán֙ wa⁠yȧ֣rĕʼ ʼeţ-dá̇wi֔yd wa⁠yé̇ẕéʼ֙ min-ha⁠gò̇֔ren wa⁠yi̇şĕ̌ţȧ֧ẖẇ lĕ⁠dáwi֛yd ʼapȧ֖yim ʼáֽrĕẕá⁠h׃"],[21,22,"וַ⁠יֹּ֨אמֶר דָּוִ֜יד אֶל־אָרְנָ֗ן תְּנָ⁠ה־לִּ⁠י֙ מְק֣וֹם הַ⁠גֹּ֔רֶן וְ⁠אֶבְנֶה־בּ֥⁠וֹ מִזְבֵּ֖חַ לַ⁠יהוָ֑ה בְּ⁠כֶ֤סֶף מָלֵא֙ תְּנֵ֣⁠הוּ לִ֔⁠י וְ⁠תֵעָצַ֥ר הַ⁠מַּגֵּפָ֖ה מֵ⁠עַ֥ל הָ⁠עָֽם׃","wa⁠yò̇֨ʼmer dá̇wi֜yd ʼel-ʼárĕná֗n ţĕ̇ná⁠h-li̇⁠y֙ mĕq֣wòm ha⁠gò̇֔ren wĕ⁠ʼebĕneh-ḃ֥⁠wò mizĕbé֖̇ẖa la⁠yhwá֑h bĕ̇⁠ke֤sep máléʼ֙ ţĕ̇né֣⁠hẇ li֔⁠y wĕ⁠ţéʻáẕa֥r ha⁠mȧgé̇pá֖h mé⁠ʻa֥l há⁠ʻáֽm׃"],[21,23,"וַ⁠יֹּ֨אמֶר אָרְנָ֤ן אֶל־דָּוִיד֙ קַֽח־לָ֔⁠ךְ וְ⁠יַ֛עַשׂ אֲדֹנִ֥⁠י הַ⁠מֶּ֖לֶךְ הַ⁠טּ֣וֹב בְּ⁠עֵינָ֑י⁠ו רְאֵה֩ נָתַ֨תִּי הַ⁠בָּקָ֜ר לָֽ⁠עֹל֗וֹת וְ⁠הַ⁠מּוֹרִגִּ֧ים לָ⁠עֵצִ֛ים וְ⁠הַ⁠חִטִּ֥ים לַ⁠מִּנְחָ֖ה הַ⁠כֹּ֥ל נָתָֽתִּי׃","wa⁠yò̇֨ʼmer ʼárĕná֤n ʼel-dá̇wiyd֙ qaֽẖ-lá֔⁠kĕ wĕ⁠ya֛ʻaş̂ ʼàdòni֥⁠y ha⁠mė֖lekĕ ha⁠ṫ֣wòb bĕ̇⁠ʻéyná֑y⁠w rĕʼéh֩ náţa֨ţi̇y ha⁠bá̇qá֜r láֽ⁠ʻòl֗wòţ wĕ⁠ha⁠ṁwòrigi֧̇ym lá⁠ʻéẕi֛ym wĕ⁠ha⁠ẖiti֥̇ym la⁠mi̇nĕẖá֖h ha⁠kò֥̇l náţáֽţi̇y׃"],[21,24,"וַ⁠יֹּ֨אמֶר הַ⁠מֶּ֤לֶךְ דָּוִיד֙ לְ⁠אָרְנָ֔ן לֹ֕א כִּֽי־קָנֹ֥ה אֶקְנֶ֖ה בְּ⁠כֶ֣סֶף מָלֵ֑א כִּ֠י לֹא־אֶשָּׂ֤א אֲשֶׁר־לְ⁠ךָ֙ לַ⁠יהוָ֔ה וְ⁠הַעֲל֥וֹת עוֹלָ֖ה חִנָּֽם׃","wa⁠yò̇֨ʼmer ha⁠mė֤lekĕ dá̇wiyd֙ lĕ⁠ʼárĕná֔n lò֕ʼ kiֽ̇y-qánò֥h ʼeqĕne֖h bĕ̇⁠ke֣sep málé֑ʼ ki̇֠y lòʼ-ʼeşá֤̇̂ʼ ʼàşěr-lĕ⁠ká֙ la⁠yhwá֔h wĕ⁠haʻàl֥wòţ ʻwòlá֖h ẖináֽ̇m׃"],[21,25,"וַ⁠יִּתֵּ֥ן דָּוִ֛יד לְ⁠אָרְנָ֖ן בַּ⁠מָּק֑וֹם שִׁקְלֵ֣י זָהָ֔ב מִשְׁקָ֖ל שֵׁ֥שׁ מֵאֽוֹת׃","wa⁠yi̇ţé֥̇n dá̇wi֛yd lĕ⁠ʼárĕná֖n bȧ⁠má̇q֑wòm şǐqĕlé֣y záhá֔b mişĕ̌qá֖l şé֥̌ş̌ méʼֽwòţ׃"],[21,26,"וַ⁠יִּבֶן֩ שָׁ֨ם דָּוִ֤יד מִזְבֵּ֨חַ֙ לַ⁠יהוָ֔ה וַ⁠יַּ֥עַל עֹל֖וֹת וּ⁠שְׁלָמִ֑ים וַ⁠יִּקְרָא֙ אֶל־יְהוָ֔ה וַ⁠יַּֽעֲנֵ֤⁠הוּ בָ⁠אֵשׁ֙ מִן־הַ⁠שָּׁמַ֔יִם עַ֖ל מִזְבַּ֥ח הָ⁠עֹלָֽה׃פ","wa⁠yi̇ben֩ şá̌֨m dá̇wi֤yd mizĕbé̇֨ẖa֙ la⁠yhwá֔h wa⁠yȧ֥ʻal ʻòl֖wòţ ẇ⁠şĕ̌lámi֑ym wa⁠yi̇qĕráʼ֙ ʼel-yĕhwá֔h wa⁠yȧֽʻàné֤⁠hẇ bá⁠ʼéş̌֙ min-ha⁠şá̇̌ma֔yim ʻa֖l mizĕbȧ֥ẖ há⁠ʻòláֽh׃p"],[21,27,"וַ⁠יֹּ֤אמֶר יְהוָה֙ לַ⁠מַּלְאָ֔ךְ וַ⁠יָּ֥שֶׁב חַרְבּ֖⁠וֹ אֶל־נְדָנָֽ⁠הּ׃","wa⁠yò֤̇ʼmer yĕhwáh֙ la⁠mȧlĕʼá֔kĕ wa⁠yá֥̇şěb ẖarĕḃ֖⁠wò ʼel-nĕdánáֽ⁠ḣ׃"],[21,28,"בָּ⁠עֵ֣ת הַ⁠הִ֔יא בִּ⁠רְא֤וֹת דָּוִיד֙ כִּי־עָנָ֣⁠הוּ יְהוָ֔ה בְּ⁠גֹ֖רֶן אָרְנָ֣ן הַ⁠יְבוּסִ֑י וַ⁠יִּזְבַּ֖ח שָֽׁם׃","bá̇⁠ʻé֣ţ ha⁠hi֔yʼ bi̇⁠rĕʼ֤wòţ dá̇wiyd֙ ki̇y-ʻáná֣⁠hẇ yĕhwá֔h bĕ̇⁠gò֖ren ʼárĕná֣n ha⁠yĕbẇsi֑y wa⁠yi̇zĕbȧ֖ẖ şáֽ̌m׃"],[21,29,"וּ⁠מִשְׁכַּ֣ן יְ֠הוָה אֲשֶׁר־עָשָׂ֨ה מֹשֶׁ֧ה בַ⁠מִּדְבָּ֛ר וּ⁠מִזְבַּ֥ח הָ⁠עוֹלָ֖ה בָּ⁠עֵ֣ת הַ⁠הִ֑יא בַּ⁠בָּמָ֖ה בְּ⁠גִבְעֽוֹן׃","ẇ⁠mişĕ̌kȧ֣n yĕ֠hwáh ʼàşěr-ʻáşá̂֨h mòşě֧h ba⁠mi̇dĕbá֛̇r ẇ⁠mizĕbȧ֥ẖ há⁠ʻwòlá֖h bá̇⁠ʻé֣ţ ha⁠hi֑yʼ bȧ⁠bá̇má֖h bĕ̇⁠gibĕʻֽwòn׃"],[21,30,"וְ⁠לֹא־יָכֹ֥ל דָּוִ֛יד לָ⁠לֶ֥כֶת לְ⁠פָנָ֖י⁠ו לִ⁠דְרֹ֣שׁ אֱלֹהִ֑ים כִּ֣י נִבְעַ֔ת מִ⁠פְּנֵ֕י חֶ֖רֶב מַלְאַ֥ךְ יְהוָֽה׃ס","wĕ⁠lòʼ-yákò֥l dá̇wi֛yd lá⁠le֥keţ lĕ⁠páná֖y⁠w li⁠dĕrò֣ş̌ ʼèlòhi֑ym ki֣̇y nibĕʻa֔ţ mi⁠pĕ̇né֕y ẖe֖reb malĕʼa֥kĕ yĕhwáֽh׃s"],[22,1,"וַ⁠יֹּ֣אמֶר דָּוִ֔יד זֶ֣ה ה֔וּא בֵּ֖ית יְהוָ֣ה הָ⁠אֱלֹהִ֑ים וְ⁠זֶה־מִּזְבֵּ֥חַ לְ⁠עֹלָ֖ה לְ⁠יִשְׂרָאֵֽל׃ס","wa⁠yò֣̇ʼmer dá̇wi֔yd ze֣h h֔ẇʼ bé֖̇yţ yĕhwá֣h há⁠ʼèlòhi֑ym wĕ⁠zeh-mi̇zĕbé֥̇ẖa lĕ⁠ʻòlá֖h lĕ⁠yişĕ̂ráʼéֽl׃s"],[22,2,"וַ⁠יֹּ֣אמֶר דָּוִ֔יד לִ⁠כְנוֹס֙ אֶת־הַ⁠גֵּרִ֔ים אֲשֶׁ֖ר בְּ⁠אֶ֣רֶץ יִשְׂרָאֵ֑ל וַ⁠יַּעֲמֵ֣ד חֹֽצְבִ֗ים לַ⁠חְצוֹב֙ אַבְנֵ֣י גָזִ֔ית לִ⁠בְנ֖וֹת בֵּ֥ית הָ⁠אֱלֹהִֽים׃","wa⁠yò֣̇ʼmer dá̇wi֔yd li⁠kĕnwòs֙ ʼeţ-ha⁠gé̇ri֔ym ʼàşě֖r bĕ̇⁠ʼe֣reẕ yişĕ̂ráʼé֑l wa⁠yȧʻàmé֣d ẖòֽẕĕbi֗ym la⁠ẖĕẕwòb֙ ʼabĕné֣y gázi֔yţ li⁠bĕn֖wòţ bé֥̇yţ há⁠ʼèlòhiֽym׃"],[22,3,"וּ⁠בַרְזֶ֣ל ׀ לָ֠⁠רֹב לַֽ⁠מִּסְמְרִ֞ים לְ⁠דַלְת֧וֹת הַ⁠שְּׁעָרִ֛ים וְ⁠לַֽ⁠מְחַבְּר֖וֹת הֵכִ֣ין דָּוִ֑יד וּ⁠נְחֹ֥שֶׁת לָ⁠רֹ֖ב אֵ֥ין מִשְׁקָֽל׃","ẇ⁠barĕze֣l ׀ lá֠⁠ròb laֽ⁠mi̇sĕmĕri֞ym lĕ⁠dalĕţ֧wòţ ha⁠şĕ̇̌ʻári֛ym wĕ⁠laֽ⁠mĕẖabĕ̇r֖wòţ héki֣yn dá̇wi֑yd ẇ⁠nĕẖò֥şěţ lá⁠rò֖b ʼé֥yn mişĕ̌qáֽl׃"],[22,4,"וַ⁠עֲצֵ֥י אֲרָזִ֖ים לְ⁠אֵ֣ין מִסְפָּ֑ר כִּֽי הֵ֠בִיאוּ הַ⁠צִּֽידֹנִ֨ים וְ⁠הַ⁠צֹּרִ֜ים עֲצֵ֧י אֲרָזִ֛ים לָ⁠רֹ֖ב לְ⁠דָוִֽיד׃פ","wa⁠ʻàẕé֥y ʼàrázi֖ym lĕ⁠ʼé֣yn misĕpá֑̇r kiֽ̇y hé֠biyʼẇ ha⁠ẕiֽ̇ydòni֨ym wĕ⁠ha⁠ẕò̇ri֜ym ʻàẕé֧y ʼàrázi֛ym lá⁠rò֖b lĕ⁠dáwiֽyd׃p"],[22,5,"וַ⁠יֹּ֣אמֶר דָּוִ֗יד שְׁלֹמֹ֣ה בְנִ⁠י֮ נַ֣עַר וָ⁠רָךְ֒ וְ⁠הַ⁠בַּ֜יִת לִ⁠בְנ֣וֹת לַ⁠יהוָ֗ה לְ⁠הַגְדִּ֨יל ׀ לְ⁠מַ֜עְלָ⁠ה לְ⁠שֵׁ֤ם וּ⁠לְ⁠תִפְאֶ֨רֶת֙ לְ⁠כָל־הָ֣⁠אֲרָצ֔וֹת אָכִ֥ינָה נָּ֖א ל֑⁠וֹ וַ⁠יָּ֧כֶן דָּוִ֛יד לָ⁠רֹ֖ב לִ⁠פְנֵ֥י מוֹתֽ⁠וֹ׃","wa⁠yò֣̇ʼmer dá̇wi֗yd şĕ̌lòmò֣h bĕni⁠y֮ na֣ʻar wá⁠rákĕ֒ wĕ⁠ha⁠bȧ֜yiţ li⁠bĕn֣wòţ la⁠yhwá֗h lĕ⁠hagĕdi̇֨yl ׀ lĕ⁠ma֜ʻĕlá⁠h lĕ⁠şé֤̌m ẇ⁠lĕ⁠ţipĕʼe֨reţ֙ lĕ⁠kál-há֣⁠ʼàráẕ֔wòţ ʼáki֥ynáh ná֖̇ʼ l֑⁠wò wa⁠yá֧̇ken dá̇wi֛yd lá⁠rò֖b li⁠pĕné֥y mwòţֽ⁠wò׃"],[22,6,"וַ⁠יִּקְרָ֖א לִ⁠שְׁלֹמֹ֣ה בְנ֑⁠וֹ וַ⁠יְצַוֵּ֨⁠הוּ֙ לִ⁠בְנ֣וֹת בַּ֔יִת לַ⁠יהוָ֖ה אֱלֹהֵ֥י יִשְׂרָאֵֽל׃ס","wa⁠yi̇qĕrá֖ʼ li⁠şĕ̌lòmò֣h bĕn֑⁠wò wa⁠yĕẕawé̇֨⁠hẇ֙ li⁠bĕn֣wòţ bȧ֔yiţ la⁠yhwá֖h ʼèlòhé֥y yişĕ̂ráʼéֽl׃s"],[22,7,"וַ⁠יֹּ֥אמֶר דָּוִ֖יד לִ⁠שְׁלֹמֹ֑ה בנ⁠ו אֲנִי֙ הָיָ֣ה עִם־לְבָבִ֔⁠י לִ⁠בְנ֣וֹת בַּ֔יִת לְ⁠שֵׁ֖ם יְהוָ֥ה אֱלֹהָֽ⁠י׃","wa⁠yò֥̇ʼmer dá̇wi֖yd li⁠şĕ̌lòmò֑h bn⁠w ʼàniy֙ háyá֣h ʻim-lĕbábi֔⁠y li⁠bĕn֣wòţ bȧ֔yiţ lĕ⁠şé֖̌m yĕhwá֥h ʼèlòháֽ⁠y׃"],[22,8,"וַ⁠יְהִ֨י עָלַ֤⁠י דְּבַר־יְהוָה֙ לֵ⁠אמֹ֔ר דָּ֤ם לָ⁠רֹב֙ שָׁפַ֔כְתָּ וּ⁠מִלְחָמ֥וֹת גְּדֹל֖וֹת עָשִׂ֑יתָ לֹֽא־תִבְנֶ֥ה בַ֨יִת֙ לִ⁠שְׁמִ֔⁠י כִּ֚י דָּמִ֣ים רַבִּ֔ים שָׁפַ֥כְתָּ אַ֖רְצָ⁠ה לְ⁠פָנָֽ⁠י׃","wa⁠yĕhi֨y ʻála֤⁠y dĕ̇bar-yĕhwáh֙ lé⁠ʼmò֔r dá֤̇m lá⁠ròb֙ şá̌pa֔kĕţá̇ ẇ⁠milĕẖám֥wòţ gĕ̇dòl֖wòţ ʻáşî֑yţá lòֽʼ-ţibĕne֥h ba֨yiţ֙ li⁠şĕ̌mi֔⁠y ki֚̇y dá̇mi֣ym rabi̇֔ym şá̌pa֥kĕţá̇ ʼa֖rĕẕá⁠h lĕ⁠pánáֽ⁠y׃"],[22,9,"הִנֵּה־בֵ֞ן נוֹלָ֣ד לָ֗⁠ךְ ה֤וּא יִהְיֶה֙ אִ֣ישׁ מְנוּחָ֔ה וַ⁠הֲנִח֥וֹתִי ל֛⁠וֹ מִ⁠כָּל־אוֹיְבָ֖י⁠ו מִ⁠סָּבִ֑יב כִּ֤י שְׁלֹמֹה֙ יִהְיֶ֣ה שְׁמ֔⁠וֹ וְ⁠שָׁל֥וֹם וָ⁠שֶׁ֛קֶט אֶתֵּ֥ן עַל־יִשְׂרָאֵ֖ל בְּ⁠יָמָֽי⁠ו׃","hiné̇h-bé֞n nwòlá֣d lá֗⁠kĕ h֤ẇʼ yihĕyeh֙ ʼi֣yş̌ mĕnẇẖá֔h wa⁠hàniẖ֥wòţiy l֛⁠wò mi⁠ká̇l-ʼwòyĕbá֖y⁠w mi⁠sá̇bi֑yb ki֤̇y şĕ̌lòmòh֙ yihĕye֣h şĕ̌m֔⁠wò wĕ⁠şá̌l֥wòm wá⁠şě֛qet ʼeţé֥̇n ʻal-yişĕ̂ráʼé֖l bĕ̇⁠yámáֽy⁠w׃"],[22,10,"הֽוּא־יִבְנֶ֥ה בַ֨יִת֙ לִ⁠שְׁמִ֔⁠י וְ⁠הוּא֙ יִהְיֶה־לִּ֣⁠י לְ⁠בֵ֔ן וַ⁠אֲנִי־ל֖⁠וֹ לְ⁠אָ֑ב וַ⁠הֲכִ֨ינוֹתִ֜י כִּסֵּ֧א מַלְכוּת֛⁠וֹ עַל־יִשְׂרָאֵ֖ל עַד־עוֹלָֽם׃","hֽẇʼ-yibĕne֥h ba֨yiţ֙ li⁠şĕ̌mi֔⁠y wĕ⁠hẇʼ֙ yihĕyeh-li֣̇⁠y lĕ⁠bé֔n wa⁠ʼàniy-l֖⁠wò lĕ⁠ʼá֑b wa⁠hàki֨ynwòţi֜y ki̇sé֧̇ʼ malĕkẇţ֛⁠wò ʻal-yişĕ̂ráʼé֖l ʻad-ʻwòláֽm׃"],[22,11,"עַתָּ֣ה בְנִ֔⁠י יְהִ֥י יְהוָ֖ה עִמָּ֑⁠ךְ וְ⁠הִצְלַחְתָּ֗ וּ⁠בָנִ֨יתָ֙ בֵּ֚ית יְהוָ֣ה אֱלֹהֶ֔י⁠ךָ כַּ⁠אֲשֶׁ֖ר דִּבֶּ֥ר עָלֶֽי⁠ךָ׃","ʻaţá֣̇h bĕni֔⁠y yĕhi֥y yĕhwá֖h ʻimá֑̇⁠kĕ wĕ⁠hiẕĕlaẖĕţá̇֗ ẇ⁠báni֨yţá֙ bé֚̇yţ yĕhwá֣h ʼèlòhe֔y⁠ká kȧ⁠ʼàşě֖r di̇bė֥r ʻáleֽy⁠ká׃"],[22,12,"אַ֣ךְ יִֽתֶּן־לְּ⁠ךָ֤ יְהוָה֙ שֵׂ֣כֶל וּ⁠בִינָ֔ה וִֽ⁠יצַוְּ⁠ךָ֖ עַל־יִשְׂרָאֵ֑ל וְ⁠לִ⁠שְׁמ֕וֹר אֶת־תּוֹרַ֖ת יְהוָ֥ה אֱלֹהֶֽי⁠ךָ׃","ʼa֣kĕ yiֽţėn-lĕ̇⁠ká֤ yĕhwáh֙ şé֣̂kel ẇ⁠biyná֔h wiֽ⁠yẕawĕ̇⁠ká֖ ʻal-yişĕ̂ráʼé֑l wĕ⁠li⁠şĕ̌m֕wòr ʼeţ-ţ̇wòra֖ţ yĕhwá֥h ʼèlòheֽy⁠ká׃"],[22,13,"אָ֣ז תַּצְלִ֔יחַ אִם־תִּשְׁמ֗וֹר לַ⁠עֲשׂוֹת֙ אֶת־הַֽ⁠חֻקִּ֣ים וְ⁠אֶת־הַ⁠מִּשְׁפָּטִ֔ים אֲשֶׁ֨ר צִוָּ֧ה יְהוָ֛ה אֶת־מֹשֶׁ֖ה עַל־יִשְׂרָאֵ֑ל חֲזַ֣ק וֶ⁠אֱמָ֔ץ אַל־תִּירָ֖א וְ⁠אַל־תֵּחָֽת׃","ʼá֣z ţȧẕĕli֔yẖa ʼim-ţi̇şĕ̌m֗wòr la⁠ʻàş̂wòţ֙ ʼeţ-haֽ⁠ẖuqi֣̇ym wĕ⁠ʼeţ-ha⁠mi̇şĕ̌pá̇ti֔ym ʼàşě֨r ẕiwá֧̇h yĕhwá֛h ʼeţ-mòşě֖h ʻal-yişĕ̂ráʼé֑l ẖàza֣q we⁠ʼèmá֔ẕ ʼal-ţi̇yrá֖ʼ wĕ⁠ʼal-ţé̇ẖáֽţ׃"],[22,14,"וְ⁠הִנֵּ֨ה בְ⁠עָנְיִ֜⁠י הֲכִינ֣וֹתִי לְ⁠בֵית־יְהוָ֗ה זָהָ֞ב כִּכָּרִ֤ים מֵֽאָה־אֶ֨לֶף֙ וְ⁠כֶ֗סֶף אֶ֤לֶף אֲלָפִים֙ כִּכָּרִ֔ים וְ⁠לַ⁠נְּחֹ֤שֶׁת וְ⁠לַ⁠בַּרְזֶל֙ אֵ֣ין מִשְׁקָ֔ל כִּ֥י לָ⁠רֹ֖ב הָיָ֑ה וְ⁠עֵצִ֤ים וַ⁠אֲבָנִים֙ הֲכִינ֔וֹתִי וַ⁠עֲלֵי⁠הֶ֖ם תּוֹסִֽיף׃","wĕ⁠hiné̇֨h bĕ⁠ʻánĕyi֜⁠y hàkiyn֣wòţiy lĕ⁠béyţ-yĕhwá֗h záhá֞b ki̇ká̇ri֤ym méֽʼáh-ʼe֨lep֙ wĕ⁠ke֗sep ʼe֤lep ʼàlápiym֙ ki̇ká̇ri֔ym wĕ⁠la⁠nĕ̇ẖò֤şěţ wĕ⁠la⁠bȧrĕzel֙ ʼé֣yn mişĕ̌qá֔l ki֥̇y lá⁠rò֖b háyá֑h wĕ⁠ʻéẕi֤ym wa⁠ʼàbániym֙ hàkiyn֔wòţiy wa⁠ʻàléy⁠he֖m ţ̇wòsiֽyp׃"],[22,15,"וְ⁠עִמְּ⁠ךָ֤ לָ⁠רֹב֙ עֹשֵׂ֣י מְלָאכָ֔ה חֹצְבִ֕ים וְ⁠חָרָשֵׁ֥י אֶ֖בֶן וָ⁠עֵ֑ץ וְ⁠כָל־חָכָ֖ם בְּ⁠כָל־מְלָאכָֽה׃","wĕ⁠ʻimĕ̇⁠ká֤ lá⁠ròb֙ ʻòşé֣̂y mĕláʼká֔h ẖòẕĕbi֕ym wĕ⁠ẖáráşé֥̌y ʼe֖ben wá⁠ʻé֑ẕ wĕ⁠kál-ẖáká֖m bĕ̇⁠kál-mĕláʼkáֽh׃"],[22,16,"לַ⁠זָּהָ֥ב לַ⁠כֶּ֛סֶף וְ⁠לַ⁠נְּחֹ֥שֶׁת וְ⁠לַ⁠בַּרְזֶ֖ל אֵ֣ין מִסְפָּ֑ר ק֣וּם וַ⁠עֲשֵׂ֔ה וִ⁠יהִ֥י יְהוָ֖ה עִמָּֽ⁠ךְ׃","la⁠zá̇há֥b la⁠kė֛sep wĕ⁠la⁠nĕ̇ẖò֥şěţ wĕ⁠la⁠bȧrĕze֖l ʼé֣yn misĕpá֑̇r q֣ẇm wa⁠ʻàşé̂֔h wi⁠yhi֥y yĕhwá֖h ʻimáֽ̇⁠kĕ׃"],[22,17,"וַ⁠יְצַ֤ו דָּוִיד֙ לְ⁠כָל־שָׂרֵ֣י יִשְׂרָאֵ֔ל לַ⁠עְזֹ֖ר לִ⁠שְׁלֹמֹ֥ה בְנֽ⁠וֹ׃","wa⁠yĕẕa֤w dá̇wiyd֙ lĕ⁠kál-şá̂ré֣y yişĕ̂ráʼé֔l la⁠ʻĕzò֖r li⁠şĕ̌lòmò֥h bĕnֽ⁠wò׃"],[22,18,"הֲ⁠לֹ֨א יְהוָ֤ה אֱלֹֽהֵי⁠כֶם֙ עִמָּ⁠כֶ֔ם וְ⁠הֵנִ֥יחַ לָ⁠כֶ֖ם מִ⁠סָּבִ֑יב כִּ֣י ׀ נָתַ֣ן בְּ⁠יָדִ֗⁠י אֵ֚ת יֹשְׁבֵ֣י הָ⁠אָ֔רֶץ וְ⁠נִכְבְּשָׁ֥ה הָ⁠אָ֛רֶץ לִ⁠פְנֵ֥י יְהוָ֖ה וְ⁠לִ⁠פְנֵ֥י עַמּֽ⁠וֹ׃","hà⁠lò֨ʼ yĕhwá֤h ʼèlòֽhéy⁠kem֙ ʻimá̇⁠ke֔m wĕ⁠héni֥yẖa lá⁠ke֖m mi⁠sá̇bi֑yb ki֣̇y ׀ náţa֣n bĕ̇⁠yádi֗⁠y ʼé֚ţ yòşĕ̌bé֣y há⁠ʼá֔reẕ wĕ⁠nikĕbĕ̇şá֥̌h há⁠ʼá֛reẕ li⁠pĕné֥y yĕhwá֖h wĕ⁠li⁠pĕné֥y ʻaṁֽ⁠wò׃"],[22,19,"עַתָּ֗ה תְּנ֤וּ לְבַבְ⁠כֶם֙ וְ⁠נַפְשְׁ⁠כֶ֔ם לִ⁠דְר֖וֹשׁ לַ⁠יהוָ֣ה אֱלֹהֵי⁠כֶ֑ם וְ⁠ק֗וּמוּ וּ⁠בְנוּ֙ אֶת־מִקְדַּשׁ֙ יְהוָ֣ה הָֽ⁠אֱלֹהִ֔ים לְ⁠הָבִ֞יא אֶת־אֲר֣וֹן בְּרִית־יְהוָ֗ה וּ⁠כְלֵי֙ קֹ֣דֶשׁ הָֽ⁠אֱלֹהִ֔ים לַ⁠בַּ֖יִת הַ⁠נִּבְנֶ֥ה לְ⁠שֵׁם־יְהוָֽה׃פ","ʻaţá̇֗h ţĕ̇n֤ẇ lĕbabĕ⁠kem֙ wĕ⁠napĕşĕ̌⁠ke֔m li⁠dĕr֖wòş̌ la⁠yhwá֣h ʼèlòhéy⁠ke֑m wĕ⁠q֗ẇmẇ ẇ⁠bĕnẇ֙ ʼeţ-miqĕdȧş̌֙ yĕhwá֣h hֽá⁠ʼèlòhi֔ym lĕ⁠hábi֞yʼ ʼeţ-ʼàr֣wòn bĕ̇riyţ-yĕhwá֗h ẇ⁠kĕléy֙ qò֣deş̌ háֽ⁠ʼèlòhi֔ym la⁠bȧ֖yiţ ha⁠ni̇bĕne֥h lĕ⁠şé̌m-yĕhwáֽh׃p"],[23,1,"וְ⁠דָוִ֥יד זָקֵ֖ן וְ⁠שָׂבַ֣ע יָמִ֑ים וַ⁠יַּמְלֵ֛ךְ אֶת־שְׁלֹמֹ֥ה בְנ֖⁠וֹ עַל־יִשְׂרָאֵֽל׃","wĕ⁠dáwi֥yd záqé֖n wĕ⁠şá̂ba֣ʻ yámi֑ym wa⁠yȧmĕlé֛kĕ ʼeţ-şĕ̌lòmò֥h bĕn֖⁠wò ʻal-yişĕ̂ráʼéֽl׃"],[23,2,"וַ⁠יֶּאֱסֹף֙ אֶת־כָּל־שָׂרֵ֣י יִשְׂרָאֵ֔ל וְ⁠הַ⁠כֹּהֲנִ֖ים וְ⁠הַ⁠לְוִיִּֽם׃","wa⁠yėʼèsòp֙ ʼeţ-ká̇l-şá̂ré֣y yişĕ̂ráʼé֔l wĕ⁠ha⁠kò̇hàni֖ym wĕ⁠ha⁠lĕwiyiֽ̇m׃"],[23,3,"וַ⁠יִּסָּֽפְרוּ֙ הַ⁠לְוִיִּ֔ם מִ⁠בֶּ֛ן שְׁלֹשִׁ֥ים שָׁנָ֖ה וָ⁠מָ֑עְלָ⁠ה וַ⁠יְהִ֨י מִסְפָּרָ֤⁠ם לְ⁠גֻלְגְּלֹתָ⁠ם֙ לִ⁠גְבָרִ֔ים שְׁלֹשִׁ֥ים וּ⁠שְׁמוֹנָ֖ה אָֽלֶף׃","wa⁠yi̇sáֽ̇pĕrẇ֙ ha⁠lĕwiyi̇֔m mi⁠bė֛n şĕ̌lòşǐ֥ym şá̌ná֖h wá⁠má֑ʻĕlá⁠h wa⁠yĕhi֨y misĕpá̇rá֤⁠m lĕ⁠gulĕgĕ̇lòţá⁠m֙ li⁠gĕbári֔ym şĕ̌lòşǐ֥ym ẇ⁠şĕ̌mwòná֖h ʼáֽlep׃"],[23,4,"מֵ⁠אֵ֗לֶּה לְ⁠נַצֵּ֨חַ֙ עַל־מְלֶ֣אכֶת בֵּית־יְהוָ֔ה עֶשְׂרִ֥ים וְ⁠אַרְבָּעָ֖ה אָ֑לֶף וְ⁠שֹׁטְרִ֥ים וְ⁠שֹׁפְטִ֖ים שֵׁ֥שֶׁת אֲלָפִֽים׃","mé⁠ʼé֗lėh lĕ⁠naẕé̇֨ẖa֙ ʻal-mĕle֣ʼkeţ bé̇yţ-yĕhwá֔h ʻeşĕ̂ri֥ym wĕ⁠ʼarĕbá̇ʻá֖h ʼá֑lep wĕ⁠şò̌tĕri֥ym wĕ⁠şò̌pĕti֖ym şé֥̌şěţ ʼàlápiֽym׃"],[23,5,"וְ⁠אַרְבַּ֥עַת אֲלָפִ֖ים שֹׁעֲרִ֑ים וְ⁠אַרְבַּ֤עַת אֲלָפִים֙ מְהַֽלְלִ֣ים לַ⁠יהוָ֔ה בַּ⁠כֵּלִ֕ים אֲשֶׁ֥ר עָשִׂ֖יתִי לְ⁠הַלֵּֽל׃","wĕ⁠ʼarĕbȧ֥ʻaţ ʼàlápi֖ym şò̌ʻàri֑ym wĕ⁠ʼarĕbȧ֤ʻaţ ʼàlápiym֙ mĕhaֽlĕli֣ym la⁠yhwá֔h bȧ⁠ké̇li֕ym ʼàşě֥r ʻáşî֖yţiy lĕ⁠haléֽ̇l׃"],[23,6,"וַ⁠יֶּֽחָלְקֵ֥⁠ם דָּוִ֖יד מַחְלְק֑וֹת ס לִ⁠בְנֵ֣י לֵוִ֔י לְ⁠גֵרְשׁ֖וֹן קְהָ֥ת וּ⁠מְרָרִֽי׃ס","wa⁠yėֽẖálĕqé֥⁠m dá̇wi֖yd maẖĕlĕq֑wòţ s li⁠bĕné֣y léwi֔y lĕ⁠gérĕş֖̌wòn qĕhá֥ţ ẇ⁠mĕráriֽy׃s"],[23,7,"לַ⁠גֵּרְשֻׁנִּ֖י לַעְדָּ֥ן וְ⁠שִׁמְעִֽי׃ס","la⁠gé̇rĕşǔni֖̇y laʻĕdá֥̇n wĕ⁠şǐmĕʻiֽy׃s"],[23,8,"בְּנֵ֣י לַעְדָּ֗ן הָ⁠רֹ֧אשׁ יְחִיאֵ֛ל וְ⁠זֵתָ֥ם וְ⁠יוֹאֵ֖ל שְׁלֹשָֽׁה׃ס","bĕ̇né֣y laʻĕdá̇֗n há⁠rò֧ʼş̌ yĕẖiyʼé֛l wĕ⁠zéţá֥m wĕ⁠ywòʼé֖l şĕ̌lòşáֽ̌h׃s"],[23,9,"בְּנֵ֣י שִׁמְעִ֗י שלמות וַ⁠חֲזִיאֵ֛ל וְ⁠הָרָ֖ן שְׁלֹשָׁ֑ה אֵ֛לֶּה רָאשֵׁ֥י הָ⁠אָב֖וֹת לְ⁠לַעְדָּֽן׃ס","bĕ̇né֣y şǐmĕʻi֗y şlmwţ wa⁠ẖàziyʼé֛l wĕ⁠hárá֖n şĕ̌lòşá֑̌h ʼé֛lėh ráʼşé֥̌y há⁠ʼáb֖wòţ lĕ⁠laʻĕdáֽ̇n׃s"],[23,10,"וּ⁠בְנֵ֣י שִׁמְעִ֔י יַ֣חַת זִינָ֔א וִ⁠יע֖וּשׁ וּ⁠בְרִיעָ֑ה אֵ֥לֶּה בְנֵי־שִׁמְעִ֖י אַרְבָּעָֽה׃","ẇ⁠bĕné֣y şǐmĕʻi֔y ya֣ẖaţ ziyná֔ʼ wi⁠yʻ֖ẇş̌ ẇ⁠bĕriyʻá֑h ʼé֥lėh bĕnéy-şǐmĕʻi֖y ʼarĕbá̇ʻáֽh׃"],[23,11,"וַֽ⁠יְהִי־יַ֣חַת הָ⁠רֹ֔אשׁ וְ⁠זִיזָ֖ה הַ⁠שֵּׁנִ֑י וִ⁠יע֤וּשׁ וּ⁠בְרִיעָה֙ לֹֽא־הִרְבּ֣וּ בָנִ֔ים וַ⁠יִּֽהְיוּ֙ לְ⁠בֵ֣ית אָ֔ב לִ⁠פְקֻדָּ֖ה אֶחָֽת׃ס","waֽ⁠yĕhiy-ya֣ẖaţ há⁠rò֔ʼş̌ wĕ⁠ziyzá֖h ha⁠şé̇̌ni֑y wi⁠yʻ֤ẇş̌ ẇ⁠bĕriyʻáh֙ lòֽʼ-hirĕḃ֣ẇ báni֔ym wa⁠yiֽ̇hĕyẇ֙ lĕ⁠bé֣yţ ʼá֔b li⁠pĕqudá֖̇h ʼeẖáֽţ׃s"],[23,12,"בְּנֵ֣י קְהָ֗ת עַמְרָ֥ם יִצְהָ֛ר חֶבְר֥וֹן וְ⁠עֻזִּיאֵ֖ל אַרְבָּעָֽה׃ס","bĕ̇né֣y qĕhá֗ţ ʻamĕrá֥m yiẕĕhá֛r ẖebĕr֥wòn wĕ⁠ʻuzi̇yʼé֖l ʼarĕbá̇ʻáֽh׃s"],[23,13,"בְּנֵ֥י עַמְרָ֖ם אַהֲרֹ֣ן וּ⁠מֹשֶׁ֑ה וַ⁠יִּבָּדֵ֣ל אַהֲרֹ֡ן לְֽ⁠הַקְדִּישׁ⁠וֹ֩ קֹ֨דֶשׁ קָֽדָשִׁ֤ים הֽוּא־וּ⁠בָנָי⁠ו֙ עַד־עוֹלָ֔ם לְ⁠הַקְטִיר֩ לִ⁠פְנֵ֨י יְהוָ֧ה לְ⁠שָׁרְת֛⁠וֹ וּ⁠לְ⁠בָרֵ֥ךְ בִּ⁠שְׁמ֖⁠וֹ עַד־עוֹלָֽם׃","bĕ̇né֥y ʻamĕrá֖m ʼahàrò֣n ẇ⁠mòşě֑h wa⁠yi̇bá̇dé֣l ʼahàrò֡n lĕֽ⁠haqĕdi̇yş̌⁠wò֩ qò֨deş̌ qáֽdáşǐ֤ym hֽẇʼ-ẇ⁠bánáy⁠w֙ ʻad-ʻwòlá֔m lĕ⁠haqĕtiyr֩ li⁠pĕné֨y yĕhwá֧h lĕ⁠şá̌rĕţ֛⁠wò ẇ⁠lĕ⁠báré֥kĕ bi̇⁠şĕ̌m֖⁠wò ʻad-ʻwòláֽm׃"],[23,14,"וּ⁠מֹשֶׁ֖ה אִ֣ישׁ הָ⁠אֱלֹהִ֑ים בָּנָ֕י⁠ו יִקָּרְא֖וּ עַל־שֵׁ֥בֶט הַ⁠לֵּוִֽי׃","ẇ⁠mòşě֖h ʼi֣yş̌ há⁠ʼèlòhi֑ym bá̇ná֕y⁠w yiqá̇rĕʼ֖ẇ ʻal-şé֥̌bet ha⁠lé̇wiֽy׃"],[23,15,"בְּנֵ֣י מֹשֶׁ֔ה גֵּרְשֹׁ֖ם וֶ⁠אֱלִיעֶֽזֶר׃","bĕ̇né֣y mòşě֔h gé̇rĕşò֖̌m we⁠ʼèliyʻeֽzer׃"],[23,16,"בְּנֵ֥י גֵרְשׁ֖וֹם שְׁבוּאֵ֥ל הָ⁠רֹֽאשׁ׃","bĕ̇né֥y gérĕş֖̌wòm şĕ̌bẇʼé֥l há⁠ròֽʼş̌׃"],[23,17,"וַ⁠יִּֽהְי֥וּ בְנֵי־אֱלִיעֶ֖זֶר רְחַבְיָ֣ה הָ⁠רֹ֑אשׁ וְ⁠לֹא־הָיָ֤ה לֶ⁠אֱלִיעֶ֨זֶר֙ בָּנִ֣ים אֲחֵרִ֔ים וּ⁠בְנֵ֥י רְחַבְיָ֖ה רָב֥וּ לְ⁠מָֽעְלָ⁠ה׃","wa⁠yiֽ̇hĕy֥ẇ bĕnéy-ʼèliyʻe֖zer rĕẖabĕyá֣h há⁠rò֑ʼş̌ wĕ⁠lòʼ-háyá֤h le⁠ʼèliyʻe֨zer֙ bá̇ni֣ym ʼàẖéri֔ym ẇ⁠bĕné֥y rĕẖabĕyá֖h ráb֥ẇ lĕ⁠máֽʻĕlá⁠h׃"],[23,18,"בְּנֵ֥י יִצְהָ֖ר שְׁלֹמִ֥ית הָ⁠רֹֽאשׁ׃ס","bĕ̇né֥y yiẕĕhá֖r şĕ̌lòmi֥yţ há⁠ròֽʼş̌׃s"],[23,19,"בְּנֵ֖י חֶבְר֑וֹן יְרִיָּ֤הוּ הָ⁠רֹאשׁ֙ אֲמַרְיָ֣ה הַ⁠שֵּׁנִ֔י יַחֲזִיאֵל֙ הַ⁠שְּׁלִישִׁ֔י וִֽ⁠יקַמְעָ֖ם הָ⁠רְבִיעִֽי׃","bĕ̇né֖y ẖebĕr֑wòn yĕriyá֤̇hẇ há⁠ròʼş̌֙ ʼàmarĕyá֣h ha⁠şé̇̌ni֔y yaẖàziyʼél֙ ha⁠şĕ̇̌liyşǐ֔y wiֽ⁠yqamĕʻá֖m há⁠rĕbiyʻiֽy׃"],[23,20,"בְּנֵ֖י עֻזִּיאֵ֑ל מִיכָ֣ה הָ⁠רֹ֔אשׁ וְ⁠יִשִּׁיָּ֖ה הַ⁠שֵּׁנִֽי׃ס","bĕ̇né֖y ʻuzi̇yʼé֑l miyká֣h há⁠rò֔ʼş̌ wĕ⁠yişi̇̌yá֖̇h ha⁠şé̇̌niֽy׃s"],[23,21,"בְּנֵ֤י מְרָרִי֙ מַחְלִ֣י וּ⁠מוּשִׁ֔י בְּנֵ֥י מַחְלִ֖י אֶלְעָזָ֥ר וְ⁠קִֽישׁ׃","bĕ̇né֤y mĕráriy֙ maẖĕli֣y ẇ⁠mẇşǐ֔y bĕ̇né֥y maẖĕli֖y ʼelĕʻázá֥r wĕ⁠qiֽyş̌׃"],[23,22,"וַ⁠יָּ֨מָת֙ אֶלְעָזָ֔ר וְ⁠לֹא־הָ֥יוּ ל֛⁠וֹ בָּנִ֖ים כִּ֣י אִם־בָּנ֑וֹת וַ⁠יִּשָּׂא֥וּ⁠ם בְּנֵי־קִ֖ישׁ אֲחֵי⁠הֶֽם׃","wa⁠yá̇֨máţ֙ ʼelĕʻázá֔r wĕ⁠lòʼ-há֥yẇ l֛⁠wò bá̇ni֖ym ki֣̇y ʼim-bá̇n֑wòţ wa⁠yi̇şá̇̂ʼ֥ẇ⁠m bĕ̇néy-qi֖yş̌ ʼàẖéy⁠heֽm׃"],[23,23,"בְּנֵ֣י מוּשִׁ֗י מַחְלִ֥י וְ⁠עֵ֛דֶר וִ⁠ירֵמ֖וֹת שְׁלֹשָֽׁה׃","bĕ̇né֣y mẇşǐ֗y maẖĕli֥y wĕ⁠ʻé֛der wi⁠yrém֖wòţ şĕ̌lòşáֽ̌h׃"],[23,24,"אֵ֣לֶּה בְנֵֽי־לֵוִי֩ לְ⁠בֵ֨ית אֲבֹתֵי⁠הֶ֜ם רָאשֵׁ֧י הָ⁠אָב֣וֹת לִ⁠פְקוּדֵי⁠הֶ֗ם בְּ⁠מִסְפַּ֤ר שֵׁמוֹת֙ לְ⁠גֻלְגְּלֹתָ֔⁠ם עֹשֵׂה֙ הַ⁠מְּלָאכָ֔ה לַ⁠עֲבֹדַ֖ת בֵּ֣ית יְהוָ֑ה מִ⁠בֶּ֛ן עֶשְׂרִ֥ים שָׁנָ֖ה וָ⁠מָֽעְלָ⁠ה׃","ʼé֣lėh bĕnéֽy-léwiy֩ lĕ⁠bé֨yţ ʼàbòţéy⁠he֜m ráʼşé֧̌y há⁠ʼáb֣wòţ li⁠pĕqẇdéy⁠he֗m bĕ̇⁠misĕpȧ֤r şé̌mwòţ֙ lĕ⁠gulĕgĕ̇lòţá֔⁠m ʻòşé̂h֙ ha⁠mĕ̇láʼká֔h la⁠ʻàbòda֖ţ bé֣̇yţ yĕhwá֑h mi⁠bė֛n ʻeşĕ̂ri֥ym şá̌ná֖h wá⁠máֽʻĕlá⁠h׃"],[23,25,"כִּ֚י אָמַ֣ר דָּוִ֔יד הֵנִ֛יחַ יְהוָ֥ה אֱלֹהֵֽי־יִשְׂרָאֵ֖ל לְ⁠עַמּ֑⁠וֹ וַ⁠יִּשְׁכֹּ֥ן בִּ⁠ירוּשָׁלִַ֖ם עַד־לְ⁠עוֹלָֽם׃","ki֚̇y ʼáma֣r dá̇wi֔yd héni֛yẖa yĕhwá֥h ʼèlòhéֽy-yişĕ̂ráʼé֖l lĕ⁠ʻaṁ֑⁠wò wa⁠yi̇şĕ̌kò֥̇n bi̇⁠yrẇşá̌lia֖m ʻad-lĕ⁠ʻwòláֽm׃"],[23,26,"וְ⁠גַ֖ם לַ⁠לְוִיִּ֑ם אֵין־לָ⁠שֵׂ֧את אֶת־הַ⁠מִּשְׁכָּ֛ן וְ⁠אֶת־כָּל־כֵּלָ֖י⁠ו לַ⁠עֲבֹדָתֽ⁠וֹ׃","wĕ⁠ga֖m la⁠lĕwiyi֑̇m ʼéyn-lá⁠şé֧̂ʼţ ʼeţ-ha⁠mi̇şĕ̌ká֛̇n wĕ⁠ʼeţ-ká̇l-ké̇lá֖y⁠w la⁠ʻàbòdáţֽ⁠wò׃"],[23,27,"כִּ֣י בְ⁠דִבְרֵ֤י דָוִיד֙ הָ⁠אַ֣חֲרֹנִ֔ים הֵ֖מָּה מִסְפַּ֣ר בְּנֵי־לֵוִ֑י מִ⁠בֶּ֛ן עֶשְׂרִ֥ים שָׁנָ֖ה וּ⁠לְ⁠מָֽעְלָ⁠ה׃","ki֣̇y bĕ⁠dibĕré֤y dáwiyd֙ há⁠ʼa֣ẖàròni֔ym hé֖má̇h misĕpȧ֣r bĕ̇néy-léwi֑y mi⁠bė֛n ʻeşĕ̂ri֥ym şá̌ná֖h ẇ⁠lĕ⁠máֽʻĕlá⁠h׃"],[23,28,"כִּ֣י מַעֲמָדָ֞⁠ם לְ⁠יַד־בְּנֵ֣י אַהֲרֹ֗ן לַ⁠עֲבֹדַת֙ בֵּ֣ית יְהוָ֔ה עַל־הַ⁠חֲצֵרוֹת֙ וְ⁠עַל־הַ⁠לְּשָׁכ֔וֹת וְ⁠עַֽל־טָהֳרַ֖ת לְ⁠כָל־קֹ֑דֶשׁ וּ⁠מַֽעֲשֵׂ֔ה עֲבֹדַ֖ת בֵּ֥ית הָ⁠אֱלֹהִֽים׃","ki֣̇y maʻàmádá֞⁠m lĕ⁠yad-bĕ̇né֣y ʼahàrò֗n la⁠ʻàbòdaţ֙ bé֣̇yţ yĕhwá֔h ʻal-ha⁠ẖàẕérwòţ֙ wĕ⁠ʻal-ha⁠lĕ̇şá̌k֔wòţ wĕ⁠ʻaֽl-táhora֖ţ lĕ⁠kál-qò֑deş̌ ẇ⁠mֽaʻàşé̂֔h ʻàbòda֖ţ bé֥̇yţ há⁠ʼèlòhiֽym׃"],[23,29,"וּ⁠לְ⁠לֶ֨חֶם הַֽ⁠מַּעֲרֶ֜כֶת וּ⁠לְ⁠סֹ֤לֶת לְ⁠מִנְחָה֙ וְ⁠לִ⁠רְקִיקֵ֣י הַ⁠מַּצּ֔וֹת וְ⁠לַֽ⁠מַּחֲבַ֖ת וְ⁠לַ⁠מֻּרְבָּ֑כֶת וּ⁠לְ⁠כָל־מְשׂוּרָ֖ה וּ⁠מִדָּֽה׃","ẇ⁠lĕ⁠le֨ẖem haֽ⁠mȧʻàre֜keţ ẇ⁠lĕ⁠sò֤leţ lĕ⁠minĕẖáh֙ wĕ⁠li⁠rĕqiyqé֣y ha⁠mȧẕ̇֔wòţ wĕ⁠laֽ⁠mȧẖàba֖ţ wĕ⁠la⁠mu̇rĕbá֑̇keţ ẇ⁠lĕ⁠kál-mĕş̂ẇrá֖h ẇ⁠midáֽ̇h׃"],[23,30,"וְ⁠לַ⁠עֲמֹד֙ בַּ⁠בֹּ֣קֶר בַּ⁠בֹּ֔קֶר לְ⁠הֹד֥וֹת וּ⁠לְ⁠הַלֵּ֖ל לַ⁠יהוָ֑ה וְ⁠כֵ֖ן לָ⁠עָֽרֶב׃","wĕ⁠la⁠ʻàmòd֙ bȧ⁠bò֣̇qer bȧ⁠bò̇֔qer lĕ⁠hòd֥wòţ ẇ⁠lĕ⁠halé֖̇l la⁠yhwá֑h wĕ⁠ké֖n lá⁠ʻáֽreb׃"],[23,31,"וּ⁠לְ⁠כֹ֨ל הַעֲל֤וֹת עֹלוֹת֙ לַ⁠יהוָ֔ה לַ⁠שַּׁבָּת֔וֹת לֶ⁠חֳדָשִׁ֖ים וְ⁠לַ⁠מֹּעֲדִ֑ים בְּ⁠מִסְפָּ֨ר כְּ⁠מִשְׁפָּ֧ט עֲלֵי⁠הֶ֛ם תָּמִ֖יד לִ⁠פְנֵ֥י יְהוָֽה׃","ẇ⁠lĕ⁠kò֨l haʻàl֤wòţ ʻòlwòţ֙ la⁠yhwá֔h la⁠şȧ̌bá̇ţ֔wòţ le⁠ẖodáşǐ֖ym wĕ⁠la⁠mò̇ʻàdi֑ym bĕ̇⁠misĕpá̇֨r kĕ̇⁠mişĕ̌pá֧̇t ʻàléy⁠he֛m ţá̇mi֖yd li⁠pĕné֥y yĕhwáֽh׃"],[23,32,"וְ⁠שָׁמְר֞וּ אֶת־מִשְׁמֶ֣רֶת אֹֽהֶל־מוֹעֵ֗ד וְ⁠אֵת֙ מִשְׁמֶ֣רֶת הַ⁠קֹּ֔דֶשׁ וּ⁠מִשְׁמֶ֕רֶת בְּנֵ֥י אַהֲרֹ֖ן אֲחֵי⁠הֶ֑ם לַ⁠עֲבֹדַ֖ת בֵּ֥ית יְהוָֽה׃פ","wĕ⁠şá̌mĕr֞ẇ ʼeţ-mişĕ̌me֣reţ ʼòֽhel-mwòʻé֗d wĕ⁠ʼéţ֙ mişĕ̌me֣reţ ha⁠qò̇֔deş̌ ẇ⁠mişĕ̌me֕reţ bĕ̇né֥y ʼahàrò֖n ʼàẖéy⁠he֑m la⁠ʻàbòda֖ţ bé֥̇yţ yĕhwáֽh׃p"],[24,1,"וְ⁠לִ⁠בְנֵ֥י אַהֲרֹ֖ן מַחְלְקוֹתָ֑⁠ם בְּנֵ֣י אַהֲרֹ֔ן נָדָב֙ וַ⁠אֲבִיה֔וּא אֶלְעָזָ֖ר וְ⁠אִיתָמָֽר׃","wĕ⁠li⁠bĕné֥y ʼahàrò֖n maẖĕlĕqwòţá֑⁠m bĕ̇né֣y ʼahàrò֔n nádáb֙ wa⁠ʼàbiyh֔ẇʼ ʼelĕʻázá֖r wĕ⁠ʼiyţámáֽr׃"],[24,2,"וַ⁠יָּ֨מָת נָדָ֤ב וַ⁠אֲבִיהוּא֙ לִ⁠פְנֵ֣י אֲבִי⁠הֶ֔ם וּ⁠בָנִ֖ים לֹא־הָי֣וּ לָ⁠הֶ֑ם וַֽ⁠יְכַהֲנ֔וּ אֶלְעָזָ֖ר וְ⁠אִיתָמָֽר׃","wa⁠yá̇֨máţ nádá֤b wa⁠ʼàbiyhẇʼ֙ li⁠pĕné֣y ʼàbiy⁠he֔m ẇ⁠báni֖ym lòʼ-háy֣ẇ lá⁠he֑m waֽ⁠yĕkahàn֔ẇ ʼelĕʻázá֖r wĕ⁠ʼiyţámáֽr׃"],[24,3,"וַ⁠יֶּֽחָלְקֵ֣⁠ם דָּוִ֔יד וְ⁠צָדוֹק֙ מִן־בְּנֵ֣י אֶלְעָזָ֔ר וַ⁠אֲחִימֶ֖לֶךְ מִן־בְּנֵ֣י אִיתָמָ֑ר לִ⁠פְקֻדָּתָ֖⁠ם בַּ⁠עֲבֹדָתָֽ⁠ם׃","wa⁠yėֽẖálĕqé֣⁠m dá̇wi֔yd wĕ⁠ẕádwòq֙ min-bĕ̇né֣y ʼelĕʻázá֔r wa⁠ʼàẖiyme֖lekĕ min-bĕ̇né֣y ʼiyţámá֑r li⁠pĕqudá̇ţá֖⁠m bȧ⁠ʻàbòdáţáֽ⁠m׃"],[24,4,"וַ⁠יִּמָּצְא֣וּ בְֽנֵי־אֶלְעָזָ֡ר רַבִּ֞ים לְ⁠רָאשֵׁ֧י הַ⁠גְּבָרִ֛ים מִן־בְּנֵ֥י אִיתָמָ֖ר וַֽ⁠יַּחְלְק֑וּ⁠ם לִ⁠בְנֵ֨י אֶלְעָזָ֜ר רָאשִׁ֤ים לְ⁠בֵית־אָבוֹת֙ שִׁשָּׁ֣ה עָשָׂ֔ר וְ⁠לִ⁠בְנֵ֧י אִיתָמָ֛ר לְ⁠בֵ֥ית אֲבוֹתָ֖⁠ם שְׁמוֹנָֽה׃","wa⁠yi̇má̇ẕĕʼ֣ẇ bĕֽnéy-ʼelĕʻázá֡r rabi̇֞ym lĕ⁠ráʼşé֧̌y ha⁠gĕ̇bári֛ym min-bĕ̇né֥y ʼiyţámá֖r waֽ⁠yȧẖĕlĕq֑ẇ⁠m li⁠bĕné֨y ʼelĕʻázá֜r ráʼşǐ֤ym lĕ⁠béyţ-ʼábwòţ֙ şǐşá֣̇̌h ʻáşá̂֔r wĕ⁠li⁠bĕné֧y ʼiyţámá֛r lĕ⁠bé֥yţ ʼàbwòţá֖⁠m şĕ̌mwònáֽh׃"],[24,5,"וַ⁠יַּחְלְק֥וּ⁠ם בְּ⁠גוֹרָל֖וֹת אֵ֣לֶּה עִם־אֵ֑לֶּה כִּי־הָי֤וּ שָֽׂרֵי־קֹ֨דֶשׁ֙ וְ⁠שָׂרֵ֣י הָ⁠אֱלֹהִ֔ים מִ⁠בְּנֵ֥י אֶלְעָזָ֖ר וּ⁠בִ⁠בְנֵ֥י אִיתָמָֽר׃ס","wa⁠yȧẖĕlĕq֥ẇ⁠m bĕ̇⁠gwòrál֖wòţ ʼé֣lėh ʻim-ʼé֑lėh ki̇y-háy֤ẇ şáֽ̂réy-qò֨deş̌֙ wĕ⁠şá̂ré֣y há⁠ʼèlòhi֔ym mi⁠bĕ̇né֥y ʼelĕʻázá֖r ẇ⁠bi⁠bĕné֥y ʼiyţámáֽr׃s"],[24,6,"וַֽ⁠יִּכְתְּבֵ֡⁠ם שְֽׁמַֽעְיָה֩ בֶן־נְתַנְאֵ֨ל הַ⁠סּוֹפֵ֜ר מִן־הַ⁠לֵּוִ֗י לִ⁠פְנֵ֨י הַ⁠מֶּ֤לֶךְ וְ⁠הַ⁠שָּׂרִים֙ וְ⁠צָד֣וֹק הַ⁠כֹּהֵ֗ן וַ⁠אֲחִימֶ֨לֶךְ֙ בֶּן־אֶבְיָתָ֔ר וְ⁠רָאשֵׁי֙ הָֽ⁠אָב֔וֹת לַ⁠כֹּהֲנִ֖ים וְ⁠לַ⁠לְוִיִּ֑ם בֵּֽית־אָ֣ב אֶחָ֗ד אָחֻז֙ לְ⁠אֶלְעָזָ֔ר וְ⁠אָחֻ֥ז ׀ אָחֻ֖ז לְ⁠אִיתָמָֽר׃פ","wֽa⁠yi̇kĕţĕ̇bé֡⁠m şĕֽ̌maֽʻĕyáh֩ ben-nĕţanĕʼé֨l ha⁠ṡwòpé֜r min-ha⁠lé̇wi֗y li⁠pĕné֨y ha⁠mė֤lekĕ wĕ⁠ha⁠şá̇̂riym֙ wĕ⁠ẕád֣wòq ha⁠kò̇hé֗n wa⁠ʼàẖiyme֨lekĕ֙ bėn-ʼebĕyáţá֔r wĕ⁠ráʼşé̌y֙ háֽ⁠ʼáb֔wòţ la⁠kò̇hàni֖ym wĕ⁠la⁠lĕwiyi֑̇m béֽ̇yţ-ʼá֣b ʼeẖá֗d ʼáẖuz֙ lĕ⁠ʼelĕʻázá֔r wĕ⁠ʼáẖu֥z ׀ ʼáẖu֖z lĕ⁠ʼiyţámáֽr׃p"],[24,7,"וַ⁠יֵּצֵ֞א הַ⁠גּוֹרָ֤ל הָ⁠רִאשׁוֹן֙ לִ⁠יה֣וֹיָרִ֔יב לִֽ⁠ידַעְיָ֖ה הַ⁠שֵּׁנִֽי׃","wa⁠yé̇ẕé֞ʼ ha⁠ġwòrá֤l há⁠riʼş̌wòn֙ li⁠yh֣wòyári֔yb liֽ⁠ydaʻĕyá֖h ha⁠şé̇̌niֽy׃"],[24,8,"לְ⁠חָרִם֙ הַ⁠שְּׁלִישִׁ֔י לִ⁠שְׂעֹרִ֖ים הָ⁠רְבִעִֽי׃","lĕ⁠ẖárim֙ ha⁠şĕ̇̌liyşǐ֔y li⁠şĕ̂ʻòri֖ym há⁠rĕbiʻiֽy׃"],[24,9,"לְ⁠מַלְכִּיָּה֙ הַ⁠חֲמִישִׁ֔י לְ⁠מִיָּמִ֖ן הַ⁠שִּׁשִּֽׁי׃","lĕ⁠malĕki̇yá̇h֙ ha⁠ẖàmiyşǐ֔y lĕ⁠miyá̇mi֖n ha⁠şi̇̌şiֽ̇̌y׃"],[24,10,"לְ⁠הַקּוֹץ֙ הַ⁠שְּׁבִעִ֔י לַ⁠אֲבִיָּ֖ה הַ⁠שְּׁמִינִֽי׃","lĕ⁠haq̇wòẕ֙ ha⁠şĕ̇̌biʻi֔y la⁠ʼàbiyá֖̇h ha⁠şĕ̇̌miyniֽy׃"],[24,11,"לְ⁠יֵשׁ֨וּעַ֙ הַ⁠תְּשִׁעִ֔י לִ⁠שְׁכַנְיָ֖הוּ הָ⁠עֲשִׂרִֽי׃","lĕ⁠yéş̌֨ẇʻa֙ ha⁠ţĕ̇şǐʻi֔y li⁠şĕ̌kanĕyá֖hẇ há⁠ʻàşîriֽy׃"],[24,12,"לְ⁠אֶלְיָשִׁיב֙ עַשְׁתֵּ֣י עָשָׂ֔ר לְ⁠יָקִ֖ים שְׁנֵ֥ים עָשָֽׂר׃","lĕ⁠ʼelĕyáşǐyb֙ ʻaşĕ̌ţé֣̇y ʻáşá̂֔r lĕ⁠yáqi֖ym şĕ̌né֥ym ʻáşáֽ̂r׃"],[24,13,"לְ⁠חֻפָּה֙ שְׁלֹשָׁ֣ה עָשָׂ֔ר לְ⁠יֶֽשֶׁבְאָ֖ב אַרְבָּעָ֥ה עָשָֽׂר׃","lĕ⁠ẖupá̇h֙ şĕ̌lòşá֣̌h ʻáşá̂֔r lĕ⁠yeֽşěbĕʼá֖b ʼarĕbá̇ʻá֥h ʻáşáֽ̂r׃"],[24,14,"לְ⁠בִלְגָּה֙ חֲמִשָּׁ֣ה עָשָׂ֔ר לְ⁠אִמֵּ֖ר שִׁשָּׁ֥ה עָשָֽׂר׃","lĕ⁠bilĕgá̇h֙ ẖàmişá֣̇̌h ʻáşá̂֔r lĕ⁠ʼimé֖̇r şǐşá֥̇̌h ʻáşáֽ̂r׃"],[24,15,"לְ⁠חֵזִיר֙ שִׁבְעָ֣ה עָשָׂ֔ר לְ⁠הַ⁠פִּצֵּ֖ץ שְׁמוֹנָ֥ה עָשָֽׂר׃","lĕ⁠ẖéziyr֙ şǐbĕʻá֣h ʻáşá̂֔r lĕ⁠ha⁠pi̇ẕé֖̇ẕ şĕ̌mwòná֥h ʻáşáֽ̂r׃"],[24,16,"לִֽ⁠פְתַחְיָה֙ תִּשְׁעָ֣ה עָשָׂ֔ר לִֽ⁠יחֶזְקֵ֖אל הָ⁠עֶשְׂרִֽים׃","liֽ⁠pĕţaẖĕyáh֙ ţi̇şĕ̌ʻá֣h ʻáşá̂֔r liֽ⁠yẖezĕqé֖ʼl há⁠ʻeşĕ̂riֽym׃"],[24,17,"לְ⁠יָכִין֙ אֶחָ֣ד וְ⁠עֶשְׂרִ֔ים לְ⁠גָמ֖וּל שְׁנַ֥יִם וְ⁠עֶשְׂרִֽים׃","lĕ⁠yákiyn֙ ʼeẖá֣d wĕ⁠ʻeşĕ̂ri֔ym lĕ⁠gám֖ẇl şĕ̌na֥yim wĕ⁠ʻeşĕ̂riֽym׃"],[24,18,"לִ⁠דְלָיָ֨הוּ֙ שְׁלֹשָׁ֣ה וְ⁠עֶשְׂרִ֔ים לְ⁠מַֽעַזְיָ֖הוּ אַרְבָּעָ֥ה וְ⁠עֶשְׂרִֽים׃פ","li⁠dĕláyá֨hẇ֙ şĕ̌lòşá֣̌h wĕ⁠ʻeşĕ̂ri֔ym lĕ⁠maֽʻazĕyá֖hẇ ʼarĕbá̇ʻá֥h wĕ⁠ʻeşĕ̂riֽym׃p"],[24,19,"אֵ֣לֶּה פְקֻדָּתָ֞⁠ם לַ⁠עֲבֹדָתָ֗⁠ם לָ⁠ב֤וֹא לְ⁠בֵית־יְהוָה֙ כְּ⁠מִשְׁפָּטָ֔⁠ם בְּ⁠יַ֖ד אַהֲרֹ֣ן אֲבִי⁠הֶ֑ם כַּ⁠אֲשֶׁ֣ר צִוָּ֔⁠הוּ יְהוָ֖ה אֱלֹהֵ֥י יִשְׂרָאֵֽל׃פ","ʼé֣lėh pĕqudá̇ţá֞⁠m la⁠ʻàbòdáţá֗⁠m lá⁠b֤wòʼ lĕ⁠béyţ-yĕhwáh֙ kĕ̇⁠mişĕ̌pá̇tá֔⁠m bĕ̇⁠ya֖d ʼahàrò֣n ʼàbiy⁠he֑m kȧ⁠ʼàşě֣r ẕiwá̇֔⁠hẇ yĕhwá֖h ʼèlòhé֥y yişĕ̂ráʼéֽl׃p"],[24,20,"וְ⁠לִ⁠בְנֵ֥י לֵוִ֖י הַ⁠נּוֹתָרִ֑ים לִ⁠בְנֵ֤י עַמְרָם֙ שֽׁוּבָאֵ֔ל לִ⁠בְנֵ֥י שׁוּבָאֵ֖ל יֶחְדְּיָֽהוּ׃","wĕ⁠li⁠bĕné֥y léwi֖y ha⁠ṅwòţári֑ym li⁠bĕné֤y ʻamĕrám֙ şֽ̌ẇbáʼé֔l li⁠bĕné֥y ş̌ẇbáʼé֖l yeẖĕdĕ̇yáֽhẇ׃"],[24,21,"לִ⁠רְחַבְיָ֑הוּ לִ⁠בְנֵ֣י רְחַבְיָ֔הוּ הָ⁠רֹ֖אשׁ יִשִּׁיָּֽה׃","li⁠rĕẖabĕyá֑hẇ li⁠bĕné֣y rĕẖabĕyá֔hẇ há⁠rò֖ʼş̌ yişi̇̌yáֽ̇h׃"],[24,22,"לַ⁠יִּצְהָרִ֣י שְׁלֹמ֔וֹת לִ⁠בְנֵ֥י שְׁלֹמ֖וֹת יָֽחַת׃","la⁠yi̇ẕĕhári֣y şĕ̌lòm֔wòţ li⁠bĕné֥y şĕ̌lòm֖wòţ yáֽẖaţ׃"],[24,23,"וּ⁠בְנָ֖י יְרִיָּ֑הוּ אֲמַרְיָ֨הוּ֙ הַ⁠שֵּׁנִ֔י יַחֲזִיאֵל֙ הַ⁠שְּׁלִישִׁ֔י יְקַמְעָ֖ם הָ⁠רְבִיעִֽי׃","ẇ⁠bĕná֖y yĕriyá֑̇hẇ ʼàmarĕyá֨hẇ֙ ha⁠şé̇̌ni֔y yaẖàziyʼél֙ ha⁠şĕ̇̌liyşǐ֔y yĕqamĕʻá֖m há⁠rĕbiyʻiֽy׃"],[24,24,"בְּנֵ֤י עֻזִּיאֵל֙ מִיכָ֔ה לִ⁠בְנֵ֥י מִיכָ֖ה שמור׃","bĕ̇né֤y ʻuzi̇yʼél֙ miyká֔h li⁠bĕné֥y miyká֖h şmwr׃"],[24,25,"אֲחִ֤י מִיכָה֙ יִשִּׁיָּ֔ה לִ⁠בְנֵ֥י יִשִּׁיָּ֖ה זְכַרְיָֽהוּ׃","ʼàẖi֤y miykáh֙ yişi̇̌yá̇֔h li⁠bĕné֥y yişi̇̌yá֖̇h zĕkarĕyáֽhẇ׃"],[24,26,"בְּנֵ֤י מְרָרִי֙ מַחְלִ֣י וּ⁠מוּשִׁ֔י בְּנֵ֖י יַעֲזִיָּ֥הֽוּ בְנֽ⁠וֹ׃","bĕ̇né֤y mĕráriy֙ maẖĕli֣y ẇ⁠mẇşǐ֔y bĕ̇né֖y yaʻàziyá֥̇hֽẇ bĕnֽ⁠wò׃"],[24,27,"בְּנֵ֖י מְרָרִ֑י לְ⁠יַֽעֲזִיָּ֣הֽוּ בְנ֔⁠וֹ וְ⁠שֹׁ֥הַם וְ⁠זַכּ֖וּר וְ⁠עִבְרִֽי׃","bĕ̇né֖y mĕrári֑y lĕ⁠yaֽʻàziyá֣̇hֽẇ bĕn֔⁠wò wĕ⁠şò֥̌ham wĕ⁠zak֖̇ẇr wĕ⁠ʻibĕriֽy׃"],[24,28,"לְ⁠מַחְלִי֙ אֶלְעָזָ֔ר וְ⁠לֹא־הָ֥יָה ל֖⁠וֹ בָּנִֽים׃","lĕ⁠maẖĕliy֙ ʼelĕʻázá֔r wĕ⁠lòʼ-há֥yáh l֖⁠wò bá̇niֽym׃"],[24,29,"לְ⁠קִ֖ישׁ בְּנֵי־קִ֥ישׁ יְרַחְמְאֵֽל׃","lĕ⁠qi֖yş̌ bĕ̇néy-qi֥yş̌ yĕraẖĕmĕʼéֽl׃"],[24,30,"וּ⁠בְנֵ֣י מוּשִׁ֔י מַחְלִ֥י וְ⁠עֵ֖דֶר וִ⁠ירִימ֑וֹת אֵ֛לֶּה בְּנֵ֥י הַ⁠לְוִיִּ֖ם לְ⁠בֵ֥ית אֲבֹתֵי⁠הֶֽם׃","ẇ⁠bĕné֣y mẇşǐ֔y maẖĕli֥y wĕ⁠ʻé֖der wi⁠yriym֑wòţ ʼé֛lėh bĕ̇né֥y ha⁠lĕwiyi֖̇m lĕ⁠bé֥yţ ʼàbòţéy⁠heֽm׃"],[24,31,"וַ⁠יַּפִּילוּ֩ גַם־הֵ֨ם גּוֹרָל֜וֹת לְ⁠עֻמַּ֣ת ׀ אֲחֵי⁠הֶ֣ם בְּנֵֽי־אַהֲרֹ֗ן לִ⁠פְנֵ֨י דָוִ֤יד הַ⁠מֶּ֨לֶךְ֙ וְ⁠צָד֣וֹק וַ⁠אֲחִימֶ֔לֶךְ וְ⁠רָאשֵׁי֙ הָֽ⁠אָב֔וֹת לַ⁠כֹּהֲנִ֖ים וְ⁠לַ⁠לְוִיִּ֑ם אָב֣וֹת הָ⁠רֹ֔אשׁ לְ⁠עֻמַּ֖ת אָחִ֥י⁠ו הַ⁠קָּטָֽן׃ס","wa⁠yȧpi̇ylẇ֩ gam-hé֨m ġwòrál֜wòţ lĕ⁠ʻumȧ֣ţ ׀ ʼàẖéy⁠he֣m bĕ̇néֽy-ʼahàrò֗n li⁠pĕné֨y dáwi֤yd ha⁠mė֨lekĕ֙ wĕ⁠ẕád֣wòq wa⁠ʼàẖiyme֔lekĕ wĕ⁠ráʼşé̌y֙ háֽ⁠ʼáb֔wòţ la⁠kò̇hàni֖ym wĕ⁠la⁠lĕwiyi֑̇m ʼáb֣wòţ há⁠rò֔ʼş̌ lĕ⁠ʻumȧ֖ţ ʼáẖi֥y⁠w ha⁠qá̇táֽn׃s"],[25,1,"וַ⁠יַּבְדֵּ֣ל דָּוִיד֩ וְ⁠שָׂרֵ֨י הַ⁠צָּבָ֜א לַ⁠עֲבֹדָ֗ה לִ⁠בְנֵ֤י אָסָף֙ וְ⁠הֵימָ֣ן וִֽ⁠ידוּת֔וּן ה⁠נביאים בְּ⁠כִנֹּר֥וֹת בִּ⁠נְבָלִ֖ים וּ⁠בִ⁠מְצִלְתָּ֑יִם וַֽ⁠יְהִי֙ מִסְפָּרָ֔⁠ם אַנְשֵׁ֥י מְלָאכָ֖ה לַ⁠עֲבֹדָתָֽ⁠ם׃","wa⁠yȧbĕdé֣̇l dá̇wiyd֩ wĕ⁠şá̂ré֨y ha⁠ẕá̇bá֜ʼ la⁠ʻàbòdá֗h li⁠bĕné֤y ʼásáp֙ wĕ⁠héymá֣n wiֽ⁠ydẇţ֔ẇn h⁠nbyʼym bĕ̇⁠kinò̇r֥wòţ bi̇⁠nĕbáli֖ym ẇ⁠bi⁠mĕẕilĕţá֑̇yim waֽ⁠yĕhiy֙ misĕpá̇rá֔⁠m ʼanĕşé֥̌y mĕláʼká֖h la⁠ʻàbòdáţáֽ⁠m׃"],[25,2,"לִ⁠בְנֵ֣י אָסָ֗ף זַכּ֧וּר וְ⁠יוֹסֵ֛ף וּ⁠נְתַנְיָ֥ה וַ⁠אֲשַׂרְאֵ֖לָה בְּנֵ֣י אָסָ֑ף עַ֚ל יַד־אָסָ֔ף הַ⁠נִּבָּ֖א עַל־יְדֵ֥י הַ⁠מֶּֽלֶךְ׃","li⁠bĕné֣y ʼásá֗p zak֧̇ẇr wĕ⁠ywòsé֛p ẇ⁠nĕţanĕyá֥h wa⁠ʼàşârĕʼé֖láh bĕ̇né֣y ʼásá֑p ʻa֚l yad-ʼásá֔p ha⁠ni̇bá֖̇ʼ ʻal-yĕdé֥y ha⁠mėֽlekĕ׃"],[25,3,"לִ⁠ידוּת֑וּן בְּנֵ֣י יְדוּת֡וּן גְּדַלְיָ֡הוּ וּ⁠צְרִ֡י וִֽ֠⁠ישַׁעְיָהוּ חֲשַׁבְיָ֨הוּ וּ⁠מַתִּתְיָ֜הוּ שִׁשָּׁ֗ה עַל֩ יְדֵ֨י אֲבִי⁠הֶ֤ם יְדוּתוּן֙ בַּ⁠כִּנּ֔וֹר הַ⁠נִּבָּ֕א עַל־הֹד֥וֹת וְ⁠הַלֵּ֖ל לַ⁠יהוָֽה׃ס","li⁠ydẇţ֑ẇn bĕ̇né֣y yĕdẇţ֡ẇn gĕ̇dalĕyá֡hẇ ẇ⁠ẕĕri֡y wiֽ֠⁠yşǎʻĕyáhẇ ẖàşǎbĕyá֨hẇ ẇ⁠maţi̇ţĕyá֜hẇ şǐşá̇̌֗h ʻal֩ yĕdé֨y ʼàbiy⁠he֤m yĕdẇţẇn֙ bȧ⁠ki̇ṅ֔wòr ha⁠ni̇bá̇֕ʼ ʻal-hòd֥wòţ wĕ⁠halé֖̇l la⁠yhwáֽh׃s"],[25,4,"לְ⁠הֵימָ֑ן בְּנֵ֣י הֵימָ֡ן בֻּקִּיָּ֡הוּ מַתַּנְיָ֡הוּ עֻ֠זִּיאֵל שְׁבוּאֵ֨ל וִֽ⁠ירִימ֜וֹת חֲנַנְיָ֣ה חֲנָ֗נִי אֱלִיאָ֤תָה גִדַּ֨לְתִּי֙ וְ⁠רֹמַ֣מְתִּי עֶ֔זֶר יָשְׁבְּקָ֣שָׁה מַלּ֔וֹתִי הוֹתִ֖יר מַחֲזִיאֽוֹת׃","lĕ⁠héymá֑n bĕ̇né֣y héymá֡n bu̇qi̇yá̇֡hẇ maţȧnĕyá֡hẇ ʻu֠zi̇yʼél şĕ̌bẇʼé֨l wiֽ⁠yriym֜wòţ ẖànanĕyá֣h ẖàná֗niy ʼèliyʼá֤ţáh gidȧ֨lĕţi̇y֙ wĕ⁠ròma֣mĕţi̇y ʻe֔zer yáşĕ̌bĕ̇qá֣şá̌h mal̇֔wòţiy hwòţi֖yr maẖàziyʼֽwòţ׃"],[25,5,"כָּל־אֵ֨לֶּה בָנִ֜ים לְ⁠הֵימָ֗ן חֹזֵ֥ה הַ⁠מֶּ֛לֶךְ בְּ⁠דִבְרֵ֥י הָ⁠אֱלֹהִ֖ים לְ⁠הָרִ֣ים קָ֑רֶן וַ⁠יִּתֵּ֨ן הָ⁠אֱלֹהִ֜ים לְ⁠הֵימָ֗ן בָּנִ֛ים אַרְבָּעָ֥ה עָשָׂ֖ר וּ⁠בָנ֥וֹת שָׁלֽוֹשׁ׃","ká̇l-ʼé֨lėh báni֜ym lĕ⁠héymá֗n ẖòzé֥h ha⁠mė֛lekĕ bĕ̇⁠dibĕré֥y há⁠ʼèlòhi֖ym lĕ⁠hári֣ym qá֑ren wa⁠yi̇ţé̇֨n há⁠ʼèlòhi֜ym lĕ⁠héymá֗n bá̇ni֛ym ʼarĕbá̇ʻá֥h ʻáşá֖̂r ẇ⁠bán֥wòţ şá̌lֽwòş̌׃"],[25,6,"כָּל־אֵ֣לֶּה עַל־יְדֵי֩ אֲבִי⁠הֶ֨ם בַּ⁠שִּׁ֜יר בֵּ֣ית יְהוָ֗ה בִּ⁠מְצִלְתַּ֨יִם֙ נְבָלִ֣ים וְ⁠כִנֹּר֔וֹת לַ⁠עֲבֹדַ֖ת בֵּ֣ית הָ⁠אֱלֹהִ֑ים עַ֚ל יְדֵ֣י הַ⁠מֶּ֔לֶךְ ס אָסָ֥ף וִ⁠ידוּת֖וּן וְ⁠הֵימָֽן׃","ká̇l-ʼé֣lėh ʻal-yĕdéy֩ ʼàbiy⁠he֨m bȧ⁠şi̇̌֜yr bé֣̇yţ yĕhwá֗h bi̇⁠mĕẕilĕţȧ֨yim֙ nĕbáli֣ym wĕ⁠kinò̇r֔wòţ la⁠ʻàbòda֖ţ bé֣̇yţ há⁠ʼèlòhi֑ym ʻa֚l yĕdé֣y ha⁠mė֔lekĕ s ʼásá֥p wi⁠ydẇţ֖ẇn wĕ⁠héymáֽn׃"],[25,7,"וַ⁠יְהִ֤י מִסְפָּרָ⁠ם֙ עִם־אֲחֵי⁠הֶ֔ם מְלֻמְּדֵי־שִׁ֖יר לַ⁠יהוָ֑ה כָּל־הַ֨⁠מֵּבִ֔ין מָאתַ֖יִם שְׁמוֹנִ֥ים וּ⁠שְׁמוֹנָֽה׃","wa⁠yĕhi֤y misĕpá̇rá⁠m֙ ʻim-ʼàẖéy⁠he֔m mĕlumĕ̇déy-şǐ֖yr la⁠yhwá֑h ká̇l-ha֨⁠mé̇bi֔yn máʼţa֖yim şĕ̌mwòni֥ym ẇ⁠şĕ̌mwònáֽh׃"],[25,8,"וַ⁠יַּפִּ֜ילוּ גּוֹרָל֣וֹת מִשְׁמֶ֗רֶת לְ⁠עֻמַּת֙ כַּ⁠קָּטֹ֣ן כַּ⁠גָּד֔וֹל מֵבִ֖ין עִם־תַּלְמִֽיד׃פ","wa⁠yȧpi̇֜ylẇ ġwòrál֣wòţ mişĕ̌me֗reţ lĕ⁠ʻumȧţ֙ kȧ⁠qá̇tò֣n kȧ⁠gá̇d֔wòl mébi֖yn ʻim-ţȧlĕmiֽyd׃p"],[25,9,"וַ⁠יֵּצֵ֞א הַ⁠גּוֹרָ֧ל הָ⁠רִאשׁ֛וֹן לְ⁠אָסָ֖ף לְ⁠יוֹסֵ֑ף גְּדַלְיָ֨הוּ֙ הַ⁠שֵּׁנִ֔י הֽוּא־וְ⁠אֶחָ֥י⁠ו וּ⁠בָנָ֖י⁠ו שְׁנֵ֥ים עָשָֽׂר׃","wa⁠yé̇ẕé֞ʼ ha⁠ġwòrá֧l há⁠riʼş֛̌wòn lĕ⁠ʼásá֖p lĕ⁠ywòsé֑p gĕ̇dalĕyá֨hẇ֙ ha⁠şé̇̌ni֔y hֽẇʼ-wĕ⁠ʼeẖá֥y⁠w ẇ⁠báná֖y⁠w şĕ̌né֥ym ʻáşáֽ̂r׃"],[25,10,"הַ⁠שְּׁלִשִׁ֣י זַכּ֔וּר בָּנָ֥י⁠ו וְ⁠אֶחָ֖י⁠ו שְׁנֵ֥ים עָשָֽׂר׃","ha⁠şĕ̇̌lişǐ֣y zak̇֔ẇr bá̇ná֥y⁠w wĕ⁠ʼeẖá֖y⁠w şĕ̌né֥ym ʻáşáֽ̂r׃"],[25,11,"הָ⁠רְבִיעִי֙ לַ⁠יִּצְרִ֔י בָּנָ֥י⁠ו וְ⁠אֶחָ֖י⁠ו שְׁנֵ֥ים עָשָֽׂר׃","há⁠rĕbiyʻiy֙ la⁠yi̇ẕĕri֔y bá̇ná֥y⁠w wĕ⁠ʼeẖá֖y⁠w şĕ̌né֥ym ʻáşáֽ̂r׃"],[25,12,"הַ⁠חֲמִישִׁ֣י נְתַנְיָ֔הוּ בָּנָ֥י⁠ו וְ⁠אֶחָ֖י⁠ו שְׁנֵ֥ים עָשָֽׂר׃","ha⁠ẖàmiyşǐ֣y nĕţanĕyá֔hẇ bá̇ná֥y⁠w wĕ⁠ʼeẖá֖y⁠w şĕ̌né֥ym ʻáşáֽ̂r׃"],[25,13,"הַ⁠שִּׁשִּׁ֣י בֻקִּיָּ֔הוּ בָּנָ֥י⁠ו וְ⁠אֶחָ֖י⁠ו שְׁנֵ֥ים עָשָֽׂר׃","ha⁠şi̇̌şi֣̇̌y buqi̇yá̇֔hẇ bá̇ná֥y⁠w wĕ⁠ʼeẖá֖y⁠w şĕ̌né֥ym ʻáşáֽ̂r׃"],[25,14,"הַ⁠שְּׁבִעִ֣י יְשַׂרְאֵ֔לָה בָּנָ֥י⁠ו וְ⁠אֶחָ֖י⁠ו שְׁנֵ֥ים עָשָֽׂר׃","ha⁠şĕ̇̌biʻi֣y yĕşârĕʼé֔láh bá̇ná֥y⁠w wĕ⁠ʼeẖá֖y⁠w şĕ̌né֥ym ʻáşáֽ̂r׃"],[25,15,"הַ⁠שְּׁמִינִ֣י יְשַֽׁעְיָ֔הוּ בָּנָ֥י⁠ו וְ⁠אֶחָ֖י⁠ו שְׁנֵ֥ים עָשָֽׂר׃","ha⁠şĕ̇̌miyni֣y yĕşǎֽʻĕyá֔hẇ bá̇ná֥y⁠w wĕ⁠ʼeẖá֖y⁠w şĕ̌né֥ym ʻáşáֽ̂r׃"],[25,16,"הַ⁠תְּשִׁיעִ֣י מַתַּנְיָ֔הוּ בָּנָ֥י⁠ו וְ⁠אֶחָ֖י⁠ו שְׁנֵ֥ים עָשָֽׂר׃","ha⁠ţĕ̇şǐyʻi֣y maţȧnĕyá֔hẇ bá̇ná֥y⁠w wĕ⁠ʼeẖá֖y⁠w şĕ̌né֥ym ʻáşáֽ̂r׃"],[25,17,"הָ⁠עֲשִׂירִ֣י שִׁמְעִ֔י בָּנָ֥י⁠ו וְ⁠אֶחָ֖י⁠ו שְׁנֵ֥ים עָשָֽׂר׃","há⁠ʻàşîyri֣y şǐmĕʻi֔y bá̇ná֥y⁠w wĕ⁠ʼeẖá֖y⁠w şĕ̌né֥ym ʻáşáֽ̂r׃"],[25,18,"עַשְׁתֵּֽי־עָשָׂ֣ר עֲזַרְאֵ֔ל בָּנָ֥י⁠ו וְ⁠אֶחָ֖י⁠ו שְׁנֵ֥ים עָשָֽׂר׃","ʻaşĕ̌ţéֽ̇y-ʻáşá֣̂r ʻàzarĕʼé֔l bá̇ná֥y⁠w wĕ⁠ʼeẖá֖y⁠w şĕ̌né֥ym ʻáşáֽ̂r׃"],[25,19,"הַ⁠שְּׁנֵ֤ים עָשָׂר֙ לַ⁠חֲשַׁבְיָ֔ה בָּנָ֥י⁠ו וְ⁠אֶחָ֖י⁠ו שְׁנֵ֥ים עָשָֽׂר׃","ha⁠şĕ̇̌né֤ym ʻáşá̂r֙ la⁠ẖàşǎbĕyá֔h bá̇ná֥y⁠w wĕ⁠ʼeẖá֖y⁠w şĕ̌né֥ym ʻáşáֽ̂r׃"],[25,20,"לִ⁠שְׁלֹשָׁ֤ה עָשָׂר֙ שֽׁוּבָאֵ֔ל בָּנָ֥י⁠ו וְ⁠אֶחָ֖י⁠ו שְׁנֵ֥ים עָשָֽׂר׃","li⁠şĕ̌lòşá֤̌h ʻáşá̂r֙ şֽ̌ẇbáʼé֔l bá̇ná֥y⁠w wĕ⁠ʼeẖá֖y⁠w şĕ̌né֥ym ʻáşáֽ̂r׃"],[25,21,"לְ⁠אַרְבָּעָ֤ה עָשָׂר֙ מַתִּתְיָ֔הוּ בָּנָ֥י⁠ו וְ⁠אֶחָ֖י⁠ו שְׁנֵ֥ים עָשָֽׂר׃","lĕ⁠ʼarĕbá̇ʻá֤h ʻáşá̂r֙ maţi̇ţĕyá֔hẇ bá̇ná֥y⁠w wĕ⁠ʼeẖá֖y⁠w şĕ̌né֥ym ʻáşáֽ̂r׃"],[25,22,"לַ⁠חֲמִשָּׁ֤ה עָשָׂר֙ לִֽ⁠ירֵמ֔וֹת בָּנָ֥י⁠ו וְ⁠אֶחָ֖י⁠ו שְׁנֵ֥ים עָשָֽׂר׃","la⁠ẖàmişá֤̇̌h ʻáşá̂r֙ liֽ⁠yrém֔wòţ bá̇ná֥y⁠w wĕ⁠ʼeẖá֖y⁠w şĕ̌né֥ym ʻáşáֽ̂r׃"],[25,23,"לְ⁠שִׁשָּׁ֤ה עָשָׂר֙ לַ⁠חֲנַנְיָ֔הוּ בָּנָ֥י⁠ו וְ⁠אֶחָ֖י⁠ו שְׁנֵ֥ים עָשָֽׂר׃","lĕ⁠şǐşá֤̇̌h ʻáşá̂r֙ la⁠ẖànanĕyá֔hẇ bá̇ná֥y⁠w wĕ⁠ʼeẖá֖y⁠w şĕ̌né֥ym ʻáşáֽ̂r׃"],[25,24,"לְ⁠שִׁבְעָ֤ה עָשָׂר֙ לְ⁠יָשְׁבְּקָ֔שָׁה בָּנָ֥י⁠ו וְ⁠אֶחָ֖י⁠ו שְׁנֵ֥ים עָשָֽׂר׃","lĕ⁠şǐbĕʻá֤h ʻáşá̂r֙ lĕ⁠yáşĕ̌bĕ̇qá֔şá̌h bá̇ná֥y⁠w wĕ⁠ʼeẖá֖y⁠w şĕ̌né֥ym ʻáşáֽ̂r׃"],[25,25,"לִ⁠שְׁמוֹנָ֤ה עָשָׂר֙ לַ⁠חֲנָ֔נִי בָּנָ֥י⁠ו וְ⁠אֶחָ֖י⁠ו שְׁנֵ֥ים עָשָֽׂר׃","li⁠şĕ̌mwòná֤h ʻáşá̂r֙ la⁠ẖàná֔niy bá̇ná֥y⁠w wĕ⁠ʼeẖá֖y⁠w şĕ̌né֥ym ʻáşáֽ̂r׃"],[25,26,"לְ⁠תִשְׁעָ֤ה עָשָׂר֙ לְ⁠מַלּ֔וֹתִי בָּנָ֥י⁠ו וְ⁠אֶחָ֖י⁠ו שְׁנֵ֥ים עָשָֽׂר׃","lĕ⁠ţişĕ̌ʻá֤h ʻáşá̂r֙ lĕ⁠mal̇֔wòţiy bá̇ná֥y⁠w wĕ⁠ʼeẖá֖y⁠w şĕ̌né֥ym ʻáşáֽ̂r׃"],[25,27,"לְ⁠עֶשְׂרִים֙ לֶֽ⁠אֱלִיָּ֔תָה בָּנָ֥י⁠ו וְ⁠אֶחָ֖י⁠ו שְׁנֵ֥ים עָשָֽׂר׃","lĕ⁠ʻeşĕ̂riym֙ leֽ⁠ʼèliyá̇֔ţáh bá̇ná֥y⁠w wĕ⁠ʼeẖá֖y⁠w şĕ̌né֥ym ʻáşáֽ̂r׃"],[25,28,"לְ⁠אֶחָ֤ד וְ⁠עֶשְׂרִים֙ לְ⁠הוֹתִ֔יר בָּנָ֥י⁠ו וְ⁠אֶחָ֖י⁠ו שְׁנֵ֥ים עָשָֽׂר׃","lĕ⁠ʼeẖá֤d wĕ⁠ʻeşĕ̂riym֙ lĕ⁠hwòţi֔yr bá̇ná֥y⁠w wĕ⁠ʼeẖá֖y⁠w şĕ̌né֥ym ʻáşáֽ̂r׃"],[25,29,"לִ⁠שְׁנַ֤יִם וְ⁠עֶשְׂרִים֙ לְ⁠גִדַּ֔לְתִּי בָּנָ֥י⁠ו וְ⁠אֶחָ֖י⁠ו שְׁנֵ֥ים עָשָֽׂר׃","li⁠şĕ̌na֤yim wĕ⁠ʻeşĕ̂riym֙ lĕ⁠gidȧ֔lĕţi̇y bá̇ná֥y⁠w wĕ⁠ʼeẖá֖y⁠w şĕ̌né֥ym ʻáşáֽ̂r׃"],[25,30,"לִ⁠שְׁלֹשָׁ֤ה וְ⁠עֶשְׂרִים֙ לְ⁠מַ֣חֲזִיא֔וֹת בָּנָ֥י⁠ו וְ⁠אֶחָ֖י⁠ו שְׁנֵ֥ים עָשָֽׂר׃","li⁠şĕ̌lòşá֤̌h wĕ⁠ʻeşĕ̂riym֙ lĕ⁠ma֣ẖàziyʼ֔wòţ bá̇ná֥y⁠w wĕ⁠ʼeẖá֖y⁠w şĕ̌né֥ym ʻáşáֽ̂r׃"],[25,31,"לְ⁠אַרְבָּעָ֤ה וְ⁠עֶשְׂרִים֙ לְ⁠רוֹמַ֣מְתִּי עָ֔זֶר בָּנָ֥י⁠ו וְ⁠אֶחָ֖י⁠ו שְׁנֵ֥ים עָשָֽׂר׃פ","lĕ⁠ʼarĕbá̇ʻá֤h wĕ⁠ʻeşĕ̂riym֙ lĕ⁠rwòma֣mĕţi̇y ʻá֔zer bá̇ná֥y⁠w wĕ⁠ʼeẖá֖y⁠w şĕ̌né֥ym ʻáşáֽ̂r׃p"],[26,1,"לְ⁠מַחְלְק֖וֹת לְ⁠שֹׁעֲרִ֑ים לַ⁠קָּרְחִ֕ים מְשֶֽׁלֶמְיָ֥הוּ בֶן־קֹרֵ֖א מִן־בְּנֵ֥י אָסָֽף׃","lĕ⁠maẖĕlĕq֖wòţ lĕ⁠şò̌ʻàri֑ym la⁠qá̇rĕẖi֕ym mĕşěֽlemĕyá֥hẇ ben-qòré֖ʼ min-bĕ̇né֥y ʼásáֽp׃"],[26,2,"וְ⁠לִ⁠מְשֶֽׁלֶמְיָ֖הוּ בָּנִ֑ים זְכַרְיָ֤הוּ הַ⁠בְּכוֹר֙ יְדִֽיעֲאֵ֣ל הַ⁠שֵּׁנִ֔י זְבַדְיָ֨הוּ֙ הַ⁠שְּׁלִישִׁ֔י יַתְנִיאֵ֖ל הָ⁠רְבִיעִֽי׃","wĕ⁠li⁠mĕşěֽlemĕyá֖hẇ bá̇ni֑ym zĕkarĕyá֤hẇ ha⁠bĕ̇kwòr֙ yĕdiֽyʻàʼé֣l ha⁠şé̇̌ni֔y zĕbadĕyá֨hẇ֙ ha⁠şĕ̇̌liyşǐ֔y yaţĕniyʼé֖l há⁠rĕbiyʻiֽy׃"],[26,3,"עֵילָ֤ם הַ⁠חֲמִישִׁי֙ יְהוֹחָנָ֣ן הַ⁠שִּׁשִּׁ֔י אֶלְיְהוֹעֵינַ֖י הַ⁠שְּׁבִיעִֽי׃","ʻéylá֤m ha⁠ẖàmiyşǐy֙ yĕhwòẖáná֣n ha⁠şi̇̌şi̇̌֔y ʼelĕyĕhwòʻéyna֖y ha⁠şĕ̇̌biyʻiֽy׃"],[26,4,"וּ⁠לְ⁠עֹבֵ֥ד אֱדֹ֖ם בָּנִ֑ים שְׁמַֽעְיָ֤ה הַ⁠בְּכוֹר֙ יְהוֹזָבָ֣ד הַ⁠שֵּׁנִ֔י יוֹאָ֤ח הַ⁠שְּׁלִשִׁי֙ וְ⁠שָׂכָ֣ר הָ⁠רְבִיעִ֔י וּ⁠נְתַנְאֵ֖ל הַ⁠חֲמִישִֽׁי׃","ẇ⁠lĕ⁠ʻòbé֥d ʼèdò֖m bá̇ni֑ym şĕ̌maֽʻĕyá֤h ha⁠bĕ̇kwòr֙ yĕhwòzábá֣d ha⁠şé̇̌ni֔y ywòʼá֤ẖ ha⁠şĕ̇̌lişǐy֙ wĕ⁠şá̂ká֣r há⁠rĕbiyʻi֔y ẇ⁠nĕţanĕʼé֖l ha⁠ẖàmiyşǐֽy׃"],[26,5,"עַמִּיאֵ֤ל הַ⁠שִּׁשִּׁי֙ יִשָׂשכָ֣ר הַ⁠שְּׁבִיעִ֔י פְּעֻלְּתַ֖י הַ⁠שְּׁמִינִ֑י כִּ֥י בֵרֲכ֖⁠וֹ אֱלֹהִֽים׃פ","ʻami̇yʼé֤l ha⁠şi̇̌şi̇̌y֙ yişá̂şká֣r ha⁠şĕ̇̌biyʻi֔y pĕ̇ʻulĕ̇ţa֖y ha⁠şĕ̇̌miyni֑y ki֥̇y béràk֖⁠wò ʼèlòhiֽym׃p"],[26,6,"וְ⁠לִֽ⁠שְׁמַֽעְיָ֤ה בְנ⁠וֹ֙ נוֹלַ֣ד בָּנִ֔ים הַ⁠מִּמְשָׁלִ֖ים לְ⁠בֵ֣ית אֲבִי⁠הֶ֑ם כִּֽי־גִבּ֥וֹרֵי חַ֖יִל הֵֽמָּה׃","wĕ⁠liֽ⁠şĕ̌maֽʻĕyá֤h bĕn⁠wò֙ nwòla֣d bá̇ni֔ym ha⁠mi̇mĕşá̌li֖ym lĕ⁠bé֣yţ ʼàbiy⁠he֑m kiֽ̇y-giḃ֥wòréy ẖa֖yil héֽmá̇h׃"],[26,7,"בְּנֵ֣י שְׁמַֽעְיָ֗ה עָ֠תְנִי וּ⁠רְפָאֵ֨ל וְ⁠עוֹבֵ֧ד אֶלְזָבָ֛ד אֶחָ֖י⁠ו בְּנֵי־חָ֑יִל אֱלִיה֖וּ וּ⁠סְמַכְיָֽהוּ׃","bĕ̇né֣y şĕ̌maֽʻĕyá֗h ʻá֠ţĕniy ẇ⁠rĕpáʼé֨l wĕ⁠ʻwòbé֧d ʼelĕzábá֛d ʼeẖá֖y⁠w bĕ̇néy-ẖá֑yil ʼèliyh֖ẇ ẇ⁠sĕmakĕyáֽhẇ׃"],[26,8,"כָּל־אֵ֜לֶּה מִ⁠בְּנֵ֣י ׀ עֹבֵ֣ד אֱדֹ֗ם הֵ֤מָּה וּ⁠בְנֵי⁠הֶם֙ וַ⁠אֲחֵי⁠הֶ֔ם אִֽישׁ־חַ֥יִל בַּ⁠כֹּ֖חַ לַ⁠עֲבֹדָ֑ה שִׁשִּׁ֥ים וּ⁠שְׁנַ֖יִם לְ⁠עֹבֵ֥ד אֱדֹֽם׃","ká̇l-ʼé֜lėh mi⁠bĕ̇né֣y ׀ ʻòbé֣d ʼèdò֗m hé֤má̇h ẇ⁠bĕnéy⁠hem֙ wa⁠ʼàẖéy⁠he֔m ʼiֽyş̌-ẖa֥yil bȧ⁠kò֖̇ẖa la⁠ʻàbòdá֑h şǐşi֥̇̌ym ẇ⁠şĕ̌na֖yim lĕ⁠ʻòbé֥d ʼèdòֽm׃"],[26,9,"וְ⁠לִ⁠מְשֶֽׁלֶמְיָ֗הוּ בָּנִ֧ים וְ⁠אַחִ֛ים בְּנֵי־חָ֖יִל שְׁמוֹנָ֥ה עָשָֽׂר׃ס","wĕ⁠li⁠mĕşěֽlemĕyá֗hẇ bá̇ni֧ym wĕ⁠ʼaẖi֛ym bĕ̇néy-ẖá֖yil şĕ̌mwòná֥h ʻáşáֽ̂r׃s"],[26,10,"וּ⁠לְ⁠חֹסָ֥ה מִן־בְּנֵי־מְרָרִ֖י בָּנִ֑ים שִׁמְרִ֤י הָ⁠רֹאשׁ֙ כִּ֣י לֹא־הָיָ֣ה בְכ֔וֹר וַ⁠יְשִׂימֵ֥⁠הוּ אָבִ֖י⁠הוּ לְ⁠רֹֽאשׁ׃","ẇ⁠lĕ⁠ẖòsá֥h min-bĕ̇néy-mĕrári֖y bá̇ni֑ym şǐmĕri֤y há⁠ròʼş̌֙ ki֣̇y lòʼ-háyá֣h bĕk֔wòr wa⁠yĕşîymé֥⁠hẇ ʼábi֖y⁠hẇ lĕ⁠ròֽʼş̌׃"],[26,11,"חִלְקִיָּ֤הוּ הַ⁠שֵּׁנִי֙ טְבַלְיָ֣הוּ הַ⁠שְּׁלִשִׁ֔י זְכַרְיָ֖הוּ הָ⁠רְבִעִ֑י כָּל־בָּנִ֧ים וְ⁠אַחִ֛ים לְ⁠חֹסָ֖ה שְׁלֹשָׁ֥ה עָשָֽׂר׃","ẖilĕqiyá֤̇hẇ ha⁠şé̇̌niy֙ tĕbalĕyá֣hẇ ha⁠şĕ̇̌lişǐ֔y zĕkarĕyá֖hẇ há⁠rĕbiʻi֑y ká̇l-bá̇ni֧ym wĕ⁠ʼaẖi֛ym lĕ⁠ẖòsá֖h şĕ̌lòşá֥̌h ʻáşáֽ̂r׃"],[26,12,"לְ֠⁠אֵלֶּה מַחְלְק֨וֹת הַ⁠שֹּֽׁעֲרִ֜ים לְ⁠רָאשֵׁ֧י הַ⁠גְּבָרִ֛ים מִשְׁמָר֖וֹת לְ⁠עֻמַּ֣ת אֲחֵי⁠הֶ֑ם לְ⁠שָׁרֵ֖ת בְּ⁠בֵ֥ית יְהוָֽה׃","lĕ֠⁠ʼélėh maẖĕlĕq֨wòţ ha⁠şòֽ̇̌ʻàri֜ym lĕ⁠ráʼşé֧̌y ha⁠gĕ̇bári֛ym mişĕ̌már֖wòţ lĕ⁠ʻumȧ֣ţ ʼàẖéy⁠he֑m lĕ⁠şá̌ré֖ţ bĕ̇⁠bé֥yţ yĕhwáֽh׃"],[26,13,"וַ⁠יַּפִּ֨ילוּ גוֹרָל֜וֹת כַּ⁠קָּטֹ֧ן כַּ⁠גָּד֛וֹל לְ⁠בֵ֥ית אֲבוֹתָ֖⁠ם לְ⁠שַׁ֥עַר וָ⁠שָֽׁעַר׃פ","wa⁠yȧpi̇֨ylẇ gwòrál֜wòţ kȧ⁠qá̇tò֧n kȧ⁠gá̇d֛wòl lĕ⁠bé֥yţ ʼàbwòţá֖⁠m lĕ⁠şǎ֥ʻar wá⁠şáֽ̌ʻar׃p"],[26,14,"וַ⁠יִּפֹּ֧ל הַ⁠גּוֹרָ֛ל מִזְרָ֖חָ⁠ה לְ⁠שֶֽׁלֶמְיָ֑הוּ וּ⁠זְכַרְיָ֨הוּ בְנ֜⁠וֹ יוֹעֵ֣ץ ׀ בְּ⁠שֶׂ֗כֶל הִפִּ֨ילוּ֙ גּֽוֹרָל֔וֹת וַ⁠יֵּצֵ֥א גוֹרָל֖⁠וֹ צָפֽוֹנָ⁠ה׃ס","wa⁠yi̇pò֧̇l ha⁠ġwòrá֛l mizĕrá֖ẖá⁠h lĕ⁠şěֽlemĕyá֑hẇ ẇ⁠zĕkarĕyá֨hẇ bĕn֜⁠wò ywòʻé֣ẕ ׀ bĕ̇⁠şê֗kel hipi̇֨ylẇ֙ ġֽwòrál֔wòţ wa⁠yé̇ẕé֥ʼ gwòrál֖⁠wò ẕápֽwòná⁠h׃s"],[26,15,"לְ⁠עֹבֵ֥ד אֱדֹ֖ם נֶ֑גְבָּ⁠ה וּ⁠לְ⁠בָנָ֖י⁠ו בֵּ֥ית הָ⁠אֲסֻפִּֽים׃","lĕ⁠ʻòbé֥d ʼèdò֖m ne֑gĕbá̇⁠h ẇ⁠lĕ⁠báná֖y⁠w bé֥̇yţ há⁠ʼàsupiֽ̇ym׃"],[26,16,"לְ⁠שֻׁפִּ֤ים וּ⁠לְ⁠חֹסָה֙ לַֽ⁠מַּעֲרָ֔ב עִ֚ם שַׁ֣עַר שַׁלֶּ֔כֶת בַּֽ⁠מְסִלָּ֖ה הָ⁠עוֹלָ֑ה מִשְׁמָ֖ר לְ⁠עֻמַּ֥ת מִשְׁמָֽר׃","lĕ⁠şǔpi֤̇ym ẇ⁠lĕ⁠ẖòsáh֙ laֽ⁠mȧʻàrá֔b ʻi֚m şǎ֣ʻar şǎlė֔keţ bȧֽ⁠mĕsilá֖̇h há⁠ʻwòlá֑h mişĕ̌má֖r lĕ⁠ʻumȧ֥ţ mişĕ̌máֽr׃"],[26,17,"לַ⁠מִּזְרָח֮ הַ⁠לְוִיִּ֣ם שִׁשָּׁה֒ לַ⁠צָּפ֤וֹנָ⁠ה לַ⁠יּוֹם֙ אַרְבָּעָ֔ה לַ⁠נֶּ֥גְבָּ⁠ה לַ⁠יּ֖וֹם אַרְבָּעָ֑ה וְ⁠לָ⁠אֲסֻפִּ֖ים שְׁנַ֥יִם שְׁנָֽיִם׃","la⁠mi̇zĕráẖ֮ ha⁠lĕwiyi֣̇m şǐşá̇̌h֒ la⁠ẕá̇p֤wòná⁠h la⁠ẏwòm֙ ʼarĕbá̇ʻá֔h la⁠nė֥gĕbá̇⁠h la⁠ẏ֖wòm ʼarĕbá̇ʻá֑h wĕ⁠lá⁠ʼàsupi֖̇ym şĕ̌na֥yim şĕ̌náֽyim׃"],[26,18,"לַ⁠פַּרְבָּ֖ר לַֽ⁠מַּעֲרָ֑ב אַרְבָּעָה֙ לַֽ⁠מְסִלָּ֔ה שְׁנַ֖יִם לַ⁠פַּרְבָּֽר׃","la⁠pȧrĕbá֖̇r laֽ⁠mȧʻàrá֑b ʼarĕbá̇ʻáh֙ laֽ⁠mĕsilá̇֔h şĕ̌na֖yim la⁠pȧrĕbáֽ̇r׃"],[26,19,"אֵ֗לֶּה מַחְלְקוֹת֙ הַ⁠שֹּׁ֣עֲרִ֔ים לִ⁠בְנֵ֥י הַ⁠קָּרְחִ֖י וְ⁠לִ⁠בְנֵ֥י מְרָרִֽי׃","ʼé֗lėh maẖĕlĕqwòţ֙ ha⁠şò֣̇̌ʻàri֔ym li⁠bĕné֥y ha⁠qá̇rĕẖi֖y wĕ⁠li⁠bĕné֥y mĕráriֽy׃"],[26,20,"וְֽ⁠הַ⁠לְוִיִּ֑ם אֲחִיָּ֗ה עַל־אֽוֹצְרוֹת֙ בֵּ֣ית הָ⁠אֱלֹהִ֔ים וּ⁠לְ⁠אֹֽצְר֖וֹת הַ⁠קֳּדָשִֽׁים׃","wĕֽ⁠ha⁠lĕwiyi֑̇m ʼàẖiyá̇֗h ʻal-ʼֽwòẕĕrwòţ֙ bé֣̇yţ há⁠ʼèlòhi֔ym ẇ⁠lĕ⁠ʼòֽẕĕr֖wòţ ha⁠qȯdáşǐֽym׃"],[26,21,"בְּנֵ֣י לַ֠עְדָּן בְּנֵ֨י הַ⁠גֵּרְשֻׁנִּ֜י לְ⁠לַעְדָּ֗ן רָאשֵׁ֧י הָ⁠אָב֛וֹת לְ⁠לַעְדָּ֥ן הַ⁠גֵּרְשֻׁנִּ֖י יְחִיאֵלִֽי׃","bĕ̇né֣y la֠ʻĕdá̇n bĕ̇né֨y ha⁠gé̇rĕşǔni̇֜y lĕ⁠laʻĕdá̇֗n ráʼşé֧̌y há⁠ʼáb֛wòţ lĕ⁠laʻĕdá֥̇n ha⁠gé̇rĕşǔni֖̇y yĕẖiyʼéliֽy׃"],[26,22,"בְּנֵ֖י יְחִֽיאֵלִ֑י זֵתָם֙ וְ⁠יוֹאֵ֣ל אָחִ֔י⁠ו עַל־אֹצְר֖וֹת בֵּ֥ית יְהוָֽה׃","bĕ̇né֖y yĕẖiֽyʼéli֑y zéţám֙ wĕ⁠ywòʼé֣l ʼáẖi֔y⁠w ʻal-ʼòẕĕr֖wòţ bé֥̇yţ yĕhwáֽh׃"],[26,23,"לַֽ⁠עַמְרָמִי֙ לַ⁠יִּצְהָרִ֔י לַֽ⁠חֶבְרוֹנִ֖י לָֽ⁠עָזִּיאֵלִֽי׃","laֽ⁠ʻamĕrámiy֙ la⁠yi̇ẕĕhári֔y laֽ⁠ẖebĕrwòni֖y láֽ⁠ʻázi̇yʼéliֽy׃"],[26,24,"וּ⁠שְׁבֻאֵל֙ בֶּן־גֵּרְשׁ֣וֹם בֶּן־מֹשֶׁ֔ה נָגִ֖יד עַל־הָ⁠אֹצָרֽוֹת׃","ẇ⁠şĕ̌buʼél֙ bėn-gé̇rĕş֣̌wòm bėn-mòşě֔h nági֖yd ʻal-há⁠ʼòẕárֽwòţ׃"],[26,25,"וְ⁠אֶחָ֖י⁠ו לֶֽ⁠אֱלִיעֶ֑זֶר רְחַבְיָ֨הוּ בְנ֜⁠וֹ וִֽ⁠ישַׁעְיָ֤הוּ בְנ⁠וֹ֙ וְ⁠יֹרָ֣ם בְּנ֔⁠וֹ וְ⁠זִכְרִ֥י בְנ֖⁠וֹ ו⁠שלמות בְּנֽ⁠וֹ׃","wĕ⁠ʼeẖá֖y⁠w leֽ⁠ʼèliyʻe֑zer rĕẖabĕyá֨hẇ bĕn֜⁠wò wiֽ⁠yşǎʻĕyá֤hẇ bĕn⁠wò֙ wĕ⁠yòrá֣m bĕ̇n֔⁠wò wĕ⁠zikĕri֥y bĕn֖⁠wò w⁠şlmwţ bĕ̇nֽ⁠wò׃"],[26,26,"ה֧וּא שְׁלֹמ֣וֹת וְ⁠אֶחָ֗י⁠ו עַ֣ל כָּל־אֹצְר֤וֹת הַ⁠קֳּדָשִׁים֙ אֲשֶׁ֨ר הִקְדִּ֜ישׁ דָּוִ֣יד הַ⁠מֶּ֗לֶךְ וְ⁠רָאשֵׁ֧י הָ⁠אָב֛וֹת לְ⁠שָׂרֵֽי־הָ⁠אֲלָפִ֥ים וְ⁠הַ⁠מֵּא֖וֹת וְ⁠שָׂרֵ֥י הַ⁠צָּבָֽא׃","h֧ẇʼ şĕ̌lòm֣wòţ wĕ⁠ʼeẖá֗y⁠w ʻa֣l ká̇l-ʼòẕĕr֤wòţ ha⁠qȯdáşǐym֙ ʼàşě֨r hiqĕdi̇֜yş̌ dá̇wi֣yd ha⁠mė֗lekĕ wĕ⁠ráʼşé֧̌y há⁠ʼáb֛wòţ lĕ⁠şá̂réֽy-há⁠ʼàlápi֥ym wĕ⁠ha⁠mé̇ʼ֖wòţ wĕ⁠şá̂ré֥y ha⁠ẕá̇báֽʼ׃"],[26,27,"מִן־הַ⁠מִּלְחָמ֥וֹת וּ⁠מִן־הַ⁠שָּׁלָ֖ל הִקְדִּ֑ישׁוּ לְ⁠חַזֵּ֖ק לְ⁠בֵ֥ית יְהוָֽה׃","min-ha⁠mi̇lĕẖám֥wòţ ẇ⁠min-ha⁠şá̇̌lá֖l hiqĕdi֑̇yş̌ẇ lĕ⁠ẖazé֖̇q lĕ⁠bé֥yţ yĕhwáֽh׃"],[26,28,"וְ⁠כֹ֨ל הַֽ⁠הִקְדִּ֜ישׁ שְׁמוּאֵ֤ל הָ⁠רֹאֶה֙ וְ⁠שָׁא֣וּל בֶּן־קִ֔ישׁ וְ⁠אַבְנֵ֣ר בֶּן־נֵ֔ר וְ⁠יוֹאָ֖ב בֶּן־צְרוּיָ֑ה כֹּ֚ל הַ⁠מַּקְדִּ֔ישׁ עַ֥ל יַד־שְׁלֹמִ֖ית וְ⁠אֶחָֽי⁠ו׃פ","wĕ⁠kò֨l haֽ⁠hiqĕdi̇֜yş̌ şĕ̌mẇʼé֤l há⁠ròʼeh֙ wĕ⁠şá̌ʼ֣ẇl bėn-qi֔yş̌ wĕ⁠ʼabĕné֣r bėn-né֔r wĕ⁠ywòʼá֖b bėn-ẕĕrẇyá֑h kò֚̇l ha⁠mȧqĕdi̇֔yş̌ ʻa֥l yad-şĕ̌lòmi֖yţ wĕ⁠ʼeẖáֽy⁠w׃p"],[26,29,"לַ⁠יִּצְהָרִ֞י כְּנַנְיָ֣הוּ וּ⁠בָנָ֗י⁠ו לַ⁠מְּלָאכָ֤ה הַ⁠חִֽיצוֹנָה֙ עַל־יִשְׂרָאֵ֔ל לְ⁠שֹׁטְרִ֖ים וּ⁠לְ⁠שֹׁפְטִֽים׃","la⁠yi̇ẕĕhári֞y kĕ̇nanĕyá֣hẇ ẇ⁠báná֗y⁠w la⁠mĕ̇láʼká֤h ha⁠ẖiֽyẕwònáh֙ ʻal-yişĕ̂ráʼé֔l lĕ⁠şò̌tĕri֖ym ẇ⁠lĕ⁠şò̌pĕtiֽym׃"],[26,30,"לַֽ⁠חֶבְרוֹנִ֡י חֲשַׁבְיָהוּ֩ וְ⁠אֶחָ֨י⁠ו בְּנֵי־חַ֜יִל אֶ֣לֶף וּ⁠שְׁבַע־מֵא֗וֹת עַ֚ל פְּקֻדַּ֣ת יִשְׂרָאֵ֔ל מֵ⁠עֵ֥בֶר לַ⁠יַּרְדֵּ֖ן מַעְרָ֑בָ⁠ה לְ⁠כֹל֙ מְלֶ֣אכֶת יְהוָ֔ה וְ⁠לַ⁠עֲבֹדַ֖ת הַ⁠מֶּֽלֶךְ׃","laֽ⁠ẖebĕrwòni֡y ẖàşǎbĕyáhẇ֩ wĕ⁠ʼeẖá֨y⁠w bĕ̇néy-ẖa֜yil ʼe֣lep ẇ⁠şĕ̌baʻ-méʼ֗wòţ ʻa֚l pĕ̇qudȧ֣ţ yişĕ̂ráʼé֔l mé⁠ʻé֥ber la⁠yȧrĕdé֖̇n maʻĕrá֑bá⁠h lĕ⁠kòl֙ mĕle֣ʼkeţ yĕhwá֔h wĕ⁠la⁠ʻàbòda֖ţ ha⁠mėֽlekĕ׃"],[26,31,"לַֽ⁠חֶבְרוֹנִי֙ יְרִיָּ֣ה הָ⁠רֹ֔אשׁ לַֽ⁠חֶבְרוֹנִ֥י לְ⁠תֹלְדֹתָ֖י⁠ו לְ⁠אָב֑וֹת בִּ⁠שְׁנַ֨ת הָֽ⁠אַרְבָּעִ֜ים לְ⁠מַלְכ֤וּת דָּוִיד֙ נִדְרָ֔שׁוּ וַ⁠יִּמָּצֵ֥א בָ⁠הֶ֛ם גִּבּ֥וֹרֵי חַ֖יִל בְּ⁠יַעְזֵ֥יר גִּלְעָֽד׃","laֽ⁠ẖebĕrwòniy֙ yĕriyá֣̇h há⁠rò֔ʼş̌ laֽ⁠ẖebĕrwòni֥y lĕ⁠ţòlĕdòţá֖y⁠w lĕ⁠ʼáb֑wòţ bi̇⁠şĕ̌na֨ţ háֽ⁠ʼarĕbá̇ʻi֜ym lĕ⁠malĕk֤ẇţ dá̇wiyd֙ nidĕrá֔ş̌ẇ wa⁠yi̇má̇ẕé֥ʼ bá⁠he֛m gi̇ḃ֥wòréy ẖa֖yil bĕ̇⁠yaʻĕzé֥yr gi̇lĕʻáֽd׃"],[26,32,"וְ⁠אֶחָ֣י⁠ו בְּנֵי־חַ֗יִל אַלְפַּ֛יִם וּ⁠שְׁבַ֥ע מֵא֖וֹת רָאשֵׁ֣י הָ⁠אָב֑וֹת וַ⁠יַּפְקִידֵ֞⁠ם דָּוִ֣יד הַ⁠מֶּ֗לֶךְ עַל־הָ⁠ראוּבֵנִ֤י וְ⁠הַ⁠גָּדִי֙ וַ⁠חֲצִי֙ שֵׁ֣בֶט הַֽ⁠מְנַשִּׁ֔י לְ⁠כָל־דְּבַ֥ר הָ⁠אֱלֹהִ֖ים וּ⁠דְבַ֥ר הַ⁠מֶּֽלֶךְ׃פ","wĕ⁠ʼeẖá֣y⁠w bĕ̇néy-ẖa֗yil ʼalĕpȧ֛yim ẇ⁠şĕ̌ba֥ʻ méʼ֖wòţ ráʼşé֣̌y há⁠ʼáb֑wòţ wa⁠yȧpĕqiydé֞⁠m dá̇wi֣yd ha⁠mė֗lekĕ ʻal-há⁠rʼẇbéni֤y wĕ⁠ha⁠gá̇diy֙ wa⁠ẖàẕiy֙ şé֣̌bet haֽ⁠mĕnaşi̇̌֔y lĕ⁠kál-dĕ̇ba֥r há⁠ʼèlòhi֖ym ẇ⁠dĕba֥r ha⁠mėֽlekĕ׃p"],[27,1,"וּ⁠בְנֵ֣י יִשְׂרָאֵ֣ל ׀ לְֽ⁠מִסְפָּרָ֡⁠ם רָאשֵׁ֣י הָ⁠אָב֣וֹת וְ⁠שָׂרֵ֣י הָֽ⁠אֲלָפִ֣ים ׀ וְ⁠הַ⁠מֵּא֡וֹת וְ⁠שֹׁטְרֵי⁠הֶם֩ הַ⁠מְשָׁרְתִ֨ים אֶת־הַ⁠מֶּ֜לֶךְ לְ⁠כֹ֣ל ׀ דְּבַ֣ר הַֽ⁠מַּחְלְק֗וֹת הַ⁠בָּאָ֤ה וְ⁠הַ⁠יֹּצֵאת֙ חֹ֣דֶשׁ בְּ⁠חֹ֔דֶשׁ לְ⁠כֹ֖ל חָדְשֵׁ֣י הַ⁠שָּׁנָ֑ה הַֽ⁠מַּחֲלֹ֨קֶת֙ הָֽ⁠אַחַ֔ת עֶשְׂרִ֥ים וְ⁠אַרְבָּעָ֖ה אָֽלֶף׃ס","ẇ⁠bĕné֣y yişĕ̂ráʼé֣l ׀ lĕֽ⁠misĕpá̇rá֡⁠m ráʼşé֣̌y há⁠ʼáb֣wòţ wĕ⁠şá̂ré֣y háֽ⁠ʼàlápi֣ym ׀ wĕ⁠ha⁠mé̇ʼ֡wòţ wĕ⁠şò̌tĕréy⁠hem֩ ha⁠mĕşá̌rĕţi֨ym ʼeţ-ha⁠mė֜lekĕ lĕ⁠kò֣l ׀ dĕ̇ba֣r haֽ⁠mȧẖĕlĕq֗wòţ ha⁠bá̇ʼá֤h wĕ⁠ha⁠yò̇ẕéʼţ֙ ẖò֣deş̌ bĕ̇⁠ẖò֔deş̌ lĕ⁠kò֖l ẖádĕşé֣̌y ha⁠şá̇̌ná֑h haֽ⁠mȧẖàlò֨qeţ֙ háֽ⁠ʼaẖa֔ţ ʻeşĕ̂ri֥ym wĕ⁠ʼarĕbá̇ʻá֖h ʼáֽlep׃s"],[27,2,"עַ֞ל הַ⁠מַּחֲלֹ֤קֶת הָ⁠רִֽאשׁוֹנָה֙ לַ⁠חֹ֣דֶשׁ הָ⁠רִאשׁ֔וֹן יָֽשָׁבְעָ֖ם בֶּן־זַבְדִּיאֵ֑ל וְ⁠עַל֙ מַֽחֲלֻקְתּ֔⁠וֹ עֶשְׂרִ֥ים וְ⁠אַרְבָּעָ֖ה אָֽלֶף׃","ʻa֞l ha⁠mȧẖàlò֤qeţ há⁠riֽʼş̌wònáh֙ la⁠ẖò֣deş̌ há⁠riʼş̌֔wòn yáֽşá̌bĕʻá֖m bėn-zabĕdi̇yʼé֑l wĕ⁠ʻal֙ maֽẖàluqĕţ̇֔⁠wò ʻeşĕ̂ri֥ym wĕ⁠ʼarĕbá̇ʻá֖h ʼáֽlep׃"],[27,3,"מִן־בְּנֵי־פֶ֗רֶץ הָ⁠רֹ֛אשׁ לְ⁠כָל־שָׂרֵ֥י הַ⁠צְּבָא֖וֹת לַ⁠חֹ֥דֶשׁ הָ⁠רִאשֽׁוֹן׃","min-bĕ̇néy-pe֗reẕ há⁠rò֛ʼş̌ lĕ⁠kál-şá̂ré֥y ha⁠ẕĕ̇báʼ֖wòţ la⁠ẖò֥deş̌ há⁠riʼşֽ̌wòn׃"],[27,4,"וְ⁠עַ֞ל מַחֲלֹ֣קֶת ׀ הַ⁠חֹ֣דֶשׁ הַ⁠שֵּׁנִ֗י דּוֹדַ֤י הָ⁠אֲחוֹחִי֙ וּ⁠מַ֣חֲלֻקְתּ֔⁠וֹ וּ⁠מִקְל֖וֹת הַ⁠נָּגִ֑יד וְ⁠עַל֙ מַחֲלֻקְתּ֔⁠וֹ עֶשְׂרִ֥ים וְ⁠אַרְבָּעָ֖ה אָֽלֶף׃ס","wĕ⁠ʻa֞l maẖàlò֣qeţ ׀ ha⁠ẖò֣deş̌ ha⁠şé̇̌ni֗y ḋwòda֤y há⁠ʼàẖwòẖiy֙ ẇ⁠ma֣ẖàluqĕţ̇֔⁠wò ẇ⁠miqĕl֖wòţ ha⁠ná̇gi֑yd wĕ⁠ʻal֙ maẖàluqĕţ̇֔⁠wò ʻeşĕ̂ri֥ym wĕ⁠ʼarĕbá̇ʻá֖h ʼáֽlep׃s"],[27,5,"שַׂ֣ר הַ⁠צָּבָ֤א הַ⁠שְּׁלִישִׁי֙ לַ⁠חֹ֣דֶשׁ הַ⁠שְּׁלִישִׁ֔י בְּנָיָ֧הוּ בֶן־יְהוֹיָדָ֛ע הַ⁠כֹּהֵ֖ן רֹ֑אשׁ וְ⁠עַל֙ מַחֲלֻקְתּ֔⁠וֹ עֶשְׂרִ֥ים וְ⁠אַרְבָּעָ֖ה אָֽלֶף׃","şâ֣r ha⁠ẕá̇bá֤ʼ ha⁠şĕ̇̌liyşǐy֙ la⁠ẖò֣deş̌ ha⁠şĕ̇̌liyşǐ֔y bĕ̇náyá֧hẇ ben-yĕhwòyádá֛ʻ ha⁠kò̇hé֖n rò֑ʼş̌ wĕ⁠ʻal֙ maẖàluqĕţ̇֔⁠wò ʻeşĕ̂ri֥ym wĕ⁠ʼarĕbá̇ʻá֖h ʼáֽlep׃"],[27,6,"ה֧וּא בְנָיָ֛הוּ גִּבּ֥וֹר הַ⁠שְּׁלֹשִׁ֖ים וְ⁠עַל־הַ⁠שְּׁלֹשִׁ֑ים וּ⁠מַ֣חֲלֻקְתּ֔⁠וֹ עַמִּיזָבָ֖ד בְּנֽ⁠וֹ׃ס","h֧ẇʼ bĕnáyá֛hẇ gi̇ḃ֥wòr ha⁠şĕ̇̌lòşǐ֖ym wĕ⁠ʻal-ha⁠şĕ̇̌lòşǐ֑ym ẇ⁠ma֣ẖàluqĕţ̇֔⁠wò ʻami̇yzábá֖d bĕ̇nֽ⁠wò׃s"],[27,7,"הָֽ⁠רְבִיעִ֞י לַ⁠חֹ֣דֶשׁ הָ⁠רְבִיעִ֗י עֲשָׂה־אֵל֙ אֲחִ֣י יוֹאָ֔ב וּ⁠זְבַדְיָ֥ה בְנ֖⁠וֹ אַחֲרָ֑י⁠ו וְ⁠עַל֙ מַחֲלֻקְתּ֔⁠וֹ עֶשְׂרִ֥ים וְ⁠אַרְבָּעָ֖ה אָֽלֶף׃ס","háֽ⁠rĕbiyʻi֞y la⁠ẖò֣deş̌ há⁠rĕbiyʻi֗y ʻàşá̂h-ʼél֙ ʼàẖi֣y ywòʼá֔b ẇ⁠zĕbadĕyá֥h bĕn֖⁠wò ʼaẖàrá֑y⁠w wĕ⁠ʻal֙ maẖàluqĕţ̇֔⁠wò ʻeşĕ̂ri֥ym wĕ⁠ʼarĕbá̇ʻá֖h ʼáֽlep׃s"],[27,8,"הַ⁠חַמִישִׁי֙ לַ⁠חֹ֣דֶשׁ הַ⁠חֲמִישִׁ֔י הַ⁠שַּׂ֖ר שַׁמְה֣וּת הַ⁠יִּזְרָ֑ח וְ⁠עַל֙ מַחֲלֻקְתּ֔⁠וֹ עֶשְׂרִ֥ים וְ⁠אַרְבָּעָ֖ה אָֽלֶף׃ס","ha⁠ẖamiyşǐy֙ la⁠ẖò֣deş̌ ha⁠ẖàmiyşǐ֔y ha⁠şȧ֖̂r şǎmĕh֣ẇţ ha⁠yi̇zĕrá֑ẖ wĕ⁠ʻal֙ maẖàluqĕţ̇֔⁠wò ʻeşĕ̂ri֥ym wĕ⁠ʼarĕbá̇ʻá֖h ʼáֽlep׃s"],[27,9,"הַ⁠שִּׁשִּׁי֙ לַ⁠חֹ֣דֶשׁ הַ⁠שִּׁשִּׁ֔י עִירָ֥א בֶן־עִקֵּ֖שׁ הַ⁠תְּקוֹעִ֑י וְ⁠עַל֙ מַחֲלֻקְתּ֔⁠וֹ עֶשְׂרִ֥ים וְ⁠אַרְבָּעָ֖ה אָֽלֶף׃ס","ha⁠şi̇̌şi̇̌y֙ la⁠ẖò֣deş̌ ha⁠şi̇̌şi̇̌֔y ʻiyrá֥ʼ ben-ʻiqé֖̇ş̌ ha⁠ţĕ̇qwòʻi֑y wĕ⁠ʻal֙ maẖàluqĕţ̇֔⁠wò ʻeşĕ̂ri֥ym wĕ⁠ʼarĕbá̇ʻá֖h ʼáֽlep׃s"],[27,10,"הַ⁠שְּׁבִיעִי֙ לַ⁠חֹ֣דֶשׁ הַ⁠שְּׁבִיעִ֔י חֶ֥לֶץ הַ⁠פְּלוֹנִ֖י מִן־בְּנֵ֣י אֶפְרָ֑יִם וְ⁠עַל֙ מַחֲלֻקְתּ֔⁠וֹ עֶשְׂרִ֥ים וְ⁠אַרְבָּעָ֖ה אָֽלֶף׃ס","ha⁠şĕ̇̌biyʻiy֙ la⁠ẖò֣deş̌ ha⁠şĕ̇̌biyʻi֔y ẖe֥leẕ ha⁠pĕ̇lwòni֖y min-bĕ̇né֣y ʼepĕrá֑yim wĕ⁠ʻal֙ maẖàluqĕţ̇֔⁠wò ʻeşĕ̂ri֥ym wĕ⁠ʼarĕbá̇ʻá֖h ʼáֽlep׃s"],[27,11,"הַ⁠שְּׁמִינִי֙ לַ⁠חֹ֣דֶשׁ הַ⁠שְּׁמִינִ֔י סִבְּכַ֥י הַ⁠חֻשָׁתִ֖י לַ⁠זַּרְחִ֑י וְ⁠עַל֙ מַחֲלֻקְתּ֔⁠וֹ עֶשְׂרִ֥ים וְ⁠אַרְבָּעָ֖ה אָֽלֶף׃ס","ha⁠şĕ̇̌miyniy֙ la⁠ẖò֣deş̌ ha⁠şĕ̇̌miyni֔y sibĕ̇ka֥y ha⁠ẖuşá̌ţi֖y la⁠zȧrĕẖi֑y wĕ⁠ʻal֙ maẖàluqĕţ̇֔⁠wò ʻeşĕ̂ri֥ym wĕ⁠ʼarĕbá̇ʻá֖h ʼáֽlep׃s"],[27,12,"הַ⁠תְּשִׁיעִי֙ לַ⁠חֹ֣דֶשׁ הַ⁠תְּשִׁיעִ֔י אֲבִיעֶ֥זֶר הָ⁠עַנְּתֹתִ֖י ל⁠בנימיני וְ⁠עַל֙ מַחֲלֻקְתּ֔⁠וֹ עֶשְׂרִ֥ים וְ⁠אַרְבָּעָ֖ה אָֽלֶף׃ס","ha⁠ţĕ̇şǐyʻiy֙ la⁠ẖò֣deş̌ ha⁠ţĕ̇şǐyʻi֔y ʼàbiyʻe֥zer há⁠ʻanĕ̇ţòţi֖y l⁠bnymyny wĕ⁠ʻal֙ maẖàluqĕţ̇֔⁠wò ʻeşĕ̂ri֥ym wĕ⁠ʼarĕbá̇ʻá֖h ʼáֽlep׃s"],[27,13,"הָ⁠עֲשִׂירִי֙ לַ⁠חֹ֣דֶשׁ הָ⁠עֲשִׂירִ֔י מַהְרַ֥י הַ⁠נְּטֽוֹפָתִ֖י לַ⁠זַּרְחִ֑י וְ⁠עַל֙ מַֽחֲלֻקְתּ֔⁠וֹ עֶשְׂרִ֥ים וְ⁠אַרְבָּעָ֖ה אָֽלֶף׃ס","há⁠ʻàşîyriy֙ la⁠ẖò֣deş̌ há⁠ʻàşîyri֔y mahĕra֥y ha⁠nĕ̇tֽwòpáţi֖y la⁠zȧrĕẖi֑y wĕ⁠ʻal֙ maֽẖàluqĕţ̇֔⁠wò ʻeşĕ̂ri֥ym wĕ⁠ʼarĕbá̇ʻá֖h ʼáֽlep׃s"],[27,14,"עַשְׁתֵּֽי־עָשָׂר֙ לְ⁠עַשְׁתֵּ֣י־עָשָׂ֣ר הַ⁠חֹ֔דֶשׁ בְּנָיָ֥ה הַ⁠פִּרְעָתוֹנִ֖י מִן־בְּנֵ֣י אֶפְרָ֑יִם וְ⁠עַל֙ מַחֲלֻקְתּ֔⁠וֹ עֶשְׂרִ֥ים וְ⁠אַרְבָּעָ֖ה אָֽלֶף׃ס","ʻaşĕ̌ţéֽ̇y-ʻáşá̂r֙ lĕ⁠ʻaşĕ̌ţé֣̇y-ʻáşá֣̂r ha⁠ẖò֔deş̌ bĕ̇náyá֥h ha⁠pi̇rĕʻáţwòni֖y min-bĕ̇né֣y ʼepĕrá֑yim wĕ⁠ʻal֙ maẖàluqĕţ̇֔⁠wò ʻeşĕ̂ri֥ym wĕ⁠ʼarĕbá̇ʻá֖h ʼáֽlep׃s"],[27,15,"הַ⁠שְּׁנֵ֤ים עָשָׂר֙ לִ⁠שְׁנֵ֣ים עָשָׂ֣ר הַ⁠חֹ֔דֶשׁ חֶלְדַּ֥י הַ⁠נְּטוֹפָתִ֖י לְ⁠עָתְנִיאֵ֑ל וְ⁠עַל֙ מַחֲלֻקְתּ֔⁠וֹ עֶשְׂרִ֥ים וְ⁠אַרְבָּעָ֖ה אָֽלֶף׃פ","ha⁠şĕ̇̌né֤ym ʻáşá̂r֙ li⁠şĕ̌né֣ym ʻáşá֣̂r ha⁠ẖò֔deş̌ ẖelĕdȧ֥y ha⁠nĕ̇twòpáţi֖y lĕ⁠ʻáţĕniyʼé֑l wĕ⁠ʻal֙ maẖàluqĕţ̇֔⁠wò ʻeşĕ̂ri֥ym wĕ⁠ʼarĕbá̇ʻá֖h ʼáֽlep׃p"],[27,16,"וְ⁠עַל֙ שִׁבְטֵ֣י יִשְׂרָאֵ֔ל לָ⁠רֽאוּבֵנִ֣י נָגִ֔יד אֱלִיעֶ֖זֶר בֶּן־זִכְרִ֑י ס לַ⁠שִּׁ֨מְעוֹנִ֔י שְׁפַטְיָ֖הוּ בֶּֽן־מַעֲכָֽה׃ס","wĕ⁠ʻal֙ şǐbĕté֣y yişĕ̂ráʼé֔l lá⁠rֽʼẇbéni֣y nági֔yd ʼèliyʻe֖zer bėn-zikĕri֑y s la⁠şi̇̌֨mĕʻwòni֔y şĕ̌patĕyá֖hẇ bėֽn-maʻàkáֽh׃s"],[27,17,"לְ⁠לֵוִ֛י חֲשַׁבְיָ֥ה בֶן־קְמוּאֵ֖ל לְ⁠אַהֲרֹ֥ן צָדֽוֹק׃ס","lĕ⁠léwi֛y ẖàşǎbĕyá֥h ben-qĕmẇʼé֖l lĕ⁠ʼahàrò֥n ẕádֽwòq׃s"],[27,18,"לִֽ⁠יהוּדָ֕ה אֱלִיה֖וּ מֵ⁠אֲחֵ֣י דָוִ֑יד לְ⁠יִ֨שָׂשכָ֔ר עָמְרִ֖י בֶּן־מִיכָאֵֽל׃ס","liֽ⁠yhẇdá֕h ʼèliyh֖ẇ mé⁠ʼàẖé֣y dáwi֑yd lĕ⁠yi֨şá̂şká֔r ʻámĕri֖y bėn-miykáʼéֽl׃s"],[27,19,"לִ⁠זְבוּלֻ֕ן יִֽשְׁמַֽעְיָ֖הוּ בֶּן־עֹבַדְיָ֑הוּ לְ⁠נַ֨פְתָּלִ֔י יְרִימ֖וֹת בֶּן־עַזְרִיאֵֽל׃ס","li⁠zĕbẇlu֕n yiֽşĕ̌maֽʻĕyá֖hẇ bėn-ʻòbadĕyá֑hẇ lĕ⁠na֨pĕţá̇li֔y yĕriym֖wòţ bėn-ʻazĕriyʼéֽl׃s"],[27,20,"לִ⁠בְנֵ֣י אֶפְרַ֔יִם הוֹשֵׁ֖עַ בֶּן־עֲזַזְיָ֑הוּ לַ⁠חֲצִי֙ שֵׁ֣בֶט מְנַשֶּׁ֔ה יוֹאֵ֖ל בֶּן־פְּדָיָֽהוּ׃ס","li⁠bĕné֣y ʼepĕra֔yim hwòşé֖̌ʻa bėn-ʻàzazĕyá֑hẇ la⁠ẖàẕiy֙ şé֣̌bet mĕnaşė̌֔h ywòʼé֖l bėn-pĕ̇dáyáֽhẇ׃s"],[27,21,"לַ⁠חֲצִ֤י הַֽ⁠מְנַשֶּׁה֙ גִּלְעָ֔דָ⁠ה יִדּ֖וֹ בֶּן־זְכַרְיָ֑הוּ ס לְ⁠בִנְיָמִ֔ן יַעֲשִׂיאֵ֖ל בֶּן־אַבְנֵֽר׃ס","la⁠ẖàẕi֤y haֽ⁠mĕnaşė̌h֙ gi̇lĕʻá֔dá⁠h yiḋ֖wò bėn-zĕkarĕyá֑hẇ s lĕ⁠binĕyámi֔n yaʻàşîyʼé֖l bėn-ʼabĕnéֽr׃s"],[27,22,"לְ⁠דָ֕ן עֲזַרְאֵ֖ל בֶּן־יְרֹחָ֑ם אֵ֕לֶּה שָׂרֵ֖י שִׁבְטֵ֥י יִשְׂרָאֵֽל׃","lĕ⁠dá֕n ʻàzarĕʼé֖l bėn-yĕròẖá֑m ʼé֕lėh şá̂ré֖y şǐbĕté֥y yişĕ̂ráʼéֽl׃"],[27,23,"וְ⁠לֹא־נָשָׂ֤א דָוִיד֙ מִסְפָּרָ֔⁠ם לְ⁠מִ⁠בֶּ֛ן עֶשְׂרִ֥ים שָׁנָ֖ה וּ⁠לְ⁠מָ֑טָּה כִּ֚י אָמַ֣ר יְהוָ֔ה לְ⁠הַרְבּ֥וֹת אֶת־יִשְׂרָאֵ֖ל כְּ⁠כוֹכְבֵ֥י הַ⁠שָּׁמָֽיִם׃","wĕ⁠lòʼ-náşá֤̂ʼ dáwiyd֙ misĕpá̇rá֔⁠m lĕ⁠mi⁠bė֛n ʻeşĕ̂ri֥ym şá̌ná֖h ẇ⁠lĕ⁠má֑tá̇h ki֚̇y ʼáma֣r yĕhwá֔h lĕ⁠harĕḃ֥wòţ ʼeţ-yişĕ̂ráʼé֖l kĕ̇⁠kwòkĕbé֥y ha⁠şá̇̌máֽyim׃"],[27,24,"יוֹאָ֨ב בֶּן־צְרוּיָ֜ה הֵחֵ֤ל לִ⁠מְנוֹת֙ וְ⁠לֹ֣א כִלָּ֔ה וַ⁠יְהִ֥י בָ⁠זֹ֛את קֶ֖צֶף עַל־יִשְׂרָאֵ֑ל וְ⁠לֹ֤א עָלָה֙ הַ⁠מִּסְפָּ֔ר בְּ⁠מִסְפַּ֥ר דִּבְרֵֽי־הַ⁠יָּמִ֖ים לַ⁠מֶּ֥לֶךְ דָּוִֽיד׃ס","ywòʼá֨b bėn-ẕĕrẇyá֜h héẖé֤l li⁠mĕnwòţ֙ wĕ⁠lò֣ʼ kilá̇֔h wa⁠yĕhi֥y bá⁠zò֛ʼţ qe֖ẕep ʻal-yişĕ̂ráʼé֑l wĕ⁠lò֤ʼ ʻáláh֙ ha⁠mi̇sĕpá̇֔r bĕ̇⁠misĕpȧ֥r di̇bĕréֽy-ha⁠yá̇mi֖ym la⁠mė֥lekĕ dá̇wiֽyd׃s"],[27,25,"וְ⁠עַל֙ אֹצְר֣וֹת הַ⁠מֶּ֔לֶךְ עַזְמָ֖וֶת בֶּן־עֲדִיאֵ֑ל ס וְ⁠עַ֣ל הָֽ⁠אֹצָר֡וֹת בַּ⁠שָּׂדֶ֞ה בֶּ⁠עָרִ֤ים וּ⁠בַ⁠כְּפָרִים֙ וּ⁠בַ⁠מִּגְדָּל֔וֹת יְהוֹנָתָ֖ן בֶּן־עֻזִּיָּֽהוּ׃ס","wĕ⁠ʻal֙ ʼòẕĕr֣wòţ ha⁠mė֔lekĕ ʻazĕmá֖weţ bėn-ʻàdiyʼé֑l s wĕ⁠ʻa֣l háֽ⁠ʼòẕár֡wòţ bȧ⁠şá̇̂de֞h bė⁠ʻári֤ym ẇ⁠ba⁠kĕ̇páriym֙ ẇ⁠ba⁠mi̇gĕdá̇l֔wòţ yĕhwònáţá֖n bėn-ʻuzi̇yáֽ̇hẇ׃s"],[27,26,"וְ⁠עַ֗ל עֹשֵׂי֙ מְלֶ֣אכֶת הַ⁠שָּׂדֶ֔ה לַ⁠עֲבֹדַ֖ת הָ⁠אֲדָמָ֑ה עֶזְרִ֖י בֶּן־כְּלֽוּב׃","wĕ⁠ʻa֗l ʻòşé̂y֙ mĕle֣ʼkeţ ha⁠şá̇̂de֔h la⁠ʻàbòda֖ţ há⁠ʼàdámá֑h ʻezĕri֖y bėn-kĕ̇lֽẇb׃"],[27,27,"וְ⁠עַל־הַ֨⁠כְּרָמִ֔ים שִׁמְעִ֖י הָ⁠רָֽמָתִ֑י וְ⁠עַ֤ל שֶׁ⁠בַּ⁠כְּרָמִים֙ לְ⁠אֹצְר֣וֹת הַ⁠יַּ֔יִן זַבְדִּ֖י הַ⁠שִּׁפְמִֽי׃ס","wĕ⁠ʻal-ha֨⁠kĕ̇rámi֔ym şǐmĕʻi֖y há⁠ráֽmáţi֑y wĕ⁠ʻa֤l şě⁠bȧ⁠kĕ̇rámiym֙ lĕ⁠ʼòẕĕr֣wòţ ha⁠yȧ֔yin zabĕdi֖̇y ha⁠şi̇̌pĕmiֽy׃s"],[27,28,"וְ⁠עַל־הַ⁠זֵּיתִ֤ים וְ⁠הַ⁠שִּׁקְמִים֙ אֲשֶׁ֣ר בַּ⁠שְּׁפֵלָ֔ה בַּ֥עַל חָנָ֖ן הַ⁠גְּדֵרִ֑י ס וְ⁠עַל־אֹצְר֥וֹת הַ⁠שֶּׁ֖מֶן יוֹעָֽשׁ׃ס","wĕ⁠ʻal-ha⁠zé̇yţi֤ym wĕ⁠ha⁠şi̇̌qĕmiym֙ ʼàşě֣r bȧ⁠şĕ̇̌pélá֔h bȧ֥ʻal ẖáná֖n ha⁠gĕ̇déri֑y s wĕ⁠ʻal-ʼòẕĕr֥wòţ ha⁠şė֖̌men ywòʻáֽş̌׃s"],[27,29,"וְ⁠עַל־הַ⁠בָּקָר֙ הָ⁠רֹעִ֣ים בַּ⁠שָּׁר֔וֹן שטרי הַ⁠שָּׁרוֹנִ֑י וְ⁠עַל־הַ⁠בָּקָר֙ בָּֽ⁠עֲמָקִ֔ים שָׁפָ֖ט בֶּן־עַדְלָֽי׃ס","wĕ⁠ʻal-ha⁠bá̇qár֙ há⁠ròʻi֣ym bȧ⁠şá̇̌r֔wòn ştry ha⁠şá̇̌rwòni֑y wĕ⁠ʻal-ha⁠bá̇qár֙ báֽ̇⁠ʻàmáqi֔ym şá̌pá֖t bėn-ʻadĕláֽy׃s"],[27,30,"וְ⁠עַל־הַ֨⁠גְּמַלִּ֔ים אוֹבִ֖יל הַ⁠יִּשְׁמְעֵלִ֑י וְ⁠עַל־הָ֣⁠אֲתֹנ֔וֹת יֶחְדְּיָ֖הוּ הַ⁠מֵּרֹנֹתִֽי׃ס","wĕ⁠ʻal-ha֨⁠gĕ̇mali̇֔ym ʼwòbi֖yl ha⁠yi̇şĕ̌mĕʻéli֑y wĕ⁠ʻal-há֣⁠ʼàţòn֔wòţ yeẖĕdĕ̇yá֖hẇ ha⁠mé̇rònòţiֽy׃s"],[27,31,"וְ⁠עַל־הַ⁠צֹּ֖אן יָזִ֣יז הַֽ⁠הַגְרִ֑י כָּל־אֵ֨לֶּה֙ שָׂרֵ֣י הָ⁠רְכ֔וּשׁ אֲשֶׁ֖ר לַ⁠מֶּ֥לֶךְ דָּוִֽיד׃","wĕ⁠ʻal-ha⁠ẕò֖̇ʼn yázi֣yz haֽ⁠hagĕri֑y ká̇l-ʼé֨lėh֙ şá̂ré֣y há⁠rĕk֔ẇş̌ ʼàşě֖r la⁠mė֥lekĕ dá̇wiֽyd׃"],[27,32,"וִֽ⁠יהוֹנָתָ֤ן דּוֹד־דָּוִיד֙ יוֹעֵ֔ץ אִישׁ־מֵבִ֥ין וְ⁠סוֹפֵ֖ר ה֑וּא וִֽ⁠יחִיאֵ֥ל בֶּן־חַכְמוֹנִ֖י עִם־בְּנֵ֥י הַ⁠מֶּֽלֶךְ׃","wiֽ⁠yhwònáţá֤n ḋwòd-dá̇wiyd֙ ywòʻé֔ẕ ʼiyş̌-mébi֥yn wĕ⁠swòpé֖r h֑ẇʼ wiֽ⁠yẖiyʼé֥l bėn-ẖakĕmwòni֖y ʻim-bĕ̇né֥y ha⁠mėֽlekĕ׃"],[27,33,"וַ⁠אֲחִיתֹ֖פֶל יוֹעֵ֣ץ לַ⁠מֶּ֑לֶךְ ס וְ⁠חוּשַׁ֥י הָ⁠אַרְכִּ֖י רֵ֥עַ הַ⁠מֶּֽלֶךְ׃","wa⁠ʼàẖiyţò֖pel ywòʻé֣ẕ la⁠mė֑lekĕ s wĕ⁠ẖẇşǎ֥y há⁠ʼarĕki֖̇y ré֥ʻa ha⁠mėֽlekĕ׃"],[27,34,"וְ⁠אַחֲרֵ֣י אֲחִיתֹ֗פֶל יְהוֹיָדָ֤ע בֶּן־בְּנָיָ֨הוּ֙ וְ⁠אֶבְיָתָ֔ר וְ⁠שַׂר־צָבָ֥א לַ⁠מֶּ֖לֶךְ יוֹאָֽב׃פ","wĕ⁠ʼaẖàré֣y ʼàẖiyţò֗pel yĕhwòyádá֤ʻ bėn-bĕ̇náyá֨hẇ֙ wĕ⁠ʼebĕyáţá֔r wĕ⁠şâr-ẕábá֥ʼ la⁠mė֖lekĕ ywòʼáֽb׃p"],[28,1,"וַ⁠יַּקְהֵ֣ל דָּוִ֣יד אֶת־כָּל־שָׂרֵ֣י יִשְׂרָאֵ֡ל שָׂרֵ֣י הַ⁠שְּׁבָטִ֣ים וְ⁠שָׂרֵ֣י הַ⁠מַּחְלְק֣וֹת הַ⁠מְשָׁרְתִ֪ים אֶת־הַ⁠מֶּ֟לֶךְ וְ⁠שָׂרֵ֣י הָ⁠אֲלָפִ֣ים וְ⁠שָׂרֵ֣י הַ⁠מֵּא֡וֹת וְ⁠שָׂרֵ֣י כָל־רְכוּשׁ־וּ⁠מִקְנֶה֩ ׀ לַ⁠מֶּ֨לֶךְ וּ⁠לְ⁠בָנָ֜י⁠ו עִם־הַ⁠סָּרִיסִ֧ים וְ⁠הַ⁠גִּבּוֹרִ֛ים וּֽ⁠לְ⁠כָל־גִּבּ֥וֹר חָ֖יִל אֶל־יְרוּשָׁלִָֽם׃","wa⁠yȧqĕhé֣l dá̇wi֣yd ʼeţ-ká̇l-şá̂ré֣y yişĕ̂ráʼé֡l şá̂ré֣y ha⁠şĕ̇̌báti֣ym wĕ⁠şá̂ré֣y ha⁠mȧẖĕlĕq֣wòţ ha⁠mĕşá̌rĕţi֪ym ʼeţ-ha⁠mė֟lekĕ wĕ⁠şá̂ré֣y há⁠ʼàlápi֣ym wĕ⁠şá̂ré֣y ha⁠mé̇ʼ֡wòţ wĕ⁠şá̂ré֣y kál-rĕkẇş̌-ẇ⁠miqĕneh֩ ׀ la⁠mė֨lekĕ ẇ⁠lĕ⁠báná֜y⁠w ʻim-ha⁠sá̇riysi֧ym wĕ⁠ha⁠gi̇ḃwòri֛ym ẇֽ⁠lĕ⁠kál-gi̇ḃ֥wòr ẖá֖yil ʼel-yĕrẇşá̌liáֽm׃"],[28,2,"וַ⁠יָּ֨קָם דָּוִ֤יד הַ⁠מֶּ֨לֶךְ֙ עַל־רַגְלָ֔י⁠ו וַ⁠יֹּ֕אמֶר שְׁמָע֖וּ⁠נִי אַחַ֣⁠י וְ⁠עַמִּ֑⁠י אֲנִ֣י עִם־לְבָבִ֡⁠י לִ⁠בְנוֹת֩ בֵּ֨ית מְנוּחָ֜ה לַ⁠אֲר֣וֹן בְּרִית־יְהוָ֗ה וְ⁠לַ⁠הֲדֹם֙ רַגְלֵ֣י אֱלֹהֵ֔י⁠נוּ וַ⁠הֲכִינ֖וֹתִי לִ⁠בְנֽוֹת׃","wa⁠yá̇֨qám dá̇wi֤yd ha⁠mė֨lekĕ֙ ʻal-ragĕlá֔y⁠w wa⁠yò̇֕ʼmer şĕ̌máʻ֖ẇ⁠niy ʼaẖa֣⁠y wĕ⁠ʻami֑̇⁠y ʼàni֣y ʻim-lĕbábi֡⁠y li⁠bĕnwòţ֩ bé̇֨yţ mĕnẇẖá֜h la⁠ʼàr֣wòn bĕ̇riyţ-yĕhwá֗h wĕ⁠la⁠hàdòm֙ ragĕlé֣y ʼèlòhé֔y⁠nẇ wa⁠hàkiyn֖wòţiy li⁠bĕnֽwòţ׃"],[28,3,"וְ⁠הָ⁠אֱלֹהִים֙ אָ֣מַר לִ֔⁠י לֹא־תִבְנֶ֥ה בַ֖יִת לִ⁠שְׁמִ֑⁠י כִּ֣י אִ֧ישׁ מִלְחָמ֛וֹת אַ֖תָּה וְ⁠דָמִ֥ים שָׁפָֽכְתָּ׃","wĕ⁠há⁠ʼèlòhiym֙ ʼá֣mar li֔⁠y lòʼ-ţibĕne֥h ba֖yiţ li⁠şĕ̌mi֑⁠y ki֣̇y ʼi֧yş̌ milĕẖám֛wòţ ʼa֖ţá̇h wĕ⁠dámi֥ym şá̌páֽkĕţá̇׃"],[28,4,"וַ⁠יִּבְחַ֡ר יְהוָ֣ה אֱלֹהֵי֩ יִשְׂרָאֵ֨ל בִּ֜⁠י מִ⁠כֹּ֣ל בֵּית־אָבִ֗⁠י לִ⁠הְי֨וֹת לְ⁠מֶ֤לֶךְ עַל־יִשְׂרָאֵל֙ לְ⁠עוֹלָ֔ם כִּ֤י בִֽ⁠יהוּדָה֙ בָּחַ֣ר לְ⁠נָגִ֔יד וּ⁠בְ⁠בֵ֥ית יְהוּדָ֖ה בֵּ֣ית אָבִ֑⁠י וּ⁠בִ⁠בְנֵ֣י אָבִ֔⁠י בִּ֣⁠י רָצָ֔ה לְ⁠הַמְלִ֖יךְ עַל־כָּל־יִשְׂרָאֵֽל׃","wa⁠yi̇bĕẖa֡r yĕhwá֣h ʼèlòhéy֩ yişĕ̂ráʼé֨l bi̇֜⁠y mi⁠kò֣̇l bé̇yţ-ʼábi֗⁠y li⁠hĕy֨wòţ lĕ⁠me֤lekĕ ʻal-yişĕ̂ráʼél֙ lĕ⁠ʻwòlá֔m ki֤̇y biֽ⁠yhẇdáh֙ bá̇ẖa֣r lĕ⁠nági֔yd ẇ⁠bĕ⁠bé֥yţ yĕhẇdá֖h bé֣̇yţ ʼábi֑⁠y ẇ⁠bi⁠bĕné֣y ʼábi֔⁠y bi֣̇⁠y ráẕá֔h lĕ⁠hamĕli֖ykĕ ʻal-ká̇l-yişĕ̂ráʼéֽl׃"],[28,5,"וּ⁠מִ⁠כָּ֨ל־בָּנַ֔⁠י כִּ֚י רַבִּ֣ים בָּנִ֔ים נָ֥תַן לִ֖⁠י יְהוָ֑ה וַ⁠יִּבְחַר֙ בִּ⁠שְׁלֹמֹ֣ה בְנִ֔⁠י לָ⁠שֶׁ֗בֶת עַל־כִּסֵּ֛א מַלְכ֥וּת יְהוָ֖ה עַל־יִשְׂרָאֵֽל׃","ẇ⁠mi⁠ká̇֨l-bá̇na֔⁠y ki֚̇y rabi֣̇ym bá̇ni֔ym ná֥ţan li֖⁠y yĕhwá֑h wa⁠yi̇bĕẖar֙ bi̇⁠şĕ̌lòmò֣h bĕni֔⁠y lá⁠şě֗beţ ʻal-ki̇sé֛̇ʼ malĕk֥ẇţ yĕhwá֖h ʻal-yişĕ̂ráʼéֽl׃"],[28,6,"וַ⁠יֹּ֣אמֶר לִ֔⁠י שְׁלֹמֹ֣ה בִנְ⁠ךָ֔ הֽוּא־יִבְנֶ֥ה בֵיתִ֖⁠י וַ⁠חֲצֵרוֹתָ֑⁠י כִּי־בָחַ֨רְתִּי ב֥⁠וֹ לִ⁠י֙ לְ⁠בֵ֔ן וַ⁠אֲנִ֖י אֶֽהְיֶה־לּ֥⁠וֹ לְ⁠אָֽב׃","wa⁠yò֣̇ʼmer li֔⁠y şĕ̌lòmò֣h binĕ⁠ká֔ hֽẇʼ-yibĕne֥h béyţi֖⁠y wa⁠ẖàẕérwòţá֑⁠y ki̇y-báẖa֨rĕţi̇y b֥⁠wò li⁠y֙ lĕ⁠bé֔n wa⁠ʼàni֖y ʼeֽhĕyeh-l֥̇⁠wò lĕ⁠ʼáֽb׃"],[28,7,"וַ⁠הֲכִינוֹתִ֥י אֶת־מַלְכוּת֖⁠וֹ עַד־לְ⁠עוֹלָ֑ם אִם־יֶחֱזַ֗ק לַ⁠עֲשׂ֛וֹת מִצְוֺתַ֥⁠י וּ⁠מִשְׁפָּטַ֖⁠י כַּ⁠יּ֥וֹם הַ⁠זֶּֽה׃","wa⁠hàkiynwòţi֥y ʼeţ-malĕkẇţ֖⁠wò ʻad-lĕ⁠ʻwòlá֑m ʼim-yeẖèza֗q la⁠ʻàş֛̂wòţ miẕĕwֺţa֥⁠y ẇ⁠mişĕ̌pá̇ta֖⁠y kȧ⁠ẏ֥wòm ha⁠zėֽh׃"],[28,8,"וְ֠⁠עַתָּה לְ⁠עֵינֵ֨י כָל־יִשְׂרָאֵ֤ל קְהַל־יְהוָה֙ וּ⁠בְ⁠אָזְנֵ֣י אֱלֹהֵ֔י⁠נוּ שִׁמְר֣וּ וְ⁠דִרְשׁ֔וּ כָּל־מִצְוֺ֖ת יְהוָ֣ה אֱלֹהֵי⁠כֶ֑ם לְמַ֤עַן תִּֽירְשׁוּ֙ אֶת־הָ⁠אָ֣רֶץ הַ⁠טּוֹבָ֔ה וְ⁠הִנְחַלְתֶּ֛ם לִ⁠בְנֵי⁠כֶ֥ם אַחֲרֵי⁠כֶ֖ם עַד־עוֹלָֽם׃פ","wĕ֠⁠ʻaţá̇h lĕ⁠ʻéyné֨y kál-yişĕ̂ráʼé֤l qĕhal-yĕhwáh֙ ẇ⁠bĕ⁠ʼázĕné֣y ʼèlòhé֔y⁠nẇ şǐmĕr֣ẇ wĕ⁠dirĕş̌֔ẇ ká̇l-miẕĕwֺ֖ţ yĕhwá֣h ʼèlòhéy⁠ke֑m lĕma֤ʻan ţiֽ̇yrĕş̌ẇ֙ ʼeţ-há⁠ʼá֣reẕ ha⁠ṫwòbá֔h wĕ⁠hinĕẖalĕţė֛m li⁠bĕnéy⁠ke֥m ʼaẖàréy⁠ke֖m ʻad-ʻwòláֽm׃p"],[28,9,"וְ⁠אַתָּ֣ה שְׁלֹמֹֽה־בְנִ֡⁠י דַּע֩ אֶת־אֱלֹהֵ֨י אָבִ֜י⁠ךָ וְ⁠עָבְדֵ֗⁠הוּ בְּ⁠לֵ֤ב שָׁלֵם֙ וּ⁠בְ⁠נֶ֣פֶשׁ חֲפֵצָ֔ה כִּ֤י כָל־לְבָבוֹת֙ דּוֹרֵ֣שׁ יְהוָ֔ה וְ⁠כָל־יֵ֥צֶר מַחֲשָׁב֖וֹת מֵבִ֑ין אִֽם־תִּדְרְשֶׁ֨⁠נּוּ֙ יִמָּ֣צֵא לָ֔⁠ךְ וְ⁠אִם־תַּֽעַזְבֶ֖⁠נּוּ יַזְנִיחֲ⁠ךָ֥ לָ⁠עַֽד׃","wĕ⁠ʼaţá֣̇h şĕ̌lòmòֽh-bĕni֡⁠y dȧʻ֩ ʼeţ-ʼèlòhé֨y ʼábi֜y⁠ká wĕ⁠ʻábĕdé֗⁠hẇ bĕ̇⁠lé֤b şá̌lém֙ ẇ⁠bĕ⁠ne֣peş̌ ẖàpéẕá֔h ki֤̇y kál-lĕbábwòţ֙ ḋwòré֣ş̌ yĕhwá֔h wĕ⁠kál-yé֥ẕer maẖàşá̌b֖wòţ mébi֑yn ʼiֽm-ţi̇dĕrĕşě֨⁠ṅẇ֙ yimá֣̇ẕéʼ lá֔⁠kĕ wĕ⁠ʼim-ţȧֽʻazĕbe֖⁠ṅẇ yazĕniyẖà⁠ká֥ lá⁠ʻaֽd׃"],[28,10,"רְאֵ֣ה ׀ עַתָּ֗ה כִּֽי־יְהוָ֛ה בָּ֧חַר בְּ⁠ךָ֛ לִ⁠בְנֽוֹת־בַּ֥יִת לַ⁠מִּקְדָּ֖שׁ חֲזַ֥ק וַ⁠עֲשֵֽׂה׃פ","rĕʼé֣h ׀ ʻaţá̇֗h kiֽ̇y-yĕhwá֛h bá֧̇ẖar bĕ̇⁠ká֛ li⁠bĕnֽwòţ-bȧ֥yiţ la⁠mi̇qĕdá֖̇ş̌ ẖàza֥q wa⁠ʻàşéֽ̂h׃p"],[28,11,"וַ⁠יִּתֵּ֣ן דָּוִ֣יד לִ⁠שְׁלֹמֹ֣ה בְנ֡⁠וֹ אֶת־תַּבְנִ֣ית הָ⁠אוּלָם֩ וְֽ⁠אֶת־בָּ֨תָּ֜י⁠ו וְ⁠גַנְזַכָּ֧י⁠ו וַ⁠עֲלִיֹּתָ֛י⁠ו וַ⁠חֲדָרָ֥י⁠ו הַ⁠פְּנִימִ֖ים וּ⁠בֵ֥ית הַ⁠כַּפֹּֽרֶת׃","wa⁠yi̇ţé֣̇n dá̇wi֣yd li⁠şĕ̌lòmò֣h bĕn֡⁠wò ʼeţ-ţȧbĕni֣yţ há⁠ʼẇlám֩ wֽĕ⁠ʼeţ-bá̇֨ţá̇֜y⁠w wĕ⁠ganĕzaká֧̇y⁠w wa⁠ʻàliyò̇ţá֛y⁠w wa⁠ẖàdárá֥y⁠w ha⁠pĕ̇niymi֖ym ẇ⁠bé֥yţ ha⁠kȧpòֽ̇reţ׃"],[28,12,"וְ⁠תַבְנִ֗ית כֹּל֩ אֲשֶׁ֨ר הָיָ֤ה בָ⁠ר֨וּחַ֙ עִמּ֔⁠וֹ לְ⁠חַצְר֧וֹת בֵּית־יְהוָ֛ה וּ⁠לְ⁠כָל־הַ⁠לְּשָׁכ֖וֹת סָבִ֑יב לְ⁠אֹֽצְרוֹת֙ בֵּ֣ית הָ⁠אֱלֹהִ֔ים וּ⁠לְ⁠אֹצְר֖וֹת הַ⁠קֳּדָשִֽׁים׃","wĕ⁠ţabĕni֗yţ kò̇l֩ ʼàşě֨r háyá֤h bá⁠r֨ẇẖa֙ ʻiṁ֔⁠wò lĕ⁠ẖaẕĕr֧wòţ bé̇yţ-yĕhwá֛h ẇ⁠lĕ⁠kál-ha⁠lĕ̇şá̌k֖wòţ sábi֑yb lĕ⁠ʼòֽẕĕrwòţ֙ bé֣̇yţ há⁠ʼèlòhi֔ym ẇ⁠lĕ⁠ʼòẕĕr֖wòţ ha⁠qȯdáşǐֽym׃"],[28,13,"וּֽ⁠לְ⁠מַחְלְקוֹת֙ הַ⁠כֹּהֲנִ֣ים וְ⁠הַ⁠לְוִיִּ֔ם וּֽ⁠לְ⁠כָל־מְלֶ֖אכֶת עֲבוֹדַ֣ת בֵּית־יְהוָ֑ה וּֽ⁠לְ⁠כָל־כְּלֵ֖י עֲבוֹדַ֥ת בֵּית־יְהוָֽה׃","ẇֽ⁠lĕ⁠maẖĕlĕqwòţ֙ ha⁠kò̇hàni֣ym wĕ⁠ha⁠lĕwiyi̇֔m ẇֽ⁠lĕ⁠kál-mĕle֖ʼkeţ ʻàbwòda֣ţ bé̇yţ-yĕhwá֑h ẇֽ⁠lĕ⁠kál-kĕ̇lé֖y ʻàbwòda֥ţ bé̇yţ-yĕhwáֽh׃"],[28,14,"לַ⁠זָּהָ֤ב בַּ⁠מִּשְׁקָל֙ לַ⁠זָּהָ֔ב לְ⁠כָל־כְּלֵ֖י עֲבוֹדָ֣ה וַ⁠עֲבוֹדָ֑ה לְ⁠כֹ֨ל כְּלֵ֤י הַ⁠כֶּ֨סֶף֙ בְּ⁠מִשְׁקָ֔ל לְ⁠כָל־כְּלֵ֖י עֲבוֹדָ֥ה וַ⁠עֲבוֹדָֽה׃","la⁠zá̇há֤b bȧ⁠mi̇şĕ̌qál֙ la⁠zá̇há֔b lĕ⁠kál-kĕ̇lé֖y ʻàbwòdá֣h wa⁠ʻàbwòdá֑h lĕ⁠kò֨l kĕ̇lé֤y ha⁠kė֨sep֙ bĕ̇⁠mişĕ̌qá֔l lĕ⁠kál-kĕ̇lé֖y ʻàbwòdá֥h wa⁠ʻàbwòdáֽh׃"],[28,15,"וּ⁠מִשְׁקָ֞ל לִ⁠מְנֹר֣וֹת הַ⁠זָּהָ֗ב וְ⁠נֵרֹֽתֵי⁠הֶם֙ זָהָ֔ב בְּ⁠מִשְׁקַל־מְנוֹרָ֥ה וּ⁠מְנוֹרָ֖ה וְ⁠נֵרֹתֶ֑י⁠הָ וְ⁠לִ⁠מְנֹר֨וֹת הַ⁠כֶּ֤סֶף בְּ⁠מִשְׁקָל֙ לִ⁠מְנוֹרָ֣ה וְ⁠נֵרֹתֶ֔י⁠הָ כַּ⁠עֲבוֹדַ֖ת מְנוֹרָ֥ה וּ⁠מְנוֹרָֽה׃","ẇ⁠mişĕ̌qá֞l li⁠mĕnòr֣wòţ ha⁠zá̇há֗b wĕ⁠néròֽţéy⁠hem֙ záhá֔b bĕ̇⁠mişĕ̌qal-mĕnwòrá֥h ẇ⁠mĕnwòrá֖h wĕ⁠néròţe֑y⁠há wĕ⁠li⁠mĕnòr֨wòţ ha⁠kė֤sep bĕ̇⁠mişĕ̌qál֙ li⁠mĕnwòrá֣h wĕ⁠néròţe֔y⁠há kȧ⁠ʻàbwòda֖ţ mĕnwòrá֥h ẇ⁠mĕnwòráֽh׃"],[28,16,"וְ⁠אֶת־הַ⁠זָּהָ֥ב מִשְׁקָ֛ל לְ⁠שֻׁלְחֲנ֥וֹת הַֽ⁠מַּעֲרֶ֖כֶת לְ⁠שֻׁלְחַ֣ן וְ⁠שֻׁלְחָ֑ן וְ⁠כֶ֖סֶף לְ⁠שֻׁלְחֲנ֥וֹת הַ⁠כָּֽסֶף׃","wĕ⁠ʼeţ-ha⁠zá̇há֥b mişĕ̌qá֛l lĕ⁠şǔlĕẖàn֥wòţ haֽ⁠mȧʻàre֖keţ lĕ⁠şǔlĕẖa֣n wĕ⁠şǔlĕẖá֑n wĕ⁠ke֖sep lĕ⁠şǔlĕẖàn֥wòţ ha⁠káֽ̇sep׃"],[28,17,"וְ⁠הַ⁠מִּזְלָג֧וֹת וְ⁠הַ⁠מִּזְרָק֛וֹת וְ⁠הַ⁠קְּשָׂוֺ֖ת זָהָ֣ב טָה֑וֹר וְ⁠לִ⁠כְפוֹרֵ֨י הַ⁠זָּהָ֤ב בְּ⁠מִשְׁקָל֙ לִ⁠כְפ֣וֹר וּ⁠כְפ֔וֹר וְ⁠לִ⁠כְפוֹרֵ֥י הַ⁠כֶּ֛סֶף בְּ⁠מִשְׁקָ֖ל לִ⁠כְפ֥וֹר וּ⁠כְפֽוֹר׃","wĕ⁠ha⁠mi̇zĕlág֧wòţ wĕ⁠ha⁠mi̇zĕráq֛wòţ wĕ⁠ha⁠qĕ̇şá̂wֺ֖ţ záhá֣b táh֑wòr wĕ⁠li⁠kĕpwòré֨y ha⁠zá̇há֤b bĕ̇⁠mişĕ̌qál֙ li⁠kĕp֣wòr ẇ⁠kĕp֔wòr wĕ⁠li⁠kĕpwòré֥y ha⁠kė֛sep bĕ̇⁠mişĕ̌qá֖l li⁠kĕp֥wòr ẇ⁠kĕpֽwòr׃"],[28,18,"וּ⁠לְ⁠מִזְבַּ֧ח הַ⁠קְּטֹ֛רֶת זָהָ֥ב מְזֻקָּ֖ק בַּ⁠מִּשְׁקָ֑ל וּ⁠לְ⁠תַבְנִ֣ית הַ⁠מֶּרְכָּבָ֗ה הַ⁠כְּרֻבִ֤ים זָהָב֙ לְ⁠פֹ֣רְשִׂ֔ים וְ⁠סֹכְכִ֖ים עַל־אֲר֥וֹן בְּרִית־יְהוָֽה׃","ẇ⁠lĕ⁠mizĕbȧ֧ẖ ha⁠qĕ̇tò֛reţ záhá֥b mĕzuqá֖̇q bȧ⁠mi̇şĕ̌qá֑l ẇ⁠lĕ⁠ţabĕni֣yţ ha⁠mėrĕká̇bá֗h ha⁠kĕ̇rubi֤ym záháb֙ lĕ⁠pò֣rĕşî֔ym wĕ⁠sòkĕki֖ym ʻal-ʼàr֥wòn bĕ̇riyţ-yĕhwáֽh׃"],[28,19,"הַ⁠כֹּ֥ל בִּ⁠כְתָ֛ב מִ⁠יַּ֥ד יְהוָ֖ה עָלַ֣⁠י הִשְׂכִּ֑יל כֹּ֖ל מַלְאֲכ֥וֹת הַ⁠תַּבְנִֽית׃פ","ha⁠kò֥̇l bi̇⁠kĕţá֛b mi⁠yȧ֥d yĕhwá֖h ʻála֣⁠y hişĕ̂ki֑̇yl kò֖̇l malĕʼàk֥wòţ ha⁠ţȧbĕniֽyţ׃p"],[28,20,"וַ⁠יֹּ֨אמֶר דָּוִ֜יד לִ⁠שְׁלֹמֹ֣ה בְנ֗⁠וֹ חֲזַ֤ק וֶ⁠אֱמַץ֙ וַ⁠עֲשֵׂ֔ה אַל־תִּירָ֖א וְ⁠אַל־תֵּחָ֑ת כִּי֩ יְהוָ֨ה אֱלֹהִ֤ים אֱלֹהַ⁠י֙ עִמָּ֔⁠ךְ לֹ֤א יַרְפְּ⁠ךָ֙ וְ⁠לֹ֣א יַֽעַזְבֶ֔⁠ךָּ עַד־לִ⁠כְל֕וֹת כָּל־מְלֶ֖אכֶת עֲבוֹדַ֥ת בֵּית־יְהוָֽה׃","wa⁠yò̇֨ʼmer dá̇wi֜yd li⁠şĕ̌lòmò֣h bĕn֗⁠wò ẖàza֤q we⁠ʼèmaẕ֙ wa⁠ʻàşé̂֔h ʼal-ţi̇yrá֖ʼ wĕ⁠ʼal-ţé̇ẖá֑ţ ki̇y֩ yĕhwá֨h ʼèlòhi֤ym ʼèlòha⁠y֙ ʻimá̇֔⁠kĕ lò֤ʼ yarĕpĕ̇⁠ká֙ wĕ⁠lò֣ʼ yaֽʻazĕbe֔⁠ká̇ ʻad-li⁠kĕl֕wòţ ká̇l-mĕle֖ʼkeţ ʻàbwòda֥ţ bé̇yţ-yĕhwáֽh׃"],[28,21,"וְ⁠הִנֵּ֗ה מַחְלְקוֹת֙ הַ⁠כֹּהֲנִ֣ים וְ⁠הַ⁠לְוִיִּ֔ם לְ⁠כָל־עֲבוֹדַ֖ת בֵּ֣ית הָ⁠אֱלֹהִ֑ים וְ⁠עִמְּ⁠ךָ֙ בְ⁠כָל־מְלָאכָ֜ה לְ⁠כָל־נָדִ֤יב בַּֽ⁠חָכְמָה֙ לְ⁠כָל־עֲבוֹדָ֔ה וְ⁠הַ⁠שָּׂרִ֥ים וְ⁠כָל־הָ⁠עָ֖ם לְ⁠כָל־דְּבָרֶֽי⁠ךָ׃פ","wĕ⁠hiné̇֗h maẖĕlĕqwòţ֙ ha⁠kò̇hàni֣ym wĕ⁠ha⁠lĕwiyi̇֔m lĕ⁠kál-ʻàbwòda֖ţ bé֣̇yţ há⁠ʼèlòhi֑ym wĕ⁠ʻimĕ̇⁠ká֙ bĕ⁠kál-mĕláʼká֜h lĕ⁠kál-nádi֤yb bȧֽ⁠ẖákĕmáh֙ lĕ⁠kál-ʻàbwòdá֔h wĕ⁠ha⁠şá̇̂ri֥ym wĕ⁠kál-há⁠ʻá֖m lĕ⁠kál-dĕ̇báreֽy⁠ká׃p"],[29,1,"וַ⁠יֹּ֨אמֶר דָּוִ֤יד הַ⁠מֶּ֨לֶךְ֙ לְ⁠כָל־הַ⁠קָּהָ֔ל שְׁלֹמֹ֨ה בְנִ֥⁠י אֶחָ֛ד בָּֽחַר־בּ֥⁠וֹ אֱלֹהִ֖ים נַ֣עַר וָ⁠רָ֑ךְ וְ⁠הַ⁠מְּלָאכָ֣ה גְדוֹלָ֔ה כִּ֣י לֹ֤א לְ⁠אָדָם֙ הַ⁠בִּירָ֔ה כִּ֖י לַ⁠יהוָ֥ה אֱלֹהִֽים׃","wa⁠yò̇֨ʼmer dá̇wi֤yd ha⁠mė֨lekĕ֙ lĕ⁠kál-ha⁠qá̇há֔l şĕ̌lòmò֨h bĕni֥⁠y ʼeẖá֛d báֽ̇ẖar-ḃ֥⁠wò ʼèlòhi֖ym na֣ʻar wá⁠rá֑kĕ wĕ⁠ha⁠mĕ̇láʼká֣h gĕdwòlá֔h ki֣̇y lò֤ʼ lĕ⁠ʼádám֙ ha⁠bi̇yrá֔h ki֖̇y la⁠yhwá֥h ʼèlòhiֽym׃"],[29,2,"וּֽ⁠כְ⁠כָל־כֹּחִ֞⁠י הֲכִינ֣וֹתִי לְ⁠בֵית־אֱלֹהַ֗⁠י הַ⁠זָּהָ֣ב ׀ לַ֠⁠זָּהָב וְ⁠הַ⁠כֶּ֨סֶף לַ⁠כֶּ֜סֶף וְ⁠הַ⁠נְּחֹ֣שֶׁת לַ⁠נְּחֹ֗שֶׁת הַ⁠בַּרְזֶל֙ לַ⁠בַּרְזֶ֔ל וְ⁠הָ⁠עֵצִ֖ים לָ⁠עֵצִ֑ים אַבְנֵי־שֹׁ֨הַם וּ⁠מִלּוּאִ֜ים אַבְנֵי־פ֣וּךְ וְ⁠רִקְמָ֗ה וְ⁠כֹ֨ל אֶ֧בֶן יְקָרָ֛ה וְ⁠אַבְנֵי־שַׁ֖יִשׁ לָ⁠רֹֽב׃","ẇֽ⁠kĕ⁠kál-kò̇ẖi֞⁠y hàkiyn֣wòţiy lĕ⁠béyţ-ʼèlòha֗⁠y ha⁠zá̇há֣b ׀ la֠⁠zá̇háb wĕ⁠ha⁠kė֨sep la⁠kė֜sep wĕ⁠ha⁠nĕ̇ẖò֣şěţ la⁠nĕ̇ẖò֗şěţ ha⁠bȧrĕzel֙ la⁠bȧrĕze֔l wĕ⁠há⁠ʻéẕi֖ym lá⁠ʻéẕi֑ym ʼabĕnéy-şò̌֨ham ẇ⁠mil̇ẇʼi֜ym ʼabĕnéy-p֣ẇkĕ wĕ⁠riqĕmá֗h wĕ⁠kò֨l ʼe֧ben yĕqárá֛h wĕ⁠ʼabĕnéy-şǎ֖yiş̌ lá⁠ròֽb׃"],[29,3,"וְ⁠ע֗וֹד בִּ⁠רְצוֹתִ⁠י֙ בְּ⁠בֵ֣ית אֱלֹהַ֔⁠י יֶשׁ־לִ֥⁠י סְגֻלָּ֖ה זָהָ֣ב וָ⁠כָ֑סֶף נָתַ֤תִּי לְ⁠בֵית־אֱלֹהַ⁠י֙ לְ⁠מַ֔עְלָ⁠ה מִ⁠כָּל־הֲכִינ֖וֹתִי לְ⁠בֵ֥ית הַ⁠קֹּֽדֶשׁ׃","wĕ⁠ʻ֗wòd bi̇⁠rĕẕwòţi⁠y֙ bĕ̇⁠bé֣yţ ʼèlòha֔⁠y yeş̌-li֥⁠y sĕgulá֖̇h záhá֣b wá⁠ká֑sep náţa֤ţi̇y lĕ⁠béyţ-ʼèlòha⁠y֙ lĕ⁠ma֔ʻĕlá⁠h mi⁠ká̇l-hàkiyn֖wòţiy lĕ⁠bé֥yţ ha⁠qòֽ̇deş̌׃"],[29,4,"שְׁלֹ֧שֶׁת אֲלָפִ֛ים כִּכְּרֵ֥י זָהָ֖ב מִ⁠זְּהַ֣ב אוֹפִ֑יר וְ⁠שִׁבְעַ֨ת אֲלָפִ֤ים כִּכַּר־כֶּ֨סֶף֙ מְזֻקָּ֔ק לָ⁠ט֖וּחַ קִיר֥וֹת הַ⁠בָּתִּֽים׃","şĕ̌lò֧şěţ ʼàlápi֛ym ki̇kĕ̇ré֥y záhá֖b mi⁠zĕ̇ha֣b ʼwòpi֑yr wĕ⁠şǐbĕʻa֨ţ ʼàlápi֤ym ki̇kȧr-kė֨sep֙ mĕzuqá̇֔q lá⁠t֖ẇẖa qiyr֥wòţ ha⁠bá̇ţiֽ̇ym׃"],[29,5,"לַ⁠זָּהָ֤ב לַ⁠זָּהָב֙ וְ⁠לַ⁠כֶּ֣סֶף לַ⁠כֶּ֔סֶף וּ⁠לְ⁠כָל־מְלָאכָ֖ה בְּ⁠יַ֣ד חָרָשִׁ֑ים וּ⁠מִ֣י מִתְנַדֵּ֔ב לְ⁠מַלֹּ֥אות יָד֛⁠וֹ הַ⁠יּ֖וֹם לַ⁠יהוָֽה׃","la⁠zá̇há֤b la⁠zá̇háb֙ wĕ⁠la⁠kė֣sep la⁠kė֔sep ẇ⁠lĕ⁠kál-mĕláʼká֖h bĕ̇⁠ya֣d ẖáráşǐ֑ym ẇ⁠mi֣y miţĕnadé̇֔b lĕ⁠malò֥̇ʼwţ yád֛⁠wò ha⁠ẏ֖wòm la⁠yhwáֽh׃"],[29,6,"וַ⁠יִּֽתְנַדְּבוּ֩ שָׂרֵ֨י הָ⁠אָב֜וֹת וְ⁠שָׂרֵ֣י ׀ שִׁבְטֵ֣י יִשְׂרָאֵ֗ל וְ⁠שָׂרֵ֤י הָ⁠אֲלָפִים֙ וְ⁠הַ⁠מֵּא֔וֹת וּ⁠לְ⁠שָׂרֵ֖י מְלֶ֥אכֶת הַ⁠מֶּֽלֶךְ׃","wa⁠yiֽ̇ţĕnadĕ̇bẇ֩ şá̂ré֨y há⁠ʼáb֜wòţ wĕ⁠şá̂ré֣y ׀ şǐbĕté֣y yişĕ̂ráʼé֗l wĕ⁠şá̂ré֤y há⁠ʼàlápiym֙ wĕ⁠ha⁠mé̇ʼ֔wòţ ẇ⁠lĕ⁠şá̂ré֖y mĕle֥ʼkeţ ha⁠mėֽlekĕ׃"],[29,7,"וַֽ⁠יִּתְּנ֞וּ לַ⁠עֲבוֹדַ֣ת בֵּית־הָ⁠אֱלֹהִ֗ים זָהָ֞ב כִּכָּרִ֣ים חֲמֵֽשֶׁת־אֲלָפִים֮ וַ⁠אֲדַרְכֹנִ֣ים רִבּוֹ֒ וְ⁠כֶ֗סֶף כִּכָּרִים֙ עֲשֶׂ֣רֶת אֲלָפִ֔ים וּ⁠נְחֹ֕שֶׁת רִבּ֛וֹ וּ⁠שְׁמוֹנַ֥ת אֲלָפִ֖ים כִּכָּרִ֑ים וּ⁠בַרְזֶ֖ל מֵֽאָה־אֶ֥לֶף כִּכָּרִֽים׃","waֽ⁠yi̇ţĕ̇n֞ẇ la⁠ʻàbwòda֣ţ bé̇yţ-há⁠ʼèlòhi֗ym záhá֞b ki̇ká̇ri֣ym ẖàméֽşěţ-ʼàlápiym֮ wa⁠ʼàdarĕkòni֣ym riḃwò֒ wĕ⁠ke֗sep ki̇ká̇riym֙ ʻàşê֣reţ ʼàlápi֔ym ẇ⁠nĕẖò֕şěţ riḃ֛wò ẇ⁠şĕ̌mwòna֥ţ ʼàlápi֖ym ki̇ká̇ri֑ym ẇ⁠barĕze֖l méֽʼáh-ʼe֥lep ki̇ká̇riֽym׃"],[29,8,"וְ⁠הַ⁠נִּמְצָ֤א אִתּ⁠וֹ֙ אֲבָנִ֔ים נָתְנ֖וּ לְ⁠אוֹצַ֣ר בֵּית־יְהוָ֑ה עַ֥ל יַד־יְחִיאֵ֖ל הַ⁠גֵּרְשֻׁנִּֽי׃","wĕ⁠ha⁠ni̇mĕẕá֤ʼ ʼiţ̇⁠wò֙ ʼàbáni֔ym náţĕn֖ẇ lĕ⁠ʼwòẕa֣r bé̇yţ-yĕhwá֑h ʻa֥l yad-yĕẖiyʼé֖l ha⁠gé̇rĕşǔniֽ̇y׃"],[29,9,"וַ⁠יִּשְׂמְח֤וּ הָ⁠עָם֙ עַל־הִֽתְנַדְּבָ֔⁠ם כִּ֚י בְּ⁠לֵ֣ב שָׁלֵ֔ם הִֽתְנַדְּב֖וּ לַ⁠יהוָ֑ה וְ⁠גַם֙ דָּוִ֣יד הַ⁠מֶּ֔לֶךְ שָׂמַ֖ח שִׂמְחָ֥ה גְדוֹלָֽה׃פ","wa⁠yi̇şĕ̂mĕẖ֤ẇ há⁠ʻám֙ ʻal-hiֽţĕnadĕ̇bá֔⁠m ki֚̇y bĕ̇⁠lé֣b şá̌lé֔m hiֽţĕnadĕ̇b֖ẇ la⁠yhwá֑h wĕ⁠gam֙ dá̇wi֣yd ha⁠mė֔lekĕ şá̂ma֖ẖ şîmĕẖá֥h gĕdwòláֽh׃p"],[29,10,"וַ⁠יְבָ֤רֶךְ דָּוִיד֙ אֶת־יְהוָ֔ה לְ⁠עֵינֵ֖י כָּל־הַ⁠קָּהָ֑ל וַ⁠יֹּ֣אמֶר דָּוִ֗יד בָּר֨וּךְ אַתָּ֤ה יְהוָה֙ אֱלֹהֵי֙ יִשְׂרָאֵ֣ל אָבִ֔י⁠נוּ מֵ⁠עוֹלָ֖ם וְ⁠עַד־עוֹלָֽם׃","wa⁠yĕbá֤rekĕ dá̇wiyd֙ ʼeţ-yĕhwá֔h lĕ⁠ʻéyné֖y ká̇l-ha⁠qá̇há֑l wa⁠yò֣̇ʼmer dá̇wi֗yd bá̇r֨ẇkĕ ʼaţá֤̇h yĕhwáh֙ ʼèlòhéy֙ yişĕ̂ráʼé֣l ʼábi֔y⁠nẇ mé⁠ʻwòlá֖m wĕ⁠ʻad-ʻwòláֽm׃"],[29,11,"לְ⁠ךָ֣ יְ֠הוָה הַ⁠גְּדֻלָּ֨ה וְ⁠הַ⁠גְּבוּרָ֤ה וְ⁠הַ⁠תִּפְאֶ֨רֶת֙ וְ⁠הַ⁠נֵּ֣צַח וְ⁠הַ⁠ה֔וֹד כִּי־כֹ֖ל בַּ⁠שָּׁמַ֣יִם וּ⁠בָ⁠אָ֑רֶץ לְ⁠ךָ֤ יְהוָה֙ הַ⁠מַּמְלָכָ֔ה וְ⁠הַ⁠מִּתְנַשֵּׂ֖א לְ⁠כֹ֥ל ׀ לְ⁠רֹֽאשׁ׃","lĕ⁠ká֣ yĕ֠hwáh ha⁠gĕ̇dulá̇֨h wĕ⁠ha⁠gĕ̇bẇrá֤h wĕ⁠ha⁠ţi̇pĕʼe֨reţ֙ wĕ⁠ha⁠né֣̇ẕaẖ wĕ⁠ha⁠h֔wòd ki̇y-kò֖l bȧ⁠şá̇̌ma֣yim ẇ⁠bá⁠ʼá֑reẕ lĕ⁠ká֤ yĕhwáh֙ ha⁠mȧmĕláká֔h wĕ⁠ha⁠mi̇ţĕnaşé֖̇̂ʼ lĕ⁠kò֥l ׀ lĕ⁠ròֽʼş̌׃"],[29,12,"וְ⁠הָ⁠עֹ֤שֶׁר וְ⁠הַ⁠כָּבוֹד֙ מִ⁠לְּ⁠פָנֶ֔י⁠ךָ וְ⁠אַתָּה֙ מוֹשֵׁ֣ל בַּ⁠כֹּ֔ל וּ⁠בְ⁠יָדְ⁠ךָ֖ כֹּ֣חַ וּ⁠גְבוּרָ֑ה וּ⁠בְ⁠יָ֣דְ⁠ךָ֔ לְ⁠גַדֵּ֥ל וּ⁠לְ⁠חַזֵּ֖ק לַ⁠כֹּֽל׃","wĕ⁠há⁠ʻò֤şěr wĕ⁠ha⁠ká̇bwòd֙ mi⁠lĕ̇⁠páne֔y⁠ká wĕ⁠ʼaţá̇h֙ mwòşé֣̌l bȧ⁠kò̇֔l ẇ⁠bĕ⁠yádĕ⁠ká֖ kò֣̇ẖa ẇ⁠gĕbẇrá֑h ẇ⁠bĕ⁠yá֣dĕ⁠ká֔ lĕ⁠gadé֥̇l ẇ⁠lĕ⁠ẖazé֖̇q la⁠kòֽ̇l׃"],[29,13,"וְ⁠עַתָּ֣ה אֱלֹהֵ֔י⁠נוּ מוֹדִ֥ים אֲנַ֖חְנוּ לָ֑⁠ךְ וּֽ⁠מְהַֽלְלִ֖ים לְ⁠שֵׁ֥ם תִּפְאַרְתֶּֽ⁠ךָ׃","wĕ⁠ʻaţá֣̇h ʼèlòhé֔y⁠nẇ mwòdi֥ym ʼàna֖ẖĕnẇ lá֑⁠kĕ ẇֽ⁠mĕhaֽlĕli֖ym lĕ⁠şé֥̌m ţi̇pĕʼarĕţėֽ⁠ká׃"],[29,14,"וְ⁠כִ֨י מִ֤י אֲנִי֙ וּ⁠מִ֣י עַמִּ֔⁠י כִּֽי־נַעְצֹ֣ר כֹּ֔חַ לְ⁠הִתְנַדֵּ֖ב כָּ⁠זֹ֑את כִּֽי־מִמְּ⁠ךָ֣ הַ⁠כֹּ֔ל וּ⁠מִ⁠יָּדְ⁠ךָ֖ נָתַ֥נּוּ לָֽ⁠ךְ׃","wĕ⁠ki֨y mi֤y ʼàniy֙ ẇ⁠mi֣y ʻami̇֔⁠y kiֽ̇y-naʻĕẕò֣r kò̇֔ẖa lĕ⁠hiţĕnadé֖̇b ká̇⁠zò֑ʼţ kiֽ̇y-mimĕ̇⁠ká֣ ha⁠kò̇֔l ẇ⁠mi⁠yá̇dĕ⁠ká֖ náţa֥ṅẇ láֽ⁠kĕ׃"],[29,15,"כִּֽי־גֵרִ֨ים אֲנַ֧חְנוּ לְ⁠פָנֶ֛י⁠ךָ וְ⁠תוֹשָׁבִ֖ים כְּ⁠כָל־אֲבֹתֵ֑י⁠נוּ כַּ⁠צֵּ֧ל ׀ יָמֵ֛י⁠נוּ עַל־הָ⁠אָ֖רֶץ וְ⁠אֵ֥ין מִקְוֶֽה׃","kiֽ̇y-géri֨ym ʼàna֧ẖĕnẇ lĕ⁠páne֛y⁠ká wĕ⁠ţwòşá̌bi֖ym kĕ̇⁠kál-ʼàbòţé֑y⁠nẇ kȧ⁠ẕé֧̇l ׀ yámé֛y⁠nẇ ʻal-há⁠ʼá֖reẕ wĕ⁠ʼé֥yn miqĕweֽh׃"],[29,16,"יְהוָ֣ה אֱלֹהֵ֔י⁠נוּ כֹ֣ל הֶ⁠הָמ֤וֹן הַ⁠זֶּה֙ אֲשֶׁ֣ר הֲכִינֹ֔נוּ לִ⁠בְנֽוֹת־לְ⁠ךָ֥ בַ֖יִת לְ⁠שֵׁ֣ם קָדְשֶׁ֑⁠ךָ מִ⁠יָּדְ⁠ךָ֥ היא וּ⁠לְ⁠ךָ֥ הַ⁠כֹּֽל׃","yĕhwá֣h ʼèlòhé֔y⁠nẇ kò֣l he⁠hám֤wòn ha⁠zėh֙ ʼàşě֣r hàkiynò֔nẇ li⁠bĕnֽwòţ-lĕ⁠ká֥ ba֖yiţ lĕ⁠şé֣̌m qádĕşě֑⁠ká mi⁠yá̇dĕ⁠ká֥ hyʼ ẇ⁠lĕ⁠ká֥ ha⁠kòֽ̇l׃"],[29,17,"וְ⁠יָדַ֣עְתִּי אֱלֹהַ֔⁠י כִּ֤י אַתָּה֙ בֹּחֵ֣ן לֵבָ֔ב וּ⁠מֵישָׁרִ֖ים תִּרְצֶ֑ה אֲנִ֗י בְּ⁠יֹ֤שֶׁר לְבָבִ⁠י֙ הִתְנַדַּ֣בְתִּי כָל־אֵ֔לֶּה וְ⁠עַתָּ֗ה עַמְּ⁠ךָ֙ הַ⁠נִּמְצְאוּ־פֹ֔ה רָאִ֥יתִי בְ⁠שִׂמְחָ֖ה לְ⁠הִֽתְנַדֶּב־לָֽ⁠ךְ׃","wĕ⁠yáda֣ʻĕţi̇y ʼèlòha֔⁠y ki֤̇y ʼaţá̇h֙ bò̇ẖé֣n lébá֔b ẇ⁠méyşá̌ri֖ym ţi̇rĕẕe֑h ʼàni֗y bĕ̇⁠yò֤şěr lĕbábi⁠y֙ hiţĕnadȧ֣bĕţi̇y kál-ʼé֔lėh wĕ⁠ʻaţá̇֗h ʻamĕ̇⁠ká֙ ha⁠ni̇mĕẕĕʼẇ-pò֔h ráʼi֥yţiy bĕ⁠şîmĕẖá֖h lĕ⁠hiֽţĕnadėb-láֽ⁠kĕ׃"],[29,18,"יְהוָ֗ה אֱ֠לֹהֵי אַבְרָהָ֞ם יִצְחָ֤ק וְ⁠יִשְׂרָאֵל֙ אֲבֹתֵ֔י⁠נוּ שֳׁמְרָ⁠ה־זֹּ֣את לְ⁠עוֹלָ֔ם לְ⁠יֵ֥צֶר מַחְשְׁב֖וֹת לְבַ֣ב עַמֶּ֑⁠ךָ וְ⁠הָכֵ֥ן לְבָבָ֖⁠ם אֵלֶֽי⁠ךָ׃","yĕhwá֗h ʼè֠lòhéy ʼabĕráhá֞m yiẕĕẖá֤q wĕ⁠yişĕ̂ráʼél֙ ʼàbòţé֔y⁠nẇ şǒmĕrá⁠h-zò֣̇ʼţ lĕ⁠ʻwòlá֔m lĕ⁠yé֥ẕer maẖĕşĕ̌b֖wòţ lĕba֣b ʻamė֑⁠ká wĕ⁠háké֥n lĕbábá֖⁠m ʼéleֽy⁠ká׃"],[29,19,"וְ⁠לִ⁠שְׁלֹמֹ֣ה בְנִ֗⁠י תֵּ֚ן לֵבָ֣ב שָׁלֵ֔ם לִ⁠שְׁמוֹר֙ מִצְוֺתֶ֔י⁠ךָ עֵדְוֺתֶ֖י⁠ךָ וְ⁠חֻקֶּ֑י⁠ךָ וְ⁠לַ⁠עֲשׂ֣וֹת הַ⁠כֹּ֔ל וְ⁠לִ⁠בְנ֖וֹת הַ⁠בִּירָ֥ה אֲשֶׁר־הֲכִינֽוֹתִי׃פ","wĕ⁠li⁠şĕ̌lòmò֣h bĕni֗⁠y ţé֚̇n lébá֣b şá̌lé֔m li⁠şĕ̌mwòr֙ miẕĕwֺţe֔y⁠ká ʻédĕwֺţe֖y⁠ká wĕ⁠ẖuqė֑y⁠ká wĕ⁠la⁠ʻàş֣̂wòţ ha⁠kò̇֔l wĕ⁠li⁠bĕn֖wòţ ha⁠bi̇yrá֥h ʼàşěr-hàkiynֽwòţiy׃p"],[29,20,"וַ⁠יֹּ֤אמֶר דָּוִיד֙ לְ⁠כָל־הַ⁠קָּהָ֔ל בָּֽרְכוּ־נָ֖א אֶת־יְהוָ֣ה אֱלֹהֵי⁠כֶ֑ם וַ⁠יְבָרֲכ֣וּ כָֽל־הַ⁠קָּהָ֗ל לַ⁠יהוָה֙ אֱלֹהֵ֣י אֲבֹֽתֵי⁠הֶ֔ם וַ⁠יִּקְּד֧וּ וַ⁠יִּֽשְׁתַּחֲו֛וּ לַ⁠יהוָ֖ה וְ⁠לַ⁠מֶּֽלֶךְ׃","wa⁠yò֤̇ʼmer dá̇wiyd֙ lĕ⁠kál-ha⁠qá̇há֔l báֽ̇rĕkẇ-ná֖ʼ ʼeţ-yĕhwá֣h ʼèlòhéy⁠ke֑m wa⁠yĕbáràk֣ẇ káֽl-ha⁠qá̇há֗l la⁠yhwáh֙ ʼèlòhé֣y ʼàbòֽţéy⁠he֔m wa⁠yi̇qĕ̇d֧ẇ wa⁠yiֽ̇şĕ̌ţȧẖàw֛ẇ la⁠yhwá֖h wĕ⁠la⁠mėֽlekĕ׃"],[29,21,"וַ⁠יִּזְבְּח֣וּ לַ⁠יהוָ֣ה ׀ זְ֠בָחִים וַ⁠יַּעֲל֨וּ עֹל֜וֹת לַ⁠יהוָ֗ה לְֽ⁠מָחֳרַת֮ הַ⁠יּ֣וֹם הַ⁠הוּא֒ פָּרִ֨ים אֶ֜לֶף אֵילִ֥ים אֶ֛לֶף כְּבָשִׂ֥ים אֶ֖לֶף וְ⁠נִסְכֵּי⁠הֶ֑ם וּ⁠זְבָחִ֥ים לָ⁠רֹ֖ב לְ⁠כָל־יִשְׂרָאֵֽל׃","wa⁠yi̇zĕbĕ̇ẖ֣ẇ la⁠yhwá֣h ׀ zĕ֠báẖiym wa⁠yȧʻàl֨ẇ ʻòl֜wòţ la⁠yhwá֗h lĕֽ⁠máẖoraţ֮ ha⁠ẏ֣wòm ha⁠hẇʼ֒ pá̇ri֨ym ʼe֜lep ʼéyli֥ym ʼe֛lep kĕ̇báşî֥ym ʼe֖lep wĕ⁠nisĕké̇y⁠he֑m ẇ⁠zĕbáẖi֥ym lá⁠rò֖b lĕ⁠kál-yişĕ̂ráʼéֽl׃"],[29,22,"וַ⁠יֹּאכְל֨וּ וַ⁠יִּשְׁתּ֜וּ לִ⁠פְנֵ֧י יְהוָ֛ה בַּ⁠יּ֥וֹם הַ⁠ה֖וּא בְּ⁠שִׂמְחָ֣ה גְדוֹלָ֑ה וַ⁠יַּמְלִ֤יכוּ שֵׁנִית֙ לִ⁠שְׁלֹמֹ֣ה בֶן־דָּוִ֔יד וַ⁠יִּמְשְׁח֧וּ לַ⁠יהוָ֛ה לְ⁠נָגִ֥יד וּ⁠לְ⁠צָד֖וֹק לְ⁠כֹהֵֽן׃","wa⁠yò̇ʼkĕl֨ẇ wa⁠yi̇şĕ̌ţ̇֜ẇ li⁠pĕné֧y yĕhwá֛h bȧ⁠ẏ֥wòm ha⁠h֖ẇʼ bĕ̇⁠şîmĕẖá֣h gĕdwòlá֑h wa⁠yȧmĕli֤ykẇ şé̌niyţ֙ li⁠şĕ̌lòmò֣h ben-dá̇wi֔yd wa⁠yi̇mĕşĕ̌ẖ֧ẇ la⁠yhwá֛h lĕ⁠nági֥yd ẇ⁠lĕ⁠ẕád֖wòq lĕ⁠kòhéֽn׃"],[29,23,"וַ⁠יֵּ֣שֶׁב שְׁ֠לֹמֹה עַל־כִּסֵּ֨א יְהוָ֧ה ׀ לְ⁠מֶ֛לֶךְ תַּֽחַת־דָּוִ֥יד אָבִ֖י⁠ו וַ⁠יַּצְלַ֑ח וַ⁠יִּשְׁמְע֥וּ אֵלָ֖י⁠ו כָּל־יִשְׂרָאֵֽל׃","wa⁠yé֣̇şěb şĕ̌֠lòmòh ʻal-ki̇sé̇֨ʼ yĕhwá֧h ׀ lĕ⁠me֛lekĕ ţȧֽẖaţ-dá̇wi֥yd ʼábi֖y⁠w wa⁠yȧẕĕla֑ẖ wa⁠yi̇şĕ̌mĕʻ֥ẇ ʼélá֖y⁠w ká̇l-yişĕ̂ráʼéֽl׃"],[29,24,"וְ⁠כָל־הַ⁠שָּׂרִים֙ וְ⁠הַ⁠גִּבֹּרִ֔ים וְ⁠גַ֕ם כָּל־בְּנֵ֖י הַ⁠מֶּ֣לֶךְ דָּוִ֑יד נָ֣תְנוּ יָ֔ד תַּ֖חַת שְׁלֹמֹ֥ה הַ⁠מֶּֽלֶךְ׃","wĕ⁠kál-ha⁠şá̇̂riym֙ wĕ⁠ha⁠gi̇bò̇ri֔ym wĕ⁠ga֕m ká̇l-bĕ̇né֖y ha⁠mė֣lekĕ dá̇wi֑yd ná֣ţĕnẇ yá֔d ţȧ֖ẖaţ şĕ̌lòmò֥h ha⁠mėֽlekĕ׃"],[29,25,"וַ⁠יְגַדֵּ֨ל יְהוָ֤ה אֶת־שְׁלֹמֹה֙ לְ⁠מַ֔עְלָ⁠ה לְ⁠עֵינֵ֖י כָּל־יִשְׂרָאֵ֑ל וַ⁠יִּתֵּ֤ן עָלָי⁠ו֙ ה֣וֹד מַלְכ֔וּת אֲ֠שֶׁר לֹֽא־הָיָ֧ה עַל־כָּל־מֶ֛לֶךְ לְ⁠פָנָ֖י⁠ו עַל־יִשְׂרָאֵֽל׃פ","wa⁠yĕgadé̇֨l yĕhwá֤h ʼeţ-şĕ̌lòmòh֙ lĕ⁠ma֔ʻĕlá⁠h lĕ⁠ʻéyné֖y ká̇l-yişĕ̂ráʼé֑l wa⁠yi̇ţé֤̇n ʻáláy⁠w֙ h֣wòd malĕk֔ẇţ ʼà֠şěr lòֽʼ-háyá֧h ʻal-ká̇l-me֛lekĕ lĕ⁠páná֖y⁠w ʻal-yişĕ̂ráʼéֽl׃p"],[29,26,"וְ⁠דָוִיד֙ בֶּן־יִשָׁ֔י מָלַ֖ךְ עַל־כָּל־יִשְׂרָאֵֽל׃","wĕ⁠dáwiyd֙ bėn-yişá̌֔y mála֖kĕ ʻal-ká̇l-yişĕ̂ráʼéֽl׃"],[29,27,"וְ⁠הַ⁠יָּמִ֗ים אֲשֶׁ֤ר מָלַךְ֙ עַל־יִשְׂרָאֵ֔ל אַרְבָּעִ֖ים שָׁנָ֑ה בְּ⁠חֶבְר֤וֹן מָלַךְ֙ שֶׁ֣בַע שָׁנִ֔ים וּ⁠בִ⁠ירוּשָׁלִַ֥ם מָלַ֖ךְ שְׁלֹשִׁ֥ים וְ⁠שָׁלֽוֹשׁ׃","wĕ⁠ha⁠yá̇mi֗ym ʼàşě֤r málakĕ֙ ʻal-yişĕ̂ráʼé֔l ʼarĕbá̇ʻi֖ym şá̌ná֑h bĕ̇⁠ẖebĕr֤wòn málakĕ֙ şě֣baʻ şá̌ni֔ym ẇ⁠bi⁠yrẇşá̌lia֥m mála֖kĕ şĕ̌lòşǐ֥ym wĕ⁠şá̌lֽwòş̌׃"],[29,28,"וַ⁠יָּ֨מָת֙ בְּ⁠שֵׂיבָ֣ה טוֹבָ֔ה שְׂבַ֥ע יָמִ֖ים עֹ֣שֶׁר וְ⁠כָב֑וֹד וַ⁠יִּמְלֹ֛ךְ שְׁלֹמֹ֥ה בְנ֖⁠וֹ תַּחְתָּֽי⁠ו׃","wa⁠yá̇֨máţ֙ bĕ̇⁠şé̂ybá֣h twòbá֔h şĕ̂ba֥ʻ yámi֖ym ʻò֣şěr wĕ⁠káb֑wòd wa⁠yi̇mĕlò֛kĕ şĕ̌lòmò֥h bĕn֖⁠wò ţȧẖĕţáֽ̇y⁠w׃"],[29,29,"וְ⁠דִבְרֵי֙ דָּוִ֣יד הַ⁠מֶּ֔לֶךְ הָ⁠רִאשֹׁנִ֖ים וְ⁠הָ⁠אֲחרֹנִ֑ים הִנָּ֣⁠ם כְּתוּבִ֗ים עַל־דִּבְרֵי֙ שְׁמוּאֵ֣ל הָ⁠רֹאֶ֔ה וְ⁠עַל־דִּבְרֵי֙ נָתָ֣ן הַ⁠נָּבִ֔יא וְ⁠עַל־דִּבְרֵ֖י גָּ֥ד הַ⁠חֹזֶֽה׃","wĕ⁠dibĕréy֙ dá̇wi֣yd ha⁠mė֔lekĕ há⁠riʼşò̌ni֖ym wĕ⁠há⁠ʼàẖròni֑ym hiná֣̇⁠m kĕ̇ţẇbi֗ym ʻal-di̇bĕréy֙ şĕ̌mẇʼé֣l há⁠ròʼe֔h wĕ⁠ʻal-di̇bĕréy֙ náţá֣n ha⁠ná̇bi֔yʼ wĕ⁠ʻal-di̇bĕré֖y gá֥̇d ha⁠ẖòzeֽh׃"],[29,30,"עִ֥ם כָּל־מַלְכוּת֖⁠וֹ וּ⁠גְבוּרָת֑⁠וֹ וְ⁠הָ⁠עִתִּ֗ים אֲשֶׁ֨ר עָבְר֤וּ עָלָי⁠ו֙ וְ⁠עַל־יִשְׂרָאֵ֔ל וְ⁠עַ֖ל כָּל־מַמְלְכ֥וֹת הָ⁠אֲרָצֽוֹת׃פ","ʻi֥m ká̇l-malĕkẇţ֖⁠wò ẇ⁠gĕbẇráţ֑⁠wò wĕ⁠há⁠ʻiţi̇֗ym ʼàşě֨r ʻábĕr֤ẇ ʻáláy⁠w֙ wĕ⁠ʻal-yişĕ̂ráʼé֔l wĕ⁠ʻa֖l ká̇l-mamĕlĕk֥wòţ há⁠ʼàráẕֽwòţ׃p"]]}};